[30438] = {id=30438,name="A Marsh Lily for Jogu",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,objectivesText="Progress: The watersh shay that I will have great fortune today.",starts={{npcID=58710,x=0.534,y=0.524,zoneID=5805}},ends={{npcID=58710,x=0.534,y=0.524,zoneID=5805}},coords={x=0.534,y=0.524,source="quest_giver",zoneID=5805},questType="standard"},
[30439] = {id=30439,name="A Dish for Jogu",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,objectivesText="Progress: You know what goes with a good drink? A good meal.",starts={{npcID=58710,x=0.534,y=0.524,zoneID=5805}},ends={{npcID=58710,x=0.534,y=0.524,zoneID=5805}},coords={x=0.534,y=0.524,source="quest_giver",zoneID=5805},questType="standard"},
[30442] = {id=30442,name="Blanche's Boomer Brew",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=6101,description="Brew Blanche's Boomer Brew by Protecting the Brewkegs.",objectivesText="Help create the Boomer Brew. If the Brewkegs catch on fire, fix them!",starts={{x=0.38,y=0.3,mapID=371,npcID=59569}},ends={{x=0.38,y=0.3,mapID=371,npcID=59569}},coords={mapID=371,x=0.38,y=0.3},questType="standard"},
[30444] = {id=30444,name="No Reprieve",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="We've been granted a brief respite from the mogu attacks as they attempt to recoup near the Five Sisters to our north. I would like you to see to it that they not be granted a similar reprieve. Show no mercy.",objectivesText="Kill 8 Shao-Tien mogu near the Five Sisters. Progress: These mogu are like roaches. It seems near impossible to do away with them for good.",starts={{x=0.214,y=0.715,mapID=390,npcID=58919}},ends={{x=0.214,y=0.715,mapID=390,npcID=58919}},coords={mapID=390,x=0.214,y=0.715},questType="standard"},
[30445] = {id=30445,name="The Waters of Youth",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="She is headstrong, my little Lyalia . I should have known she would try to challenge the Lord Reclaimer. Since her mother died, I forsook much of the time I should have spent with her in search of immortality, insisting that we could live forever, together. And now my obsession has cost my little Lyalia her life. Please, $p, when she wakes, tell her I love her.",objectivesText="Give Vaeldrin's message to Lyalia .",starts={{npcID=58745,x=0.674,y=0.326,zoneID=6134}},ends={{npcID=58821,x=0.248,y=0.34,zoneID=6134}},coords={x=0.674,y=0.326,source="quest_giver",zoneID=6134},questType="standard"},
[30449] = {id=30449,name="Darkmoon Crane Deck",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="Now that you have gathered all of the Crane cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.",objectivesText="Return the Crane Deck to the Darkmoon Faire when it comes to town. Progress: I see that you have managed to complete a Crane deck ! Congratulations!",starts={{x=0.519,y=0.609,mapID=407,npcID=14847}},ends={{npcID=14847,x=0.518,y=0.606,zoneID=5861}},coords={mapID=407,x=0.519,y=0.609},questType="standard"},
[30450] = {id=30450,name="Darkmoon Ox Deck",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="Now that you have gathered all of the Ox cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.",objectivesText="Return the Ox Deck to the Darkmoon Faire when it comes to town. Progress: I see that you have managed to complete a Ox deck ! Congratulations!",starts={{x=0.519,y=0.609,mapID=407,npcID=14847}},ends={{npcID=14847,x=0.518,y=0.606,zoneID=5861}},coords={mapID=407,x=0.519,y=0.609},questType="standard"},
[30451] = {id=30451,name="Darkmoon Serpent Deck",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,mapID=407,description="Now that you have gathered all of the Serpent cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.",ends={{npcID=14847,x=0.518,y=0.606,mapID=407}},questType="standard"},
[30452] = {id=30452,name="Darkmoon Tiger Deck",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="Now that you have gathered all of the Tiger cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.",objectivesText="Return the Tiger Deck to the Darkmoon Faire when it comes to town. Progress: I see that you have managed to complete a Tiger deck ! Congratulations!",starts={{x=0.519,y=0.609,mapID=407,npcID=14847}},ends={{npcID=14847,x=0.518,y=0.606,zoneID=5861}},coords={mapID=407,x=0.519,y=0.609},questType="standard"},
[30457] = {id=30457,name="Call Out Their Leader",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=390,description="Clearly, you are a hero come to aid us. Slay the Bataari Tribe in the Kun-Lai Pass to the northwest until the Bataari Fire-Warrior is angered enough to appear. Dispatch him.",objectivesText="Slay 10 Bataari Tribe Members in the Kun-Lai Pass until the Bataari Fire-Warrior appears. Then kill him. Progress: If the war leader of the yaungol is slain, surely our village will be saved and the refugees will be able to return to their farms.",starts={{npcID=59073,x=0.722,y=0.918,zoneID=5841}},ends={{npcID=59073,x=0.722,y=0.918,zoneID=5841}},coords={x=0.722,y=0.918,source="quest_giver",zoneID=5841},questType="standard"},
[30458] = {id=30458,name="The Scouts Return",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,mapID=371,description=", your friends have returned from their scouting mission. They need to see you immediately. I'm afraid... Well, I'd better say no more. You will see for yourself.",objectivesText="Speak to Rell Nightwind at the Glassfin Village in the Jade Forest .",questType="standard"},
[30459] = {id=30459,name="All of the Arrows",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="As soon as their reinforcements arrive, the yaungol are going to overrun our position here. If they do that, the village will be lost. Would you be willing to retrieve as many arrows off the battlefield as you can carry? I have a plan that just might save us with your help.",starts={{npcID=59076,x=0.708,y=0.904,mapID=379}},ends={{npcID=59076,x=0.708,y=0.904,mapID=379}},coords={x=0.708,y=0.904,source="quest_giver",mapID=379},questType="standard"},
[30460] = {id=30460,name="Hit Medicine",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Our warriors are fighting to keep the yaungol at bay in the Kun-Lai Pass to the northwest. Take this liniment. It is a powerful medicine that has been passed down in my family over the generations. Use the dit da jow to heal the injured warriors if you do not have healing powers of your own to use on them.",objectivesText="Use the Dit Da Jow or your own healing to aid 8 Injured Binan Warriors . Progress: There are yet more injured warriors in need of aid, <class>.",starts={{npcID=59077,x=0.716,y=0.928,zoneID=5841}},ends={{npcID=59077,x=0.716,y=0.928,zoneID=5841}},coords={x=0.716,y=0.928,source="quest_giver",zoneID=5841},questType="standard"},
[30461] = {id=30461,name="Into the Wilds",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,mapID=418,description="Deep in the wilds rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout followers. I suspect they'll know something about what happened here. The temple is located on the southern coast of the wilds, where the Krasarang River meets the sea.",objectivesText="Locate Koro Mistwalker near the Temple of the Red Crane at the southern end of Krasarang River.",starts={{npcID=57744,x=0.758,y=0.076,zoneID=6134}},ends={{npcID=58547,x=0.442,y=0.43,zoneID=6134}},coords={x=0.758,y=0.076,source="quest_giver",zoneID=6134},questType="standard"},
[30462] = {id=30462,name="Into the Wilds",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="Deep in the wilds rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout followers. I suspect they'll know something about what happened here. The temple is located on the southern coast of the wilds, where the Krasarang River meets the sea.",objectivesText="Locate Koro Mistwalker near the Temple of the Red Crane at the southern end of Krasarang River.",starts={{npcID=57744,x=0.758,y=0.076,zoneID=6134}},ends={{npcID=58547,x=0.442,y=0.43,zoneID=6134}},coords={x=0.758,y=0.076,source="quest_giver",zoneID=6134},questType="standard"},
[30464] = {id=30464,name="Going West",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,mapID=418,description="Leza now walks with the ancestors of this strange land. I must look now to the living. Kor has led a group of our scouts west deeper into the jungle. Track him down and lend what aid you can to him. We will join you as quickly as we are able.",starts={{npcID=58113,x=0.604,y=0.254,mapID=418}},ends={{npcID=58114,x=0.598,y=0.248,mapID=418}},coords={x=0.604,y=0.254,source="quest_giver",mapID=418},questType="standard"},
[30465] = {id=30465,name="Going on the Offensive",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="Ha! So my father just wasted twenty years of our lives on a fool's errand! I'm taking charge. When Tyrande sent us here she was very specific that we not come back until we find the source of the Light that she saw in her visions. It's obvious now that the Pools of Youth were not it. We are pressing westward and could use your help. Meet us at the Sentinel Basecamp further west when you are ready.",objectivesText="Speak with Lyalia at the Sentinel Basecamp in the Krasarang Wilds .",starts={{npcID=58735,x=0.674,y=0.326,zoneID=6134}},ends={{npcID=58821,x=0.248,y=0.34,zoneID=6134}},coords={x=0.674,y=0.326,source="quest_giver",zoneID=6134},questType="standard"},
[30466] = {id=30466,name="Sufficient Motivation",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,mapID=371,description="Training these savages has been quite a task, . Finding ways to motivate them was easy enough; the problem is keeping them motivated.. and focused... and awake. Now that you're back, you can help me in getting the less disciplined Hozen moving, if you catch my drift. I'll leave the method up to you.",starts={{npcID=57108,x=0.28,y=0.47,mapID=371}},ends={{npcID=57108,x=0.28,y=0.47,mapID=371}},coords={x=0.28,y=0.47,source="quest_giver",mapID=371},questType="standard"},
[30467] = {id=30467,name="My Son...",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="My son - can you find my son? When the Jinyu attacked, he ran off in the confusion. I don't know if they've done anything with him, or if he's still alive, even. Nothing else matters if I can't find him. I'd ask Mei... but something's wrong with her. She seems too... impulsive since the attack. I just can't trust that she'd bring him back safely.",starts={{npcID=59263,x=0.748,y=0.888,mapID=379}},ends={{npcID=59272,x=0.746,y=0.768,mapID=379}},coords={x=0.748,y=0.888,source="quest_giver",mapID=379},questType="standard"},
[30468] = {id=30468,name="Enraged Vengeance",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="I don't think I've ever been as... as furious as now. What betrayal! I fought them off when they attacked, killed a few here, but Merchant Shi is too much of a coward to let me go and finish the job! You, do it for me. Kill them. Kill them all.",objectivesText="Kill 15 Enraged Jinyu. Progress: Are they dead?",starts={{npcID=59273,x=0.748,y=0.886,zoneID=5841}},ends={{npcID=59273,x=0.748,y=0.886,zoneID=5841}},coords={x=0.748,y=0.886,source="quest_giver",zoneID=5841},questType="standard"},
[30469] = {id=30469,name="Repossession",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="Of course, the first priority is finding my son. But, if we save ourselves only to starve, then what have we accomplished, in the end? Please, I need you to recover some of the supplies that the Jinyu took from our caravan.",objectivesText="Collect 8 Stolen Supplies . Progress: Have you found the supplies?",starts={{npcID=59263,x=0.748,y=0.888,zoneID=5841}},ends={{npcID=59263,x=0.748,y=0.888,zoneID=5841}},coords={x=0.748,y=0.888,source="quest_giver",zoneID=5841},questType="standard"},
[30470] = {id=30470,name="A Gift For Tina",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="That Tina Mudclaw is in the Halfhill Market today, visiting her sister. She's really nice, but she's really hard to get gifts for! There's a little jewel that can be found in the cliffs to the north. It's called a chrysoberyl, and it changes color when you hold it. I'll bet she doesn't have one of THOSE! Look inside the virmen caves. I bet you'll find one really fast.",starts={{npcID=64464,x=0.526,y=0.504,mapID=376}},ends={{npcID=58761,x=0.45,y=0.338,mapID=376}},coords={x=0.526,y=0.504,source="quest_giver",mapID=376},questType="standard"},
[30471] = {id=30471,name="A Gift For Chee Chee",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="That crazy Chee Chee is actually pretty neat. Mah always said that hozen were nothing but trouble, but... I guess he's just a better hozen then the rest of them. We should do something nice for him! Those mountain hozen in the west make some really fancy stir fry, and keep bowls of it inside their little hozen houses. I bet Chee Chee would love some!",objectivesText="Obtain an Authentic Valley Stir Fry . Progress: Mmm?",starts={{npcID=64464,x=0.526,y=0.504,zoneID=5805}},ends={{npcID=58709,x=0.53,y=0.52,zoneID=5805}},coords={x=0.526,y=0.504,source="quest_giver",zoneID=5805},questType="standard"},
[30472] = {id=30472,name="A Gift For Sho",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Sho - that girl who lives up in the mountains - is in town today. I saw her walking toward the Halfhill Market. Such a long walk... she must be hungry! And I think I know just the thing that she'll like. The hozen up on the Skyrange cook a soup out of fish and apples. It sounds gross, I know... but it's awesome. You'll find it near their big, scary totem.",objectivesText="Obtain a bowl of Yu-Ping Soup . Progress: Oh! Hello, <name>.",starts={{npcID=64464,x=0.526,y=0.504,zoneID=5805}},ends={{npcID=58708,x=0.53,y=0.52,zoneID=5805}},coords={x=0.526,y=0.504,source="quest_giver",zoneID=5805},questType="standard"},
[30473] = {id=30473,name="A Gift For Fish",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="That Fish Fellreed is kind of weird. First of all, her name's Fish. That's weird. Once you talk to her, though, she's really a nice lady. Did you know that she's an animal lover? I've got an idea! The Kunzen hozen, in the mountains to the west, make little animal statues and put them in their huts to scare off bad guys. I bet Fish would LOVE something weird like that!",objectivesText="Obtain a Yak Statuette from the inside of a Kunzen hozen hut. Progress: Hey, <name>! What's up?",starts={{npcID=64464,x=0.526,y=0.504,zoneID=5805}},ends={{npcID=58705,x=0.528,y=0.518,zoneID=5805}},coords={x=0.526,y=0.504,source="quest_giver",zoneID=5805},questType="standard"},
[30474] = {id=30474,name="A Gift For Ella",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="That poor Ella . She's so shy! I saw her standing in the Halfhill Market, looking really hungry, but afraid to talk to any of the chefs. We should bring her some food! And not any boring food - something special. The Kunzen hozen make spicy shrimp dumplings from ingredients they've stolen from our farms. I don't like spicy food, but Ella might!",objectivesText="Obtain Spicy Shrimp Dumplings . Progress: Oh, umm... hi.",starts={{npcID=64464,x=0.526,y=0.504,zoneID=5805}},ends={{npcID=58647,x=0.53,y=0.516,zoneID=5805}},coords={x=0.526,y=0.504,source="quest_giver",zoneID=5805},questType="standard"},
[30475] = {id=30475,name="A Gift For Fung",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Farmer Fung is pretty mean, and just a little scary. Mah always said that he was one of the best farmers in the valley, though. I think I know the perfect gift for a mean, kind of scary guy like him. There's some big plainshawks that circle the hills to the west of here. You should get one, find a big piece of meat, and then ask Kol Ironpaw to grill it up!",objectivesText="Obtain a Bloody Plainshawk Leg from a Monstrous Plainshawk, and then bring it to Kol Ironpaw in the Halfhill Market. Progress: Harrumph!",starts={{npcID=64464,x=0.526,y=0.504,zoneID=5805}},ends={{npcID=57298,x=0.482,y=0.338,zoneID=5805}},coords={x=0.526,y=0.504,source="quest_giver",zoneID=5805},questType="standard"},
[30476] = {id=30476,name="A Gift For Old Hillpaw",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Old Hillpaw has about a million chickens on his farm... but that's not what he REALLY loves. I saw. He collects blue feathers. I don't realy know where to get a blue feather around here, but I do know where to find some blue pearls! Check the oysters in Cattail Lake to the northwest. I'm sure a blue pearl will look nice with his feather collection!",objectivesText="Find a Blue Freshwater Pearl . Progress: <name>! You startled me.",starts={{npcID=64464,x=0.526,y=0.504,zoneID=5805}},ends={{npcID=58707,x=0.53,y=0.518,zoneID=5805}},coords={x=0.526,y=0.504,source="quest_giver",zoneID=5805},questType="standard"},
[30477] = {id=30477,name="A Gift For Haohan",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Haohan Mudclaw is the big boss of the Tillers union and the richest guy in the Valley! He's been nice to let me stay here, so I want to do something nice for him. He likes expensive stuff, like ruby shards, but I don't have a lot of money, so I need to get him something else. I know! I've seen a great big fish in Cattail Lake! We should get one of its teeth as a gift!",objectivesText="Obtain an Enormous Cattail Grouper Tooth . Progress: Need something, <class>?",starts={{npcID=64464,x=0.526,y=0.504,zoneID=5805}},ends={{npcID=57402,x=0.446,y=0.34,zoneID=5805}},coords={x=0.526,y=0.504,source="quest_giver",zoneID=5805},questType="standard"},
[30478] = {id=30478,name="A Gift For Jogu",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Sometimes I feel sad for Jogu. He's the only jinyu around, and I don't think he has any friends. Other than his smelly bottle, of course. You know what? I've got an idea. Farmer Yoon has a basket of craneberries inside his house, and a few apples as well. I'm sure you could bring them to the stillmaster in the Halfhill Market and get him to brew something special for Jogu.",objectivesText="Obtain 8 of Yoon's Apples and 50 of Yoon's Craneberries , then bring them to Bobo Ironpaw to brew into Apple-Berry Hooch . Progress: Hmm?",starts={{npcID=64464,x=0.526,y=0.504,zoneID=5805}},ends={{npcID=58710,x=0.534,y=0.524,zoneID=5805}},coords={x=0.526,y=0.504,source="quest_giver",zoneID=5805},questType="standard"},
[30479] = {id=30479,name="A Gift For Gina",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Have you seen Gina Mudclaw , the market girl? She has it all - looks, brains, and nice big tummy. Could you deliver a gift for me? I wanted to pick some orchids that grow on top of the big hills to the west, but I can't climb that high. Could you pick a few and bring them to Gina? Oh, and when you see her... tell her I said \"hi\".",objectivesText="Obtain a Goldenfire Orchid . Progress: Hey there!",starts={{npcID=64464,x=0.526,y=0.504,zoneID=5805}},ends={{npcID=58706,x=0.532,y=0.516,zoneID=5805}},coords={x=0.526,y=0.504,source="quest_giver",zoneID=5805},questType="standard"},
[30480] = {id=30480,name="The Ritual",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="From the moment I first rose from the river, I knew I was destined to be Waterspeaker. I was taught many rituals, and have performed all of them, save one. There was one, an extremely ancient one, that we were told to call upon if our people ever turned against us. This must have happened in our people's distant past, because we haven't needed to use it in our village's memory. I suppose now is the time to do so.",objectivesText="Speak with Waterspeaker Gorai , and then complete the Ritual. Progress: That... was not what I expected.",starts={{npcID=60973,x=0.75,y=0.88,zoneID=5841}},ends={{npcID=60973,x=0.75,y=0.88,zoneID=5841}},coords={x=0.75,y=0.88,source="quest_giver",zoneID=5841},questType="standard"},
[30481] = {id=30481,name="Carved in Stone",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="You see the shiny stones in the walls? Rook wants some. The mogu been collecting them, so they have some to take too maybe. If you find stones, you please bring them to Rook? Rook will be your friend.",objectivesText="Collect 12 Guo-Lai Runestones . Progress: You find stones for Rook? Please?",starts={{npcID=59333}},questType="standard"},
[30482] = {id=30482,name="The Soul-Gatherer",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="A single large mogu performing a ritual on the lake caught your attention while you were killing the other mogu in the area. It seems unwise to let his ritual complete.",objectivesText="Kill Shadowmaster Sydow and recover the beads from his corpse. Progress: <He looks at you expectantly.>",starts={{npcID=58470}},questType="standard"},
[30483] = {id=30483,name="NOT USED",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5840,mapID=1530,questType="standard"},
[30484] = {id=30484,name="Gauging Our Progress",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,mapID=371,description="The time for war is at hand, ! We've been training these natives non-stop since you left, and I believe they're as good as they're going to get. See for yourself. Check in with the others and return with your findings. We must rely on our enemy being somehow... even less prepared.",objectivesText="Check in with Shademaster Kiryn, Rivett Clutchpop, Shokia, and Riko. Progress: How is our combat training coming along?",starts={{npcID=57108,x=0.28,y=0.47,zoneID=5785}},ends={{npcID=57108,x=0.28,y=0.47,zoneID=5785}},coords={x=0.28,y=0.47,source="quest_giver",zoneID=5785},questType="standard"},
[30485] = {id=30485,name="Last Piece of the Puzzle",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,mapID=371,description="These hozen are behaving most unnaturally, . Marching in formation? In armor? This troubles me. We must discuss it at another time, however. I have come to ask for your assistance. The ancient fresco, where last we spoke, is nearly unveiled. I am certain that it holds ancient wisdom - knowledge that the emperor wanted us to remember. My meditations alone may not be enough to discern its meaning. Please, take this heirloom to the shrine of my ancestors. I shall require their assistance.",objectivesText="Use Cho's Heirloom at Cho's Family Shrine on Serpent's Overlook. Speak with Mishi for transportation.",starts={{npcID=59377,x=0.282,y=0.468,zoneID=5785}},ends={{npcID=59411,x=0.446,y=0.67,zoneID=5785}},coords={x=0.282,y=0.468,source="quest_giver",zoneID=5785},questType="standard"},
[30487] = {id=30487,name="Comin' Round the Mountain",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="The mountain pass is very dangerous. You need much luck to survive. Nephew Bentnail will show you the way. Perhaps today is a lucky day to travel though. Wind blows from the east; this is good sign. Grummles always travel best when east wind blows. Climb in the cart when you are ready to leave.",objectivesText="Escort the cart and guides safely up Neverest Mountain.",starts={{npcID=59696,x=0.572,y=0.612,zoneID=5841}},ends={{npcID=60175,x=0.48,y=0.49,zoneID=5841}},coords={x=0.572,y=0.612,source="quest_giver",zoneID=5841},questType="standard"},
[30488] = {id=30488,name="The Missing Muskpaw",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="What the heck are you supposed to be? |5 ? Never heard of one of them. You here to help or to steal my yaks? Look, if yer' insistin' on helpin' out, go find my boy. He got himself grabbed by a bunch of sprites and probably doesn't even know we lost the ranch. They dragged him off to Pranksters' Hollow south east of here. Go rescue him an' I'll see about giving you a reward of some sort.",objectivesText="Find Muskpaw Jr. in Pranksters' Hollow.",starts={{x=0.716,y=0.702,mapID=379,npcID=59353}},ends={{x=0.716,y=0.702,mapID=379,npcID=59353}},coords={mapID=379,x=0.716,y=0.702},questType="standard"},
[30489] = {id=30489,name="Fresh Needle Scent",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="Say, if you really are here to help, I could use me some needles off them sprites in Pranksters' Hollow. The grummles don't believe in luck they can't smell. They'll pay better for yaks that have that fresh needle scent.",objectivesText="Gather 100 Pungent Sprite Needles . Progress: Mmm. Nothing like the fresh scent of needle.",starts={{npcID=59353,x=0.71,y=0.692,zoneID=5841}},ends={{npcID=59353,x=0.71,y=0.692,zoneID=5841}},coords={x=0.71,y=0.692,source="quest_giver",zoneID=5841},questType="standard"},
[30490] = {id=30490,name="Yakity Yak",level=20,requiredLevel=20,faction="none",expansion=4,zoneID=5841,mapID=379,description="Yaungols! They come through here taking what they want and destroying whatever's left. I can't have these thugs destroy the last pieces of the Yak Wash here. It's all my boy and I have left. Head over to our old ranch and dish out some pain on them yaungols. I bet if you kill enough of them they'll think twice before attacking anything in this area.",objectivesText="Kill 9 Burilgi Despoilers at the Muskpaw Ranch.",questType="standard"},
[30491] = {id=30491,name="At the Yak Wash",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Look, my father is crazy. I love him, but he's crazy. These yaungol managed to completely obliterate our ranch and scattered our yaks every which way. If I know my father though, he's going to try to go head to head with the yaungol to get the yaks back. Can you help us round up some of the yaks so my father doesn't do anything stupid? Just ride them over to the Yak Wash so we can clean them up and sell them to the grummles.",objectivesText="Bring 6 Escaped Yaks to the Wash Entrance at Lao & Son's Yak Wash. Progress: The grummles always insist they have better luck with cleaned yaks. As long as they pay more I'm not going to argue. We need the gold. Now more than ever.",starts={{x=0.653,y=0.623,mapID=381,npcID=61693}},ends={{x=0.653,y=0.623,mapID=381,npcID=61693}},coords={mapID=381,x=0.653,y=0.623},questType="standard"},
[30492] = {id=30492,name="Back in Yak",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="I wasn't lying about your reward. Here, take these washed yaks to the grummle caravan master Eightcoins. You can find him at the Grummle Bazaar west of here. He'll credit us and give you a delivery fee. He may be short, but he is our biggest customer. Return to me if you lose the yaks. More often than not they just come right back here anyway. Once they've been cleaned that is.",objectivesText="Bring the Washed Yaks to Lucky Eightcoins at the Grummle Bazaar in Kun-Lai Summit . Return to Muskpaw Jr. if you lose your yaks.",starts={{npcID=59354,x=0.714,y=0.692,zoneID=5841}},ends={{npcID=59371,x=0.646,y=0.616,zoneID=5841}},coords={x=0.714,y=0.692,source="quest_giver",zoneID=5841},questType="standard"},
[30495] = {id=30495,name="Love's Labor",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="Can I trouble you for another favor? We're way behind schedule, and this jade shipment is the last we need to finish the great statue. I've got my hands full, so could you run this ore over to the other foremen? Historian Dinh , Surveyor Sawa , and Kitemaster Shoku can all be found around the base of the statue. Taskmaster Emi is directing production at the top of the statue. We're on a deadline, so make sure you do it fast! Time's a wasting!",objectivesText="Deliver the jade to Historian Dinh , Surveyor Sawa , Kitemaster Shoku , and Taskmaster Emi . Progress: Did you deliver the jade in time?",starts={{npcID=59391,x=0.482,y=0.612,zoneID=5785}},ends={{npcID=59391,x=0.482,y=0.612,zoneID=5785}},coords={x=0.482,y=0.612,source="quest_giver",zoneID=5785},questType="standard"},
[30496] = {id=30496,name="The Waterspeaker's Staff",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="There is great dissent in Inkgill, . Elder Shai Hu drank the sha-corrupted waters of the mere, and forced the others to do the same. When I protested, Orachi of the town guard confiscated my ritual staff and banished me. Now, I am not only an exile, I am unable to speak with the waters that once gave me guidance! I am not a fighter. But if you are, perhaps you can recover my staff from Orachi? He is in town to our north.",objectivesText="Recover Waterspeaker Gorai 's Stolen Inkgill Ritual Staff from Orachi in Inkgill Mere. Progress: Have you found the staff?",starts={{npcID=60973,x=0.75,y=0.88,zoneID=5841}},ends={{npcID=60973,x=0.75,y=0.88,zoneID=5841}},coords={x=0.75,y=0.88,source="quest_giver",zoneID=5841},questType="standard"},
[30498] = {id=30498,name="Get Back Here!",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,mapID=371,description="Oh, before I forget, I have something I was asked to deliver to you. A letter from one of your companions, I assume. I was made to understand that your presence was urgently required, so I took the liberty of arranging your passage. Speak to Ginsa Arroweye just south of here when you're ready. She has a kite waiting.",objectivesText="Report to Admiral Taylor in Pearlfin Village. Provided item:",starts={{npcID=57242,x=0.558,y=0.57,zoneID=5785}},ends={{npcID=55122,x=0.58,y=0.806,zoneID=5785}},coords={x=0.558,y=0.57,source="quest_giver",zoneID=5785},questType="standard"},
[30499] = {id=30499,name="Get Back Here!",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="Oh, before I forget, I have something I was asked to deliver to you. A letter from one of your companions, I assume. I was made to understand that your presence was urgently required, so I took the liberty of arranging your passage. Speak to Ginsa Arroweye just south of here when you're ready. She has a kite waiting.",objectivesText="Return to General Nazgrim at Grookin Hill. Provided item:",starts={{npcID=57242,x=0.558,y=0.57,zoneID=5785}},ends={{npcID=57108,x=0.28,y=0.47,zoneID=5785}},coords={x=0.558,y=0.57,source="quest_giver",zoneID=5785},questType="standard"},
[30500] = {id=30500,name="Residual Fallout",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="Pandaria is a mystical land, traveler. It bears repeating that some of its secrets remain hidden, even to Lorewalkers. Sealing those fissures did not mend what has been broken. If the legends are true, it will take much more to release this land from the grasp of the Sha. The aggression of that battle awakened a host of living negative emotions. What you see here is likely the first of many such manifestations. For now, we can only try to diminish their presence here.",objectivesText="Destroy 10 Sha Echoes Progress: This, it seems, is only the tip of the iceberg, <name>.",starts={{npcID=59418,x=0.492,y=0.614,zoneID=5785}},ends={{npcID=59418,x=0.492,y=0.614,zoneID=5785}},coords={x=0.492,y=0.614,source="quest_giver",zoneID=5785},questType="standard"},
[30502] = {id=30502,name="Jaded Heart",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="The more powerful remnants of that horrible manifestation may be too much for you to handle on your own, . I fear I'd be of little help in terms of actual combat, but I can suggest a solution. The great jade statue was soon to become a living serpent - one of our revered celestials. Its construction imbued it with special powers that may sufficiently weaken these adversaries.",objectivesText="Use Celestial Jade Chunks to defeat 6 Sha Remnants . Progress: Do you have the jade, <name>?",starts={{npcID=59418,x=0.492,y=0.614,zoneID=5785}},ends={{npcID=59418,x=0.492,y=0.614,zoneID=5785}},coords={x=0.492,y=0.614,source="quest_giver",zoneID=5785},questType="standard"},
[30504] = {id=30504,name="Emergency Response",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,mapID=371,description="Your companions have made themselves at home in our land, and brought with them a dangerous conflict. The full extent of their destruction here we cannot yet know. Already it is... unspeakable. Nevertheless, to forsake your friends out of spite would be against our way. Any that yet live are doubtlessly wounded and in desperate need of care. These fireworks were to celebrate the statue's completion. Use them near your companions to signal Mishi, and she will bear them off to safety.",objectivesText="Use Cho's Fireworks near General Nazgrim , Shademaster Kiryn , Shokia , and Rivett Clutchpop .",starts={{npcID=59418,x=0.492,y=0.614,zoneID=5785}},ends={{npcID=59418,x=0.492,y=0.614,zoneID=5785}},coords={x=0.492,y=0.614,source="quest_giver",zoneID=5785},questType="standard"},
[30506] = {id=30506,name="Admiral Taylor has Awakened",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="It would seem that your Admiral Taylor has awakened from his injuries. He and his people are upstairs in the apothecary's house back in Binan Village. He has requested your presence.",objectivesText="Speak with Admiral Taylor at Binan Village in Kun-Lai Summit .",starts={{npcID=59076,x=0.708,y=0.904,zoneID=5841}},ends={{npcID=59441,x=0.716,y=0.93,zoneID=5841}},coords={x=0.708,y=0.904,source="quest_giver",zoneID=5841},questType="standard"},
[30507] = {id=30507,name="Admiral Taylor has Awakened",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="It would seem that your Admiral Taylor has awakened from his injuries. He and his people are upstairs in the apothecary's house across the way. He has requested your presence.",objectivesText="Speak with Admiral Taylor at Binan Village in Kun-Lai Summit .",starts={{npcID=59073,x=0.722,y=0.918,zoneID=5841}},ends={{npcID=59441,x=0.716,y=0.93,zoneID=5841}},coords={x=0.722,y=0.918,source="quest_giver",zoneID=5841},questType="standard"},
[30508] = {id=30508,name="Admiral Taylor has Awakened",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="It would seem that your Admiral Taylor has awakened from his injuries. He and his people are upstairs. He has requested your presence.",objectivesText="Speak with Admiral Taylor at Binan Village in Kun-Lai Summit .",starts={{npcID=59077,x=0.716,y=0.928,zoneID=5841}},ends={{npcID=59441,x=0.716,y=0.93,zoneID=5841}},coords={x=0.716,y=0.928,source="quest_giver",zoneID=5841},questType="standard"},
[30509] = {id=30509,name="General Nazgrim has Awakened",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,description="It would seem that your General Nazgrim has awakened from his injuries. He and his people are upstairs in the apothecary's house back in Binan Village. He has requested your presence.",objectivesText="Speak with General Nazgrim at Binan Village in Kun-Lai Summit .",starts={{npcID=59076,x=0.708,y=0.904,zoneID=5841}},ends={{npcID=59442,x=0.716,y=0.932,zoneID=5841}},coords={x=0.708,y=0.904,source="quest_giver",zoneID=5841},questType="standard"},
[30510] = {id=30510,name="General Nazgrim has Awakened",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,description="It would seem that your General Nazgrim has awakened from his injuries. He and his people are upstairs in the apothecary's house across the way. He has requested your presence.",objectivesText="Speak with General Nazgrim at Binan Village in Kun-Lai Summit .",starts={{npcID=59073,x=0.722,y=0.918,zoneID=5841}},ends={{npcID=59442,x=0.716,y=0.932,zoneID=5841}},coords={x=0.722,y=0.918,source="quest_giver",zoneID=5841},questType="standard"},
[30511] = {id=30511,name="General Nazgrim has Awakened",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,description="It would seem that your General Nazgrim has awakened from his injuries. He and his people are upstairs. He has requested your presence.",objectivesText="Speak with General Nazgrim at Binan Village in Kun-Lai Summit .",starts={{npcID=59077,x=0.716,y=0.928,zoneID=5841}},ends={{npcID=59442,x=0.716,y=0.932,zoneID=5841}},coords={x=0.716,y=0.928,source="quest_giver",zoneID=5841},questType="standard"},
[30512] = {id=30512,name="Westwind Rest",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="Admiral Taylor winces in pain.> Jade Forest was a disaster. Anduin's gone. We lost some good people. We didn't stop the Horde from advancing into the continent. But I think I've found a way to get the locals on our side. You just helped fight off some of these \"yaungol\", no? I hear yaungol sacked Westwind Rest, a local village. We've been told that two groups of survivors have camped out along the road west out of town. We help them out, maybe they'll consider siding with the Allliance.",objectivesText="Speak with Farmhand Bo and Elder Tsulan in the Yaungol Advance. Progress: I will not rest until our people are returned and this village rebuilt.",starts={{npcID=59441,x=0.716,y=0.93,zoneID=5841}},ends={{npcID=63542,x=0.546,y=0.842,zoneID=5841}},coords={x=0.716,y=0.93,source="quest_giver",zoneID=5841},questType="standard"},
[30513] = {id=30513,name="Eastwind Rest",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,description="I am injured, but we can't stop here. The hozen were... unreliable. The pandaren would be much better allies. You have seen the refugees in this village, and heard of the yaungol invasion, no? Well, we've heard from the locals that Eastwind Rest, a nearby village, was destroyed by the Yaungol. Apparently some survivors have gathered along the road out of town. Go. Take the road west. Gather the survivors. We'll help them rebuild. Then, they will see the advantage of joining the Horde!",objectivesText="Speak with Farmhand Ko and Elder Shiao in Kun Lai Summit. Progress: I will not rest until our people are returned and this village rebuilt.",starts={{npcID=59442,x=0.716,y=0.932,zoneID=5841}},ends={{npcID=63535,x=0.624,y=0.796,zoneID=5841}},coords={x=0.716,y=0.932,source="quest_giver",zoneID=5841},questType="standard"},
[30514] = {id=30514,name="Challenge Accepted",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="The yaungol have always been a difficult, proud people, but never this violent or aggressive. I do not know what has prompted this change in their behavior, but we don't have time to find out, now. We fear for our lives and livelihoods as long as Ur-Bataar , leader of the Bataari yaungol, lives. Go, set the banner in his camp ablaze to challenge him, and then defeat him in battle. Only then will we be secure.",starts={{npcID=63542,x=0.546,y=0.842,mapID=379}},ends={{npcID=63542,x=0.546,y=0.842,mapID=379}},coords={x=0.546,y=0.842,source="quest_giver",mapID=379},questType="standard"},
[30515] = {id=30515,name="Challenge Accepted",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,description="The yaungol have always been a difficult, proud people, but never this violent or aggressive. I do not know what has prompted this change in their behavior, but we don't have time to find out, now. We fear for our lives and livelihoods as long as Ur-Bataar , leader of the Bataari yaungol, lives. Go, set the banner in his camp ablaze to challenge him, and then defeat him in battle. Only then will we be secure.",starts={{npcID=63535,x=0.624,y=0.796,mapID=379}},ends={{npcID=63535,x=0.624,y=0.796,mapID=379}},coords={x=0.624,y=0.796,source="quest_giver",mapID=379},questType="standard"},
[30516] = {id=30516,name="Growing the Farm I: A Little Problem",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="So you need to whack some wily weeds? No problem, neighbor! Only thing is, I'm running low on weed killer. I make my own concoction - very potent, totally organic and good for the earth. Plants love it! Well... except for those pesky weeds. They hate the stuff! If you bring me some Spideroot from the terraces just west of us, I'll make a fresh batch and go down to Yoon's farm myself. I would gather some myself but... well... I hate spiders. You'll see what I mean.",starts={{npcID=57385,x=0.386,y=0.516,mapID=376}},ends={{npcID=57385,x=0.386,y=0.516,mapID=376}},coords={x=0.386,y=0.516,source="quest_giver",mapID=376},questType="standard"},
[30517] = {id=30517,name="Farmer Fung's Vote I: Yak Attack",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="The next voting member on the Tiller's council is Farmer Fung , and it's easy to see why. That man's vegetables are the biggest in the valley! I only hope that someday I can grow pumpkins as big as his. If we hope to join the Tillers, he would be the next person to convince.",objectivesText="Speak to Farmer Fung at The Heartland or the Halfhill Market in the Valley of the Four Winds .",starts={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},ends={{npcID=57298,x=0.482,y=0.338,zoneID=5805}},coords={x=0.522,y=0.488,source="quest_giver",zoneID=5805},questType="standard"},
[30518] = {id=30518,name="Farmer Fung's Vote II: On the Loose",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="You want my vote for Farmer Yoon? Ha! You're joking, right? Listen, I'm not going to vote for some citypaw with no lick a' knowledge about farming the earth. It would be an embarrassment to farm alongside you or that Yoon shmuck. Now let me deal with my own problems. Some devil let my prize yaks loose, and now they're running wild northwest of Halfhill. If I could just get my yaks back, then maybe I'd be able to sleep at night.",objectivesText="Return 5 Escaped Shagskins to Farmer Fung 's yak pen at the very north end of the Verdant Belt. Progress: What do you want?",starts={{npcID=57298,x=0.482,y=0.338,zoneID=5805}},ends={{npcID=57298,x=0.482,y=0.338,zoneID=5805}},coords={x=0.482,y=0.338,source="quest_giver",zoneID=5805},questType="standard"},
[30519] = {id=30519,name="Nana's Vote I: Nana's Secret Recipe",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="The next vote we'll need is from Nana Mudclaw . She's Haohan's grandmother, and she's been a Tiller longer than you and I have been alive! She's still working at the Tillers building in Halfhill. Why don't you pay her a visit?",objectivesText="Speak to Nana Mudclaw at Halfhill in the Valley of the Four Winds .",starts={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},ends={{npcID=64597,x=0.546,y=0.47,zoneID=5805}},coords={x=0.522,y=0.488,source="quest_giver",zoneID=5805},questType="standard"},
[30521] = {id=30521,name="Haohan's Vote I: Bungalow Break-In",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="This is going to be tough, . The last vote we need comes from Haohan Mudclaw , the head of the Tillers Union. I know he wasn't too keen on us to start, but we've learned so much about farming, I'm sure he'll have a change of heart! Go speak to him. You can be very convincing, right?",objectivesText="Speak to Haohan Mudclaw at The Heartland or at Halfhill Market in the Valley of the Four Winds .",starts={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},ends={{npcID=57402,x=0.446,y=0.34,zoneID=5805}},coords={x=0.522,y=0.488,source="quest_giver",zoneID=5805},questType="standard"},
[30522] = {id=30522,name="Haohan's Vote II: The Real Culprits",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="What are YOU doing here, citypaw? Look, I've got my hands full with a break-in at my shed to the west. Some rascals came in the middle of the night and ransacked the place. I've got missing seeds, broken tools, and eaten inventory to deal with. I'll just add it to my list of other troubles: a whole wagon of melons stolen, a broken water pump, animals ruining my harvest... I wish that I could just get to the bottom of all this already!",starts={{npcID=57402,x=0.446,y=0.34,mapID=376}},ends={{npcID=58646,x=0.522,y=0.488,mapID=376}},coords={x=0.446,y=0.34,source="quest_giver",mapID=376},questType="standard"},
[30523] = {id=30523,name="Growing the Farm II: The Broken Wagon",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Hey . I've been looking at that wagon every day, day in and day out, since the day I moved in. Quite an eyesore, don't you think? I heard in town that Fish Fellreed is quite handy with tools. She might be able to fix it up, and then we could turn that patch of land into a plot for farming. Why don't you talk to her and see if she'd be willing to do the job?",objectivesText="Speak to Fish Fellreed at Cattail Lake or the Halfhill Market in the Valley of the Four Winds .",starts={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},ends={{npcID=58705,x=0.528,y=0.518,zoneID=5805}},coords={x=0.522,y=0.488,source="quest_giver",zoneID=5805},questType="standard"},
[30524] = {id=30524,name="Growing the Farm II: Knock on Wood",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Sure! I know just the wagon that you're talkin' about! I can fix it right up, but I'll need wood. There's a whole lot of it down at the bottom of the lake. If you fish it right out - haha, get it? Fish? Oh I just crack myself up sometimes. Anyway, you bring me here some 'o that wood and then I'll get right to work!",objectivesText="Collect 100 Waxed Planks . Progress: That lake is plum full o' treasures! You just gotta know what to look for.",starts={{npcID=58705,x=0.528,y=0.518,zoneID=5805}},ends={{npcID=58705,x=0.528,y=0.518,zoneID=5805}},coords={x=0.528,y=0.518,source="quest_giver",zoneID=5805},questType="standard"},
[30525] = {id=30525,name="Haohan's Vote III: Pure Poison",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="All right, . This is our big chance! Mr. Mudclaw's farm is in big trouble. Those mountain hozen are coming down at night, wrecking his crops and eating his hard-earned harvest. We've got to get rid of them for good, and I know just how to do it. Back in the day, my grandpa showed me how to mix a wounding poison to deal with the pests on the farm. The virmen warrens to the north hold the key ingredients for my mixture. Don't look so worried, ! I'm pretty sure this is going to work.",objectivesText="Collect 1 Bloodbloom , 1 Cave Lily , 1 Ghostcap , and 1 Violet Lichen . Progress: The hozen are going to get a big surprise!",starts={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},ends={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},coords={x=0.522,y=0.488,source="quest_giver",zoneID=5805},questType="standard"},
[30526] = {id=30526,name="Lost and Lonely",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="The starving, mangy dog whines piteously and attempts a brief wag of its tail. It looks like it could use a good meal right about now.",objectivesText="Collect 20 Tasty T-Bone from the Skyrange Mushan on the Skyrange in the Valley of the Four Winds . Progress: A light comes into the dog's eyes. It seems to recognize you.",starts={{npcID=59533,x=0.424,y=0.5,zoneID=5805}},ends={{npcID=59533,x=0.424,y=0.5,zoneID=5805}},coords={x=0.424,y=0.5,source="quest_giver",zoneID=5805},questType="standard"},
[30527] = {id=30527,name="Haohan's Vote IV: Melons For Felons",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="All right, now I happen to know that those mountain hozen love a delicious, sweet melon. Mr. Haohan's last harvest of melons got stolen, so we're going to have to grow some of our own. Once we have our harvest, we'll use them to lure the nasty hozen's leader out of its cave!",starts={{npcID=58646,x=0.522,y=0.488,mapID=376}},ends={{npcID=58646,x=0.522,y=0.488,mapID=376}},coords={x=0.522,y=0.488,source="quest_giver",mapID=376},questType="standard"},
[30528] = {id=30528,name="Haohan's Vote V: Chief Yip-Yip",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="You ready for the final step of the plan? The leader of the Kunzen hozen is a brute by the name of Chief Yip-Yip . It's said that he is nearly impervious to pain. I've injected the melons with a toxic mixture, so don't try eating them! Once you get his attention, throw these melons onto the ground. Yip-Yip won't be able to resist a sweet striped melon. When he takes a bite, he'll be temporarily weakened, and you should find yourself an opening to attack.",objectivesText="Kill Chief Yip-Yip at Kunzen Cave to the northwest. Progress: Did it work? Is Chief Yip-Yip slain?",starts={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},ends={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},coords={x=0.522,y=0.488,source="quest_giver",zoneID=5805},questType="standard"},
[30529] = {id=30529,name="Growing the Farm III: The Mossy Boulder",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="Now that we're officially members of the Tillers Union, Mr. Mudclaw said he'd be happy to help us upturn this big ole' rock in the middle of our field. Once we clear away that stone, I've got something special planned. Run down and give him a holler to let him know that we're ready.",starts={{npcID=58646,x=0.522,y=0.488,mapID=376}},ends={{npcID=57402,x=0.446,y=0.34,mapID=376}},coords={x=0.522,y=0.488,source="quest_giver",mapID=376},questType="standard"},
[30530] = {id=30530,name="Tracking Event: Started First Expansion",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[30531] = {id=30531,name="Tracking Event: Finished First Expansion",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[30532] = {id=30532,name="Tracking Event: Started Second Expansion",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[30533] = {id=30533,name="Tracking Event: Finished Second Expansion",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[30534] = {id=30534,name="A Second Hand",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Despite your best efforts, the work is starting to pile up around here. Perhaps you could ask one of your best friends if they'd like to help out at Sunsong Ranch.",objectivesText="Speak to one of your best friends and ask them to work on Sunsong Ranch. Progress: It's a sturdy rake.",starts={{npcID=215705,x=0.521,y=0.49,zoneID=5805}},ends={{npcID=215705,x=0.521,y=0.49,zoneID=5805}},coords={x=0.521,y=0.49,source="quest_giver",zoneID=5805},questType="standard"},
[30535] = {id=30535,name="Learn and Grow I: Seeds",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="Well, first things first! I'm going to need lots of help 'round here. If we're going to be partners, you've got to learn how to harvest crops, and if you wanna harvest crops you gotta plant seeds! Now it's my understanding that a mister, uh... Grainfell? No, that wasn't it... Greedfill? That doesn't sound right... Greenfield! That's his name! He's the man to see for seeds. Greenfield's got a stall over at Halfhill Market, directly southeast of here - go see him and pick up some vegetable seeds.",starts={{npcID=58646,x=0.522,y=0.488,mapID=376}},ends={{npcID=58646,x=0.522,y=0.488,mapID=376}},coords={x=0.522,y=0.488,source="quest_giver",mapID=376},questType="standard"},
[30536] = {id=30536,name="FLAG - Weed War Training",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,description="Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you. Now if you'll excuse me, my friends and I trying to decide something. We can talk again afterwards.",objectivesText="Listen to Xiao and his companions.",questType="standard"},
[30564] = {id=30564,name="Tracking Event: Talked to Dog at Farm",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[30565] = {id=30565,name="An Unexpected Advantage",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,mapID=371,description="Things seem to be goin' our way more and more lately, . I was out doin some explorin' when I came upon this little beauty. Problem is she's one of a set and the other one is still in pieces. I'd have gotten it together by now if those pesky Grimleers hadn't ambushed me and taken some of the gears and bolts. Hey, ye seem to be pretty good at handlin' the natives. Ye wouldn't mind goin' and helpin' ol'Sully out would ye?",objectivesText="Retrieve the missing Water-Damaged Gears and Rusty Locking Bolts from the Hozen Ambushers to the East. Progress: Did ye find my missing gears and bolts?",starts={{npcID=59550,x=0.586,y=0.822,zoneID=5785}},ends={{npcID=59550,x=0.586,y=0.822,zoneID=5785}},coords={x=0.586,y=0.822,source="quest_giver",zoneID=5785},questType="standard"},
[30566] = {id=30566,name="FLAG - Pest Problems Training",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,description="Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you. Now if you'll excuse me, my friends and I trying to decide something. We can talk again afterwards.",objectivesText="Listen to Xiao and his companions.",questType="standard"},
[30567] = {id=30567,name="Blanche's Boomer Brew",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=6101,description="Can you smell it in the air? A storm is brewing! And so am I! Meet me at the hilltop when the storm hits and together we'll whip up a keg of my most famous brew. Can I count on your help?",objectivesText="Complete the \"Brewing Storm\" Scenario.",starts={{npcID=59569,x=0.388,y=0.312,zoneID=5785}},ends={{npcID=59569,x=0.388,y=0.312,zoneID=5785}},coords={x=0.388,y=0.312,source="quest_giver",zoneID=5785},questType="dungeon"},
[30568] = {id=30568,name="Helping the Cause",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=6771,mapID=371,description="Welcome back, ! It seems the Jinyu have taken to our training even better than I had hoped. We're in the final stages of our preparations now. I need someone to go check in with Amber, Bold Karasshi , and Mishka . See if they need any help to complete their training. You'll find Karasshi and Mishka here in Pearlfin Village. Amber is training recruits in Slingtail Pits to the northwest.",objectivesText="Check in with Bold Karasshi, Amber Kearnen, and Mishka. Progress: Is everyone in order and ready to move?",starts={{npcID=55122,x=0.58,y=0.806,zoneID=5785}},ends={{npcID=55122,x=0.58,y=0.806,zoneID=5785}},coords={x=0.58,y=0.806,source="quest_giver",zoneID=5785},questType="standard"},
[30569] = {id=30569,name="Trouble on the Farmstead",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="I... I escaped from Farmer Chow 's, to the southeast of here. It's been taken over by yaungol, but the old man and his wife just won't give it up! Please, go there and help him out. Maybe if you do, he'll be willing to send some folks back here and help you guys farm up some food for the new town?",objectivesText="Speak with Farmer Chow at the Chow Farmstead in Kun-Lai Summit .",starts={{npcID=63754,x=0.538,y=0.84,zoneID=5841}},ends={{npcID=59573,x=0.602,y=0.858,zoneID=5841}},coords={x=0.538,y=0.84,source="quest_giver",zoneID=5841},questType="standard"},
[30570] = {id=30570,name="Trouble on the Farmstead",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,description="I... I escaped from Farmer Chow 's, to the southeast of here. It's been taken over by yaungol, but the old man and his wife just won't give it up! Please, go there and help him... Maybe if you do, he'll be willing to send some folks back here and help you guys farm up some food for the new town?",objectivesText="Speak with Farmer Chow at the Chow Farmstead in Kun-Lai Summit .",starts={{npcID=63751,x=0.636,y=0.866,zoneID=5841}},ends={{npcID=59573,x=0.602,y=0.858,zoneID=5841}},coords={x=0.636,y=0.866,source="quest_giver",zoneID=5841},questType="standard"},
[30571] = {id=30571,name="Farmhand Freedom",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Those Ordo yaungol are working my farmhands to death! It just ain't right. Please, , save them before it's too late.",starts={{npcID=59573,x=0.602,y=0.858,mapID=379}},ends={{npcID=59573,x=0.602,y=0.858,mapID=379}},coords={x=0.602,y=0.858,source="quest_giver",mapID=379},questType="standard"},
[30573] = {id=30573,name="Tracking Event: Started Third Expansion",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[30574] = {id=30574,name="Tracking Event: Finished Third Expansion",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[30575] = {id=30575,name="Round 'Em Up",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="Mobility is going to be key to maintaining our foothold in this new land. Problem is, there's no way to maintain mobility without mounts, and... well, we don't have many of those here, now do we? The local yaks seem to make good mounts. At least, the local pandaren say they do. Why don't you go round some up for us?",starts={{npcID=59441,x=0.716,y=0.93,mapID=379}},ends={{npcID=59441,x=0.716,y=0.93,mapID=379}},coords={x=0.716,y=0.93,source="quest_giver",mapID=379},questType="standard"},
[30581] = {id=30581,name="... and the Pot, Too!",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Sure, I'm willing to help you guys out. But we need to eat, too! I don't even have a pot to cook in! Let alone ingredients to put in it! Here's a list of the things that I need. Now get!",objectivesText="Collect 12 Root Vegetables and 1 Cast Iron Pot . Progress: Do you have everything from the list?!",starts={{npcID=59636,x=0.602,y=0.858,zoneID=5841}},ends={{npcID=59636,x=0.602,y=0.858,zoneID=5841}},coords={x=0.602,y=0.858,source="quest_giver",zoneID=5841},questType="standard"},
[30582] = {id=30582,name="The Late Mrs. Muskpaw",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="This well worn trinket has several markings on it confessing love and adoration from the late Mrs. Muskpaw. Perhaps Lao would like his wife's trinket back.",objectivesText="Bring the Muskpaw Keepsake to Lao Muskpaw . Progress: Oh, and what have you there.",starts={{x=0.703,y=0.719,mapID=379}},ends={{npcID=59353,x=0.71,y=0.692,zoneID=5841}},coords={mapID=379,x=0.703,y=0.719},questType="standard"},
[30583] = {id=30583,name="Blue Dwarf Needs Food Badly",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=6141,mapID=379,description="Oi! We need ta' get us some food, if we're gonna survive here for long! Ye' may not know it, but I'm somethin' of a cook me'self. Why don'tcha go out there and fetch us some meaty bits. I can cook 'em up and feed us for weeks! Or, days, at least.",objectivesText="Collect 160 Kun-Lai Meaty Bits . Progress: Well... ya' got my meat?",starts={{npcID=59450,x=0.54,y=0.832,zoneID=5841}},ends={{npcID=59450,x=0.54,y=0.832,zoneID=5841}},coords={x=0.54,y=0.832,source="quest_giver",zoneID=5841},questType="standard"},
[30584] = {id=30584,name="Shocking!",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Have you ever had a fresh dojani eel ? No? Well you have not lived then! Head north up to the dojani river and fish up a few for us. Be careful, those eels can zap you if you're not careful!",objectivesText="Fish up 7 Dojani Eels from the Dojani River in Krasarang Wilds. Progress: Were you able to catch the eels?",starts={{npcID=59584,x=0.678,y=0.452,zoneID=6134}},ends={{npcID=59584,x=0.678,y=0.452,zoneID=6134}},coords={x=0.678,y=0.452,source="quest_giver",zoneID=6134},questType="standard"},
[30585] = {id=30585,name="What Lurks Below",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Legend tells of a great beast in the forest to the north. My son is missing and I fear he may have wandered too near its lair.... Head northwest to Krasari Falls and look for a mysterious whirlpool - this is the key to revealing what is hidden there. Kill the wretched beast and recover any clues to my son's whereabouts.",objectivesText="Find an Ancient Fishing Pool at Krasari Falls to the northwest and fish in it to lure the beast out of hiding. Progress: What news of my son?",starts={{npcID=60673,x=0.682,y=0.422,zoneID=6134}},ends={{npcID=60673,x=0.682,y=0.422,zoneID=6134}},coords={x=0.682,y=0.422,source="quest_giver",zoneID=6134},questType="standard"},
[30586] = {id=30586,name="Jagged Abalone",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Pandaren have been harvesting jagged abalone in this area for generations. Now it's time for you to learn the ritual. The abalone can be found just northeast of here in narsong trench. Be careful, we have noticed increased shark activity in that area recently.",objectivesText="Harvest 9 Jagged Abalone Meat from the Jagged Abalone in Narsong Trench to the northeast. Progress: Did you see any sharks down there?",starts={{npcID=59584,x=0.678,y=0.452,zoneID=6134}},ends={{npcID=59584,x=0.678,y=0.452,zoneID=6134}},coords={x=0.678,y=0.452,source="quest_giver",zoneID=6134},questType="standard"},
[30587] = {id=30587,name="Yakity Yak",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="For now, the yaungol invaders seem content to steal yaks. Surveying the area, however, you notice they could easily move on the Yak Wash at any moment. Thinning their numbers may help show the yaungol that this area is protected.",objectivesText="Kill 9 Burilgi Despoilers at the Muskpaw Ranch. Progress: Them yak stealing, ranch smashing, bad breath yaungols gotta learn a thing or two about attacking decent folk.",starts={{x=0.7,y=0.718,mapID=379}},ends={{npcID=59353,x=0.71,y=0.692,zoneID=5841}},coords={mapID=379,x=0.7,y=0.718},questType="standard"},
[30588] = {id=30588,name="Fishing for a Bruising",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="The riverblade saurok clan is attacking one of our local fishing expeditions! They need help right away! Thin those saurok out and help that expedition return safely!",starts={{npcID=59586,x=0.676,y=0.436,mapID=418}},ends={{npcID=59586,x=0.676,y=0.436,mapID=418}},coords={x=0.676,y=0.436,source="quest_giver",mapID=418},questType="standard"},
[30589] = {id=30589,name="Wrecking the Wreck",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,mapID=378,description="To dislodge the alliance ship, we need to find our engineer. He parted ways with us when we were escaping the wreckage. You should be able to find him somewhere in the western forest. Tell him Korga sent you and he'll get in line to help.",objectivesText="Speak to Makael Bay in the Pei-Wu Forest.",starts={{npcID=60042,x=0.502,y=0.766,zoneID=5736}},ends={{npcID=60055,x=0.364,y=0.724,zoneID=5736}},coords={x=0.502,y=0.766,source="quest_giver",zoneID=5736},questType="standard"},
[30590] = {id=30590,name="Handle With Care",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,mapID=378,description="We can help you get your ship free, but we'll need more of the explosives we were trying to take back from the Alliance to make it happen. I ordered the men to grab all the explosives they could before making our escape. If you sift through the wreckage and bodies to our south, there should be some explosive bundles among them, those that didn't already blow up anyway. Get me enough of them and I think I can put something together for ya.",objectivesText="Recover 6 Packed Explosive Charges. Progress: You're in one piece. That's a good sign. Did you get your hands on what I asked for?",starts={{npcID=60055,x=0.364,y=0.724,zoneID=5736}},ends={{npcID=60055,x=0.364,y=0.724,zoneID=5736}},coords={x=0.364,y=0.724,source="quest_giver",zoneID=5736},questType="standard"},
[30591] = {id=30591,name="Preying on the Predators",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=7902,mapID=378,description="The forest has become far more dangerous ever since Shen-zin Su began shaking. The tigers are agitated and have begun attacking the refugees, and on occasion, me as well. If these injured and weak survivors are to make it to safety here at the hut, we need to help clear the forest for them.",objectivesText="Kill 9 Pei-Wu Tigers .",starts={{npcID=55943,x=0.5,y=0.764,zoneID=5736}},ends={{npcID=55943,x=0.5,y=0.764,zoneID=5736}},coords={x=0.5,y=0.764,source="quest_giver",zoneID=5736},questType="standard"},
[30592] = {id=30592,name="The Burlap Trail: To Burlap Waystation",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Bad fortune for grummles today. Hozen have begun to ravage! They attack our supply line to the Serpent's Spine. Can you help? We are not fighters. We are grummles. Good fortune to those who help grummles. Go with a group of grummles to the Burlap Waystation. Keep them safe. Make sure at least one grummle survives. Grummles shall reward. Grummles always reward.",objectivesText="Protect a group of grummles travelling to the Burlap Waystation. At least one grummle must survive. If you lose your grummles, you can search the Burlap Trail or return to One Keg and wait for the next group to leave. Progress: Good fortune to friends of grummles.",starts={{npcID=59701,x=0.58,y=0.614,zoneID=5841}},ends={{npcID=59703,x=0.516,y=0.678,zoneID=5841}},coords={x=0.58,y=0.614,source="quest_giver",zoneID=5841},questType="standard"},
[30593] = {id=30593,name="Deanimate the Reanimated",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="The admiral's asked me to take care of a major problem, but my specialty's in healing, not fighting! The pandaren in the camp here have told me that something is animating the statues to the northeast at Mogujia. Will you help me out, ? We can't afford to have a fight with an army of statues right now.",objectivesText="Destroy any 14 Terracotta Warriors or Terracotta Guardians.",starts={{npcID=59451,x=0.536,y=0.832,zoneID=5841}},ends={{npcID=59451,x=0.536,y=0.832,zoneID=5841}},coords={x=0.536,y=0.832,source="quest_giver",zoneID=5841},questType="standard"},
[30594] = {id=30594,name="Deanimate the Reanimated",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,description="I've got much to do here, . I could use your help. There's a place to the northwest. The pandaren here call it Mogujia. Something's causing the statues there to animate, and our pandaren friends here are pretty spooked about it. If they're not dealt with soon, we might have a serious problem. We just moved in. It's not like we can afford to fight a war with an army of statues right now.",objectivesText="Destroy any 14 Terracotta Warriors or Terracotta Guardians.",starts={{npcID=59449,x=0.626,y=0.806,zoneID=5841}},ends={{npcID=59449,x=0.626,y=0.806,zoneID=5841}},coords={x=0.626,y=0.806,source="quest_giver",zoneID=5841},questType="standard"},
[30595] = {id=30595,name="Profiting off of the Past",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=6134,mapID=418,description="Let me guess, you're here to deal with the mogu statues that are being reanimated. What a coincidence, I'm here to, um... conduct research on the mogu. I tell you what, if you bring me as many of the mogu relics in there that you can carry, I'll give you a cut. Of the research... funding.",starts={{npcID=59821,x=0.596,y=0.782,mapID=379}},ends={{npcID=59821,x=0.596,y=0.782,mapID=379}},coords={x=0.596,y=0.782,source="quest_giver",mapID=418},questType="standard"},
[30596] = {id=30596,name="A Zandalari Troll?",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="While you've been destroying the reanimated mogu statues, the unmistakable accent of a Zandalari troll has been taunting you. It's clear that the threat to Westerly Rest will not end until he's been dealt with.",objectivesText="Kill the Zandalari Soulraiser.",questType="standard"},
[30597] = {id=30597,name="Strange Spherical Stone",level=30,requiredLevel=30,faction="none",expansion=4,zoneID=6757,mapID=554,description="This beautiful stone clearly has magical potential... at least to one trained in alchemy. You are certain that with the right herbs native to Pandaria, this stone could become very useful.",objectivesText="Infuse the stone with several Golden Lotus .",questType="standard"},
[30598] = {id=30598,name="Who Knew Fish Liked Eggs?",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Great cranes have been nesting in this area for generations. The Narsong Spires provide a sheltered area to rear their young. Their pristine eggs are revered as bait for catching the silver goby . Retrieve a crane egg and see if you can catch a goby!",objectivesText="Collect a Pristine Egg from the Narsong Spires and use it to catch a Silver Goby . Progress: Did you catch a silver goby ?",starts={{npcID=60673,x=0.682,y=0.422,zoneID=6134}},ends={{npcID=60673,x=0.682,y=0.422,zoneID=6134}},coords={x=0.682,y=0.422,source="quest_giver",zoneID=6134},questType="standard"},
[30599] = {id=30599,name="A Monkey Idol",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Before, grummles keep hozen from ravaging by bribing with food. But now the Broketooth hozen south of here have their big magic idols. The Ook of Dook has trained them to use their idols to get power from sacrifices. They are using them to kill grummles! You must destroy these idols! For every idol, there is a chief. Kill the chief and throw corpse on their altar.",objectivesText="Use the Corpses of Tak Tak , Dak Dak , and Ko Ko on their respective altars. Progress: Hozen are learning that it is most bad fortune to get sacrificed on one's own altar.",starts={{x=0.519,y=0.672,mapID=379,npcID=59452}},ends={{x=0.519,y=0.672,mapID=379,npcID=59452}},coords={mapID=379,x=0.519,y=0.672},questType="standard"},
[30600] = {id=30600,name="No Pack Left Behind",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="The Broketooth hozen south of here killed all of my grummles. What is worse, their packages are undelivered. Fortune frowns on a grummlepack undelivered. Please, give my grummles peace on the great trail of beyond and bring their grummlepacks to me. I will see they are delivered.",objectivesText="Recover 8 Grummlepacks from Camp Broketooth or The Deeper. Progress: Grummles are a simple people. We are made to explore and deliver.",starts={{npcID=59452,x=0.52,y=0.672,zoneID=5841}},ends={{npcID=59452,x=0.52,y=0.672,zoneID=5841}},coords={x=0.52,y=0.672,source="quest_giver",zoneID=5841},questType="standard"},
[30601] = {id=30601,name="Instant Courage",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="It is very bad fortune to travel mountain paths without a good guide. We grummles make the best guides, but many have run away. They fear the mountain pass now. Many good grummles disappear up there. Grummles are good at many things, but are not very brave. Maybe with fire lotus incense you can make them brave. Then they will show you the way.",objectivesText="Inspire 3 Hiding Guides in Howlingwind Cavern to help you.",starts={{x=0.572,y=0.611,mapID=379,npcID=59696}},ends={{x=0.572,y=0.611,mapID=379,npcID=59696}},coords={mapID=379,x=0.572,y=0.611},questType="standard"},
[30602] = {id=30602,name="The Rabbitsfoot",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="The Broketooth hozen stole our Rabbitsfoot! He was the grummle with the biggest luckydo. This is very bad fortune indeed. Please, , we need our Rabbitsfoot back. We need his good fortune back. Can you search the Broketooth Outpost for him?",objectivesText="Rescue Brother Rabbitsfoot from the Broketooth Outpost.",starts={{npcID=59703,x=0.516,y=0.678,zoneID=5841}},ends={{npcID=59452,x=0.52,y=0.672,zoneID=5841}},coords={x=0.516,y=0.678,source="quest_giver",zoneID=5841},questType="standard"},
[30603] = {id=30603,name="The Broketooth Ravage",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="They took my luckydo! Their leader hozen here, Mo Mo, stole my rabbitsfoot. This is most bad fortune for grummles. My rabbitsfoot is a big luckydo for grummles everywhere. If hozen learn how to get luck from my rabbitsfoot then all is lost. Please can you get it back?",objectivesText="Retrieve Rabbitsfoot's Luckydo from Mo Mo. Progress: Grummles named for the luckydo that gives the most fortune to specific grummle. It is most important that hozen not steal a grummle's luck.",starts={{npcID=59806,x=0.49,y=0.704,zoneID=5841}},ends={{npcID=59452,x=0.52,y=0.672,zoneID=5841}},coords={x=0.49,y=0.704,source="quest_giver",zoneID=5841},questType="standard"},
[30604] = {id=30604,name="Breaking Broketooth",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="Hozen only ravage when they think their supplies are too few for their number of mouths. Problem is, hozen always have more mouths than food. We have very few grummles these days. It is a hard thing to ask, but can you be a friend to grummles, and destroy some of the Broketooth hozen south of here? It is the only way to prevent them from destroying the landscape.",objectivesText="Kill 8 Broketooth Chargers and 6 Broketooth Tossers .",starts={{npcID=59452,x=0.52,y=0.672,zoneID=5841}},ends={{npcID=59452,x=0.52,y=0.672,zoneID=5841}},coords={x=0.52,y=0.672,source="quest_giver",zoneID=5841},questType="standard"},
[30605] = {id=30605,name="Lucky Yakshoe",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="While you were gone, I saw a group of grummles coming down the Burlap Trail. It was led by my Brother Yakshoe . But then the Knucklethumps attacked. They took my brother and his grummles north. Please, $p! Save my brother. He always has bad fortune and no luck, but he is my brother. Look for him at the alter in front of Fort Silverback.",objectivesText="Rescue Brother Yakshoe .",starts={{npcID=59452,x=0.52,y=0.672,zoneID=5841}},ends={{npcID=59894,x=0.52,y=0.672,zoneID=5841}},coords={x=0.52,y=0.672,source="quest_giver",zoneID=5841},questType="standard"},
[30606] = {id=30606,name="Thumping Knucklethump",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="The Knucklethump hozen have new chief, the Ook of Dook. He sees fear in the west, anger in the south, hatred in the north, and yaungols in the east. And so he sets his hozen to ravage, gathering food and supplies for coming famine. They are many Knucklethumps and dangerous. Please, Luckydo, can you defeat their fighters?",objectivesText="Slay 8 Knucklethump Smashers or Jibstabbers at Knucklethump Hole. Progress: It is sad so many hozen must die.",starts={{npcID=59894,x=0.52,y=0.672,zoneID=5841}},ends={{npcID=59452,x=0.52,y=0.672,zoneID=5841}},coords={x=0.52,y=0.672,source="quest_giver",zoneID=5841},questType="standard"},
[30607] = {id=30607,name="Hozen Love Their Keys",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="The hozen have a yeti! They call it Old Poot Poot and keep it at the back of their cave. Hozen are normally scared of yeti, but now they feed it grummles. They have a Hunter Chief, Cho Cho the Wicked. Can you see if he has a key on him to the yeti shackles? Bad fortune for hozen if a yeti is loose in their fort.",objectivesText="Get the Yeti Shackle Key from Cho Cho the Wicked and release Old Poot Poot . Progress: A luckydo would be wise to never travel near a yeti on a dirty yak.",starts={{x=0.505,y=0.64,mapID=379,npcID=59894}},ends={{x=0.505,y=0.64,mapID=379,npcID=59894}},coords={mapID=379,x=0.505,y=0.64},questType="standard"},
[30608] = {id=30608,name="The Snackrifice",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="They took my grummles! Hozen don't eat grummles, but yeti do. And the Knucklethumps have a yeti. Please rescue my grummles. Cut them down or let them out of cages. Rescue them any way you can. Many fortunes and rewards if you do this.",objectivesText="Rescue 5 Imprisoned Grummles by cutting them down or releasing them from cages.",starts={{x=0.505,y=0.64,mapID=379,npcID=59894}},ends={{x=0.505,y=0.64,mapID=379,npcID=59894}},coords={mapID=379,x=0.505,y=0.64},questType="standard"},
[30610] = {id=30610,name="Grummle! Grummle! Grummle!",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Now that grummles are rescued, we need to rescue our supplies. The Ook of Dook is only chief because he has supplies. Go to the Dooker Dome area north west of here. Take some grummles with you. Keep them safe and get them near supply crates. Grummles know what to do from there. Rabbitsfoot and I will meet you there.",objectivesText="Lead 5 Packless Grummles to Supply Crates near the Dooker Dome. Progress: Grummles are good at carrying things.",starts={{npcID=59894,x=0.52,y=0.672,zoneID=5841}},ends={{npcID=59894,x=0.52,y=0.672,zoneID=5841}},coords={x=0.52,y=0.672,source="quest_giver",zoneID=5841},questType="standard"},
[30611] = {id=30611,name="Unleash The Yeti!",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Your yeti ride gave me an idea. The Ook of Dook has a pet yeti he named Chomp Chomp. He uses this yeti to scare other hozen in to making him the leader hozen. We need to get rid of that yeti. Go to Dooker Dome northwest of here and defeat some of the Cagemasters so Chomp Chomp is not tied up as much. Yakshoe and I will meet you there with lots of incense and a dirty yak.",objectivesText="Kill 4 Cagemasters . Progress: We found a yak. Did you take out some hozen?",starts={{npcID=59452,x=0.52,y=0.672,zoneID=5841}},ends={{npcID=59452,x=0.52,y=0.672,zoneID=5841}},coords={x=0.52,y=0.672,source="quest_giver",zoneID=5841},questType="standard"},
[30612] = {id=30612,name="The Leader Hozen",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="The time has come to face the Ook of Dook . We beat him, and the hozen won't have someone telling them to ravage. Here is the plan: Yakshoe will lead Tassle in to arena and scare away Chomp Chomp . Then, you sneak in and fight the Ook of Dook while his hozen are distracted by the yeti rampaging through their home. We'll meet you back at Kota Basecamp with a big reward. Good fortune to you, friend of grummles.",objectivesText="Enrage Chomp Chomp and then defeat the Ook of Dook .",starts={{npcID=59452,x=0.52,y=0.672,zoneID=5841}},ends={{npcID=59452,x=0.52,y=0.672,zoneID=5841}},coords={x=0.52,y=0.672,source="quest_giver",zoneID=5841},questType="standard"},
[30613] = {id=30613,name="Armored Carp",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Armored Carp are a delicacy around these parts. Unfortunately we can't fish them up since they snap our hooks with their powerful jaws. Take this fishing spear and see if you can catch a few for us.",objectivesText="Use the Fishing Spear to catch 5 Armored Carp in the waters south of Anglers Wharf. Progress: Any luck with that fishing spear?",starts={{npcID=60135,x=0.676,y=0.424,zoneID=6134}},ends={{npcID=60135,x=0.676,y=0.424,zoneID=6134}},coords={x=0.676,y=0.424,source="quest_giver",zoneID=6134},questType="standard"},
[30614] = {id=30614,name="Oil Stop",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="When the yaungols came, they began to dig up oil. What is this \"oil\", I wonder? Perhaps it is thing of much undiscovered luck. This I must know. Here, take this vial, and fill it with yaungol oil from one of their windmills. I will give you many fortunes if you bring me some.",objectivesText="Fill the Empty Oil Vial at a Yaungol Oil Derrick. Progress: Yaungols are scary. Yaungols with a luckydo like this \"oil\" are more scary.",starts={{npcID=59402,x=0.654,y=0.608,zoneID=5841}},ends={{npcID=59402,x=0.654,y=0.608,zoneID=5841}},coords={x=0.654,y=0.608,source="quest_giver",zoneID=5841},questType="standard"},
[30615] = {id=30615,name="A Zandalari Troll?",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,description="While you've been destroying the reanimated mogu statues, the unmistakable accent of a Zandalari troll has been taunting you. It's clear that the threat to Westerly Rest will not end until he's been dealt with.",objectivesText="Kill the Zandalari Soulraiser.",questType="standard"},
[30616] = {id=30616,name="Traffic Issues",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="Yaungols are attacking our Burlap Trail. This is most bad fortune for grummles. We use that trail to carry supplies to the Serpent's Spine. Without supplies, the defenders of the wall are in danger. Grummles are packers and explorers, not fighters. Could you be a luckydo for us and stop the yaungol blockade?",objectivesText="Defeat 8 Fire Camp Ruqin Yaungols.",starts={{npcID=59597,x=0.648,y=0.604,zoneID=5841}},ends={{npcID=59597,x=0.648,y=0.604,zoneID=5841}},coords={x=0.648,y=0.604,source="quest_giver",zoneID=5841},questType="standard"},
[30617] = {id=30617,name="Roadside Assistance",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="A luckydo remembers to bring incense on a journey in to the mountains. The smellier the luck the better. Can you journey up the road to One Keg and light the incense you find along the way? This will give good fortune to grummles that must travel the road. Brother Lintpocket can give you many rewards. Speak to him when you arrive.",objectivesText="Light 8 Lucky Burlap Incense sticks along the road to One Keg.",starts={{npcID=59597,x=0.648,y=0.604,zoneID=5841}},ends={{npcID=59701,x=0.58,y=0.614,zoneID=5841}},coords={x=0.648,y=0.604,source="quest_giver",zoneID=5841},questType="standard"},
[30618] = {id=30618,name="Resupplying One Keg",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="If you're looking for the best supplies in Kun-Lai you've come to the right place! Oh sure, it looks a bit empty. Don't let appearances deceive you.. Oh, who am I kidding?! Between the hozen attacks, and the sprites pillaging what few supplies we do get, my stock has dwindled to a dangerous level. If you could help me recover some of my supplies I should have enough to contribute to your journey.",objectivesText="Recover 8 Stolen Supplies from Howlingwind Cavern. Progress: Did you manage to get some of my supplies back?",starts={{npcID=59695,x=0.576,y=0.616,zoneID=5841}},ends={{npcID=59695,x=0.576,y=0.616,zoneID=5841}},coords={x=0.576,y=0.616,source="quest_giver",zoneID=5841},questType="standard"},
[30619] = {id=30619,name="Mogu?! Oh No-gu!",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="I know your friends are worried about the animating statues over at Mogujia, but I'll tell you what you should really be worried about. Where there are animated statues, there are mogu. I don't know if you've seen one before, but if you haven't... Well, let's just say mogu are bad, bad, news. While you're dealing with whatever else you're doing, you need to get the mogu behind the trouble!",objectivesText="Kill the Mogujia Soul-Caller . Progress: Did you find him? Is he dead? No? Oh, man. Don't make me worried!",starts={{npcID=63542,x=0.546,y=0.842,zoneID=5841}},ends={{npcID=63542,x=0.546,y=0.842,zoneID=5841}},coords={x=0.546,y=0.842,source="quest_giver",zoneID=5841},questType="standard"},
[30620] = {id=30620,name="Mogu?! Oh No-gu!",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,description="I know your friends are worried about the animating statues over at Mogujia, but I'll tell you what you should really be worried about. Where there are animated statues, there are Mogu. I don't know if you've seen one before, but if you haven't... Well, let's just say Mogu are bad, bad, news. While you're dealing with whatever else you're doing, you need to get the Mogu behind the trouble!",objectivesText="Kill the Mogujia Soul-Caller .",starts={{npcID=63535,x=0.624,y=0.796,zoneID=5841}},ends={{npcID=63535,x=0.624,y=0.796,zoneID=5841}},coords={x=0.624,y=0.796,source="quest_giver",zoneID=5841},questType="standard"},
[30621] = {id=30621,name="They Stole My Luck!",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="My journeys through Kun-Lai have taught me two things. First, never sneak up on a sleeping yak. Second, having luck on your side is both necessary and hard to come by. The grummles believe in carrying a lucky trinket at all times. In my mind, if one trinket can sometimes bring luck, then many trinkets would guarantee it! After arriving in One Keg my lucky trinkets were stolen by those little menace sprites. I'd be truly grateful if you could retrieve them for me.",objectivesText="Return Ji-Lu the Lucky 's Lucky Virmen's Foot , Yak Shoe, Four Winds Clover, and Gold Coin. Progress: Were you able to find my lucky trinkets? One can never have too much good luck.",starts={{npcID=59716,x=0.574,y=0.602,zoneID=5841}},ends={{npcID=59716,x=0.574,y=0.602,zoneID=5841}},coords={x=0.574,y=0.602,source="quest_giver",zoneID=5841},questType="standard"},
[30622] = {id=30622,name="The Swarm Begins",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="Without the wall to protect us, we barely stand a chance. If you hadn't gathered so many people to help us, we wouldn't have a prayer. Check in with Captain Oakenshield - he should be up near the break in the wall. Kill as many mantid as you can on the way there. If we win, we win. If we lose, we go down fighting. For Pandaria!",objectivesText="Slay 15 Ik'thik Warriors or Ik'thik Infestors . Progress: Look at the SIZE of that thing...",starts={{npcID=56720,x=0.194,y=0.568,zoneID=5805}},ends={{npcID=57198,x=0.116,y=0.494,zoneID=5805}},coords={x=0.194,y=0.568,source="quest_giver",zoneID=5805},questType="standard"},
[30623] = {id=30623,name="The Mantidote",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="You see those huge mantid commanders out there? They have a strange aura about them. It reminds me of the sadness we saw at Zhu's Watch. Perhaps... they're under the influence of the sha, too? I kept Ken-Ken's mask - the one he used to remove the sha from Yi-Mo. I believe that, if we use it on the mantid, we can convince them to turn back.",objectivesText="Use Ken-Ken's Mask on 5 Ik'thik Wing Commanders, then defeat the Manifestations of Fear that come out.",starts={{npcID=59855,x=0.18,y=0.564,zoneID=5805}},ends={{x=0.18,y=0.565,mapID=376,npcID=59855}},coords={x=0.18,y=0.564,source="quest_giver",zoneID=5805},questType="standard"},
[30624] = {id=30624,name="It Does You No Good In The Keg",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=5805,mapID=376,description="I been thinkin'. We got all this beer that Chen brewed, and we got all these people that you've gathered. We should bring the two together. There's a bunch o' folks out there in the fields, riskin' their lives for Pandaria. You an' I should at least bring 'em a keg or two. They might raise their mugs in victory. They might enjoy one last drink before gettin' skivvered by a mantid. Either way, I wouldn't want 'em to fight without a good brew in their belly.",objectivesText="Bring beer to Zhu's Wardens, the Crane Wing Priests, the Shado-Pan, and the night elf settlers.",starts={{npcID=56474,x=0.686,y=0.432,zoneID=5805}},ends={{x=0.181,y=0.557,mapID=376,npcID=56474}},coords={x=0.686,y=0.432,source="quest_giver",zoneID=5805},questType="standard"},
[30625] = {id=30625,name="Students No More",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="Those five students - the ones who were looking for the Hidden Master - they went up to the front lines, alone. I'd send Shado-Pan to aid them, but I haven't got any left. There's dangerous creatures up there near the wall. If you find those students, make sure that they haven't fallen to any of them.",objectivesText="Find the martial arts students, then help them defeat an Ik'thik Bloodrager , Egg-Matron, Tendon-Slicer, and Fearmonger.",starts={{npcID=57198,x=0.116,y=0.494,zoneID=5805}},ends={{npcID=57198,x=0.116,y=0.494,zoneID=5805}},coords={x=0.116,y=0.494,source="quest_giver",zoneID=5805},questType="standard"},
[30626] = {id=30626,name="Retreat!",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="I'm going to withdraw what few forces I have. We may have to fall back to the Stormstout Brewery, or even Halfhill. That call is Commander Loon Mai 's to make. You go ahead. Deliver word to the Commander. My Shado-Pan will be shortly behind.",objectivesText="Report to Loon Mai at Stoneplow in the Valley of the Four Winds .",starts={{npcID=57198,x=0.116,y=0.494,zoneID=5805}},ends={{npcID=56720,x=0.194,y=0.568,zoneID=5805}},coords={x=0.116,y=0.494,source="quest_giver",zoneID=5805},questType="standard"},
[30627] = {id=30627,name="The Savior of Stoneplow",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6138,mapID=376,description="That commander speaks hastily. He has the weapon he needs to win this battle. He has YOU. \"But it's too hard,\" you might say. You would be wrong. It is not too hard. NOTHING IS TOO HARD. Go now, . Go, and save Stoneplow!",objectivesText="Speak with Miss Fanny at Stoneplow. Then, with her help, defeat the Mantid Colossus. Progress: All is lost, <name>. Pack up your things. We're headed to Halfhill.",starts={{npcID=59856,x=0.18,y=0.558,zoneID=5805}},ends={{npcID=56720,x=0.194,y=0.568,zoneID=5805}},coords={x=0.18,y=0.558,source="quest_giver",zoneID=5805},questType="standard"},
[30628] = {id=30628,name="The Gratitude of Stoneplow",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="One last thing, . Don't worry, it's not another favor. You've killed enough mantid today. We recently received a shipment of high-quality armor from Kun-Lai Summit. I was planning to keep them for my men... but I can't think of anybody more deserving than you. You'll find them on the second floor of the inn, here in town.",objectivesText="Find the Commander's Cache and collect your reward.",starts={{npcID=56720,x=0.194,y=0.568,zoneID=5805}},ends={{npcID=211316,x=0.198,y=0.559,zoneID=5805}},coords={x=0.194,y=0.568,source="quest_giver",zoneID=5805},questType="standard"},
[30629] = {id=30629,name="FLAG - Player Began Finale",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,description="Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you. Now if you'll excuse me, my friends and I trying to decide something. We can talk again afterwards.",objectivesText="Listen to Xiao and his companions.",questType="standard"},
[30631] = {id=30631,name="The Shrine of Seven Stars",level=87,requiredLevel=87,faction="alliance",expansion=4,zoneID=5840,description="Look at this creature, traveler. Only moments after we arrived, this mogu assassin attacked with no warning. His blade was intended for the leader of the Golden Lotus. It is very lucky indeed that we were here to stop the attack. Seeing this attempt on Zhi's life, I fear for the safety of those who have already entered the valley. The caretakers are settling your people into the city to the southeast. Go and speak to the leaders. Make sure they are safe.",objectivesText="Speak to Jaluu the Generous , Kuru the Light-Hearted , Lucky Lin, and Matron Vi Vinh in the Vale of Eternal Blossoms . Progress: The cities are springing back to life.",starts={{x=0.566,y=0.436,mapID=390,npcID=58468}},ends={{x=0.566,y=0.436,mapID=390,npcID=58468}},coords={mapID=390,x=0.566,y=0.436},questType="standard"},
[30633] = {id=30633,name="Out with the Scouts",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="We'd been briefed on mogu sightings in the Vale, but the situation is worse than we had anticipated. Scouts are swarming all over the ruins to the northwest, gathering intel and stealing treasures. Your objective is clear - dispatch of any scouts you see. An army cannot move if we take out its eyes.",objectivesText="Kill 8 Shao-Tien Precursor . Progress: Are the scouts taken care of?",starts={{x=0.566,y=0.436,mapID=390,npcID=58465}},ends={{x=0.566,y=0.436,mapID=390,npcID=58465}},coords={mapID=390,x=0.566,y=0.436},questType="standard"},
[30634] = {id=30634,name="Barring Entry",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="Lao Softfoot and I scouted up the ruins to the north. It looks like the mogu are infiltrating the valley through a cave just up the hill, and already they are sending formidable reinforcements through. There are too many enemies to take them head on, so you'll have to meet Lao Softfoot at the entrance to the ruins. He'll help you sneak in under the cover of stealth. Then, plant this keg of explosives at the mouth of the cave. The rest should take care of itself.",objectivesText="Speak to Lao Softfoot at the entrance to Ruins Rise and follow him up the trail. Then, plant the Explosive Keg at the Ruins Rise Cave Entrance. Progress: Is the cave closed?",starts={{x=0.566,y=0.436,mapID=390,npcID=58471}},ends={{x=0.566,y=0.436,mapID=390,npcID=58471}},coords={mapID=390,x=0.566,y=0.436},questType="standard"},
[30636] = {id=30636,name="Stones of Power",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="Many thousands of years ago, the rulers of the Vale sought energy from a powerful crystal known as Revelite. With this substance, they were able to power cities, factories, and engines of war. Zhi the Harmonious has asked us to collect some crystals and bring them back to the city. Keep an eye out for them while you are in the ruins.",objectivesText="Collect 7 Revelite Crystals . Progress: Did you find the crystals?",starts={{x=0.566,y=0.436,mapID=390,npcID=58465}},ends={{x=0.566,y=0.436,mapID=390,npcID=58465}},coords={mapID=390,x=0.566,y=0.436},questType="standard"},
[30637] = {id=30637,name="The Guo-Lai Halls",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="As you pass by the great door, you hear sounds from deep inside. Anji mentioned that advance mogu scouts had been sighted in this area. Perhaps they made their way down to the depths below. Your senses tingling, you decide to investigate.",objectivesText="Investigate the mogu presence in the Guo-Lai Halls. Progress: What did you find in the Halls?",starts={{x=0.566,y=0.436,mapID=390,npcID=58465}},ends={{x=0.566,y=0.436,mapID=390,npcID=58465}},coords={mapID=390,x=0.566,y=0.436},questType="standard"},
[30639] = {id=30639,name="The Secrets of Guo-Lai",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="I just received information from a guard stationed near the Ruins of Guo-Lai that the Shado-Tien leader entered the halls, killing two of my men in the process. They're intent on something inside. We need to stop them. He Softfoot has already followed them in. He should be waiting for you at the entrance to the western chambers. Move quickly, <name>. I don't like the thought that the mogu may be a step ahead of us.",objectivesText="Meet with He Softfoot in the Guo-Lai Halls and uncover the mogu's purpose in the western chamber. Progress: What are you waiting for? Find He. Stop the Shao-Tien!",starts={{x=0.566,y=0.436,mapID=390,npcID=58408}},ends={{x=0.566,y=0.436,mapID=390,npcID=58408}},coords={mapID=390,x=0.566,y=0.436},questType="standard"},
[30640] = {id=30640,name="Battle Spear of the Thunder King",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="I have received some troubling news, <name>. The mogu are plotting to steal three artifacts of power from the Vale. We must retrieve the artifacts immediately and hide them for safekeeping. The first artifact is the Battle Spear of the Thunder King . Upon emperor Lei Shen's death, the spear was placed in an ancient shrine to the northwest. Bring the spear back to me.",objectivesText="Retrieve the Battle Spear of the Thunder King . Progress: It was said that the most powerful of ancient mogu could call the powers of the elements. The Thunder King himself could channel the forces of lightning onto his spear.",starts={{x=0.5725,y=0.43,mapID=390,npcID=59905}},ends={{x=0.5725,y=0.43,mapID=390,npcID=59905}},coords={mapID=390,x=0.5725,y=0.43},questType="standard"},
[30641] = {id=30641,name="Battle Helm of the Thunder King",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="The second artifact of power is the Battle Helm of the Thunder King . Emperor Lei Shen wore the helm into every battle. It became so well-known that his enemies would flee at the mere sight of it. When the Emperor died, they placed the helm in the very bottom of the Guo-Lai Halls to the west, surrounded by thousands of terracotta soldiers. Thus, they could look upon their leader and follow him into death.",objectivesText="Retrieve the Battle Helm of the Thunder King . Progress: History claims that Lei Shen feared no enemy except for one. And in the end, it was death that finally defeated him.",starts={{x=0.5725,y=0.43,mapID=390,npcID=59905}},ends={{x=0.5725,y=0.43,mapID=390,npcID=59905}},coords={mapID=390,x=0.5725,y=0.43},questType="standard"},
[30642] = {id=30642,name="Battle Axe of the Thunder King",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="The final artifact is the Thunder King's axe. Lei Shen charged into battle with his spear in one hand, and his axe in the other. It is said that he could throw his axe with brutal accuracy, and when it hit its target, it made a sound like crashing thunder. After his death, the axe was placed in a ceremonial chamber to the southwest. Needless to say, we must not let it fall into the mogu's hands.",objectivesText="Retrieve the Battle Axe of the Thunder King . Progress: Did you find the axe?",starts={{x=0.5725,y=0.43,mapID=390,npcID=59905}},ends={{x=0.5725,y=0.43,mapID=390,npcID=59905}},coords={mapID=390,x=0.5725,y=0.43},questType="standard"},
[30643] = {id=30643,name="The Mogu's Message",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="The battle against the mogu rages fiercely with neither side giving quarter. We cannot hold our position forever. Something must be done to strike a blow at the mogu, a blow from which they cannot recover. Go check in with Zhi the Harmonious at The Silent Sanctuary. I wish to hear his thoughts on this matter.",objectivesText="Speak to Zhi the Harmonious at The Silent Sanctuary in the Vale of Eternal Blossoms .",starts={{x=0.566,y=0.436,mapID=390,npcID=58408}},ends={{x=0.566,y=0.436,mapID=390,npcID=58408}},coords={mapID=390,x=0.566,y=0.436},questType="standard"},
[30644] = {id=30644,name="What Comes to Pass",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="You had better report back to the Golden Pagoda immediately.",objectivesText="Speak to Sun Tenderheart at the Golden Pagoda in the Vale of Eternal Blossoms .",starts={{x=0.4479,y=0.7634,mapID=390,npcID=59905}},ends={{x=0.4479,y=0.7634,mapID=390,npcID=59905}},coords={mapID=390,x=0.4479,y=0.7634},questType="standard"},
[30645] = {id=30645,name="The Might of Three",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="This is it, <name>. This is the end. If we don't drive the mogu from the valley, they will seize the remnants of their ancient power and use it to break Pandaria to their will. But our forces are few, and tired, and small. We bleed, while their warriors are made of stone. <name>, although all odds are against us, still I must ask you to go and help our forces slay the mogu invaders. I have prayed to the Celestials, begging their aid. I can only hope that they answer our call.",objectivesText="Slay 100 mogu invaders at the Summer Fields in the Vale of Eternal Blossoms .",starts={{x=0.5644,y=0.4326,mapID=390,npcID=58468}},ends={{x=0.5644,y=0.4326,mapID=390,npcID=58468}},coords={mapID=390,x=0.5644,y=0.4326},questType="standard"},
[30646] = {id=30646,name="The Final Power",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="I never thought it would come to this! Leven went to face Warlord Zhao-Jin the Bloodletter at the top of the palace steps, but our reinforcements cannot get through! We are the only ones who stand between him and the Vale's greatest... and most deadly... powers. Please, <name>, you must find a way to stop him!",objectivesText="Kill Warlord Zhao-Jin the Bloodletter .",starts={{x=0.742,y=0.418,mapID=390,npcID=59906}},ends={{x=0.742,y=0.418,mapID=390,npcID=59906}},coords={mapID=390,x=0.742,y=0.418},questType="standard"},
[30648] = {id=30648,name="Moving On",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="Your journey in this land has already proven most eventful, traveler. And mine, it appears, is destined to continue for a time. A chain of events began when your people arrived here, and while some of those happenings are traumatic to behold, I feel there must be a larger purpose behind your presence. For now it is wisest that you leave this place and explore Pandaria's other regions. Speak to me when you are ready to leave.",objectivesText="Speak to Fei and travel to Valley of the Four Winds.",starts={{npcID=59899,x=0.492,y=0.614,zoneID=5785}},ends={{npcID=54915,x=0.416,y=0.236,zoneID=5785}},coords={x=0.492,y=0.614,source="quest_giver",zoneID=5785},questType="standard"},
[30649] = {id=30649,name="The Shrine of Two Moons",level=87,requiredLevel=87,faction="horde",expansion=4,zoneID=5840,description="Look at this creature, traveler. Only moments after we arrived, this mogu assassin attacked with no warning. His blade was intended for the leader of the Golden Lotus. It is very lucky indeed that we were here to stop the attack. Seeing this attempt on Zhi's life, I fear for the safety of those who have already entered the valley. The caretakers are settling your people into the city to the northeast. Go and speak to the leaders. Make sure they are safe.",objectivesText="Speak to Jaluu the Generous , Mokimo the Strong , Elder Liao , and Madam Vee Luo in the Vale of Eternal Blossoms . Progress: The cities are springing back to life.",starts={{x=0.566,y=0.436,mapID=390,npcID=58468}},ends={{x=0.566,y=0.436,mapID=390,npcID=58468}},coords={mapID=390,x=0.566,y=0.436},questType="standard"},
[30650] = {id=30650,name="Pandaren Prisoners",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="Look, I know the Alliance needs recruits, and there's just not enough of us here right now to make a fighting presence of this town. But I know that the yaungol over at Fire Camp Ordo, to the northwest, have taken many of my people as prisoners. And I also know that if you would be willing to rescue them from their captivity, they'd more than likely be willing to join the Alliance. What do you say, ?",objectivesText="Free 8 Pandaren Prisoners .",starts={{npcID=63542,x=0.546,y=0.842,zoneID=5841}},ends={{npcID=59441,x=0.716,y=0.93,zoneID=5841}},coords={x=0.546,y=0.842,source="quest_giver",zoneID=5841},questType="standard"},
[30651] = {id=30651,name="Barrels of Fun",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="Oh, well now, let's have us some fun, ! Those Ordo yaungol to the northwest have saved us the trouble o' havin' to make some bombs. They already have them there. Let's put their explosive barrels to good use and destroy their oil-pumpin' machines, shall we?",objectivesText="Use Explosive Barrels found in Fire Camp Ordo to destroy the West, South, and East Oil Rigs.",starts={{npcID=59450,x=0.54,y=0.832,zoneID=5841}},ends={{npcID=59450,x=0.54,y=0.832,zoneID=5841}},coords={x=0.54,y=0.832,source="quest_giver",zoneID=5841},questType="standard"},
[30652] = {id=30652,name="In Tents Channeling",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="The yaungol of Fire Camp Ordo are a dire threat. I need you to head northwest and take out their leader. Unfortunately, his four subordinates are maintaining a fire barrier that prevents us from getting to him in the adjoining cave. Take them out and the shield will come down. You'll find them in their tents, channeling.",objectivesText="Kill the Ordo Embercaller, Ordo Pyromancer, Ordo Firespeaker, and Ordo Blazecaster.",starts={{npcID=59441,x=0.716,y=0.93,zoneID=5841}},ends={{x=0.538,y=0.836,mapID=379,npcID=59441}},coords={x=0.716,y=0.93,source="quest_giver",zoneID=5841},questType="standard"},
[30653] = {id=30653,name="It Does You No Good In The Keg",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=5805,mapID=376,description="I been thinkin'. We got all this beer that Chen brewed, and we got all these people that you've gathered. We should bring the two together. There's a bunch o' folks out there in the fields, riskin' their lives for Pandaria. You an' I should at least bring 'em a keg or two. They might raise their mugs in victory. They might enjoy one last drink before gettin' skivvered by a mantid. Either way, I wouldn't want 'em to fight without a good brew in their belly.",objectivesText="Bring beer to Zhu's Wardens, the Crane Wing Priests, the Shado-Pan, and the tauren settlers.",starts={{npcID=56474,x=0.686,y=0.432,zoneID=5805}},ends={{x=0.181,y=0.557,mapID=376,npcID=56474}},coords={x=0.686,y=0.432,source="quest_giver",zoneID=5805},questType="standard"},
[30654] = {id=30654,name="The Guo-Lai Halls",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="The mogu are up to something, I can feel it. They've been sending scouts down into the Guo-Lai Halls. According to the caretakers, the Halls are home to ancient treasures of emperors past. Not only riches, but artifacts of great power. We must prevent the mogu from accessing these treasures! Go down the ramp to the northwest and stop them!",objectivesText="Investigate the mogu presence in the Guo-Lai Halls.",starts={{x=0.566,y=0.436,mapID=390,npcID=58465}},ends={{x=0.566,y=0.436,mapID=390,npcID=58465}},coords={mapID=390,x=0.566,y=0.436},questType="standard"},
[30655] = {id=30655,name="Pandaren Prisoners",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,description="Look, I know the Horde needs recruits, and there's just not enough of us here right now to make a fighting presence of this town. But I know that the yaungol over at Fire Camp Ordo, to the west, have taken many of my people as prisoners. And I also know that if you would be willing to rescue them from their captivity, they'd more than likely be willing to join the Horde. What do you say, ?",objectivesText="Free 8 Pandaren Prisoners .",starts={{npcID=63535,x=0.624,y=0.796,zoneID=5841}},ends={{npcID=59442,x=0.716,y=0.932,zoneID=5841}},coords={x=0.624,y=0.796,source="quest_giver",zoneID=5841},questType="standard"},
[30656] = {id=30656,name="Barrels of Fun",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,description="I love blowing stuff up. It's in my blood! The yaungol to the west at Fire Camp Ordo have a ton of explosive barrels just lying around. I say we put them to good use and destroy their oil-pumpin' machines while having some fun!",starts={{npcID=59448,x=0.628,y=0.798,mapID=379}},ends={{npcID=59448,x=0.628,y=0.798,mapID=379}},coords={x=0.628,y=0.798,source="quest_giver",mapID=379},questType="standard"},
[30657] = {id=30657,name="In Tents Channeling",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,description="The yaungol of Fire Camp Ordo are the worst threat we're facing. I need you to head west and take out their leader. The coward is hiding in a cave, which is protected by a fire shield cast by his four underlings. Take them out and the shield will come down. You'll find them in their tents, channeling.",starts={{npcID=59442,x=0.716,y=0.932,mapID=379}},coords={x=0.716,y=0.932,source="quest_giver",mapID=379},questType="standard"},
[30658] = {id=30658,name="Huff & Puff",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="Have you heard of the prickly puffer fish ? Of course you haven't, you're new around these parts! They can be found in the sarjun depths, due west of here. Take this fishing spear and see if you can bring me back of few of their poison tipped spines.",starts={{npcID=60135,x=0.676,y=0.424,mapID=418}},ends={{npcID=60135,x=0.676,y=0.424,mapID=418}},coords={x=0.676,y=0.424,source="quest_giver",mapID=418},questType="standard"},
[30660] = {id=30660,name="The Ordo Warbringer",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="<The shield is down. Time to head into the cave and slay the Warbringer of the Ordo yaungol!>",objectivesText="Kill Ordo Warbringer .",ends={{npcID=59441,x=0.716,y=0.93,mapID=379}},questType="standard"},
[30661] = {id=30661,name="The Ordo Warbringer",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,description="<The shield is down. Time to head into the cave and slay the Warbringer of the Ordo!>",objectivesText="Kill the Ordo Warbringer . Progress: Wait, what are you doing here, <name>? I'd heard that the Ordo Warbringer isn't dead yet!",ends={{npcID=59442,x=0.716,y=0.932,mapID=379}},questType="standard"},
[30662] = {id=30662,name="The Ordo Warbringer",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="You've taken the shield down at Fire Camp Ordo. Go back there before the shield goes up again. Time to head into the cave and slay their chief!",objectivesText="Kill the Ordo Warbringer .",starts={{npcID=59441,x=0.716,y=0.93,zoneID=5841}},ends={{npcID=59441,x=0.716,y=0.93,zoneID=5841}},coords={x=0.716,y=0.93,source="quest_giver",zoneID=5841},questType="standard"},
[30663] = {id=30663,name="The Ordo Warbringer",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,description="You've taken the shield down at Fire Camp Ordo. Get back over there before they get that shield up again. Slay the Warbringer of the Ordo!",objectivesText="Kill the Ordo Warbringer .",starts={{npcID=59442,x=0.716,y=0.932,zoneID=5841}},ends={{npcID=59442,x=0.716,y=0.932,zoneID=5841}},coords={x=0.716,y=0.932,source="quest_giver",zoneID=5841},questType="standard"},
[30665] = {id=30665,name="The Defense of Shado-Pan Fallback",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5842,mapID=379,description="I sent for reinforcements from the Shado-Pan Monastery, but have heard nothing back. We have already lost the town. A few lucky villagers may have survived, but we are pinned down here. We do not have time to entertain strangers. If you can fight, help my men defend this tower. If not, leave, for you will not survive long here.",objectivesText="Kill 15 Sha-Infested Yaungol .",starts={{npcID=60161,x=0.444,y=0.898,zoneID=5841}},ends={{npcID=60161,x=0.444,y=0.898,zoneID=5841}},coords={x=0.444,y=0.898,source="quest_giver",zoneID=5841},questType="standard"},
[30666] = {id=30666,name="Sudden, Unexpected Crocolisk Aggression",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="Normally, my day consists of catching fish, and then eating the fish I caught, followed by sleeping. Note that I did not include \"fight with a crocolisk\" in that list of activities. You look like a handy . Can you go get rid of some of these crocolisks, so I can get back to my regular routine? The crocolisks normally keep to themselves up at Kea Krak, to the northwest.",starts={{npcID=60173,x=0.516,y=0.768,mapID=418}},ends={{npcID=60173,x=0.516,y=0.768,mapID=418}},coords={x=0.516,y=0.768,source="quest_giver",mapID=418},questType="standard"},
[30667] = {id=30667,name="Particular Plumage",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="When the crocs started attacking, they scared a bunch of the lories out of their nests, up in that island to our northwest. I can use those lories' feathers to make some specialized lures, which will come in handy if and when I get to stop defending my brethren from these reptiles. You up for some feather hunting?",objectivesText="Obtain 6 Emerald Tailfeathers , 6 Crimson Tailfeathers , and 6 Dusky Tailfeathers . Progress: <A bead of sweat twinkles in the fur above Tony's brow.>",starts={{npcID=60182,x=0.516,y=0.754,zoneID=6134}},ends={{npcID=60182,x=0.516,y=0.754,zoneID=6134}},coords={x=0.516,y=0.754,source="quest_giver",zoneID=6134},questType="standard"},
[30668] = {id=30668,name="Build Your Own Raft",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="Hmm. They don't seem to be... calming down. We're going to have to try something different. You'll need a raft. Go grab some wood planks and seaweed, and bring them over to me. I'll put something together for you.",starts={{npcID=60173,x=0.516,y=0.768,mapID=418}},ends={{npcID=60173,x=0.516,y=0.768,mapID=418}},coords={x=0.516,y=0.768,source="quest_giver",mapID=418},questType="standard"},
[30669] = {id=30669,name="The Lorewalker on the Lake",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="Your raft is down in the water below. Take it out to the middle of the lake, where you should find a woman. Her name is Ana Wu. Whenever I have a question that I can't figure out on my own, I'll ask her. She should be able to tell us why these crocolisks won't stop attacking.",starts={{npcID=60173,x=0.516,y=0.768,mapID=418}},ends={{npcID=60139,x=0.46,y=0.788,mapID=418}},coords={x=0.516,y=0.768,source="quest_giver",mapID=418},questType="standard"},
[30670] = {id=30670,name="Turnabout",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Our true enemies are the sha, not the yaungol. The sha are emotion manifest. Destructive, yes. But undisciplined. Undisciplined force cannot last. The flood, in dispersion, loses its force. The wildfire burns its fuel. And, discipline and wisdom can turn their destructive energy against themselves. Bring me the essences of the sha in the village, and I will explain further.",starts={{npcID=60161,x=0.444,y=0.898,mapID=379}},ends={{npcID=60161,x=0.444,y=0.898,mapID=379}},coords={x=0.444,y=0.898,source="quest_giver",mapID=379},questType="standard"},
[30671] = {id=30671,name="Wisdom Has A Price",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="Crocolisks attacking? I know a story about that. And I will share it with you, but first... I grow hungry. Shark meat should do the trick. You should find enough sharks in the water beneath us.",objectivesText="Obtain 5 Shark Fillets . Progress: My hunger is great, <race>. I have been on this lagoon for several days, without food.",starts={{npcID=60139,x=0.46,y=0.788,zoneID=6134}},ends={{npcID=60139,x=0.46,y=0.788,zoneID=6134}},coords={x=0.46,y=0.788,source="quest_giver",zoneID=6134},questType="standard"},
[30672] = {id=30672,name="Balance",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="The story did not end happily. The Narsong crocolisk is no more. This time, however, you may have a chance to change the ending. The hozen to the south are overfishing these waters. With the fish gone, the crocolisks are hungry and desperate - and so they attack Marista. Go now, ! Stop those hozen from their reckless fishing!",objectivesText="Slay 10 Unga Fish-Getters .",starts={{npcID=60139,x=0.46,y=0.788,zoneID=6134}},ends={{npcID=60173,x=0.516,y=0.768,zoneID=6134}},coords={x=0.46,y=0.788,source="quest_giver",zoneID=6134},questType="standard"},
[30673] = {id=30673,name="Holed Up",level=20,requiredLevel=20,faction="none",expansion=4,zoneID=5841,mapID=379,description="Thank the heavenly spirits for you, ! I don't know how much longer I could've lasted. There are other Firebough Nook survivors, I'm sure of it. Will you help rescue them and get us to the safety of Shado-Pan Fallback?",objectivesText="Rescue Jin Warmkeg , Ya Firebough , Old Lady Fung , and Sya Zhong .",questType="standard"},
[30674] = {id=30674,name="Balance Without Violence",level=15,requiredLevel=15,faction="none",expansion=4,zoneID=6134,mapID=418,description="Some of the fish that the Unga hozen have gathered don't seem do be dead yet. There may still be time to throw them back into the water.",objectivesText="Throw 6 Flailing Carp into Nayeli Lagoon.",starts={{x=0.469,y=0.848,mapID=418}},ends={{x=0.469,y=0.848,mapID=418}},coords={mapID=418,x=0.469,y=0.848},questType="standard"},
[30675] = {id=30675,name="Buried Hozen Treasure",level=15,requiredLevel=15,faction="none",expansion=4,zoneID=6134,mapID=418,description="The map you hold is crinkled, dirty, and poorly drawn, but you can see a big X on a beach. Is there buried treasure somewhere on this island?",objectivesText="Find the Buried Hozen Treasure .",starts={{x=0.481,y=0.908,mapID=418}},ends={{x=0.481,y=0.908,mapID=418}},coords={mapID=418,x=0.481,y=0.908},questType="standard"},
[30677] = {id=30677,name="Shuttle Service",level=15,requiredLevel=15,faction="none",expansion=4,zoneID=6134,mapID=418,questType="standard"},
[30678] = {id=30678,name="Like Bombing Fish In A Barrel",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Turns out these rays are not as easy to catch as I thought! You seem like a pretty smart , think you can help me out? I made the bombs but have been having trouble using the raft with my hurt leg. The rays are common in the shallows just west of here. Take the bombs and use my raft to bring me back their stingers ! Oh yeah, watch out for the hammerheads!",objectivesText="Use the Goblin Fishing Bombs to kill 3 Sting Rays and bring back their stingers to Fiznix . The Rays can be found in the shallows west of Anglers Wharf. Progress: Find any sting rays in the shallows?",starts={{npcID=60136,x=0.674,y=0.446,zoneID=6134}},ends={{npcID=60136,x=0.674,y=0.446,zoneID=6134}},coords={x=0.674,y=0.446,source="quest_giver",zoneID=6134},questType="standard"},
[30680] = {id=30680,name="Holed Up",level=20,requiredLevel=20,faction="none",expansion=4,zoneID=5841,mapID=379,description="Oh thank you, thank you, thank you. If you hadn't come along... Wait! There must be other survivors in the Nook like me! Please, , I beg you. Rescue the rest of my citizens and deliver us safely to Shado-Pan Fallback.",objectivesText="Rescue Jin Warmkeg , Ya Firebough , Old Lady Fung , and Sya Zhong .",questType="standard"},
[30681] = {id=30681,name="Holed Up",level=20,requiredLevel=20,faction="none",expansion=4,zoneID=5841,mapID=379,description="Oh, thank you! There's no way I could have made it back on my own. Come to think of it, there must be others around Firebough Nook that need to be rescued. Shall we go collect them and then head to the safety of Shado-Pan Fallback?",objectivesText="Rescue Jin Warmkeg , Ya Firebough , Old Lady Fung , and Sya Zhong .",questType="standard"},
[30682] = {id=30682,name="Holed Up",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="I can't believe you made it here! I don't know how much longer I could have stayed hidden in here. I'm sure that there are others. , we have to rescue them! Then we can go to Shado-Pan Fallback. The master there will know what to do!",objectivesText="Rescue Jin Warmkeg , Ya Firebough , Old Lady Fung , and Sya Zhong . Progress: There are survivors out there? Surely there are more, <name>?",starts={{npcID=60178,x=0.43,y=0.882,zoneID=5841}},ends={{npcID=60161,x=0.444,y=0.898,zoneID=5841}},coords={x=0.43,y=0.882,source="quest_giver",zoneID=5841},questType="standard"},
[30683] = {id=30683,name="One Traveler's Misfortune",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Did you have to throw our supplies at them?! Why not use your weapon? Maybe fancy spells or kicks? Why the supplies?! Now we don't have enough to last us, especially with Nephew Bentnail here. His appetite is like a yeti's! You threw it, you get us more. There is wreckage down the path. Maybe you will find supplies there.",objectivesText="Search the Abandoned Wreckage for supplies. Progress: Nephew Bentnail has already eaten two days worth of food. I hope you found us more!",starts={{npcID=60175,x=0.48,y=0.49,zoneID=5841}},ends={{npcID=60175,x=0.48,y=0.49,zoneID=5841}},coords={x=0.48,y=0.49,source="quest_giver",zoneID=5841},questType="standard"},
[30684] = {id=30684,name="Seeker's Folly",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="I'm sure your pandaren friend has some ideas about what the mogu are after. He headed up the mountain a few days ago without a guide, and asked that only you be sent up after him. He was very specific: \"The must endure the trek alone, with only thoughts. will honor each shrine before meeting me at the top.\" The path is just northwest of the camp, marked by flags. Please be careful! Seeker's Folly is a dangerous trek even on a lucky day.",objectivesText="Brave the path of Seeker's Folly to find Lorewalker Cho , stopping to reflect at the three shrines along the way. Progress: There are two shrines on the path below us, and one more just behind us.",starts={{npcID=60175,x=0.48,y=0.49,zoneID=5841}},ends={{npcID=60795,x=0.438,y=0.51,zoneID=5841}},coords={x=0.48,y=0.49,source="quest_giver",zoneID=5841},questType="standard"},
[30690] = {id=30690,name="Unmasking the Yaungol",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Simply killing Kobai will accomplish nothing, as he is possessed by a particularly powerful and destructive Sha - Malevolent Fury . You will use the trap I have fashioned from the Blinding Rage Essences you brought. Lure him into the trap, and then steal his mask. Once you put it on, Malevolent Fury will appear and attempt to take control of you. Defeat him, and we will have made a victory of this tragic situation. You can find him to the north of the retreat, where he taunts us in insane rage.",objectivesText="Lure Kobai into the Blinding Rage Trap , steal the Mask of Malevolent Fury from him, and then defeat Malevolent Fury . Progress: Is Malevolent Fury gone?",starts={{npcID=60161,x=0.444,y=0.898,zoneID=5841}},ends={{npcID=60161,x=0.444,y=0.898,zoneID=5841}},coords={x=0.444,y=0.898,source="quest_giver",zoneID=5841},questType="standard"},
[30691] = {id=30691,name="Misery",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="While you are in the water below, you should slay Nahassa , the mortbreath patriarch. He suffers. I can feel his death cries ululating up to the surface of the lagoon. Find his cave, and put him out of his misery. Not because it will solve Marista's crocolisk problem. Simply out of mercy.",objectivesText="Put Nahassa out his misery. Progress: Please, <name>. Even the great beasts of this world have a right to die in dignity.",starts={{npcID=60139,x=0.46,y=0.788,zoneID=6134}},ends={{npcID=60139,x=0.46,y=0.788,zoneID=6134}},coords={x=0.46,y=0.788,source="quest_giver",zoneID=6134},questType="standard"},
[30692] = {id=30692,name="The Burlap Trail: To Kota Basecamp",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="This here's hozen lands. Very dangerous. But grummles must trek through. Supplies must reach the Serpent's Spine. Go, protect the next wave of grummles on their trek to Kota Basecamp. If at least one survives, good fortune will find its way to you.",objectivesText="Protect a group of grummles from the Burlap Waystation to the Kota Basecamp. At least one grummle must survive. If you lose your grummles, you can search the Burlap Trial or return to the Burlap Waystation and wait for the next group to leave. Progress: Welcome to Kota Basecamp, friend of grummles.",starts={{npcID=59703,x=0.516,y=0.678,zoneID=5841}},ends={{npcID=59755,x=0.424,y=0.69,zoneID=5841}},coords={x=0.516,y=0.678,source="quest_giver",zoneID=5841},questType="standard"},
[30694] = {id=30694,name="Tread Lightly",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="My students tell me the surrounding area is littered with deadly traps, no doubt set by the saurok. Stumbling into one gets you a face full of spikes. As the saying goes: \"The Way is rife with danger - tread lightly, and with scrutiny.\" Here, this is scrutiny. It should be long enough to set the traps off at a safe distance.",objectivesText="Use \"Scrutiny\" to set off 10 Riverblade Spike Traps from a safe distance. Progress: Well, I don't see any spikes in your face. That's a good sign.",starts={{npcID=59138,x=0.406,y=0.336,zoneID=6134}},ends={{npcID=59138,x=0.406,y=0.336,zoneID=6134}},coords={x=0.406,y=0.336,source="quest_giver",zoneID=6134},questType="standard"},
[30695] = {id=30695,name="Ahead on the Way",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="Huge maws of despair are spewing out sha from the pagodas on either side of the temple. Meanwhile, your impromptu training in the Way continues. \"She who mends torn umbrella will be more dry than she who strikes at rain.\" While I take issue with that particular lesson--sometimes punching the rain can be quite effective--the meaning holds true in this case. Take out those maws of despair and give my order a chance at reclaiming the temple grounds.",objectivesText="Kill the Maw of Despair in both the eastern and western pagodas at the Temple of the Red Crane. Progress: Koro said there's a pagoda on either side of the temple. Let's find them and wipe out the sha presence in both.",starts={{npcID=59138,x=0.406,y=0.336,zoneID=6134}},ends={{npcID=59608,x=0.423,y=0.489,zoneID=6134}},coords={x=0.406,y=0.336,source="quest_giver",zoneID=6134},questType="standard"},
[30698] = {id=30698,name="Scavenger Hunt",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="YOU! You're just who I have been looking for! I need more parts for my goblin fishing bombs but I hurt my leg and can't collect them myself. You see those shipwrecks nearby? I bet they have just what I need if you can get to it and fish it out. Take my fishing raft and see what you can find! My buddy has been trying to help me out too so you might find some extra rafts near the wreckage, feel free to use em' too.",objectivesText="Use the Goblin Fishing Raft to fish up 15 Rusty Shipwreck Parts out of the floating debris near the shipwrecks. Progress: Did you find the shipwrecks?",starts={{npcID=60136,x=0.674,y=0.446,zoneID=6134}},ends={{npcID=60136,x=0.674,y=0.446,zoneID=6134}},coords={x=0.674,y=0.446,source="quest_giver",zoneID=6134},questType="standard"},
[30699] = {id=30699,name="To Winter's Blossom",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="The battle against the Sha is eternal - we can not leave this place. But I am troubled by the absence of reinforcements from the Monastery given that we sent for them days ago. You have performed admirably, perhaps you could travel to Winter's Blossom, our base camp on the way to the Shado-Pan Monastery. Speak with Lin Silentstrike once you arrive - he should know what is happening. To get there, travel north of the village and follow the road through Shado-Li Basin to Winter's Blossom.",objectivesText="Speak with Lin Silentstrike at Winter's Blossom in Kun-Lai Summit .",starts={{npcID=60161,x=0.444,y=0.898,zoneID=5841}},ends={{npcID=61816,x=0.35,y=0.594,zoneID=5841}},coords={x=0.444,y=0.898,source="quest_giver",zoneID=5841},questType="standard"},
[30700] = {id=30700,name="Snapclaw",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="A giant, poisonous crab is wrecking havoc on our local abalone stores. I need you to go down into narsong trench and take it out!",objectivesText="Kill Snapclaw in a cave at the bottom of Narsong Trench and return with his claw as proof. Progress: Did you take out that nasty crawler?",starts={{npcID=59586,x=0.676,y=0.436,zoneID=6134}},ends={{npcID=59586,x=0.676,y=0.436,zoneID=6134}},coords={x=0.676,y=0.436,source="quest_giver",zoneID=6134},questType="standard"},
[30701] = {id=30701,name="Viseclaw Soup",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Nothing tastes quite like viseclaw soup. It's a krasarang specialty! I was just about to start up on a new batch when I realized I am missing a key ingredient, the eyes! I need you to kill the viseclaw fishers on the beach and return with their eyes for the soup!",objectivesText="Kill Viseclaw Fishers on the beach and return with 16 eyes to make some yummy soup. Progress: How many of their beady little eyes did you get?",starts={{npcID=60675,x=0.672,y=0.41,zoneID=6134}},ends={{npcID=60675,x=0.672,y=0.41,zoneID=6134}},coords={x=0.672,y=0.41,source="quest_giver",zoneID=6134},questType="standard"},
[30710] = {id=30710,name="Provoking the Trolls",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5841,mapID=379,description="We've managed to push them back this far, but I doubt that we will remain safe for long if we do not deal with them once and for all. My husband, coward or fool that he is, does not wish to provoke them. I will not be cowed so. We will do just that. Slay their forward scouts. Perhaps we can provoke - and then defeat - their leader.",objectivesText="Kill 10 Zandalari Stalkers and 5 Zandalari Hexers",questType="standard"},
[30714] = {id=30714,name="Destroy the Leaders",level=1,requiredLevel=1,faction="both",expansion=4,description="And, now they fear you. Their leaders, a Blademaster and a Mage, lie deeper in the ruins. Kill them. Make them hurt. For us.",objectivesText="Kill the Zandalari Blademaster and Zandalari Mage",questType="standard"},
[30715] = {id=30715,name="A Line Unbroken",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="When we regrouped after their initial attack, we numbered three less. You can fight, and we must plan our defense should these cursed yaungol attack again. If you would help us, grant our fallen comrades their last rites, and recover their armor. You will find their bodies to the west, near the gate. And try to keep the birds off them.",objectivesText="Lay Shado-Master Zhiyao, Liu of the Thousand Blows and Shiya Boldblade to rest. Progress: Our comrades, are they at rest?",starts={{npcID=61819,x=0.35,y=0.596,zoneID=5841}},ends={{npcID=61819,x=0.35,y=0.596,zoneID=5841}},coords={x=0.35,y=0.596,source="quest_giver",zoneID=5841},questType="standard"},
[30716] = {id=30716,name="Chasing Hope",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=6134,description="Chi-Ji is always with us. Even when he is not here in the Cradle, pieces of his spirit run through the forests and beaches of the island, watching us and testing us. Prove your dexterity in the eyes of Chi-Ji, . Find and catch the spirits of the crane.",objectivesText="Touch 3 Spirits of the Crane . Progress: Return when you are finished, <name>. Now go!",starts={{npcID=60528,x=0.312,y=0.634,zoneID=6134}},ends={{npcID=60528,x=0.312,y=0.634,zoneID=6134}},coords={x=0.312,y=0.634,source="quest_giver",zoneID=6134},questType="standard"},
[30717] = {id=30717,name="Gifts of the Great Crane",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=6134,description="The cranes of Krasarang are a gift from Chi-Ji. Even the very feathers they leave behind are a gift for us to appreciate. We use these feathers to adorn our garments and to fletch arrows. But first... they must be gathered.",objectivesText="Obtain 10 Gifts of the Great Crane . Progress: Even the smallest, flimsiest feather is proof enough that Chi-Ji loves us.",starts={{npcID=60529,x=0.314,y=0.636,zoneID=6134}},ends={{npcID=60529,x=0.314,y=0.636,zoneID=6134}},coords={x=0.314,y=0.636,source="quest_giver",zoneID=6134},questType="standard"},
[30718] = {id=30718,name="Students of Chi-Ji",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=6134,description="Our order prides itself on excellence in combat. We hone these combat skills by dueling one another, here on the Cradle of Chi-Ji. Prove yourself in the eyes of the Red Crane. Venture south, into the center of the island, and duel with your fellow students.",objectivesText="Duel 10 Students of Chi-Ji. Progress: Your trial is not yet complete, <name>.",starts={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},ends={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},coords={x=0.312,y=0.634,source="quest_giver",zoneID=6134},questType="standard"},
[30719] = {id=30719,name="FLAG - Cradle of Chi-Ji Progress Bit 01",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6134,mapID=418,questType="standard"},
[30720] = {id=30720,name="FLAG - Cradle of Chi-Ji Progress Bit 02",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6134,mapID=418,questType="standard"},
[30721] = {id=30721,name="FLAG - Cradle of Chi-Ji Progress Bit 03",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6134,mapID=418,questType="standard"},
[30722] = {id=30722,name="FLAG - Cradle of Chi-Ji Progress Bit 04",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6134,mapID=418,questType="standard"},
[30723] = {id=30723,name="Honor, Even in Death",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Hmm... If Shado-Master Chong trusted you, perhaps you can help us. The yaungol are our enemies. Still, we must prove we are better than they. We will show them honor in death. As after most battles, the carrion birds have begun gathering. Thin their numbers, so the bodies of our foes will not be desecrated. They've gathered at the battlefield to the west.",objectivesText="Kill 12 Kun-Lai Scavengers. Progress: Killing those birds may not soothe my anger, but at least it proves that we are better than our enemies. They would not do such a thing.",starts={{npcID=61816,x=0.35,y=0.594,zoneID=5841}},ends={{npcID=61816,x=0.35,y=0.594,zoneID=5841}},coords={x=0.35,y=0.594,source="quest_giver",zoneID=5841},questType="standard"},
[30724] = {id=30724,name="To the Wall!",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="They are attacking again! Archers... on the wall! I need you to get up there. My wife Suna went to scout the wall with that fool Lao-Chen. Perhaps if he had spent more time preparing defenses and less building that ridiculous ale lift contraption... It matters not. Get a kite from Len, to the west, and then get up there and find my wife. She'll know what to do next.",objectivesText="Speak to Kite Master Len at Winter's Blossom in Kun-Lai Summit to take a kite up to the Ox Gate. Once there, speak to Suna Silentstrike . Progress: Lin sent you for me? How sweet.",starts={{npcID=61816,x=0.35,y=0.594,zoneID=5841}},ends={{npcID=61454,x=0.292,y=0.622,zoneID=5841}},coords={x=0.35,y=0.594,source="quest_giver",zoneID=5841},questType="standard"},
[30725] = {id=30725,name="Ellia Ravenmane",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="We regularly organize one-on-one duels with trainees that we think are well-suited for one another. We have found one such trainee for you, . Her name is Ellia Ravenmane . This will be her first duel, too. She will be waiting for you at the pavilion just to the south of here.",objectivesText="Defeat Ellia Ravenmane at the Angkhal Pavilion. Progress: Yes, you and Ellia should be a perfect match...",starts={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},ends={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},coords={x=0.312,y=0.634,source="quest_giver",zoneID=6134},questType="standard"},
[30726] = {id=30726,name="Minh Do-Tan",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Your next challenger is another relatively new trainee. His name is Minh Do-Tan , and he has won his last two matches. He will be waiting for you near the crane statue to the south.",objectivesText="Defeat Minh Do-Tan . Progress: Fight hard, <name>.",starts={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},ends={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},coords={x=0.312,y=0.634,source="quest_giver",zoneID=6134},questType="standard"},
[30727] = {id=30727,name="Ellia Ravenmane: Rematch",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Ellia Ravenmane requested a rematch with you. She seems to identify you as her \"rival\". We discourage rivalries here within the Cradle of Chi-Ji, but we rarely decline a rematch request. You will find Ellia near the Pedestal of Hope, on the island's eastern side.",objectivesText="Defeat Ellia Ravenmane near the base of the Pedestal of Hope.",starts={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},ends={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},coords={x=0.312,y=0.634,source="quest_giver",zoneID=6134},questType="standard"},
[30728] = {id=30728,name="Fat Long-Fat",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="You have been matched with a... special trainee. His name is Fat Long-Fat . Thelonius chooses his words carefully.> Fat Long-Fat ... operates outside of the normal rules of combat. He does not fight every day, and when he does, he chooses his competitor. Today, for some reason... he has selected you. You will find him atop Angkhal Pavilion.",objectivesText="Defeat Fat Long-Fat at the top of Angkhal Pavilion.",starts={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},ends={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},coords={x=0.312,y=0.634,source="quest_giver",zoneID=6134},questType="standard"},
[30729] = {id=30729,name="Julia Bates",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="We welcome all kinds here within the Cradle, as long as they recognize and subscribe to the ideologies of the Red Crane. One of our new, more exotic trainees comes from the human kingdoms to the northeast. She goes by the rather foreign-sounding name of Julia Bates . She is your next challenger. You will find her on the island's western shore.",objectivesText="Defeat Julia Bates . Progress: Stay strong, <name>.",starts={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},ends={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},coords={x=0.312,y=0.634,source="quest_giver",zoneID=6134},questType="standard"},
[30730] = {id=30730,name="Dextrous Izissha",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Jinyu normally avoid our order, but every few years, we find one that subscribes to the way of the Crane. One such jinyu is Dextrous Izissha . Izissha is your next challenger. He waits for you on the island's southwestern shore.",objectivesText="Defeat Dextrous Izissha .",starts={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},ends={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},coords={x=0.312,y=0.634,source="quest_giver",zoneID=6134},questType="standard"},
[30731] = {id=30731,name="Kuo-Na Quillpaw",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Most of the duels within the Cradle take place between two trainees. Rarely, when a trainee exhibits a rare amount of skill, they will have an opportunity to duel their trainer. Today, you duel against Kuo-Na. She will be waiting for you at the Pedestal of Hope.",objectivesText="Defeat Kuo-Na Quillpaw .",starts={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},ends={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},coords={x=0.312,y=0.634,source="quest_giver",zoneID=6134},questType="standard"},
[30732] = {id=30732,name="Ellia Ravenmane: Revenge",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Your \"rival\" has appeared again. Ellia Ravenmane has been avoiding her duties on the island, instead focusing on personal training, with the intent to defeat you in battle. \"I will destroy ,\" she said. I have honored her request for a rematch, but I will be keeping a close eye on her. Her motives may be shifting in a dangerous direction.",objectivesText="Defeat Ellia Ravenmane at Dome Balrissa.",starts={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},ends={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},coords={x=0.312,y=0.634,source="quest_giver",zoneID=6134},questType="standard"},
[30733] = {id=30733,name="Tukka-Tuk",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="You are making a name for yourself, . I received a challenge from one of our more skilled competitors. He believes you are not as strong as you seem. His name is Tukka-Tuk , the hozen. If you've ever fought against hozen before, you know that their apparent juvenility belies their battle acumen. Good luck.",objectivesText="Defeat Tukka-Tuk .",starts={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},ends={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},coords={x=0.312,y=0.634,source="quest_giver",zoneID=6134},questType="standard"},
[30734] = {id=30734,name="Huck Wheelbarrow",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Usually our trainees are adventurers like yourself, or monks from Tian Monastery, or occasionally retired Shado-Pan. Very rarely, though, we will greet trainees that have no fighting experience whatsoever. Huck Wheelbarrow is one such trainee. He has requested a duel with you. Look for him on the island's western shore.",objectivesText="Defeat Huck Wheelbarrow .",starts={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},ends={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},coords={x=0.312,y=0.634,source="quest_giver",zoneID=6134},questType="standard"},
[30735] = {id=30735,name="Mindel Sunspeaker",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Our highest-ranked trainee is an outsider like you. It is both strange and exciting to live in a time when so many foreigners have embraced the way of the Crane. Your challenger's name is Mindel Sunspeaker , and he awaits you within Angkhal Pavilion.",objectivesText="Defeat Mindel Sunspeaker .",starts={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},ends={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},coords={x=0.312,y=0.634,source="quest_giver",zoneID=6134},questType="standard"},
[30736] = {id=30736,name="Yan Quillpaw",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="You have already defeated Kuo-Na Quillpaw. You have not yet fought her brother, Yan. He will meet you at the Pedestal of Hope, and he will not hold back. His reputation as a trainer is at stake.",objectivesText="Defeat Yan Quillpaw at the Pedestal of Hope.",starts={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},ends={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},coords={x=0.312,y=0.634,source="quest_giver",zoneID=6134},questType="standard"},
[30737] = {id=30737,name="Fat Long-Fat: Rematch",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Fat Long-Fat has requested another match with you. I find this strange. And concerning. He will be waiting atop the Dome Belrissa.",objectivesText="Defeat Fat Long-Fat atop Dome Belrissa.",starts={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},ends={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},coords={x=0.312,y=0.634,source="quest_giver",zoneID=6134},questType="standard"},
[30738] = {id=30738,name="Thelonius",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="When we last spoke, I promised to tell you the secret of Fat Long-Fat. I still plan to tell you that secret... after I determine your worth. I will meet you on the western shore, and we will duel.",objectivesText="Defeat Thelonius .",starts={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},ends={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},coords={x=0.312,y=0.634,source="quest_giver",zoneID=6134},questType="standard"},
[30739] = {id=30739,name="Ellia Ravenmane: Redemption",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Ellia Ravenmane , your rival, has returned. She demands that you meet her atop the Pedestal of Hope. You need to understand, ... something horrible has happened to her. She has changed. You will see for yourself when you arrive at the pedestal. Good luck, .",objectivesText="Defeat Ellia Ravenmane atop the Pedestal of Hope.",starts={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},ends={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},coords={x=0.312,y=0.634,source="quest_giver",zoneID=6134},questType="standard"},
[30740] = {id=30740,name="Champion of Chi-Ji",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="While you will always hold a place of honor among our order, you are still welcome to participate in our duels. One of our current champions awaits you in the Dome Balrissa. I know that they would be honored to duel with you.",objectivesText="Defeat a Champion of Chi-Ji .",starts={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},ends={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},coords={x=0.312,y=0.634,source="quest_giver",zoneID=6134},questType="standard"},
[30742] = {id=30742,name="Shut it Down",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="I mussed up. Bad. It's hard work cutting seeds out of kafa berries! But I noticed goots eat the berries up and give back the seeds... in a day or so. I fed everything I had to the goots on Kota Peak and now they're nuts! Chargin' everything that moves. Kota used to be safe for Grummles to gather kafa. Not anymore. Not with them goots. Will you help?",objectivesText="Kill 12 Kafa-Crazed Mountain Goats on Kota Peak. Progress: I shoulda never fed them goots.",starts={{npcID=60596,x=0.424,y=0.696,zoneID=5841}},ends={{npcID=60596,x=0.424,y=0.696,zoneID=5841}},coords={x=0.424,y=0.696,source="quest_giver",zoneID=5841},questType="standard"},
[30743] = {id=30743,name="Gourmet Kafa",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="It was genius: kafa berries go in the goot, seeds come out. Kafa'kota is already rare and worth a fortune, but my invention--Kafa'goot--is GOURMET. But it's over now. Uncle is upset and peak is a muss. All that's left is to collect the rest of the Kafa'goot and never make it again. I won't ask you to gather it--kind of a mussy task, not fit for hero-- just mark it so I can find it easily when the mountain is safe again.",objectivesText="Mark 10 Kafa'goot \"Deposits\" on Kota Peak.",starts={{npcID=60596,x=0.424,y=0.696,zoneID=5841}},ends={{npcID=60596,x=0.424,y=0.696,zoneID=5841}},coords={x=0.424,y=0.696,source="quest_giver",zoneID=5841},questType="standard"},
[30744] = {id=30744,name="Kota Blend",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Kota Peak is famous for its kafa bushes - no other can survive at this elevation. Grummles make very good living selling Kafa'kota Blend, but it's dangerous now thanks to my cousin here. He's got the wildlife up there hooked on kafa with his scheming. Kafa'kota is more scarce than ever with goots gobblin' it up and yetis hoarding it in their caves. I pay you good for any berries you bring down from Kota. Here, take a sample. Eat it. See for yourself the power of kafa.",objectivesText="Collect 100 Kafa'kota Berries from Kota Peak. They can be found in bushes growing on the mountainside or piled up in the yeti caves.",starts={{npcID=60503,x=0.424,y=0.696,mapID=379}},coords={x=0.424,y=0.696,source="quest_giver",mapID=379},questType="standard"},
[30745] = {id=30745,name="Trouble Brewing",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="Lots of yetis in Kota, yup. Usually not too dangerous. Usually just eat goots. Then they ate the goots full of kafa... Now they're moody, cranky, sleep a lot but never seem rested. Typical kafa addicts. Gonna come outta those caves soon, I'm sure. Come lookin' for more kafa. Then we all in trouble.",objectivesText="Kill 5 Kafa-Crazed Yetis in the caves on Kota Peak.",starts={{npcID=60503,x=0.424,y=0.696,zoneID=5841}},ends={{npcID=60503,x=0.424,y=0.696,zoneID=5841}},coords={x=0.424,y=0.696,source="quest_giver",zoneID=5841},questType="standard"},
[30746] = {id=30746,name="A Fair Trade",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Eep! Please, great Kota Kon, forgive grummle. Let me go, I'll bring lots of kafa right away! Promise!",objectivesText="Bring the Bundle of Kafa'kota Berries to the Lair of Kota Kon, near the top of Kota Peak. Progress: Kota Kon wants more kafa, but I already fed her all I have! Then I tried giving her a nice bow, but she's not satisfied! <The terrified grummle gulps and leans in close to whisper.> I think she can smell the kafa I drank for breakfast...",starts={{npcID=60503,x=0.424,y=0.696,zoneID=5841}},ends={{npcID=60679,x=0.424,y=0.694,zoneID=5841}},coords={x=0.424,y=0.696,source="quest_giver",zoneID=5841},questType="standard"},
[30747] = {id=30747,name="The Burlap Grind",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Okayyy... well, she's not eating anybody. That's a good start. She must want more kafa, but we gotta give her somethin' to do with all the extra energy... I got it! The Burlap Trail! She can smash hozen out there all day! What do you think, pretty girl? Wanna smash hozens?! I think so. Here, feed her my emergency flask of kafa . She likes you.",objectivesText="Feed the Flask of Kafa to Kota Kon at Kota Basecamp, then kill 100 Hozen along The Burlap Trail. Progress: Don't push our luck... we promised her hozens-smashies.",starts={{npcID=60679,x=0.424,y=0.694,zoneID=5841}},ends={{npcID=60679,x=0.424,y=0.694,zoneID=5841}},coords={x=0.424,y=0.694,source="quest_giver",zoneID=5841},questType="standard"},
[30750] = {id=30750,name="Off the Wall!",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="The yaungol on the wall here are providing covering fire for the ones below. I don't know what Lao-chen is thinking, but I want you to deal with these archers. The good news is, up here we've got the spirit of the Ox helping us. When they're weakened, the ox spirit will stun them and you can use it to knock 'em off the wall. You'll find the archers just out that door.",objectivesText="Kill 12 Osul Veteran Archers or Osul Fire-Warriors.",starts={{npcID=61454,x=0.292,y=0.622,zoneID=5841}},ends={{npcID=61454,x=0.292,y=0.622,zoneID=5841}},coords={x=0.292,y=0.622,source="quest_giver",zoneID=5841},questType="standard"},
[30751] = {id=30751,name="A Terrible Sacrifice",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="I have an idea, and... am prepared to make a terrible sacrifice. As much as I know that we need my stout brew, to fortify our defenders for the long-term security of the Ox Gate... It is too painful to discuss details now, but please - while you are up here defending the wall, gather the barrels of oil they are using to light their arrows. We will need them.",objectivesText="Gather 6 Barrels of Yaungol Fire Oil. Progress: Do you have the oil?",starts={{npcID=61820,x=0.292,y=0.622,zoneID=5841}},ends={{npcID=61820,x=0.292,y=0.622,zoneID=5841}},coords={x=0.292,y=0.622,source="quest_giver",zoneID=5841},questType="standard"},
[30752] = {id=30752,name="Unbelievable!",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="I simply refuse to believe the guards will not grant us entry to the monastery should we impress upon them the seriousness of the situation. Friend, go east, to the sentinel in front of the Monastery, and demand admittance. I will come with you.",objectivesText="Speak to the Shado-Pan Monastery Sentinel to gain entrance to the Shado-Pan Monastery. Progress: Unbelievable!",starts={{npcID=61819,x=0.35,y=0.596,zoneID=5841}},ends={{npcID=62227,x=0.353,y=0.495,zoneID=5841}},coords={x=0.35,y=0.596,source="quest_giver",zoneID=5841},questType="standard"},
[30753] = {id=30753,name="Jumping the Shark",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="There is only one way to kill sharks where I come from, with your bare hands! I dumped a good amount of chum in the water just off the dock here, this place should be crawling with the local reef sharks in no time. Hop on the first one you see and take it out!",objectivesText="Kill a frenzied reef shark with your bare hands. Progress: Did you show that shark who's boss?",starts={{npcID=60674,x=0.682,y=0.434,zoneID=6134}},ends={{npcID=60674,x=0.682,y=0.434,zoneID=6134}},coords={x=0.682,y=0.434,source="quest_giver",zoneID=6134},questType="standard"},
[30754] = {id=30754,name="Bright Bait",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Certain fish are only attracted to bright lights. The forest north of here is home to a local pandaren firefly called a suncrawler . You should be able to find them on the base of the tree trunks all around that area. Bring me back a handful of them and I can use them for bait!",objectivesText="Collect 7 Suncrawlers in the forest north of Anglers Wharf. Progress: Any luck with those suncrawlers ?",starts={{npcID=60674,x=0.682,y=0.434,zoneID=6134}},ends={{npcID=60674,x=0.682,y=0.434,zoneID=6134}},coords={x=0.682,y=0.434,source="quest_giver",zoneID=6134},questType="standard"},
[30757] = {id=30757,name="Lord of the Shado-Pan",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5918,description="Our lord, Taran Zhu , has been overcome by a sha of pure hatred. The whole monastery has been lost! , you must find a way to free him of this possession. Last I knew, he was meditating in the Grove of Falling Blossoms.",objectivesText="Rid Taran Zhu of his possession by the Sha of Hatred.",starts={{x=0.848,y=0.56,mapID=444,npcID=62236}},ends={{x=0.848,y=0.56,mapID=444,npcID=62236}},coords={mapID=444,x=0.848,y=0.56},questType="dungeon"},
[30763] = {id=30763,name="Piranha!",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Certain fish are very difficult to catch. The wolf piranha falls squarely into this category. Lucky for me that you showed up! Put those fishing skills to the test and bring me back a few from the krasarang river due northwest of here.",objectivesText="Fish up 5 Wolf Piranha from the Krasarang River in Krasarang Wilds. Progress: Any luck?",starts={{npcID=60675,x=0.672,y=0.41,zoneID=6134}},ends={{npcID=60675,x=0.672,y=0.41,zoneID=6134}},coords={x=0.672,y=0.41,source="quest_giver",zoneID=6134},questType="standard"},
[30765] = {id=30765,name="Regaining Honor",level=20,requiredLevel=20,faction="none",expansion=4,zoneID=5841,mapID=379,description=", the yaungol warchief, Humongous, killed Shado-Master Zhen. He has his banner. You have to kill Humongous and regain Zhen's honor! If you don't, I will.",objectivesText="Retrieve Zhen's Banner .",questType="standard"},
[30766] = {id=30766,name="Profiting off of the Past",level=20,requiredLevel=20,faction="none",expansion=4,zoneID=5841,mapID=379,description="<A relic drops off of the statue. Hmm, these could prove to be valuable to the right person.> <There's a collector on the outskirts of the ruins. Perhaps he'd be interested in purchasing them from you?>",objectivesText="Collect 11 more Mogu Relics.",questType="standard"},
[30767] = {id=30767,name="Risking It All",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,mapID=378,description="Wait, what?! How could he be so reckless? Blowing the ship free is insane! They could kill Shen-zin Su, and all of us with it. I know we don't have much time, but we need to think of another way...",objectivesText="Remove the thorn from Shen-zin Su.",starts={{npcID=56416,x=0.366,y=0.842,zoneID=5736}},ends={{npcID=56418,x=0.392,y=0.862,zoneID=5736}},coords={x=0.366,y=0.842,source="quest_giver",zoneID=5736},questType="standard"},
[30768] = {id=30768,name="My Husband...",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Lin... I don't care what Ban, Lao-Chin, or even Taran Zhu says. I'm moving ahead into Townlong. I may not be able to save Lin myself, but I'm not going to sit around waiting for everyone else to catch up. Once Taran Zhu opens the doors to his precious monastery, we'll save Lin. Until then, I'll scout ahead and make sure he's alright.",objectivesText="Meet up with Suna Silentstrike at Longying Outpost in the Townlong Steppes .",starts={{npcID=61454,x=0.292,y=0.622,zoneID=5841}},ends={{npcID=60684,x=0.672,y=0.522,zoneID=5842}},coords={x=0.292,y=0.622,source="quest_giver",zoneID=5841},questType="standard"},
[30769] = {id=30769,name="First Assault",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Now that we have had time to assess our enemies' weaknesses, it is time for us to deal the yaungol a direct blow. Go and confront the Osul Sharphorn up the mesa to the west. Let them know that we are here, and that we are not scared of their threats.",objectivesText="Kill 6 Osul Sharphorns .",starts={{npcID=60688,x=0.712,y=0.566,zoneID=5842}},ends={{npcID=60684,x=0.672,y=0.522,zoneID=5842}},coords={x=0.712,y=0.566,source="quest_giver",zoneID=5842},questType="standard"},
[30770] = {id=30770,name="Running Rampant",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="There is one thing that every army needs, and that is a supply line. The enemy camp to the west contains a large beast herd, which serves as the yaungol army's main source of food. Luckily for us, the yaks and mushan beasts of this region are easily scared. Sneak in, give the beasts a good slap, and watch the results.",objectivesText="Scare 8 Long-Haired Yaks or Steppebeasts.",starts={{npcID=60688,x=0.712,y=0.566,zoneID=5842}},ends={{npcID=60687,x=0.672,y=0.522,zoneID=5842}},coords={x=0.712,y=0.566,source="quest_giver",zoneID=5842},questType="standard"},
[30771] = {id=30771,name="Perfect Pitch",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="When the Osul tribe goes to war, they coat their spears and arrows with a highly flammable, ever-burning pitch. They use this terrible weapon to shed not only blood, but to raze the homes of their enemies. I need you to collect some of this pitch while you are in their camp. We will use it to show the yaungol that when you play with fire, you can get burned.",objectivesText="Collect 8 Dark Pitch . Progress: The yaungol are not content merely to defeat their enemies. No, they would rather destroy and decimate them.",starts={{npcID=60688,x=0.712,y=0.566,zoneID=5842}},ends={{npcID=60687,x=0.672,y=0.522,zoneID=5842}},coords={x=0.712,y=0.566,source="quest_giver",zoneID=5842},questType="standard"},
[30772] = {id=30772,name="Seeing Red",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Ahead of us is the main thrust of the yaungol army. Here, they prepare their vast army to attack the villages of Kun-Lai. If we strike at the Osul now, we can cut them at their very core. Remember, for every of their number that we strike down here, we save one of our own back at home.",objectivesText="Kill 8 Osul Marauders or Osul Spitfires.",starts={{npcID=60684,x=0.672,y=0.522,zoneID=5842}},ends={{npcID=60687,x=0.672,y=0.522,zoneID=5842}},coords={x=0.672,y=0.522,source="quest_giver",zoneID=5842},questType="standard"},
[30773] = {id=30773,name="Pitching In",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="The yaungol's siege weapons - those ballista spearthrowers down there - are tearing apart our defenses both at Longying Oupost and in Kun-Lai Summit. Those terrible weapons must be destroyed. Take these explosives. I've covered them in the pitch that you collected. Toss them at those ballistas, and we'll give the yaungol a little taste of their own medicine.",objectivesText="Use Ban's Explosives to destroy 6 Osul Ballistas. Progress: Fire is a cruel weapon. Luckily, we are only using it to destroy weapons of war.",starts={{npcID=60687,x=0.672,y=0.522,zoneID=5842}},ends={{npcID=60687,x=0.672,y=0.522,zoneID=5842}},coords={x=0.672,y=0.522,source="quest_giver",zoneID=5842},questType="standard"},
[30774] = {id=30774,name="Ranger Rescue",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=9576,mapID=388,description="I must ask a most important task of you, . Somewhere among the cages in the Osul camp is my husband, Lin. He is the light of my world. Please find him and return him to me, and save as many of our fellow Shado-Pan as you can as well. You should find keys to those cages on the Osul Marauders.",objectivesText="Unlock Drywood Cages to save 4 Longying Rangers and Lin Silentstrike .",starts={{npcID=60684,x=0.672,y=0.522,zoneID=5842}},ends={{npcID=60687,x=0.672,y=0.522,zoneID=5842}},coords={x=0.672,y=0.522,source="quest_giver",zoneID=5842},questType="standard"},
[30775] = {id=30775,name="The Exile",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="What is there to say, stranger? I fought Jung Duk and lost. I was the fool to believe he would fight fairly. Now, my own brothers turned against me, and here I am, speaking to our enemies. I know you have come for Osul blood. I only ask that you hunt down the three who betrayed me. Urang , who poisoned my drink. Ku-Tong , who bent my spear. And Battat , whose dagger slipped into my side as my victory was assured. Do this, and I can die in peace.",objectivesText="Kill Urang , Ku-Tong , and Battat . Progress: How could they have betrayed me? They were once my brothers! Why did they turn on me? WHY? I hate them! I will slaughter them all!",starts={{npcID=60735,x=0.67,y=0.514,zoneID=5842}},ends={{npcID=60735,x=0.67,y=0.514,zoneID=5842}},coords={x=0.67,y=0.514,source="quest_giver",zoneID=5842},questType="standard"},
[30776] = {id=30776,name="Jung Duk",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="THIS. IS. WAR. I will have the heads of everyone who took Lin from me. EVERYONE! We will begin with the Osul leader, Jung Duk . Take this Shado-Pan war banner and place it at the center of their camp. Jung Duk will have no choice but to face you. Show him no mercy, .",objectivesText="Plant the Shado-Pan Banner on the Ceremonial Pile, then kill Jung Duk . Progress: Jung Duk 's legacy is written in the blood of innocents.",starts={{npcID=60684,x=0.672,y=0.522,zoneID=5842}},ends={{npcID=60687,x=0.672,y=0.522,zoneID=5842}},coords={x=0.672,y=0.522,source="quest_giver",zoneID=5842},questType="standard"},
[30777] = {id=30777,name="In Search of Suna",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="I have bad news. When I returned, Suna was already gone. The others say that she took her things and headed down the road to the east, muttering about hunting down the source of the yaungol aggression. I cannot allow her to venture into dangerous territory alone. I've already prepared a group of soldiers to push further east. We are leaving shortly. Hop on the caravan if you wish to travel with the Shado-Pan. You can also meet us there if you wish.",objectivesText="Speak to Ban Bearheart after arriving at Hatred's Vice.",starts={{npcID=60687,x=0.672,y=0.522,zoneID=5842}},ends={{npcID=61261,x=0.826,y=0.73,zoneID=5842}},coords={x=0.672,y=0.522,source="quest_giver",zoneID=5842},questType="standard"},
[30778] = {id=30778,name="Dust to Dust",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=390,description="If we are to make camp here, we cannot leave all of these yaungol bodies lying to rot. Take this torch and set fire to the villagers' corpses. The incense from the torch should purify the earth and air around them as well. Even our enemies deserve to be laid to rest.",objectivesText="Use the Shado-Pan Torch on 20 Palewind Villagers . Progress: The stench of death is overpowering.",starts={{npcID=61261,x=0.826,y=0.73,zoneID=5842}},ends={{npcID=61261,x=0.826,y=0.73,zoneID=5842}},coords={x=0.826,y=0.73,source="quest_giver",zoneID=5842},questType="standard"},
[30779] = {id=30779,name="Slaying the Scavengers",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=390,description="The rotting corpses are attracting hyena scavengers. In addition to spreading diseases from feeding on the dead, the feral creatures will attack us on sight. Go and eradicate the beasts. It is unfortunate, but ultimately for the best.",objectivesText="Kill 8 Ashfang Hyenas . Progress: It is better to be safe than sorry.",starts={{npcID=61261,x=0.826,y=0.73,zoneID=5842}},ends={{npcID=61261,x=0.826,y=0.73,zoneID=5842}},coords={x=0.826,y=0.73,source="quest_giver",zoneID=5842},questType="standard"},
[30780] = {id=30780,name="Totemic Research",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="As we entered the village, I couldn't help but notice yaungol totems lying around this camp. I have a suspicion that there are dark forces at work here, and those totems may be the key to drawing them out. Could you bring me some of these totems for further inspection? I would like to study them.",objectivesText="Collect 9 Palewind Totems . Progress: I do believe the totems could be of use to us.",starts={{npcID=60864,x=0.826,y=0.73,zoneID=5842}},ends={{npcID=60864,x=0.826,y=0.73,zoneID=5842}},coords={x=0.826,y=0.73,source="quest_giver",zoneID=5842},questType="standard"},
[30781] = {id=30781,name="Last Toll of the Yaungol",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Ban has asked me to explore the village to determine what happened here. I noticed smoke rising up from the east, the west, northwest, and the south. I need someone I trust to watch my back. What do you say? Want to help me on my first scouting mission?",objectivesText="Take Xiao Tu to the smoke trails at Hatred's Vice. Progress: Something terrible must have happened here.",starts={{npcID=60903,x=0.826,y=0.73,zoneID=5842}},ends={{npcID=61261,x=0.826,y=0.73,zoneID=5842}},coords={x=0.826,y=0.73,source="quest_giver",zoneID=5842},questType="standard"},
[30782] = {id=30782,name="Spiteful Spirits",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=390,description="The spirits of the fallen villagers have risen! I can feel the hatred emanating from the spirits. , if we are to survive here, we must defend ourselves. This is the only way we can put them to rest.",objectivesText="Kill 10 Spiteful Spirits . Progress: The air is thick with their malicious intent.",starts={{npcID=61261,x=0.826,y=0.73,zoneID=5842}},ends={{npcID=61261,x=0.826,y=0.73,zoneID=5842}},coords={x=0.826,y=0.73,source="quest_giver",zoneID=5842},questType="standard"},
[30783] = {id=30783,name="Hatred Becomes Us",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="I should have suspected a sha presence earlier! We are safe as long as we stand inside the Totem of Harmony 's protective wards, but many of our people were not so lucky. They were trapped outside the camp when the sha's powers manifested, and now they turn upon each other! Take one of my totems with you. Place the totem near a crazed ally to purify them, but beware. You may have to face the darkness that gripped them.",objectivesText="Use the Totem of Harmony to exorcise sha spirits from 8 Crazed Shado-Pan Rangers. Defeat the Seething Hatreds to purify your allies. Progress: Our people are possessed by hatred. We must help them come to their senses!",starts={{npcID=60864,x=0.826,y=0.73,zoneID=5842}},ends={{npcID=60864,x=0.826,y=0.73,zoneID=5842}},coords={x=0.826,y=0.73,source="quest_giver",zoneID=5842},questType="standard"},
[30784] = {id=30784,name="The Point of No Return",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=390,description="One of our rangers reported seeing Suna up the hill to the northwest. I am relieved to find her safe. I had feared what she would do in her grief. Would you go speak to her on my behalf? Take this totem with you. If you encounter any danger along the way, you may find it useful.",objectivesText="Find Suna Silentstrike . Progress: If I could change the past, I would. If I could take Lin's place, I would. In a thousand lifetimes, I will never be able to repay Suna's loss, or share even a measure of her grief.",starts={{npcID=61261,x=0.826,y=0.73,zoneID=5842}},ends={{npcID=61261,x=0.826,y=0.73,zoneID=5842}},coords={x=0.826,y=0.73,source="quest_giver",zoneID=5842},questType="standard"},
[30785] = {id=30785,name="Gao-Ran Battlefront",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="With your help, we have quelled the spirits of this place. At last, they may rest in peace. Our journey into this cursed land, I am afraid, has only begun. I have some important matters to finish up here, but we will be moving out soon. I need someone to go ahead and tell Lord Taran Zhu that we are joining him. Find him at the Gao-Ran Battlefront. Tell him what has transpired here.",objectivesText="Speak to Lord Taran Zhu at the Gao-Ran Battlefront in the Townlong Steppes .",starts={{npcID=61261,x=0.826,y=0.73,zoneID=5842}},ends={{npcID=61066,x=0.764,y=0.824,zoneID=5842}},coords={x=0.826,y=0.73,source="quest_giver",zoneID=5842},questType="standard"},
[30786] = {id=30786,name="A Spear Through My Side, A Chain Through My Soul",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="My fate is sealed. The yaungol put this spear in my side. The wound will kill me. The yaungol hold me in place with their twisted, corrupted magic. The indignity of it hurts worse than my spear-wound. My death, I cannot stop. My imprisonment... you may be able to help me with this.",objectivesText="Slay Dmong Naruuk , the shaman who holds Orbiss hostage. Progress: I will not die before having my revenge.",starts={{npcID=60857,x=0.678,y=0.676,zoneID=5842}},ends={{npcID=60857,x=0.678,y=0.676,zoneID=5842}},coords={x=0.678,y=0.676,source="quest_giver",zoneID=5842},questType="standard"},
[30787] = {id=30787,name="The Torches",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Until recently, the yaungol shaman would come here to work alongside us. Now, they bend my people to their will. If we refuse, they kill us. Even if we oblige... they kill us. The yaungol mist-shaman's magic flows through his torch. Take his torch away, and he has nothing.",objectivesText="Obtain 6 Mist-Shaman's Torches. Progress: I can use these torches in my revenge. I have not succumbed to this wound yet. I can still have my revenge before I die. There is time yet.",starts={{npcID=60857,x=0.678,y=0.676,zoneID=5842}},ends={{npcID=60857,x=0.678,y=0.676,zoneID=5842}},coords={x=0.678,y=0.676,source="quest_giver",zoneID=5842},questType="standard"},
[30788] = {id=30788,name="Golgoss",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="The leader of the yaungol mist-shaman is named Jahesh. He is known for his strength. One of my kind is also known for his strength. His name is Golgoss . Golgoss sleeps within the mists of the Upper Sumprushes. Help me to summon him, and he will join me in avenging our people.",objectivesText="Summon Golgoss by planting the Mist-Shaman's Torches into the Peat Clump in the Upper Sumprushes.",starts={{npcID=60857,x=0.678,y=0.676,zoneID=5842}},ends={{npcID=60857,x=0.678,y=0.676,zoneID=5842}},coords={x=0.678,y=0.676,source="quest_giver",zoneID=5842},questType="standard"},
[30789] = {id=30789,name="Arconiss",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="If I am to fight Jahesh, leader of the yaungol mist-shaman, I must have Arconiss by my side. Arconiss ' ferocity is second to none. He rests beneath the mists of the Upper Sumprushes. Find his resting place, and then use these torches to awaken him.",objectivesText="Summon Arconiss by planting the Mist-Shaman's Torches into the Peat Mound in the Upper Sumprushes. Progress: Arconiss ' size belies his prowess in battle. He will be an asset.",starts={{npcID=60857,x=0.678,y=0.676,zoneID=5842}},ends={{npcID=60857,x=0.678,y=0.676,zoneID=5842}},coords={x=0.678,y=0.676,source="quest_giver",zoneID=5842},questType="standard"},
[30790] = {id=30790,name="Golgoss Hungers",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Golgoss' strength is great, but he requires nutrition before he can use it. The snarlthorn bushes in the Upper Sumprushes have heavy, fibrous branches. These should sate his appetite.",objectivesText="Obtain 10 Snarlvines . Progress: Golgoss' hunger is great.",starts={{npcID=60622,x=0.762,y=0.728,zoneID=5842}},ends={{npcID=60622,x=0.762,y=0.728,zoneID=5842}},coords={x=0.762,y=0.728,source="quest_giver",zoneID=5842},questType="standard"},
[30791] = {id=30791,name="Arconiss Thirsts",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Arconiss fights with unmatched fury, but his extended stay beneath the mists has left him weakened. The rodents of the swamp are plentiful, and their bodies are filled with nourishing blood. Return with blood enough to reignite Arconiss' spirit.",objectivesText="Obtain 4 Clotted Rodent's Blood . Progress: Our preparation will not take much longer.",starts={{npcID=60622,x=0.762,y=0.728,zoneID=5842}},ends={{npcID=60622,x=0.762,y=0.728,zoneID=5842}},coords={x=0.762,y=0.728,source="quest_giver",zoneID=5842},questType="standard"},
[30792] = {id=30792,name="Orbiss Fades",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="I knew death would come. I did not know that it would come this fast. I must buy time. The mist of the Upper Sumprushes is warm and fragrant. Such mist is nutritive to my kind. Gather this mist however you can... in jars, in vials, within the interior of your bags. Bring it back to me, and I can use it to remain corporeal for a bit longer.",objectivesText="Obtain 8 Gushing Mists by walking through mist geysers in the Upper Sumprushes.",starts={{npcID=60622,x=0.762,y=0.728,zoneID=5842}},ends={{npcID=60622,x=0.762,y=0.728,zoneID=5842}},coords={x=0.762,y=0.728,source="quest_giver",zoneID=5842},questType="standard"},
[30793] = {id=30793,name="Mists' Opportunity",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Now is the time to strike. Golgoss, Arconiss, and I will go east, into Jahesh's domain. Meet us there, and prepare for battle. Today, we restore the pride of our people.",objectivesText="Slay Jahesh of Osul .",starts={{npcID=60622,x=0.762,y=0.728,zoneID=5842}},ends={{npcID=60622,x=0.762,y=0.728,zoneID=5842}},coords={x=0.762,y=0.728,source="quest_giver",zoneID=5842},questType="standard"},
[30794] = {id=30794,name="Emergency Care",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="I... am alive... but barely. They killed the rest. My friends... and family... I must return to the village... But, I do not have long, and cannot move on my own... are you a healer? I... have a healing potion in my hut... search my belongings. You can use your magic, if you have it.",objectivesText="Heal Sage Liao to get him back on his feet.",starts={{npcID=60694,x=0.606,y=0.214,zoneID=5841}},ends={{npcID=60785,x=0.606,y=0.214,zoneID=5841}},coords={x=0.606,y=0.214,source="quest_giver",zoneID=5841},questType="standard"},
[30795] = {id=30795,name="Staying Connected",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="The Tongue of Ba-Shon should allow us to communicate from long distances, . If the relic works the way I think it will, I should be able to stay here and continue my meditations while you do some scouting in the Valley of Emperors. Mishi will take you to the edge of the valley so that we can test my theory. I would hate for you to be in the tombs with no way to contact me. That would be horrible!",objectivesText="Use the Tongue of Ba-Shon in the Valley of Emperors.",starts={{npcID=60795,x=0.438,y=0.51,zoneID=5841}},ends={{x=0.437,y=0.511,mapID=379,npcID=60795}},coords={x=0.438,y=0.51,source="quest_giver",zoneID=5841},questType="standard"},
[30796] = {id=30796,name="An End to Everything",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="These spirits must have been released when the tombs were opened... Death was not final for the Mogu. Instead, death was merely a stop over on the path to a new body. Spiritbinders used a foul magic to transfer spirits from one shell to the next. Years of being trapped in the tombs has left them confused. They need to be destroyed before their confusion turns to anger or worse, they find a new shell.",objectivesText="Destroy 5 Tormented Spirits . Progress: Have you disposed of the spirits yet?",starts={{x=0.573,y=0.48,mapID=379,npcID=61297}},ends={{x=0.573,y=0.48,mapID=379,npcID=61297}},coords={mapID=379,x=0.573,y=0.48},questType="standard"},
[30797] = {id=30797,name="It Was Almost Alive",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="A ritual took place here, and from the looks of it wasn't successful. Among the abandoned items a book lies open. The text on the pages is foreign to you. Carrying the whole book may be difficult, but a single page might be enough. If you can get the page to Lorewalker Cho he may be able to tell you what it says.",objectivesText="Tear a page from the open book to give to Lorewalker Cho. Progress: What have you found, <name>?",starts={{npcID=211754,x=0.572,y=0.479,zoneID=5841}},ends={{x=0.571,y=0.478,mapID=379,objectID=211754}},coords={x=0.572,y=0.479,source="quest_giver",zoneID=5841},questType="standard"},
[30798] = {id=30798,name="Breaking the Emperor's Shield",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="The Mogu have been scattered and sparse in number for many years. Their purpose in the valley makes sense now. With this many restless spirits they can build themselves an army using the guardians buried in each tomb. Combined with the Zandalari forces this would be devastating! The Tomb of Secrets houses elite warriors called the Emperor's Shield. They must not be resurrected! You'll find the tomb on the highest rise to the southwest.",objectivesText="Stop the Spiritbinding Ritual in the Tomb of Secrets. Progress: Have you gone to the Tomb of Secrets yet?",starts={{x=0.573,y=0.479,mapID=379,npcID=61297}},ends={{x=0.573,y=0.479,mapID=379,npcID=61297}},coords={mapID=379,x=0.573,y=0.479},questType="standard"},
[30799] = {id=30799,name="The Tomb of Shadows",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Given the artifacts you found on the altar, I would guess they were attempting to perform a Spiritbinding ritual. Most of the texts involving Spiritbinding were locked away in the Tomb of Shadows. Perhaps we will find the answers we seek there. Look for anything that might help us. You'll find the tomb on the first rise closest to the ritual altar.",objectivesText="Collect a rubbing of the Shen Dynasty Tablet, the Wai Dynasty Tablet, and the Qiang Dynasty Tablet in the Tomb of Shadows. Progress: Did you find anything in the Tomb of Shadows?",starts={{x=0.571,y=0.478,mapID=379,npcID=61297}},ends={{x=0.571,y=0.478,mapID=379,npcID=61297}},coords={mapID=379,x=0.571,y=0.478},questType="standard"},
[30800] = {id=30800,name="Stealing Their Thunder King",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Our only hope is to find the Thunder King's remains before they do. He must be buried within the Tomb of Conquerors. Getting to his remains will not be easy, . The tomb will no doubt be defended by guardians and other unfriendly surprises intended to ward off thieves. Once inside we will need to figure out where his remains have actually been placed.",objectivesText="Find the Bottom Fragment of Lei Shen's Tablet and restore the Tablet of Thunder. Progress: Have you figured out where the Thunder King's remains are hidden?",starts={{x=0.573,y=0.479,mapID=379,npcID=61297}},ends={{x=0.573,y=0.479,mapID=379,npcID=61297}},coords={mapID=379,x=0.573,y=0.479},questType="standard"},
[30801] = {id=30801,name="Lessons from History",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="The Thunder King was a vicious Emperor and with the Zandalari at his side he was unstoppable. His return would surely return this land to turmoil and misery. You must locate his remains and take them somewhere safe. The Tablet of Thunder should help you figure out how to access his tomb.",objectivesText="Read the Tablet of Thunder in the Tomb of Conquerors. Progress: Have you read the tablet?",starts={{x=0.573,y=0.479,mapID=379,npcID=61297}},ends={{x=0.573,y=0.479,mapID=379,npcID=61297}},coords={mapID=379,x=0.573,y=0.479},questType="standard"},
[30802] = {id=30802,name="Chasing the Storm",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="We need to figure out where they are taking the Thunder King's remains. It won't be possible for them to resurrect him in the Valley of the Emperors. They would need to be somewhere remote and secure. It appears that getting out of here may also prove to be a challenge.... Fight your way out and look for information concerning the location of the remains.",objectivesText="Find the Blood-Revealed Map on a Zandalari Warrior. Progress: Were you able to find any information on their location?",starts={{x=0.338,y=0.631,mapID=385,npcID=61297}},ends={{x=0.338,y=0.631,mapID=385,npcID=61297}},coords={mapID=385,x=0.338,y=0.631},questType="standard"},
[30804] = {id=30804,name="The Fearmaster",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="I am not gonna take this anymore. My wife, bless her, poured her heart and soul in to that ranch making it what it is today. Them yaungol got a leader over there being all smug and what not. I'll pay you handsomely if you knock that smug smile off his filthy, stinking, good for nothing face.",objectivesText="Kill the Fearmaster . Progress: So many strangers in these lands these days. Luckily you <class> seem to be all right.",starts={{npcID=59353,x=0.71,y=0.692,zoneID=5841}},ends={{npcID=59353,x=0.71,y=0.692,zoneID=5841}},coords={x=0.71,y=0.692,source="quest_giver",zoneID=5841},questType="standard"},
[30805] = {id=30805,name="Justice",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="After the mercenaries robbed us, most left. But one of them... after the others took all we had, he ran the rest of us through. For sport! Get justice for the fallen. Perhaps news of their death will raise my spirits enough to go on. You'll find them just west of here.",objectivesText="Kill Captain Ripflesh and 6 Blackmane Mercenaries.",starts={{npcID=60785,x=0.606,y=0.214,zoneID=5841}},ends={{npcID=60785,x=0.606,y=0.214,zoneID=5841}},coords={x=0.606,y=0.214,source="quest_giver",zoneID=5841},questType="standard"},
[30806] = {id=30806,name="The Scent of Life",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="Many have perished here. We will need to honor them properly, which means gathering the makings of incense of life. It doesn't just smell nice - it has restorative properties, and can even help plants grow. Maybe I can get a whiff of the ingredients to get me back on my feet. The materials can be found on creatures around here - except for the spices, which were stolen by the mercenaries who pillaged the village.",objectivesText="Gather an Opalescent Blue Crab Shell and 8 Stolen Pandaren Spices . Progress: Are those the ingredients for Incense of Life I smell on you? Or... perhaps you haven't bathed recently.",starts={{npcID=60785,x=0.606,y=0.214,zoneID=5841}},ends={{npcID=60785,x=0.606,y=0.214,zoneID=5841}},coords={x=0.606,y=0.214,source="quest_giver",zoneID=5841},questType="standard"},
[30807] = {id=30807,name="By the Falls, For the Fallen",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="I do not wish to dishonor my friends and leave them in unmarked graves. Yet, we have never needed to bury so many at once, and I am in no condition to gather materials. Please, visit the lakes that hug the mountains edge along the road to the south. Underneath the waterfalls there, you will find stones that have been polished to a sheen by the falling water. They will make suitable headstones.",objectivesText="Gather 3 Waterfall-polished Stones . Progress: The stones - have you brought them?",starts={{npcID=60785,x=0.606,y=0.214,zoneID=5841}},ends={{npcID=60785,x=0.606,y=0.214,zoneID=5841}},coords={x=0.606,y=0.214,source="quest_giver",zoneID=5841},questType="standard"},
[30808] = {id=30808,name="A Grummle's Luck",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="The yaungols stole our luckydos! Mean riders with spears took them from our caravan of brothers coming down the Burlap Trail. This is very bad fortune. If the yaungol discover the secrets of luckydos all grummles will be in big trouble. Recover our luckydos from Fire Camp Ruqin north of here and we will pay many fortunes to you.",objectivesText="Find 8 Stolen Luckydos . Progress: A luckydo is a thing of much good fortune. Yaungol know nothing of how to use luckydos... yet.",starts={{npcID=59371,x=0.646,y=0.616,zoneID=5841}},ends={{npcID=59371,x=0.646,y=0.616,zoneID=5841}},coords={x=0.646,y=0.616,source="quest_giver",zoneID=5841},questType="standard"},
[30814] = {id=30814,name="A Foot in the Door",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description=", you bear the marks of many a past battle. Good! We need more seasoned people like you to hold back the front. We've managed to secure a foothold here, but the yaungol are desperate to remove our presence. If you wish to prove your worth, go down the hill and show the yaungol that we will not back down.",objectivesText="Kill 8 Osul Chargers . Progress: We are slowly gaining ground.",starts={{npcID=60688,x=0.712,y=0.566,zoneID=5842}},ends={{npcID=60688,x=0.712,y=0.566,zoneID=5842}},coords={x=0.712,y=0.566,source="quest_giver",zoneID=5842},questType="standard"},
[30815] = {id=30815,name="The Death of Me",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="I have resolved to remove this spear from my side. For this, I require your assistance. Your grasping hands are stronger than mine.",objectivesText="Remove the spear from Orbiss .",starts={{npcID=60857,x=0.678,y=0.676,zoneID=5842}},ends={{npcID=60622,x=0.762,y=0.728,zoneID=5842}},coords={x=0.678,y=0.676,source="quest_giver",zoneID=5842},questType="standard"},
[30816] = {id=30816,name="Checking In",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="When the trolls came, they brought their mercenary... friends with them. I saw them go past us, to the fishing camp in the northwest. My cousin, a healer, lives there - can you check in with him and make sure he and his village are well?",objectivesText="Check on Sage Liao at the Zaochin Strand in Kun-Lai Summit .",starts={{npcID=60436,x=0.63,y=0.294,zoneID=5841}},ends={{npcID=60694,x=0.606,y=0.214,zoneID=5841}},coords={x=0.63,y=0.294,source="quest_giver",zoneID=5841},questType="standard"},
[30817] = {id=30817,name="The Healing of Shen-zin Su",level=1,requiredLevel=1,faction="none",expansion=4,zoneID=5736,mapID=378,description="This is what comes of such recklessness. How could he think this was even a possibility? Nevermind, there's no time for that now. We need to act to save Shen-zin Su. Find any healers you can! Rescue them, relieve them - whatever you need to do to get them over here healing the wound. Keep the healers safe at all costs!",objectivesText="Rescue and defend healers until Shen-zin Su's wound is healed.",questType="standard"},
[30818] = {id=30818,name="A New Fate",level=1,requiredLevel=1,faction="none",expansion=4,zoneID=5736,mapID=378,description=", I'm thankful the plan worked, but just barely. We would be sinking to the bottom of the ocean with all of Shen-zin Su if you hadn't been here. I don't think I can ever forgive Ji for this kind of recklessness. There will be plenty of time for reflection, but for now, we need to return to the Temple of Five Dawns. We need to let them know that Shen-zin Su has been saved, and we need to sort out the fates of these new allies.",objectivesText="Return to the Temple of Five Dawns. A cart is waiting near the Skyfire Crash-Site to take you there.",questType="standard"},
[30819] = {id=30819,name="Preparing the Remains",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="Thank you much, friend. After this tragedy, it is good that fortune has smiled on us and sent you. You have gotten justice for my fallen friends, and gathered the necessary materials to honor them. I will gather their bodies, prepare the materials for their funerals, and meet you at the graveyard. In the meantime, however, please return to my cousin and ask him to gather the villagers for the funeral.",objectivesText="Return to Li Hai and tell him about the funeral.",starts={{npcID=60785,x=0.606,y=0.214,zoneID=5841}},ends={{npcID=60436,x=0.63,y=0.294,zoneID=5841}},coords={x=0.606,y=0.214,source="quest_giver",zoneID=5841},questType="standard"},
[30820] = {id=30820,name="A Funeral",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="As I said, I will gather the town - we will be at the funeral. As the one who has done so much to honor our friends, we feel it is only right that you will be the one to light the Incense of Life and usher their spirits to the life beyond.",objectivesText="Attend the funeral and light the Incense of Life. Progress: You must light the incense to honor the dead.",starts={{npcID=60436,x=0.63,y=0.294,zoneID=5841}},ends={{npcID=60757,x=0.67,y=0.332,zoneID=5841}},coords={x=0.63,y=0.294,source="quest_giver",zoneID=5841},questType="standard"},
[30821] = {id=30821,name="The Burlap Grind",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="Alright, it's time to take Kota Kon out for her \"walk.\" We brewed two fresh pots of kafa just for her and she's all fueled up!",objectivesText="Speak with Kota Kon at Kota Basecamp to ride her, then kill 100 Hozen along The Burlap Trail. Progress: Kota Kon's waiting for you! She won't let anyone else ride her.",starts={{npcID=60679,x=0.424,y=0.694,zoneID=5841}},ends={{npcID=60679,x=0.424,y=0.694,zoneID=5841}},coords={x=0.424,y=0.694,source="quest_giver",zoneID=5841},questType="standard"},
[30823] = {id=30823,name="Shut it Down",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="My cousin over at Kota Basecamp mussed up. He mussed up bad. He was too lazy to cut seeds out of kafa berries by hand, but he noticed goots eat the berries up and give back the seeds... in a day or so. He fed everything he had to the goots on Kota Peak and now they're nuts! Chargin' everything that moves. Kota used to be safe for Grummles to gather kafa. Not anymore. Not with them goots. Will you help?",objectivesText="Kill 12 Kafa-Crazed Mountain Goats on Kota Peak.",starts={{npcID=60678,x=0.402,y=0.816,zoneID=5841}},ends={{npcID=60596,x=0.424,y=0.696,zoneID=5841}},coords={x=0.402,y=0.816,source="quest_giver",zoneID=5841},questType="standard"},
[30824] = {id=30824,name="Gourmet Kafa",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="It was a crazy idea: kafa berries go in the goot, seeds come out. Kafa'kota is already rare and worth a fortune, but my cousin's invention--Kafa'goot--is GOURMET. But it's over now. Uncle Keenbean is upset and peak is a muss. All that's left is to collect the rest of the Kafa'goot and never make it again. I won't ask you to gather it--kind of a mussy task, not fit for hero-- just mark it so we can find it easily when the mountain is safe again.",objectivesText="Mark 10 Kafa'goot \"Deposits\" on Kota Peak.",starts={{npcID=60678,x=0.402,y=0.816,zoneID=5841}},ends={{npcID=60596,x=0.424,y=0.696,zoneID=5841}},coords={x=0.402,y=0.816,source="quest_giver",zoneID=5841},questType="standard"},
[30825] = {id=30825,name="Kota Blend",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="Kota Peak is famous for its kafa bushes - no other can survive at this elevation. Grummles make very good living selling Kafa'kota Blend, but it's dangerous now thanks to our cousin. He's got the wildlife up there hooked on kafa with his scheming. Kafa'kota is more scarce than ever with goots gobblin' it up and yetis hoarding it in their caves. Uncle Keenbean will pay you good for any berries you bring down from Kota. Here, take a sample. Eat it. See for yourself the power of kafa.",objectivesText="Collect 100 Kafa'kota Berries from Kota Peak. They can be found in bushes growing on the mountainside or piled up in the yeti caves.",starts={{npcID=60677,x=0.402,y=0.816,zoneID=5841}},ends={{x=0.403,y=0.815,mapID=379,npcID=60677}},coords={x=0.402,y=0.816,source="quest_giver",zoneID=5841},questType="standard"},
[30826] = {id=30826,name="Trouble Brewing",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="Lots of yetis in Kota, yup. Usually not too dangerous. Usually just eat goots. Then stupid Cousin Gootfur over at Kota Basecamp fed kafa to the goots, and the yeti ate them goots. Now they're moody, cranky, sleep a lot but never seem rested. Typical kafa addicts. Gonna come outta those caves soon, I'm sure. Come lookin' for more kafa. Then we all in trouble.",objectivesText="Kill 5 Kafa-Crazed Yetis in the caves on Kota Peak.",starts={{npcID=60677,x=0.402,y=0.816,zoneID=5841}},ends={{npcID=60503,x=0.424,y=0.696,zoneID=5841}},coords={x=0.402,y=0.816,source="quest_giver",zoneID=5841},questType="standard"},
[30827] = {id=30827,name="What Lies Beneath",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="If my suspicions are correct, this place still reels from some lingering darkness. Whatever happened here... it could not have been the natural course of events. Even the yaungol are not so brutal as to slaughter their own kind to the point of... this. I will use the totems that you brought me to perform a cleansing ritual. I need someone to assist me in the ceremony. Let me know when you are ready.",objectivesText="Speak to Yalia Sagewhisper to begin the ceremony. Then, activate the Totem of Kindness , the Totem of Tranquility , and the Totem of Serenity . Progress: I believe that we must drive the taint from this place.",starts={{npcID=60864,x=0.826,y=0.73,zoneID=5842}},ends={{npcID=60864,x=0.826,y=0.73,zoneID=5842}},coords={x=0.826,y=0.73,source="quest_giver",zoneID=5842},questType="standard"},
[30828] = {id=30828,name="Cleansing the Mere",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Pools of the same murky substance that came out of Mei emerged in the lake recently. I will travel into the Mere with you. Point out the pools of corruption that you are ready for me to cleanse. You will need to deal with whatever comes out and protect me as I complete the ritual.",objectivesText="Point out Pools of Corruption in Inkgill Mere to Waterspeaker Gorai to let him know you are ready to defend him while he completes the cleansing ritual. Progress: Is the lake cleansed?",starts={{npcID=60973,x=0.75,y=0.88,zoneID=5841}},ends={{npcID=61065,x=0.71,y=0.826,zoneID=5841}},coords={x=0.75,y=0.88,source="quest_giver",zoneID=5841},questType="standard"},
[30829] = {id=30829,name="The Tongue of Ba-Shon",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Thank you for coming, $p. I am sorry to have been so cryptic, but I could not risk alerting the mogu to my work here. They are seeking something in the valley. Plundering the tombs of their old kings for relics of power. I could not observe them long before having to flee, but I did manage to recover a relic of my own. The Tongue of Ba-Shon will let us communicate securely over long distances, but only after I have bound it to myself. I think I'm ready to begin, if you are.",objectivesText="Assist Lorekeeper Cho in performing the Binding of Ba-Shon. Progress: I'll need to bind my essence to the Tongue, then you can use it to speak with me from anywhere.",starts={{npcID=60795,x=0.438,y=0.51,zoneID=5841}},ends={{npcID=60795,x=0.438,y=0.51,zoneID=5841}},coords={x=0.438,y=0.51,source="quest_giver",zoneID=5841},questType="standard"},
[30834] = {id=30834,name="Father and Child Reunion",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="They survived? My father is alive! I thought we would all die here in this horrible mere, at the hands of these insane Jinyu. I will find my way back - meet me back at camp.",objectivesText="Return to Merchant Shi and Wu-Peng at the southeastern shore of Inkgill Mere in Kun-Lai Summit . Progress: My boy! He is alive!",starts={{npcID=59272,x=0.746,y=0.768,zoneID=5841}},ends={{npcID=59263,x=0.748,y=0.888,zoneID=5841}},coords={x=0.746,y=0.768,source="quest_giver",zoneID=5841},questType="standard"},
[30855] = {id=30855,name="The Fall of Shai Hu",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="I can hear the voice of the Mere - it has been purified. But, this chapter in my people's history will never be closed - not until we defeat Shai Hu . He has retreated to the central island in the Mere, corrupting our holiest of sites. Beware - he is strong. But, after all we have done, I am confident we will be stronger.",objectivesText="Defeat Shai Hu . He can be found at the Waterspeaker's Sanctuary, the island in the center of Inkgill Mere in Kun-Lai Summit .",starts={{npcID=61065,x=0.71,y=0.826,zoneID=5841}},ends={{npcID=60973,x=0.75,y=0.88,zoneID=5841}},coords={x=0.71,y=0.826,source="quest_giver",zoneID=5841},questType="standard"},
[30879] = {id=30879,name="Round 1: Brewmaster Chani",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="Welcome, Challenger, to my tournament of champions! Today we test the strengths of Pandaria's most dedicated heroes. Your first opponent awaits you under the eastern gazebo. Defeat her, and you may proceed to the next round. Fight with strength, fight with honor.",objectivesText="Defeat Brewmaster Chani . Progress: Without conflict, there can be no growth. The need to change, to persevere, to improve, these are the traits that bring champions to my doorstep.",starts={{npcID=60968,x=0.664,y=0.464,zoneID=5841}},ends={{npcID=60968,x=0.664,y=0.464,zoneID=5841}},coords={x=0.664,y=0.464,source="quest_giver",zoneID=5841},questType="standard"},
[30880] = {id=30880,name="Round 1: The Streetfighter",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="Welcome, challenger, to my tournament of champions! Today we test the strengths of Pandaria's most dedicated heroes. Your first opponent awaits you under the eastern gazebo. Defeat her, and you may proceed to the next round. Fight with strength, fight with honor.",objectivesText="Defeat the Streetfighter. Progress: Without conflict, there can be no growth. The need to change, to persevere, to improve, these are the traits that bring champions to my doorstep.",starts={{npcID=60968,x=0.664,y=0.464,zoneID=5841}},ends={{npcID=60968,x=0.664,y=0.464,zoneID=5841}},coords={x=0.664,y=0.464,source="quest_giver",zoneID=5841},questType="standard"},
[30881] = {id=30881,name="Round 2: Clever Ashyo & Ken-Ken",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="You may know your next challengers. They were arguing fiercely when they arrived, so I have charged them with fighting side by side. This will teach them the strength of friendship, and possibly entertain me in the process. Go to the north eastern arena and face this jinyu and hozen. Do not be gentle, they need to learn to work together.",objectivesText="Defeat Clever Ashyo and Ken-Ken . Progress: Strength can come from an ally as much as from one's self.",starts={{npcID=60968,x=0.664,y=0.464,zoneID=5841}},ends={{npcID=60968,x=0.664,y=0.464,zoneID=5841}},coords={x=0.664,y=0.464,source="quest_giver",zoneID=5841},questType="standard"},
[30882] = {id=30882,name="Round 2: Kang Bramblestaff",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="Your next challenger is a Bramblestaff. Strength is in their blood. I remember a full century of only Bramblestaff champions. No pressure, little . Go to the eastern arena north of here and face this young challenger. See first hand if strength is earned or inherited.",objectivesText="Defeat Kang Bramblestaff . Progress: I was once defeated in a match by a Bramblestaff. In my defense, he distracted me with a ball of yarn.",starts={{npcID=60968,x=0.664,y=0.464,zoneID=5841}},ends={{npcID=60968,x=0.664,y=0.464,zoneID=5841}},coords={x=0.664,y=0.464,source="quest_giver",zoneID=5841},questType="standard"},
[30883] = {id=30883,name="Round 3: The Wrestler",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=6006,description="Your next challenger is a favorite of mine. He draws strength from raw force and determination. Plus he has a mask. Face him in the western arena when you are ready, and good luck.",objectivesText="Defeat The Wrestler . Progress: Sometimes strength can come from the outside.",starts={{npcID=60968,x=0.664,y=0.464,zoneID=5841}},ends={{npcID=60968,x=0.664,y=0.464,zoneID=5841}},coords={x=0.664,y=0.464,source="quest_giver",zoneID=5841},questType="standard"},
[30884] = {id=30884,name="Behind the Battlefront",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="This battlefront has been undermanned and unsupplied for too long during my absence in Kun-Lai. We need to get things back in order here before we can pick up the trail of the Sha of Hatred. Taoshi is my best. I've sent her north to investigate rumors of mantid that have somehow made it through the battlefront. I need someone I can trust to get out there and work with her to plug any holes in our defenses. If my reports on you are correct, I can trust you with this, right ?",objectivesText="Meet with Taoshi at Dampsoil Burrow.",starts={{npcID=61066,x=0.764,y=0.824,zoneID=5842}},ends={{npcID=61469,x=0.768,y=0.788,zoneID=5842}},coords={x=0.764,y=0.824,source="quest_giver",zoneID=5842},questType="standard"},
[30885] = {id=30885,name="Round 3: Master Boom Boom",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="Your next challenger found his strength on a beach. Particularly in a box labeled \"dynamite.\" He proves however that found strength can be as deadly as personal strength. When you are ready, face this Master Boom Boom in the Western Arena.",objectivesText="Defeat Master Boom Boom . Progress: Sometimes strength can come from the outside.",starts={{npcID=60968,x=0.664,y=0.464,zoneID=5841}},ends={{npcID=60968,x=0.664,y=0.464,zoneID=5841}},coords={x=0.664,y=0.464,source="quest_giver",zoneID=5841},questType="standard"},
[30887] = {id=30887,name="Unwelcome Intruders",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Those are mantid scouts down there. Gao-Ran's Battlefront is meant to keep them out of eastern Townlong Steppes . If we allow them north of the barricade, we may lose our foothold here. Let's clear them out. I'll be with you.",objectivesText="Kill 12 Krik'thik Deep-scouts with Taoshi 's help.",starts={{npcID=61469,x=0.768,y=0.788,zoneID=5842}},ends={{npcID=61468,x=0.794,y=0.844,zoneID=5842}},coords={x=0.768,y=0.788,source="quest_giver",zoneID=5842},questType="standard"},
[30888] = {id=30888,name="Breach in the Defenses",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Normally, it only takes a few scouts to hold this pass. Most of this territory is in sight of the wall, so archers would devastate any mantid force attempting to push through here. The problem is, most of the archers are occupied with the onslaught at the gate. Take this flare - it will help you locate the mantid that are sneaking through the eastern pass under our diminished watch. Kill any you find. We can't let them lay a trail that might lead the mantid swarms farther into the steppes.",objectivesText="Use the Shado-Pan Flare to aid in killing 10 Krik'thik Scentlayers .",starts={{npcID=61468,x=0.794,y=0.844,zoneID=5842}},ends={{npcID=61468,x=0.794,y=0.844,zoneID=5842}},coords={x=0.794,y=0.844,source="quest_giver",zoneID=5842},questType="standard"},
[30889] = {id=30889,name="Trap Setting",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Good to meet you, . We have traps all along the pass to help us catch mantid that might be sneaking through, but their numbers have been so great that most of the traps have already been triggered. Taoshi said you might be able to reset some of them while you're out there. Can you help?",objectivesText="Rearm 8 Shado-Pan Spike Traps . Progress: These traps have been very effective, the mantid numbers are just getting out of hand in these past weeks.",starts={{npcID=61467,x=0.794,y=0.844,zoneID=5842}},ends={{npcID=61467,x=0.794,y=0.844,zoneID=5842}},coords={x=0.794,y=0.844,source="quest_giver",zoneID=5842},questType="standard"},
[30890] = {id=30890,name="The Restless Watch",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="I'm being told that our scouts have been on duty in Shallowstep Pass for more than 2 days straight, no rest. No wonder mantid are slipping through. Even the most dedicated scouts would slip with those kinds of shifts. I want you to go out there and deliver orders to the scouts that they are to return to the battlefront immediately for rest and rations. I'll arrange for a new shift to be posted.",objectivesText="Deliver return orders to Scout Wei-Chin , Scout Long , Scout Ying , and Scout Jai-Gan . Progress: This whole battlefront is being worked to the bone. We need more men out here.",starts={{npcID=61468,x=0.794,y=0.844,zoneID=5842}},ends={{npcID=61468,x=0.794,y=0.844,zoneID=5842}},coords={x=0.794,y=0.844,source="quest_giver",zoneID=5842},questType="standard"},
[30891] = {id=30891,name="Treatment for the Troops",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="A new face! Pleasure to meet you. I'm Septi. I keep the Shado-Pan fighting. The mantid have poison that chews through the skin and infects the blood. It makes for a slow, excruciating death when not treated. I need pollen from the violet citron flowers. The nearest place to find them is around Dampsoil Burrow just north of the battlefront. If you happen to go in that direction, could you bring some back for me?",objectivesText="Collect 10 Violet Citron . Progress: Mixed properly, the pollen from these flowers can eat away at the poison without doing any lasting damage to the body otherwise.",starts={{npcID=61470,x=0.758,y=0.83,zoneID=5842}},ends={{npcID=61470,x=0.758,y=0.83,zoneID=5842}},coords={x=0.758,y=0.83,source="quest_giver",zoneID=5842},questType="standard"},
[30892] = {id=30892,name="Back on Their Feet",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=422,description=", I could use your help. With their long shifts, our warriors down at the southern front of the battlefront are fighting to the point of exhaustion, and many of them have been exposed to the mantid poison. We need more people to tend to the wounded. I've prepared some bandages with the herbs you brought me, but if you have some healing skills, those might work even better. Please, , get our men back on their feet so that they can get back here to safety.",objectivesText="Heal 8 Injured Gao-Ran Blackguards . Progress: With the constant mantid attacks, the men are being worked to the bone. We are undermanned on all fronts. Your help means a lot to us, <name>.",starts={{npcID=61470,x=0.758,y=0.83,zoneID=5842}},ends={{npcID=61470,x=0.758,y=0.83,zoneID=5842}},coords={x=0.758,y=0.83,source="quest_giver",zoneID=5842},questType="standard"},
[30893] = {id=30893,name="The Endless Swarm",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Gao-ran's men need help down on the southern front. If you want to stand by the Shado-Pan, that's where you should do it.",objectivesText="Kill 12 Krik'thik attackers at the Gao-Ran Battlefront.",starts={{npcID=61066,x=0.764,y=0.824,zoneID=5842}},ends={{npcID=61066,x=0.764,y=0.824,zoneID=5842}},coords={x=0.764,y=0.824,source="quest_giver",zoneID=5842},questType="standard"},
[30894] = {id=30894,name="Rummaging Through the Remains",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="I do have another task for you, , though it's a might grim. I really need to get to the bottom of this mantid poison, but to do that, I need more information directly from the source. While you're down on the southern battlefield, could you bring me back some mantid limbs so that I can examine their intact poison glands.",objectivesText="Recover 20 Krik'thik Limbs . Progress: I'm hoping to find a permanent counter to the mantid poison so that the men won't be afflicted in the first place. It may take some time to piece it together.",starts={{npcID=61470,x=0.758,y=0.83,zoneID=5842}},ends={{npcID=61470,x=0.758,y=0.83,zoneID=5842}},coords={x=0.758,y=0.83,source="quest_giver",zoneID=5842},questType="standard"},
[30895] = {id=30895,name="Improvised Ammunition",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=6138,mapID=388,description="I've got another job for you. The dragon cannons we depend on to keep the thicker swathes of mantid back are running low on ammo. The camp's cannoneers developed an improvised explosive that's made from the globe seeds down the western ridge. They dispatched a couple initiates to bring some back hours ago, but have heard nothing from them. I want to send someone a bit more capable to make sure that this gets taken care of. Are you my for this?",objectivesText="Recover 16 Volatile Dread Orbs from the Ambermarsh. Progress: Back even more quickly than expected. Did you bring the seeds?",starts={{npcID=61066,x=0.764,y=0.824,zoneID=5842}},ends={{npcID=61066,x=0.764,y=0.824,zoneID=5842}},coords={x=0.764,y=0.824,source="quest_giver",zoneID=5842},questType="standard"},
[30896] = {id=30896,name="Thieves and Troublemakers",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=6138,mapID=422,description="I can't catch the little buggers for the life of me. Kill any you can get your hands on. And keep a close eye on your valuables, they like to steal anything that isn't tied down.",objectivesText="Kill 10 Agitated Nettleskins. Progress: I haven't hated plants so much since my job back at Halfhill.",starts={{npcID=61881,x=0.704,y=0.864,zoneID=5842}},ends={{npcID=61881,x=0.704,y=0.864,zoneID=5842}},coords={x=0.704,y=0.864,source="quest_giver",zoneID=5842},questType="standard"},
[30897] = {id=30897,name="In the Wrong Hands",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Look... um... this is really embarrassing. I set down my sword for like ONE SECOND to gather some orbs, and a big sprite sprung out of nowhere, snatched it, and bounded off down the western gap. I can't go back to camp without it. Losing your weapon is a sure way to get kicked out of the Shado-Pan. It's sacred. Please, can you try to find this big sprite and get my sword back? It would mean a lot to me.",objectivesText="Recover Initiate Chao's Sword . Progress: My mom warned me this was going to happen...",starts={{npcID=61880,x=0.704,y=0.866,zoneID=5842}},ends={{npcID=61880,x=0.704,y=0.866,zoneID=5842}},coords={x=0.704,y=0.866,source="quest_giver",zoneID=5842},questType="standard"},
[30898] = {id=30898,name="Cutting the Swarm",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="The mantid numbers have been increasing since you left for the cleft. Let's put these orbs you gathered to use. Get down on the battlefront and man one of the cannons. Let none through.",objectivesText="Use a Dragon Launcher to kill 50 swarming mantid. Progress: I can't remember the last time they swarmed this thickly. They probably haven't within my lifetime.",starts={{npcID=61066,x=0.764,y=0.824,zoneID=5842}},ends={{npcID=61021,x=0.764,y=0.824,zoneID=5842}},coords={x=0.764,y=0.824,source="quest_giver",zoneID=5842},questType="standard"},
[30899] = {id=30899,name="In Skilled Hands",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description=", take these crossbow bolts and then bring them to Hawkmaster Nurong at Farwatch Overlook to the southwest. Nurong is praised among all the Wukao for being a flawless shot. His efforts are credited with holding the line here for these many months. I'm hoping you can work with him and judge for yourself. He may be the final Shado-Pan we need for the hunt.",objectivesText="Bring the Shado-Pan Crossbow Bolt Bundle to Hawkmaster Nurong . Progress: Another wave of fliers approaches. Be ready.",starts={{npcID=62274,x=0.54,y=0.78,zoneID=5842}},ends={{npcID=61020,x=0.516,y=0.872,zoneID=5842}},coords={x=0.54,y=0.78,source="quest_giver",zoneID=5842},questType="standard"},
[30900] = {id=30900,name="Terror of the Dread Wastes",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="That thing is huge! The Shado-Pan holding the battlefront were never trained for something like this... let's get down there and take it out ourselves.",objectivesText="Defeat Norvakess , the Terror of the Dread Wastes. Progress: I've never seen anything like this...",starts={{npcID=61021,x=0.764,y=0.824,zoneID=5842}},ends={{npcID=61066,x=0.764,y=0.824,zoneID=5842}},coords={x=0.764,y=0.824,source="quest_giver",zoneID=5842},questType="standard"},
[30901] = {id=30901,name="Along the Southern Front",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="I'm heading westward with Taoshi to gather the strongest I can find to confront the Sha of Hatred. I would like you to come with me.",objectivesText="Ride with Taran Zhu and Taoshi to Dusklight Hollow.",starts={{npcID=61066,x=0.764,y=0.824,zoneID=5842}},ends={{npcID=62436,x=0.674,y=0.808,zoneID=5842}},coords={x=0.764,y=0.824,source="quest_giver",zoneID=5842},questType="standard"},
[30902] = {id=30902,name="Round 4: Master Windfur",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="Well done, challenger. You have reached the final round. Your last opponent is a powerful master of the winds. He has defended his people for many years and stood as champion on more than one occasion. Face this Master Windfur in the main arena when you are ready. And challenger... good luck.",objectivesText="Defeat Master Windfur . Progress: The Master Windfur 's strength is in the air and winds around him. He has rivaled elementals in his control of such forces.",starts={{npcID=60968,x=0.664,y=0.464,zoneID=5841}},ends={{npcID=60968,x=0.664,y=0.464,zoneID=5841}},coords={x=0.664,y=0.464,source="quest_giver",zoneID=5841},questType="standard"},
[30907] = {id=30907,name="Round 4: The P.U.G.",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="And now the final round. I have selected three challengers for you to face. This may seem unfair... to a weakling. You are not a weakling, correct? Go to the main temple, stand in the grand arena, and face these three challengers. Prove you are stronger than their combined power! Good luck, Challenger!",objectivesText="Defeat Hackiss , Healiss and Tankiss . Progress: Some find strength in numbers. I respect this idea, when it is properly executed.",starts={{npcID=60968,x=0.664,y=0.464,zoneID=5841}},ends={{npcID=60968,x=0.664,y=0.464,zoneID=5841}},coords={x=0.664,y=0.464,source="quest_giver",zoneID=5841},questType="standard"},
[30910] = {id=30910,name="Greenstone Village",level=1,requiredLevel=1,faction="both",expansion=4,description="Please help! We paid some adventurers to run off all the elemental spirits and now they're back for revenge!",objectivesText="Rescue all the villagers.",questType="standard"},
[30918] = {id=30918,name="Hui's Vengeance",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6209,description="I am ashamed to ask, but for Greenstone's sake... might we now trouble you to face Vengeful Hui on our behalf...?",objectivesText="Defeat Vengeful Hui .",questType="standard"},
[30921] = {id=30921,name="The Motives of the Mantid",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description=". You may be of assistance. The Shado-Pan wishes to know why the mantid are attacking so violently. We have our suspicions, but we cannot be sure. Furthermore, we do not want the mantid to know that we are investigating them. That's where you come in. I need you to kill the mantid of Kri'vess, in the north. I will lurk behind you in the shadows, and search for clues on their bodies.",objectivesText="Slay mantid in Kri'vess so Tai Ho can look for clues on their bodies.",starts={{npcID=61482,x=0.492,y=0.712,zoneID=5842}},ends={{npcID=61482,x=0.492,y=0.712,zoneID=5842}},coords={x=0.492,y=0.712,source="quest_giver",zoneID=5842},questType="standard"},
[30922] = {id=30922,name="Natural Antiseptic",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="The Shado-Pan are rare, elite, and quite expensive to train and replace. We can't afford to have any falling to a poisoned weapon or an infected cut. That's why I need you to get... something. Let me be blunt. Mushan urine is a great, natural antiseptic. They produce a large amount of it, which is lucky... because we tend to use a lot.",objectivesText="Obtain 5 Full Mushan Bladders . Progress: It's messy work, certainly. Nowhere near as messy as digging graves.",starts={{npcID=61625,x=0.492,y=0.712,zoneID=5842}},ends={{npcID=61625,x=0.492,y=0.712,zoneID=5842}},coords={x=0.492,y=0.712,source="quest_giver",zoneID=5842},questType="standard"},
[30923] = {id=30923,name="Set the Mantid Back",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Every day, the mantid build up munitions for use on their enemies. We cannot stop them, just you and I... but we can set them back. Tai Ho hands you some explosives.> I need to keep a low profile. Would you do the honors?",objectivesText="Use Gunpowder Casks to explode the Kri'thik Weapons and the Kri'thik Supplies in Kri'vess.",starts={{npcID=61482,x=0.492,y=0.712,zoneID=5842}},ends={{npcID=61482,x=0.492,y=0.712,zoneID=5842}},coords={x=0.492,y=0.712,source="quest_giver",zoneID=5842},questType="standard"},
[30924] = {id=30924,name="The Wisdom of Niuzao",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Niuzao, the Black Ox, rests in the temple to the west. He may know why the mantid are attacking. He may, in fact, know much more than that. I will rendezvous with you at Niuzao Temple, .",objectivesText="Speak with Ogo the Younger at Niuzao Temple in the Townlong Steppes .",starts={{npcID=61482,x=0.492,y=0.712,zoneID=5842}},ends={{npcID=61581,x=0.392,y=0.622,zoneID=5842}},coords={x=0.492,y=0.712,source="quest_giver",zoneID=5842},questType="standard"},
[30925] = {id=30925,name="Niuzao's Price",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Niuzao owns a statuette which he values greatly: a small icon, in his image, sculpted by one of his long-since fallen sentinels. This statuette was recently stolen by the Sra'thik mantid, and taken to their encampment to our north. Bring back this statuette. Then we will give you - and your Shado-Pan associate - the answers you seek.",objectivesText="Kill the mantid of the Sra'thik Incursion so that Tai Ho can search their bodies for pieces of Niuzao's statuette. Progress: Niuzao does not move quickly, nor does he make rash decisions. Perform his task, and give him time to decide.",starts={{npcID=61581,x=0.392,y=0.622,zoneID=5842}},ends={{npcID=61581,x=0.392,y=0.622,zoneID=5842}},coords={x=0.392,y=0.622,source="quest_giver",zoneID=5842},questType="standard"},
[30926] = {id=30926,name="The Terrible Truth",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=389,description="It is with a heavy heart that I confirm your suspicions. The mantid are indeed under the sway of the Sha of Fear. It was OUR sworn duty to confine that creature beneath our temple. Unfortunately, our vigil faltered, our defenses buckled, and the sha escaped. It is with the mantid now. See for yourself. The mantid burrowed into the western side of our island.",objectivesText="Investigate the Niuzao Catacombs, then slay the Dread Shadow that dwells within.",starts={{npcID=61580,x=0.392,y=0.622,zoneID=5842}},ends={{npcID=61482,x=0.492,y=0.712,zoneID=5842}},coords={x=0.392,y=0.622,source="quest_giver",zoneID=5842},questType="standard"},
[30927] = {id=30927,name="Give Them Peace",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="I overheard. Our secret is out, then. When I learned that the mantid had burrowed beneath our temple, I reacted hastily. I sent dozens of guardians to defend what they could, but they were not prepared. They succumbed to fear, and never returned. A pandaren deserves to die embracing the ground, as he does in sleep... not flat on his back with his eyes transfixed in terror. Please, . Give them the peace they deserve.",objectivesText="Give peace to 10 Fear-Stricken Sentinels by closing their eyes and placing them on their bellies. Progress: I should have gone with them.",starts={{npcID=61584,x=0.394,y=0.62,zoneID=5842}},ends={{npcID=61584,x=0.394,y=0.62,zoneID=5842}},coords={x=0.394,y=0.62,source="quest_giver",zoneID=5842},questType="standard"},
[30928] = {id=30928,name="A Trail of Fear",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="You now know Niuzao's secret. We are not only the wardens of this temple... we were the wardens of the Sha of Fear that was buried beneath it. The Sha itself may have escaped... but it left traces behind. If you're truly going down into the catacombs, you should eliminate those traces, before they escape and cause greater problems than those we already face.",starts={{npcID=61585,x=0.392,y=0.62,mapID=388}},ends={{npcID=61585,x=0.392,y=0.62,mapID=388}},coords={x=0.392,y=0.62,source="quest_giver",mapID=388},questType="standard"},
[30929] = {id=30929,name="Bad Yak",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Is this the place where they replace defective yaks? Can anybody help me out, here?",objectivesText="Help Bluesaddle replace his defective yak. Progress: This yak is not a good yak. Not at all.",starts={{npcID=61161,x=0.392,y=0.62,zoneID=5842}},ends={{npcID=61161,x=0.392,y=0.62,zoneID=5842}},coords={x=0.392,y=0.62,source="quest_giver",zoneID=5842},questType="standard"},
[30930] = {id=30930,name="Pick a Yak",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="I can't find a single good yak here. ALL the yaks are bad! Some are too stinky, some too fight-y, others just scared. You look like a lucky . Here, take a lasso. See if you can find a good yak for me.",objectivesText="Use the Yak Lasso on Wild Townlong Yaks, then fight against them to see if they are suitable for Bluesaddle . Progress: See? I told you! No good yaks.",starts={{npcID=61161,x=0.392,y=0.62,zoneID=5842}},ends={{npcID=61161,x=0.392,y=0.62,zoneID=5842}},coords={x=0.392,y=0.62,source="quest_giver",zoneID=5842},questType="standard"},
[30931] = {id=30931,name="My Father's Crossbow",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="I came here to visit my dad at the temple. As soon as I got here, I saw the most terrifying thing I've ever seen. It was a mantid, walking right past me, carrying my father's crossbow . Something's happened to my dad! We've got to find out what it is... but first, we'll need his crossbow back. I saw him heading west, behind the temple.",objectivesText="Obtain Ku-Yao's Crossbow. Progress: Did... did you find it?",starts={{npcID=61539,x=0.394,y=0.618,zoneID=5842}},ends={{npcID=61539,x=0.394,y=0.618,zoneID=5842}},coords={x=0.394,y=0.618,source="quest_giver",zoneID=5842},questType="standard"},
[30932] = {id=30932,name="Father's Footsteps",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Yes, the boy's father - Sentinel Ku-Yao - has gone missing. He could be any number of places... we have no shortage of enemies these days. You're free to look around, if you wish. You might start by looking for his yak, or by asking Sentinel Yalo what he knows.",objectivesText="Find Father's Bedroll , Father's Shield , Ha-Cha , and Sentinel Yalo . Progress: Any luck?",starts={{npcID=61584,x=0.394,y=0.62,zoneID=5842}},ends={{npcID=61539,x=0.394,y=0.618,zoneID=5842}},coords={x=0.394,y=0.62,source="quest_giver",zoneID=5842},questType="standard"},
[30933] = {id=30933,name="Seeking Father",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="I've searched everywhere... but I haven't found my father. I KNOW he's alive still. He just needs his crossbow... then he'll be OK. I've heard that you Shado-Pan guys sometimes fight the mantid on Sra'vess. I don't have any way of getting there. If you ever go over there, can you look for my dad?",objectivesText="Search for Sentinel Ku-Yao . Progress: I know he's OK.",starts={{npcID=65341,x=0.486,y=0.71,zoneID=5842}},ends={{npcID=65341,x=0.486,y=0.71,zoneID=5842}},coords={x=0.486,y=0.71,source="quest_giver",zoneID=5842},questType="standard"},
[30935] = {id=30935,name="Fisherman's Tale",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="The villagers of Zouchin know the coast better than anyone in Kun-Lai. If the Zandalari are hiding on one of the islands, they will know. Mishi will take you as far as Emperor's Path. I will go ahead to speak with the village elders. Follow the path to Whispercloud Rise. Shin Whispercloud will help you reach the village.",objectivesText="Speak with Mishi to travel to the Path of Conquerors. From there find Shin Whispercloud at Whispercloud Rise.",starts={{x=0.64,y=0.733,mapID=379,npcID=61297}},ends={{npcID=61371,x=0.624,y=0.292,zoneID=5841}},coords={mapID=379,x=0.64,y=0.733},questType="standard"},
[30942] = {id=30942,name="Make A Fighter Out of Me",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Shhh! Don't speak so loudly! My father might hear you. Shomi gestures to Steelbender Doshu.> My father is delusional! He thinks I should be studying my tea pouring while our village is under attack. It's ridiculous! I have just as much courage as any man. I just don't know how to fight... yet. That's where you come in. Let me travel with you! I'm a fast learner and I won't get in the way I promise! Pleaseeeeee! If we get separated I'll meet you back in the village.",objectivesText="Kill 4 Amani Skirmishers, 4 Gurubashi Hexxers, and 3 Drakkari Frostweavers in Zouchin Province. Progress: I'll show my father he's wrong about me!",starts={{npcID=61503,x=0.636,y=0.306,zoneID=5841}},ends={{npcID=61503,x=0.636,y=0.306,zoneID=5841}},coords={x=0.636,y=0.306,source="quest_giver",zoneID=5841},questType="standard"},
[30943] = {id=30943,name="Handle With Care",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="I've seen the numbers these invaders have brought with them, this will not be an easy victory. I do know of one thing that may help us gain an advantage. There is a plant that grows around the village that can be used to make a rather effective explosive liquid. If you can gather enough I can begin brewing the mixture. The plant you are looking for is appropriately named volatile bloom. Handle it with care, .",objectivesText="Bring Elder Shu 50 Volatile Blooms. Progress: Were you able to find a suitable amount of volatile blooms?",starts={{npcID=61495,x=0.634,y=0.288,zoneID=5841}},ends={{npcID=61495,x=0.634,y=0.288,zoneID=5841}},coords={x=0.634,y=0.288,source="quest_giver",zoneID=5841},questType="standard"},
[30944] = {id=30944,name="It Takes A Village",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="The villagers have been guarding Zouchin since the first attack. They are exhausted and many are injured. If the Zandalari attack again the last thing we need is for the defenders to fall asleep on the job. Relieve them of their posts so that they might have time to heal and see their families. You'll find them stationed around the village.",objectivesText="Relieve the Exhausted Defenders from their guard posts. Progress: Are the villagers recovering?",starts={{npcID=61371,x=0.624,y=0.292,zoneID=5841}},ends={{npcID=61371,x=0.624,y=0.292,zoneID=5841}},coords={x=0.624,y=0.292,source="quest_giver",zoneID=5841},questType="standard"},
[30945] = {id=30945,name="What's Yours Is Mine",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="The elders want us to mount a defense? We're not monks, ; we need weapons if we hope to fight! Scavenge some arms from those barbarians for me. I should be able to melt them down and make something more suitable for our villagers to fight with. Bring me as many as you can carry and I'll take care of the rest.",objectivesText="Retrieve 6 Stolen Weapons from the Zandalari Invaders. Progress: We'll need more than luck to get us through this. I hope you found something I can work with.",starts={{npcID=61496,x=0.632,y=0.306,zoneID=5841}},ends={{npcID=61496,x=0.632,y=0.306,zoneID=5841}},coords={x=0.632,y=0.306,source="quest_giver",zoneID=5841},questType="standard"},
[30946] = {id=30946,name="Revelations",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="The prisoner is being kept upstairs, . It will be difficult to get information from him, but even the slightest detail about their location will help. The elders have begun questioning him already. With their help we should be able to figure out our next move. Go speak with him and see if he has any useful information.",objectivesText="Speak with the Zandalari Prisoner . Progress: What did the prisoner have to say?",starts={{npcID=63750,x=0.622,y=0.29,zoneID=5841},{npcID=63784,x=0.624,y=0.292,zoneID=5841}},ends={{npcID=63784,x=0.624,y=0.292,zoneID=5841}},coords={x=0.622,y=0.29,source="quest_giver",zoneID=5841},questType="standard"},
[30952] = {id=30952,name="The Unending Siege",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="The mantid continue to attack us. Their numbers ebb and flow, but they do not stop. It is no matter. The yak is stamina embodied. We will not bend to them. We will defend his home forever. Will you help us?",objectivesText="Defeat 12 Sra'thik attackers at Niuzao Temple.",starts={{npcID=61580,x=0.392,y=0.622,zoneID=5842}},ends={{npcID=61580,x=0.392,y=0.622,zoneID=5842}},coords={x=0.392,y=0.622,source="quest_giver",zoneID=5842},questType="standard"},
[30953] = {id=30953,name="Fallen Sentinels",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Our sentinels can fight for days on end, but even they have their limits. Since the mantid swarm began, too many of them have pushed themselves beyond their abilities. Please, aid them in whatever way you can. If you are unable to heal them yourself, you may give them some of this. A mouthful of nutritious yak's milk will give them the strength they need.",objectivesText="Heal 8 Wounded Niuzao Sentinels above 50% health. You may use the Yak's Milk Flasks or your own healing spells and abilities. Progress: Things look grim out there.",starts={{npcID=61585,x=0.392,y=0.62,zoneID=5842}},ends={{npcID=61585,x=0.392,y=0.62,zoneID=5842}},coords={x=0.392,y=0.62,source="quest_giver",zoneID=5842},questType="standard"},
[30954] = {id=30954,name="A Blade is a Blade",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="This is no time to hold to tradition. Our masons' calloused hands bleed and tremble. Our blacksmiths cannot forge weapons as quickly as our sentinels can break them. It is time to fight smart. Many of the mantid come bearing weapons, and when they die, they simply leave them on the battlefield. It would be a shame to see them go to waste.",objectivesText="Obtain 10 Sra'thik Weapons . Progress: Our men are accustomed to fighting with maces and clubs. Unfortunatly, we have little time for customs.",starts={{npcID=61581,x=0.392,y=0.622,zoneID=5842}},ends={{npcID=61581,x=0.392,y=0.622,zoneID=5842}},coords={x=0.392,y=0.622,source="quest_giver",zoneID=5842},questType="standard"},
[30955] = {id=30955,name="Paying Tribute",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Our patron Niuzao is a mountain on wheels... very difficult to move, even more difficult to stop. My point: once we get him moving, the mantid will have their arms full trying to slow him down. The easiest way to get him moving is to put food in front of him. Luckily for us, food in our temple is plentiful... even in wartime. I will send one of my strongarms with you, to shoulder the load.",objectivesText="Obtain 6 stores of Niuzao Food. Your Niuzao Strongarm will carry the food for you. Progress: Niuzao, please... it is time to join the battle...",starts={{npcID=61583,x=0.388,y=0.624,zoneID=5842}},ends={{npcID=61583,x=0.388,y=0.624,zoneID=5842}},coords={x=0.388,y=0.624,source="quest_giver",zoneID=5842},questType="standard"},
[30956] = {id=30956,name="The Siege Swells",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Today's mantid swarm is among the worst I've seen. We are lucky to have Niuzao join us in battle. Help him, . Return to the courtyard, and join in the defense of our temple.",objectivesText="Defeat 25 Sra'thik attackers at Niuzao Temple.",starts={{npcID=61580,x=0.392,y=0.622,zoneID=5842}},ends={{npcID=61580,x=0.392,y=0.622,zoneID=5842}},coords={x=0.392,y=0.622,source="quest_giver",zoneID=5842},questType="standard"},
[30957] = {id=30957,name="The Overwhelming Swarm",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="I command the sentinels of Niuzao. Every defender out there can hold his own against the mantid swarm. The kunchong, however, are something different. They are massive, violent, and without a question the biggest threat to my sentinels' lives. Only Niuzao stands a chance against them. Niuzao... and perhaps you.",objectivesText="Defeat 4 Sra'thik Kunchong . Progress: Stay stalwart, <race>. The kunchong would have their way with you.",starts={{npcID=61584,x=0.394,y=0.62,zoneID=5842}},ends={{npcID=61584,x=0.394,y=0.62,zoneID=5842}},coords={x=0.394,y=0.62,source="quest_giver",zoneID=5842},questType="standard"},
[30958] = {id=30958,name="In Battle's Shadow",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Niuzao's appearance on the battlefield is a blessing... in more ways than one. With the distraction that he's caused, our stonemasons have seized the opportunity to build up our crumbling walls. They could use your help. Toss any loose bricks you find up their way. And hurry! Niuzao will not rampage forever.",objectivesText="Throw 10 Loose Stones up to Niuzao Stonemasons. Progress: I recommend you move with haste. Niuzao's distraction will not last forever.",starts={{npcID=61583,x=0.388,y=0.624,zoneID=5842}},ends={{npcID=61585,x=0.392,y=0.62,zoneID=5842}},coords={x=0.388,y=0.624,source="quest_giver",zoneID=5842},questType="standard"},
[30959] = {id=30959,name="The Big Guns",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="The mantid now surround the Temple with their infernal war wagons. The sooner we are rid of those things, the better. You could destroy them with your own weapons and spells, but this will work much faster. Beware of retaliation from mantid that remain be inside the war wagon when it explodes. In fact, I'd stay as far away from those things as possible.",objectivesText="Destroy 3 Sra'thik War Wagons . Progress: We can push these mantid back. We can outlast them.",starts={{npcID=61581,x=0.392,y=0.622,zoneID=5842}},ends={{npcID=61581,x=0.392,y=0.622,zoneID=5842}},coords={x=0.392,y=0.622,source="quest_giver",zoneID=5842},questType="standard"},
[30960] = {id=30960,name="Returning from the Pass",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="I still have some cleanup to do here in the pass - there are some mantid still making it through. You're a valuable person to have at hand though, and I know Taran wouldn't appreciate me keeping you longer for such basic work. Taran should still be in the main camp with Gao-Ran. Report back in. I'll catch up with you a bit later.",objectivesText="Report in to Taran Zhu at the Gao-Ran Battlefront.",starts={{npcID=61468,x=0.794,y=0.844,zoneID=5842}},ends={{npcID=61066,x=0.764,y=0.824,zoneID=5842}},coords={x=0.794,y=0.844,source="quest_giver",zoneID=5842},questType="standard"},
[30961] = {id=30961,name="Savior of the Inkgill",level=0,requiredLevel=0,faction="none",expansion=4,description="I will go now to return to my kinsmen. Please visit us back at the southwestern edge of the Mere, so that we may thank you.",objectivesText="Speak with Waterspeaker Gorai at the southwestern edge of Jinyu Mere.",questType="standard"},
[30963] = {id=30963,name="The Field Armorer",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="The Shado-Pan fight. As such, their armor often gets cut, scratched, torn, and burned. And it's my job to repair it. I'm no armorer, but I can repair a broken piece of mail as long as the hole's not too big. I prefer to use shell fragments from the tortoises that live in the wild fields to the northeast. Get some for me, and I can keep more Shado-Pan armored and alive.",objectivesText="Obtain 120 Rankbite Shell Fragments . Progress: I refuse to let one of our kind fall just because of a broken set of armor.",starts={{npcID=61625,x=0.492,y=0.712,zoneID=5842}},ends={{npcID=61625,x=0.492,y=0.712,zoneID=5842}},coords={x=0.492,y=0.712,source="quest_giver",zoneID=5842},questType="standard"},
[30964] = {id=30964,name="A Proper Poultice",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="A dry bandage doesn't do much good, other than maybe keeping bugs out of the wound. In some camps, that's the best you can hope for. Not in my camp, though. I prefer to make a paste from whatever soothing herbs I can find, and layer that between bandages. The most soothing herbs I've been able to find in the field are the Mao-Willows from the fields in the northeast. If you run into any, bring them back.",objectivesText="Obtain 11 Mao-Willows . Progress: Any luck out there, <name>?",starts={{npcID=61625,x=0.492,y=0.712,zoneID=5842}},ends={{npcID=61625,x=0.492,y=0.712,zoneID=5842}},coords={x=0.492,y=0.712,source="quest_giver",zoneID=5842},questType="standard"},
[30967] = {id=30967,name="Free the Dissenters",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Not all of my fellow villagers from Inkgill are corrupted. Many heeded my warnings and did not drink of the sha-tainted waters. They are in hiding, terrified, and intimidated by the guards. Please, tell them there is hope! Go into the village to the north. Speak with them and send them to me.",objectivesText="Rescue 6 Inkgill Dissenters in Inkgill Mere.",starts={{npcID=60973,x=0.75,y=0.88,zoneID=5841}},ends={{npcID=60973,x=0.75,y=0.88,zoneID=5841}},coords={x=0.75,y=0.88,source="quest_giver",zoneID=5841},questType="standard"},
[30968] = {id=30968,name="The Sha of Hatred",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="The end of our hunt is upon us. We have gathered the strongest the Shado-Pan have to offer, and with your strength to aid us, we will defeat the Sha of Hatred and choke out its influence on the world. When we enter the tunnel, stay close, and keep hatred clear from your heart. The fight ahead will put all of us to the test. Whatever happens, it has been an honor traveling beside you, .",objectivesText="Defeat the Sha of Hatred .",starts={{npcID=62275,x=0.474,y=0.788,zoneID=5842}},ends={{npcID=62802,x=0.46,y=0.824,zoneID=5842}},coords={x=0.474,y=0.788,source="quest_giver",zoneID=5842},questType="standard"},
[30969] = {id=30969,name="A New Enemy",level=7,requiredLevel=7,faction="horde",expansion=4,zoneID=2437,description="The power of these Dark Shaman has attracted many allies, . Former members of the Horde that now work towards some dark purpose. We need to make an example of them before we have another twilight's hammer on our hands. Kill any cultist you come across and bring me their insignia.",objectivesText="Collect 5 Corrupted Insignia from any cultist in Ragefire Chasm . Progress: Have you collected the insignia?",starts={{npcID=61716}},questType="dungeon"},
[30970] = {id=30970,name="Enraged By Hatred",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="These scorpions are infected with sha. It seems to have driven them out of their hole and into our camp, seething with hatred at invaders in their territory. We need to clear the scorpions and secure the camp. Kill any you find.",objectivesText="Kill 9 Seething Fleshrippers . Progress: The Sha of Hatred's passing did this to them. I doubt this is the only thing that will have been affected by its passing.",starts={{npcID=62436,x=0.674,y=0.808,zoneID=5842}},ends={{npcID=62436,x=0.674,y=0.808,zoneID=5842}},coords={x=0.674,y=0.808,source="quest_giver",zoneID=5842},questType="standard"},
[30971] = {id=30971,name="Taking Stock",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="I was dispatched back to camp to gather pitch-tipped arrows for our archers at the bridge, and this is what I came to. I trained with most of these pandaren... I wasn't prepared for this. Still, the archers at the bridge need our help. If you could help gather arrows from the wreckage, then maybe we can salvage something from this horror.",objectivesText="Gather 120 Shado-Pan Fire Arrows . Progress: The pandaren at the bridge are depending on us...",starts={{npcID=62124,x=0.674,y=0.806,zoneID=5842}},ends={{npcID=62124,x=0.674,y=0.806,zoneID=5842}},coords={x=0.674,y=0.806,source="quest_giver",zoneID=5842},questType="standard"},
[30972] = {id=30972,name="Joining the Fight",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Lao-Chin's archers will need these arrows down at the bridge. Can you bring them?",objectivesText="Bring the Quiver of Shado-Pan Fire Arrows to Lao-Chin the Iron Belly at Dusklight Bridge. Progress: Welcome to the mess.",starts={{npcID=62124,x=0.674,y=0.806,zoneID=5842}},ends={{npcID=61016,x=0.616,y=0.792,zoneID=5842}},coords={x=0.674,y=0.806,source="quest_giver",zoneID=5842},questType="standard"},
[30973] = {id=30973,name="Up In Flames",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="The mantid coming across the bridge have thick carapaces that shrug off most of our attacks. They have a weakness though: fire. Lao-Chen's men brought kegs to the battlefield for exactly this purpose. Kick the kegs into groups of mantid, and Lao-Chin's archers will light them up. They should be easy to finish off from there.",objectivesText="Kill 10 Kor'thik Timberhusks with the aid of Lao-Chin's kegs. Progress: Creative solution. Lao-Chin impresses.",starts={{npcID=62273,x=0.616,y=0.792,zoneID=5842}},ends={{npcID=62273,x=0.616,y=0.792,zoneID=5842}},coords={x=0.616,y=0.792,source="quest_giver",zoneID=5842},questType="standard"},
[30974] = {id=30974,name="Raising Spirits",level=25,requiredLevel=25,faction="none",expansion=4,zoneID=5842,mapID=388,description="The kegs are full of my worst stock. Good for burning, crap for drinking. I've broken out some tankards of my best spirits and had them carried out amongst the kegs though - those are for my well-deserving men! Spirits to raise their spirits after endless, grueling fighting. Would you be up for spreading the good cheer?",objectivesText="Throw 8 Iron Belly Spirits to nearby Dusklight Skirmishers and Dusklight Rangers.",questType="standard"},
[30975] = {id=30975,name="The Taking of Dusklight Bridge",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=6138,mapID=388,description="Let's press these insects back across the bridge and break their spirits! Follow my lead.",objectivesText="Help Lao-Chin the Iron Belly hold the far side of the Dusklight Bridge.",starts={{npcID=61016,x=0.616,y=0.792,zoneID=5842}},ends={{npcID=62736,x=0.61,y=0.83,zoneID=5842}},coords={x=0.616,y=0.792,source="quest_giver",zoneID=5842},questType="standard"},
[30976] = {id=30976,name="Joining the Hunt",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="We are one stronger. Your help is invaluable. Let's move on westward to Rensai's Watchpost to find the last member for our party.",objectivesText="Ride with Taran Zhu , Taoshi, and Lao-Chin to Rensai's Watchpost.",starts={{npcID=62736,x=0.61,y=0.83,zoneID=5842}},ends={{npcID=62274,x=0.54,y=0.78,zoneID=5842}},coords={x=0.61,y=0.83,source="quest_giver",zoneID=5842},questType="standard"},
[30977] = {id=30977,name="Grounded Welcome",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="All of my men are down at Farwatch Overlook to the southwest, holding off mantid that are trying to fly across the chasm. As long as my marksmen have arrows, they'll ground any mantid that clear the chasm. If you're here to help, I could use some more men clearing the mantid out once they're on the ground. Are you willing, ?",objectivesText="Kill 12 grounded Kor'thik Fleetwings .",starts={{npcID=62278,x=0.54,y=0.78,zoneID=5842}},ends={{npcID=62278,x=0.54,y=0.78,zoneID=5842}},coords={x=0.54,y=0.78,source="quest_giver",zoneID=5842},questType="standard"},
[30978] = {id=30978,name="Hostile Skies",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="We're about to get hit hard... Pick up that cannon there and lend a hand, if you would. There will be no shortage of targets.",objectivesText="Shoot down 50 Kor'thik Swarmers and Voress'thalik . Progress: I could really use you on that cannon...",starts={{npcID=61020,x=0.516,y=0.872,zoneID=5842}},ends={{npcID=61020,x=0.516,y=0.872,zoneID=5842}},coords={x=0.516,y=0.872,source="quest_giver",zoneID=5842},questType="standard"},
[30979] = {id=30979,name="Devastation Below",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Let's get down there and finish that big bug off, you and I.",objectivesText="Defeat Voress'thalik with the aid of Hawkmaster Nurong .",starts={{npcID=61020,x=0.516,y=0.872,zoneID=5842}},ends={{npcID=62786,x=0.54,y=0.868,zoneID=5842}},coords={x=0.516,y=0.872,source="quest_giver",zoneID=5842},questType="standard"},
[30980] = {id=30980,name="Heroes of the Shado-Pan",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="You said that Taran Zhu is in Townlong and was asking for me? Must be something important...",objectivesText="Return with Hawkmaster Nurong to Taran Zhu at Rensai's Watchpost.",starts={{npcID=62786,x=0.54,y=0.868,zoneID=5842}},ends={{npcID=62274,x=0.54,y=0.78,zoneID=5842}},coords={x=0.54,y=0.868,source="quest_giver",zoneID=5842},questType="standard"},
[30981] = {id=30981,name="Taoshi and Korvexxis",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Taoshi is setting up an ambush for one of the mantid leaders on the south side of Sik'vess. She is tasked with retrieving his crystal so that we can use it to open the door. Two are stronger than one. I want you there to make sure it goes smoothly.",objectivesText="Kill Korvexxis with the aid of Taoshi. Progress: Our hunt is nearly over...",starts={{npcID=62274,x=0.54,y=0.78,zoneID=5842}},ends={{npcID=62275,x=0.474,y=0.788,zoneID=5842}},coords={x=0.54,y=0.78,source="quest_giver",zoneID=5842},questType="standard"},
[30982] = {id=30982,name="Animal Control",level=16,requiredLevel=15,faction="horde",expansion=4,zoneID=2437,description="The chasm is overrun with flame hounds and lava worms, and they will be entrenched indefinitely with such a large supply of trogg flesh for food. This infestation needs to be taken care of now, before they endanger the city. You look like you can handle yourself, <name>. I want you to clear a path through the beasts and make certain to take out the largest threats, Adjules and Magnaw.",objectivesText="Kill Adarogg and Slagmaw .",starts={{npcID=61724}},questType="dungeon"},
[30983] = {id=30983,name="The Dark Shaman",level=7,requiredLevel=7,faction="horde",expansion=4,zoneID=2437,description="These dark shaman have been down here for months, raising beasts and performing dark rituals. I don't know what they aim to achieve with all of this, but it's clear that they are no friend of the Horde. That's where you come in, . Fight your way through the chasm and kill Dark Shaman Koranthal and Lava Guard Gordoth .",objectivesText="Defeat Dark Shaman Koranthal and Lava Guard Gordoth .",starts={{npcID=61716}},questType="dungeon"},
[30984] = {id=30984,name="No Orc Left Behind",level=7,requiredLevel=7,faction="horde",expansion=4,zoneID=2437,description="This was supposed to be a routine sweep, . Clean up a few troggs, make sure there is no threat to the city and then be in the tavern by midday. Instead I've a group of scouts missing, flame hounds pouring out of the chasm and Xorenth going on about \"the next twilight's hammer.\" Commander Bagran spits> Go in there and get my scouts back so we can figure out what is going on down here.",objectivesText="Rescue 5 Kor'kron Scouts in Ragefire Chasm . Progress: Have you found the scouts?",starts={{npcID=61724}},questType="dungeon"},
[30986] = {id=30986,name="Ancient Mogu Crypt",level=1,requiredLevel=1,faction="none",expansion=4,zoneID=6208,description="Our scouting party got DESTROYED. Help!",objectivesText="Kill the possessed Shado-Pan Leader and cleanse the Pool of Life.",questType="dungeon"},
[30987] = {id=30987,name="Joining the Alliance",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=1519,mapID=84,description="We have a duty, . It is our responsibility to spread the Tushui philosophy beyond the edges of the Wandering Isle... and there is no better place to start doing that than here: Stormwind City , heart of the Alliance. Let's find out who their leader is. We need allies.",objectivesText="Speak with King Varian Wrynn at Stormwind Keep.",starts={{npcID=60566,x=0.742,y=0.924,zoneID=1519}},ends={{npcID=29611,x=0.856,y=0.318,zoneID=1519},{npcID=107574,x=0.858,y=0.316,zoneID=1519}},coords={x=0.742,y=0.924,source="quest_giver",zoneID=1519},questType="standard"},
[30988] = {id=30988,name="The Alliance Way",level=10,faction="alliance",expansion=4,zoneID=1519,description="I only recently received word that some of your kind might be coming our way. I'd be glad to call you an ally, if you're willing to join our cause. Walk with me, <name>.",objectivesText="Walk with King Varian Wrynn .",starts={{x=0.826,y=0.282,mapID=84,npcID=61796}},ends={{x=0.826,y=0.282,mapID=84,npcID=61796}},coords={mapID=84,x=0.826,y=0.282},questType="standard"},
[30989] = {id=30989,name="An Old Pit Fighter",level=10,faction="alliance",expansion=4,zoneID=1519,description="I need to know if you can fight. There may come a time where you will be called upon for military matters, and I need to know that you can protect my kingdom. I've heard stories about pandaren fighting techniques, but I've never seen them in person. Shall we?",objectivesText="Spar with King Varian Wrynn .",starts={{x=0.826,y=0.282,mapID=84,npcID=61796}},ends={{x=0.826,y=0.282,mapID=84,npcID=61796}},coords={mapID=84,x=0.826,y=0.282},questType="standard"},
[30990] = {id=30990,name="Open the Golden Doors",level=0,requiredLevel=0,faction="none",expansion=4,zoneID=6208,description="Defeat the mogu crypt guardian to open the golden doors.",objectivesText="Defeat the Mogu Crypt Guardian .",questType="standard"},
[30991] = {id=30991,name="Do a Barrel Roll!",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="When I trained as a Brewmaster, I didn't expect to use my knowledge like this... Did you know beer catches fire when lit? Well, with yaungol oil mixed in, it's downright explosive. I've mixed the oil in with these kegs. Roll them at the yaungol over by the gate, and ignite them when you get close. It'll take a few seconds for the keg to blow, but when it does... Well, let's just say I wouldn't want to be over there. Which is why I'll be over here. Mourning the loss of this brew.",objectivesText="Pick up a keg near Lao-Chin, roll it downhill at the yaungol, and ignite it near them to destroy 4 Osul Treelaunchers and 50 Osul Invaders . Progress: Wha? I was just thinking about my poor, poor beer...",starts={{npcID=61820,x=0.292,y=0.622,zoneID=5841}},ends={{npcID=61820,x=0.292,y=0.622,zoneID=5841}},coords={x=0.292,y=0.622,source="quest_giver",zoneID=5841},questType="standard"},
[30992] = {id=30992,name="Finish This!",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="We've heard back from Suna, on the wall. Something's going on... It looks like they are preparing for their final push. It's time to finish this, friend.",objectivesText="Finish the battle for the Ox Gate. Progress: Lin is captured... we must break Taran Zhu from his complacence!",starts={{npcID=61820,x=0.292,y=0.622,zoneID=5841}},ends={{npcID=61819,x=0.35,y=0.596,zoneID=5841}},coords={x=0.292,y=0.622,source="quest_giver",zoneID=5841},questType="standard"},
[30993] = {id=30993,name="Where are My Reinforcements?",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="This has simply gone too far. I cannot ignore our abandonment any longer. After all that's happened here, and all you've been through in Firebough, we must travel to the monastery. Whatever they are doing in there can wait! We can take my balloon up the mountain to the Monastery. It's anchored back by the camp, to the northeast.",objectivesText="Speak with Ban Bearheart outside the Shado-Pan Monastery in Kun-Lai Summit . Progress: Here we are, then.",starts={{npcID=61819,x=0.35,y=0.596,zoneID=5841}},ends={{npcID=61819,x=0.35,y=0.596,zoneID=5841}},coords={x=0.35,y=0.596,source="quest_giver",zoneID=5841},questType="standard"},
[30994] = {id=30994,name="Lao-Chin's Gambit",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Alright. Thanks to you, we have the wall under control. Good job. I'll stay up here for a little while and make sure no more yaungol get up onto the wall. You, though, should go back down and see what Lao-Chin has cooked up. I hate to say it, but maybe he had a good idea after all...",objectivesText="Speak with Lao-Chin the Iron Belly at Winter's Blossom in Kun-Lai Summit . Progress: Ah, hello again. As sad as I am to have to do this, I'm glad I came up with something.",starts={{npcID=61454,x=0.292,y=0.622,zoneID=5841}},ends={{npcID=61820,x=0.292,y=0.622,zoneID=5841}},coords={x=0.292,y=0.622,source="quest_giver",zoneID=5841},questType="standard"},
[30995] = {id=30995,name="No Man Left Behind",level=7,requiredLevel=7,faction="alliance",expansion=4,zoneID=2437,description="I sent recon out over an hour ago and none of them have reported back. And now these damned hounds are pouring out of the chasm. I don't know what's going on down there, but I'm not going anywhere till I get my men back. I want you to head in there and find them, , preferably while they are still alive.",objectivesText="Rescue 5 SI:7 Rangers in Ragefire Chasm .",starts={{npcID=61822}},questType="dungeon"},
[30996] = {id=30996,name="The Dark Shaman",level=7,requiredLevel=7,faction="alliance",expansion=4,zoneID=2437,description="These dark shaman have been down here for months, raising beasts and performing dark rituals. I don't know what they aim to achieve with all of this, but it's clear that they are no friend of the Alliance. And I need your help stopping them, . Fight your way through the chasm and kill Dark Shaman Koranthal and Lava Guard Gordoth .",objectivesText="Defeat Dark Shaman Koranthal and Lava Guard Gordoth .",starts={{npcID=61823}},questType="dungeon"},
[30997] = {id=30997,name="Animal Control",level=16,requiredLevel=15,faction="alliance",expansion=4,zoneID=2437,description="I'm glad you're here, <name>. The horde is amassing an army and I'm not going to wait to find out why. We need to strike fast and take down some of the larger beasts they have down here. I want you to head in there and take care of Adarogg and Slagmaw before the horde can use them as weapons against us.",objectivesText="Kill Adarogg and Slagmaw .",starts={{npcID=61822}},questType="dungeon"},
[30998] = {id=30998,name="A New Enemy",level=7,requiredLevel=7,faction="alliance",expansion=4,zoneID=2437,description="The horde is using dark magic to control beasts and corrupt their brethren down here, . I intend to put a stop to it, but first I need to know what it is we're fighting against. That's where you come in. Fight through the caverns and collect the insignia that the cultists carry. With them, I can study what type of magic is at work here.",objectivesText="Collect 5 Corrupted Insignia from the Dark Shaman cultists. Progress: Have you collected the insignia?",starts={{npcID=61823}},questType="dungeon"},
[30999] = {id=30999,name="Path Less Traveled",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="The toughest roads often have the most to teach us, . I will no doubt learn a great deal from following the path of Shaohao. Many years ago Shaohao traveled to the highest peak in Kun-Lai to seek the guidance of the Jade Serpent. I too will travel to Seeker's Point in search of wisdom. Perhaps you would be interested in a journey such as this? If so speak with Uncle Cloverleaf . He will help you prepare.",objectivesText="Speak to Uncle Cloverleaf in Onekeg.",starts={{npcID=61847,x=0.574,y=0.616,zoneID=5841}},ends={{npcID=59696,x=0.572,y=0.612,zoneID=5841}},coords={x=0.574,y=0.616,source="quest_giver",zoneID=5841},questType="standard"},
[31000] = {id=31000,name="Dread Space",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,mapID=1530,description="Shado-Pan marksmen keep a constant watch over the Dread Wastes from the top of the Serpent's Spine. They would surely welcome the aid of a skilled such as yourself. Take a kite and check in with Bowmistress Li .",starts={{npcID=62667,x=0.506,y=0.118,mapID=422}},ends={{npcID=62112,x=0.14,y=0.77,mapID=1530}},coords={x=0.506,y=0.118,source="quest_giver",mapID=1530},questType="standard"},
[31002] = {id=31002,name="Nope",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=390,description="We're holding, but just barely. Anything you can do to stem the tide of dreadspinners coming up the wall would be a big help. Feel like tearing open spider eggs one at a time by hand? I didn't think so. Take one of our dragon guns and light it up down there. I wanna hear those puppies pop.",objectivesText="Slay 6 Dreadspinner Tenders and use the Shado-Pan Dragon Gun to destroy 20 Dreadspinner Eggs in the Terrace of Gurthan. Progress: Hey, help me out here!",starts={{npcID=62112,x=0.14,y=0.77,zoneID=5840}},ends={{npcID=62166,x=0.724,y=0.286,zoneID=6138}},coords={x=0.14,y=0.77,source="quest_giver",zoneID=5840},questType="standard"},
[31003] = {id=31003,name="Psycho Mantid",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="You aren't going to believe what I saw! Two mantid fighting each other, whipping some serious magic back and forth. One of them didn't look like any mantid I've ever seen. Completely different color and dress to him, like some kind of... oracle or something. The other one was a total psycho, splashing sha energy around like it was a keg of Stormstout Special. Look, I gotta get back to my post, but those two are still fighting in the cave behind me and I have a feeling it's a big deal. Check it out?",objectivesText="Investigate the mantid infighting at the Terrace of Gurthan. Progress: The empress... is... misguided.",starts={{npcID=62166,x=0.724,y=0.286,zoneID=6138}},ends={{npcID=62203,x=0.736,y=0.276,zoneID=6138}},coords={x=0.724,y=0.286,source="quest_giver",zoneID=6138},questType="standard"},
[31004] = {id=31004,name="Preserved in Amber",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Take... this... Awaken... the Wind-Reaver... It is the only way... to end the swarm.",starts={{npcID=62203,x=0.736,y=0.276,mapID=422}},ends={{npcID=62202,x=0.702,y=0.256,mapID=422}},coords={x=0.736,y=0.276,source="quest_giver",mapID=422},questType="standard"},
[31005] = {id=31005,name="Wakening Sickness",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="You will forgive my current state. I have slept for many years. A Klaxxi'va should have been here to attend my Wakening with kypari sap... but you will have to do. I sense the buzzing of sapflies to the south. They gorge on the nourishing sap I need. Bring them to me.",starts={{npcID=62202,x=0.702,y=0.256,mapID=422}},ends={{npcID=62202,x=0.702,y=0.256,mapID=422}},coords={x=0.702,y=0.256,source="quest_giver",mapID=422},questType="standard"},
[31006] = {id=31006,name="The Klaxxi Council",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="I must report to the Klaxxi. They would not have woken me unless the situation were dire. You have not been entirely useless. For that, I will spare your life. The council may even find a use for you.",objectivesText="Travel to Klaxxi'vess at the center of the Dread Wastes . You may speak with Kil'ruk the Wind-Reaver in the Terrace of Gurthan for a ride, or travel on your own.",starts={{npcID=62202,x=0.702,y=0.256,zoneID=6138}},ends={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},coords={x=0.702,y=0.256,source="quest_giver",zoneID=6138},questType="standard"},
[31007] = {id=31007,name="The Dread Clutches",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="The imperial clutches have become an abomination! Clutch-Keepers rush the development of new swarmborn, saturating them in this vile \"sha\" energy before sending them away to the wall. The Klaxxi wish to stem the tide of swarmborn production in these dread clutches. Put the keepers to death!",objectivesText="Slay 6 Shek'zeer Clutch-Keepers in the Clutches of Shek'zeer.",starts={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},ends={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},coords={x=0.55,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31008] = {id=31008,name="Amber Arms",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="You! Filth! You work for me now! The amber blades of the Shek'zeer Bladesworn are the finest weapons in the empire. If you are not impaled upon them immediately after leaving here, bring me as many of the blades as you can carry! I want to make sure we have weapons in reserve, should we need them.",objectivesText="Gather 6 Amber Blades from Shek'zeer Bladesworn around the Heart of Fear and The Clutches of Shek'zeer. Speak with Kil'ruk the Wind-Reaver at Klaxxi'vess for a ride to the Heart of Fear. Progress: The bladesworn carry their swords with pride. I want them on my weapon racks!",starts={{npcID=64599,x=0.55,y=0.354,zoneID=6138}},ends={{npcID=64599,x=0.55,y=0.354,zoneID=6138}},coords={x=0.55,y=0.354,source="quest_giver",zoneID=6138},questType="standard"},
[31009] = {id=31009,name="Dead Zone",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="A Klaxxi'va whispers to the tower. It carries their whisper far; to other towers, to mantid, to paragons. The whisper bounces back, and the Klaxxi hear it. This way, they see all. A tower near the palace is quiet. This will not do. It must sing for the Klaxxi . It is my job to fix the tower, but if you serve the Klaxxi , you should serve me as well. You fix the tower, and I will wait here!",objectivesText="Use the Klaxxi Resonating Crystal on the Inactive Sonic Relay at the Heart of Fear. Speak with Kil'ruk the Wind-Reaver at Klaxxi'vess for a ride to the Heart of Fear.",starts={{npcID=64815,x=0.548,y=0.34,zoneID=6138}},ends={{x=0.547,y=0.34,mapID=422,npcID=64815}},coords={x=0.548,y=0.34,source="quest_giver",zoneID=6138},questType="standard"},
[31010] = {id=31010,name="In Her Clutch",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="The crystal sings to the Klaxxi . They sense a paragon in the clutch, east of the tower. Clutch-keepers are trying to pollute this one. the Klaxxi will not permit this. Go and find the paragon. Place your hands on his chamber, and the Klaxxi will channel their whispers through you to break him free. Protect him if you can.",objectivesText="Locate and waken the mantid paragon in The Clutches of Shek'zeer.",starts={{npcID=213973,x=0.4,y=0.39,zoneID=6138}},ends={{npcID=62774,x=0.55,y=0.354,zoneID=6138}},coords={x=0.4,y=0.39,source="quest_giver",zoneID=6138},questType="standard"},
[31011] = {id=31011,name="Enemies At Our Door",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="The Zandalari have begun their attack! You must help defend the village! If we can't push them back, we will never find the Thunder King's remains!",objectivesText="Defeat 10 Amani Beserkers, 5 Amani Behemoths , and 3 Gurubashi Bloodriders . Progress: The village must be saved!",starts={{npcID=61371,x=0.624,y=0.292,zoneID=5841}},ends={{npcID=63750,x=0.622,y=0.29,zoneID=5841}},coords={x=0.624,y=0.292,source="quest_giver",zoneID=5841},questType="standard"},
[31012] = {id=31012,name="Joining the Horde",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=1637,mapID=85,description="Here we are, ... Orgrimmar , heart of the Horde. We can be helpful beyond the edges of the Wandering Isle. There are innumerable problems out there, just waiting for us to solve them. This is what Master Shang Xi would have wanted. There's no better place to start doing that than here, with the aid of the Horde. Let's find out who their leader is. We need allies.",objectivesText="Speak with Garrosh Hellscream in Orgrimmar .",starts={{npcID=60570,x=0.456,y=0.126,zoneID=14}},ends={{npcID=39605,x=0.482,y=0.706,zoneID=1637}},coords={x=0.456,y=0.126,source="quest_giver",zoneID=14},questType="standard"},
[31013] = {id=31013,name="The Horde Way",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=1637,description="I recently received word that some of your kind might be coming our way. I've recently been trying to bolster the strength of the Horde. A few pandaren might do us good. Walk with me, .",objectivesText="Walk with Garrosh Hellscream .",starts={{npcID=39605,x=0.482,y=0.706,zoneID=1637}},ends={{npcID=39605,x=0.482,y=0.706,zoneID=1637},{npcID=62092,x=0.704,y=0.314,zoneID=1637}},coords={x=0.482,y=0.706,source="quest_giver",zoneID=1637},questType="standard"},
[31014] = {id=31014,name="Hellscream's Gift",level=10,faction="horde",expansion=4,zoneID=1637,description="I need to know if you can fight... that you can kill, and live. Eventually, each of you will be called upon for war, and I need to know that you can be counted on. I mentioned a gift earlier. It lies here, within the Ring of Valor. Step into the arena, right through this door behind me. I will test your skills.",objectivesText="Complete Garrosh's test by defeating Oggax, Gadoon, and Frozengore.",starts={{x=0.706,y=0.308,mapID=85,npcID=62092}},ends={{x=0.706,y=0.308,mapID=85,npcID=62092}},coords={mapID=85,x=0.706,y=0.308},questType="standard"},
[31015] = {id=31015,name="Your Private Collection",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5785,description="Pandaria is rich with history, legends, stories, and lore of every sort. While you are traveling throughout the world I would ask that you keep an eye open for artifacts and pieces of information that you feel would be pertinent to our work here. When you accumulate enough knowledge, we will compile it in to a volume for your personal collection here. You can, of course, return whenever you like to review the volumes we are making for you.",objectivesText="Clean off the Empty Bookshelf. Progress: So much to learn.",starts={{npcID=61962,x=0.832,y=0.296,zoneID=5840},{npcID=63577,x=0.468,y=0.46,zoneID=5785}},ends={{npcID=61962,x=0.832,y=0.296,zoneID=5840}},coords={x=0.832,y=0.296,source="quest_giver",zoneID=5840},questType="standard"},
[31016] = {id=31016,name="The Lorewalkers",level=30,requiredLevel=30,faction="none",expansion=4,zoneID=5840,mapID=1530,description="Dear $p, We have uncovered something tremendous in the Vale of Eternal Blossoms . A great repository of books, scrolls, and lore that has remained untouched since the days of the mogu empire. Please, join us at your earliest convenience. You can find this Seat of Knowledge by traveling to the infamous Mogu'shan Vaults, and then flying to the landing just above the entrance. I look forward to your arrival! Sincerely, Lorewalker Cho",objectivesText="Speak with Lorewalker Cho at the Seat of Knowledge in the Vale of Eternal Blossoms . Provided item:",questType="standard"},
[31018] = {id=31018,name="Beneath the Heart of Fear",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="The Klaxxi have detected the existence of another paragon, Wakener. This one was kept well-hidden from us, and for good reason. The Empress already has possession of this one, and her adjuncts work to destroy it even now. They are performing their sorcery in a chamber deep beneath the palace, and they must be stopped. We hold Klaxxi'vess. You must go in our stead. Find the entrance to their chamber from the ledge to the west.",objectivesText="Kill Adjunct Ek'vem , Adjunct Ikkess , Adjunct Suruz , and Adjunct Tsikzi, and then free Xaril the Poisoned Mind .",starts={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},ends={{npcID=62151,x=0.548,y=0.36,zoneID=6138}},coords={x=0.55,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31019] = {id=31019,name="Amber Is Life",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="In order for our efforts against the mantid empire to continue, we require more amber. There is a great deposit of amber underneath the lake to the south, but the area is inhabited by a savage saurok tribe. I cannot spare anyone else. You must go to the lake and test the tribe's strength. Thin their numbers and eliminate their leader, who is probably hiding in his underground cavern. Surely this is not too great a task for you?",objectivesText="Kill 7 Mistblade Rippers and the Mistblade Scale-Lord . Progress: The amber looks familiar for some reason...",starts={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},ends={{npcID=65354,x=0.668,y=0.654,zoneID=6138}},coords={x=0.55,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31020] = {id=31020,name="Feeding the Beast",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="I must join the Klaxxi Council and the other paragons immediately, but I am barely strong enough to stand. I must feed, Wakener. I sense the beating hearts of creatures on the northern bank of the lake. Kill them for me, and I shall do the rest.",objectivesText="Kill 8 Coldbite Crocolisks . Progress: I have been sleeping for many thousands of years. I must regain my strength before rejoining the Council.",starts={{x=0.668,y=0.653,mapID=422,npcID=62232}},ends={{x=0.668,y=0.653,mapID=422,npcID=62232}},coords={mapID=422,x=0.668,y=0.653},questType="standard"},
[31021] = {id=31021,name="Living Amber",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Liquid amber is most efficient for restoring a newly awakened paragon's strength, and is usually provided at a wakening ceremony. Unfortunately, it seems you did not receive these instructions, so we shall have to improvise. I can sense a vast quantity of fossilized amber in the lake below us. It will serve, but I am too weak to dig it up myself. Do this for me, and I will see to it that you are rewarded.",objectivesText="Collect 8 Living Amber , then feed them to Korven the Prime. Progress: Do you understand, Wakener? The amber gives life.",starts={{x=0.668,y=0.653,mapID=422,npcID=62232}},ends={{x=0.668,y=0.653,mapID=422,npcID=62232}},coords={mapID=422,x=0.668,y=0.653},questType="standard"},
[31022] = {id=31022,name="Kypari Zar",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="What is that tree on the hill to the west? Can it be... Kypari Zar? When I returned from my final ravage, before being elevated to a paragon, I was given the honor of planting that very tree. I see it has grown into a great kypari, but... it seems something is amiss. There is an old sonar tower at the base of the tree. Take me there, Wakener. I can use the tower to take a closer look.",objectivesText="Activate the Sonar Tower, then defend Korven the Prime as he examines the tree. Progress: What has happened to our home? Things feel amiss.",starts={{x=0.668,y=0.653,mapID=422,npcID=62232}},ends={{x=0.668,y=0.653,mapID=422,npcID=62232}},coords={mapID=422,x=0.668,y=0.653},questType="standard"},
[31023] = {id=31023,name="Relics of the Swarm",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="This strange-looking carving is covered in a complex written language that might be mantid in origin. You notice more relics strewn carelessly among the camps and inside the lake. Perhaps the Klaxxi would be interested in examining these artifacts. Who knows? Perhaps it will earn you some favor.",objectivesText="Collect 8 Mantid Relics . Progress: What do you have there?",starts={{x=0.629,y=0.578,mapID=422}},ends={{npcID=64599,x=0.55,y=0.354,zoneID=6138}},coords={mapID=422,x=0.629,y=0.578},questType="standard"},
[31024] = {id=31024,name="Kunchong Treats",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="As Kovok grows, he will require equal parts discipline and reward. I lack no shortage of discipline, but our supply of meat is almost empty. To the south, you will find turtles roaming north of the Lake of Stars and Kypari Zar. Hunt them. Kovok likes the taste of their flesh.",objectivesText="Collect 4 Meaty Turtle Haunches. Progress: What have you brought for Kovok?",starts={{npcID=63758,x=0.542,y=0.358,zoneID=6138}},ends={{npcID=63758,x=0.542,y=0.358,zoneID=6138}},coords={x=0.542,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31026] = {id=31026,name="The Root of the Problem",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Kypari Zar is dying. A creature of terrible darkness corrupts it from deep beneath its roots. The tree cannot be saved, but at least we can lessen its pain. Look. The vile creature has carved a path to its own lair. We need only follow it down the hill, just behind this tower.",objectivesText="Kill the Coldbite Matriarch . Progress: The swarm knows not of their terrible folly! These precious trees must be protected at all costs!",starts={{x=0.598,y=0.594,mapID=422,npcID=62232}},ends={{x=0.598,y=0.594,mapID=422,npcID=62232}},coords={mapID=422,x=0.598,y=0.594},questType="standard"},
[31027] = {id=31027,name="Defeat the Abomination",level=0,requiredLevel=0,faction="none",expansion=4,zoneID=6208,description="Now that the pool of life is cleansed, the way to the crypt's interior is open. Make your way down there and defeat the abomination.",objectivesText="Defeat the Abomination of Anger .",questType="standard"},
[31030] = {id=31030,name="Into the Monastery",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5918,description="This... is unspeakable. If the monastery has truly been taken over by the Sha, we will need a great effort to purge the monks inside of corruption. Gather a group of your allies, and meet me inside the Monastery.",objectivesText="Meet Ban Bearheart inside the Shado-Pan Monastery .",starts={{npcID=62227,x=0.353,y=0.495,zoneID=5841}},ends={{x=0.366,y=0.477,mapID=379,npcID=62227}},coords={x=0.353,y=0.495,source="quest_giver",zoneID=5841},questType="dungeon"},
[31031] = {id=31031,name="Into the Monastery",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5918,description="This... is unspeakable. If the monastery has truly been taken over by the Sha, we will need a great effort to purge the monks inside of corruption. Gather a group of your allies, and meet me inside the Monastery.",objectivesText="Meet Ban Bearheart inside the Shado-Pan Monastery.",starts={{npcID=61819,x=0.35,y=0.596,zoneID=5841}},ends={{x=0.353,y=0.495,mapID=379,npcID=62227}},coords={x=0.35,y=0.596,source="quest_giver",zoneID=5841},questType="dungeon"},
[31032] = {id=31032,name="Choking the Skies",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Nurong wants me to pass out torches for burning the bodies. The flying mantid are fragile, and won't last long in the hot smoke.",objectivesText="Burn 10 Kor'thik Fleetwing corpses. Progress: Some of them can make it through the smoke, but in small enough numbers that we can easily pick them off.",starts={{npcID=62573,x=0.512,y=0.83,zoneID=5842}},ends={{npcID=62573,x=0.512,y=0.83,zoneID=5842}},coords={x=0.512,y=0.83,source="quest_giver",zoneID=5842},questType="standard"},
[31034] = {id=31034,name="Enemies Below",level=7,requiredLevel=7,faction="horde",expansion=4,zoneID=2437,description="There are enemies of the Horde beneath this very city, . The Searing Blade plots to take Orgrimmar for their own, and have already taken Ragefire Chasm ! We need to storm their forces and retake what is ours! Go speak with Commander Bagran just inside Ragefire Chasm . He will have further orders for you.",starts={{npcID=3144,x=0.49,y=0.722,mapID=85},{npcID=14720,x=0.486,y=0.71,mapID=85},{npcID=39605,x=0.482,y=0.706,mapID=85},{npcID=86832,x=0.482,y=0.706,mapID=85}},coords={x=0.49,y=0.722,source="quest_giver",zoneID=1637},questType="dungeon"},
[31036] = {id=31036,name="Enemies Below",level=7,requiredLevel=7,faction="horde",expansion=4,zoneID=2437,description="Orgrimmar's Ragefire Chasm has been taken by the Dark Shaman. , we cannot allow this to pass unpunished, lest they next set their sights on Thunder Bluff. Go speak with Commander Bagran just inside the Chasm. Help him in any way you can, for our fates are intertwined.",objectivesText="Speak with Commander Bagran .",starts={{npcID=36648,x=0.598,y=0.516,zoneID=1638}},ends={{x=0.603,y=0.517,mapID=88,npcID=36648}},coords={x=0.598,y=0.516,source="quest_giver",zoneID=1638},questType="dungeon"},
[31037] = {id=31037,name="Enemies Below",level=7,requiredLevel=7,faction="horde",expansion=4,zoneID=2437,description="Orgrimmar's Ragefire Chasm has been taken by the Dark Shaman. , we cannot allow this to pass unpunished, lest they next set their sights on Undercity. Go speak with Commander Bagran just inside the Chasm. Help him in any way you can, for our fates are intertwined.",objectivesText="Speak with Commander Bagran .",starts={{npcID=10181,x=0.578,y=0.916,zoneID=1497}},ends={{x=0.578,y=0.916,mapID=90,npcID=10181}},coords={x=0.578,y=0.916,source="quest_giver",zoneID=1497},questType="dungeon"},
[31038] = {id=31038,name="The Challenger's Ring: Snow Blossom",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="News of your feats has been traveling around the camp, . In fact, Snow Blossom would like to test your skill in battle. You had best prepare yourself, . She is not easily defeated. If you can prove your worth to her, you will win a valuable friend.",objectivesText="Challenge Snow Blossom and defeat her in the Challenger's Ring. Progress: How did it go?",starts={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},ends={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},coords={x=0.49,y=0.704,source="quest_giver",zoneID=5842},questType="standard"},
[31039] = {id=31039,name="The Mogu Menace",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Our scouts have discovered a heavy mogu force at Shan'ze Dao to the northwest. The island was supposedly uninhabited, so their presence is disturbing news. Even more disturbing is the fact that they are performing sinister experiments on the island. I need a capable to check out the situation. The Shan'ze are likely to give you trouble, and if they do, kill them.",objectivesText="Kill 12 Shan'ze Serpentbinders or Shan'ze Beastmasters. Progress: How many were there?",starts={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},ends={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},coords={x=0.49,y=0.704,source="quest_giver",zoneID=5842},questType="standard"},
[31040] = {id=31040,name="Spiteful Sprites",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="The Darkwoods sprites on Shan'ze Dao have fallen to the mogu's domination. The once sly tricksters are now the full servants of the Shan'ze. They grow bolder each day, stealing and killing to satisfy their masters. They must be eliminated, but be careful. They may look harmless, but they are actually quite vicious.",objectivesText="Kill 30 Darkwoods Pixies or Darkwoods Charmers. Progress: The sprites must do as their masters command.",starts={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},ends={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},coords={x=0.49,y=0.704,source="quest_giver",zoneID=5842},questType="standard"},
[31041] = {id=31041,name="Egg Rescue!",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Eggs. Yes, you heard me right. I said eggs, and these aren't for eating. Have you ever seen a cloud serpent egg? These rare eggs look like jewels, and were once worth their weight in solid gold. Shan'ze Dao to the north normally teems with wild cloud serpents, but the mogu and the sprites have their eggs on lock-down. We need to save as many of these precious eggs as we can. I'm counting on YOU, .",objectivesText="Collect 8 Cloudrunner Eggs . Progress: Did you find any eggs? The serpents lay their eggs in nests on the beach, but the wood sprites are also known to steal them whenever they can.",starts={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},ends={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},coords={x=0.49,y=0.704,source="quest_giver",zoneID=5842},questType="standard"},
[31042] = {id=31042,name="Onyx Hearts",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="The Shan'ze Serpentbinders dominate the minds of wild cloud serpents, but they also create their own dark creatures from stone, metal, blood, and ancient sorcery. Their creations, the Onyx Stormclaws, guard the island to the northwest. I wish to study the magic binding these creatures. Bring me their hearts, so that I can better understand what sorcery we are up against.",objectivesText="Collect 4 Onyx Hearts . Progress: The Onyx Stormclaws will never disobey their masters.",starts={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},ends={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},coords={x=0.49,y=0.704,source="quest_giver",zoneID=5842},questType="standard"},
[31043] = {id=31043,name="Dark Arts",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="It is said that Shan'ze Dao was once home to a great mogu temple. There, the Shan'ze studied and practiced the art of subjugating the dead or inanimate. Much of their knowledge still remains on the island to the northwest, buried among the ruins. We need to get our hands on their knowledge - both to keep it out of their hands, and to understand the nature of their experiments.",objectivesText="Collect 8 Shan'ze Tablets . Progress: Knowledge is powerful. That is why the mogu are so dangerous.",starts={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},ends={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},coords={x=0.49,y=0.704,source="quest_giver",zoneID=5842},questType="standard"},
[31044] = {id=31044,name="Bronze Claws",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Among the Shan'ze's fiercest and most loyal creations are their quilen. These beasts will hunt until they kill their prey, or die in the process. I need you to not only cull their numbers, but also to retrieve their bronze claws . Their claws are strong and razor sharp, and we can use them to make weapons and hooks for our cause.",objectivesText="Collect 20 Bronze Claws . Progress: The quilen are fierce, but I see fierceness in your eyes as well.",starts={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},ends={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},coords={x=0.49,y=0.704,source="quest_giver",zoneID=5842},questType="standard"},
[31045] = {id=31045,name="Illusions Of The Past",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description=", I need your strength to eliminate the Shan'ze Illusionists on Shan'ze Dao, to the northwest. It wearies me to ask of you this difficult task. The illusionists are among the strongest of the Shan'ze's elite sorcerors. They will not be easy to defeat, but I know no who is better suited to the task.",objectivesText="Kill 3 Shan'ze Illusionists . Progress: Do not be fooled by their illusions.",starts={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},ends={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},coords={x=0.49,y=0.704,source="quest_giver",zoneID=5842},questType="standard"},
[31046] = {id=31046,name="Little Hatchlings",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="I have seen the cruel experiments that the Shan'ze are performing on their island to the northwest. The Shan'ze raise baby serpents from the egg. They keep the young in tiny cages, surrounded by squalor and filth. The cruelest gaolers starve and torture them. We must save as many hatchlings as we can. You have my full permission to punish any mogu that gets in your way!",objectivesText="Free 20 Cloudrunner Hatchlings . Progress: The mogu are cruel beyond measure.",starts={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},ends={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},coords={x=0.49,y=0.704,source="quest_giver",zoneID=5842},questType="standard"},
[31047] = {id=31047,name="Born Free",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Do you know the story of the great cloud serpents of Pandaria, ? Someday you must hear it. Unfortunately, there is no time to tell it now. What you must know is that the wild cloudrunner serpents of Townlong are in trouble. The mogu are capturing wild serpents and corrupting their minds, bending them to their sinister will. Go to Shan'ze Dao, to the northwest. Free the adult serpents from their chains. Save them!",objectivesText="Free 6 Wild Cloudrunners from their chains. Progress: The wild cloudrunners should remain free.",starts={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},ends={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},coords={x=0.49,y=0.704,source="quest_giver",zoneID=5842},questType="standard"},
[31048] = {id=31048,name="Grave Consequences",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="We've found ancient mogu burial urns among the ruins on Shan'ze Dao. This is normally no problem, except these urns are home to angry mogu spirits. Not only do these urns pose a danger to anyone unlucky enough to find one, but they could be used for destruction if they were to fall into the wrong hands. We must rid Shan'ze Dao of their presence.",objectivesText="Kill 24 Shan'ze Ancestors . Shan'ze Ancestors may be found inside Mogu Burial Urns. Progress: Did the spirits cause you any problems?",starts={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},ends={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},coords={x=0.49,y=0.704,source="quest_giver",zoneID=5842},questType="standard"},
[31049] = {id=31049,name="In Sprite Of Everything",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="The sprites of Shan'ze Dao have always been capricious tricksters, but now they have fallen under the mogu's influence. Even as we speak, they gather under a new leader. We cannot allow this to happen. Their mischievous pranks were one thing, but united, their dark magic is too powerful and too dangerous to comprehend. Take out their leader before it is too late.",objectivesText="Kill the Darkwoods Faerie . Progress: The sprites are easily manipulated, and too dangerous to ignore.",starts={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},ends={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},coords={x=0.49,y=0.704,source="quest_giver",zoneID=5842},questType="standard"},
[31050] = {id=31050,name="Chose Fire Mage",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31051] = {id=31051,name="Chose Frost Mage",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31052] = {id=31052,name="Chose Priest",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31053] = {id=31053,name="Tracking Event: Started Shado-Pan Dailies",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31054] = {id=31054,name="Unlocked Yalia Sagewhisper",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31055] = {id=31055,name="Between a Saurok and a Hard Place",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,description="Dear $p, We have received your research on the saurok and believe we have pieced together clues about their past. If you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection. Thank you for your diligence! Sincerely, Lorewalker Cho",objectivesText="Bring Between a Saurok and a Hard Place to Lorewalker Cho . Provided item:",starts={{x=0.832,y=0.296,mapID=390,npcID=61962}},ends={{npcID=61962,x=0.832,y=0.296,zoneID=5840}},coords={mapID=390,x=0.832,y=0.296},questType="standard"},
[31058] = {id=31058,name="The Funky Monkey Brew",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6309,description="Pirates! Our shores have been scoured by the most ill-tempered, ill-mannered, ill-hygienic, and ill-good hozen that ever was found in Pandaria. And to make matters worse, they claim to serve the legendary Captain Ook ! We see them every night partying and brewing punch on their island Unga Ingoo . I say we take their brew for a change! I think I can even improve their mix. Gather up some friends and meet me on the southern side of Unga Ingoo . It is time for a Brew Run!",objectivesText="Defeat Captain Ook . Progress: These hozen pack some mean toys and some meaner brews.",starts={{npcID=65289,x=0.52,y=0.768,zoneID=6134}},ends={{npcID=65289,x=0.52,y=0.768,zoneID=6134},{npcID=62491,x=0.504,y=0.62,zoneID=6309}},coords={x=0.52,y=0.768,source="quest_giver",zoneID=6134},questType="dungeon"},
[31061] = {id=31061,name="Riding the Storm",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Shan Bu, the leader of the Shan'ze, is performing some kind of dark ritual at the summit of the island to the northwest. We believe that the subjugated Shan'ze Cloudrunners are powering the spell. How, we still do not know. We believe that the Shan'ze Cloudrunners can still be saved from the corruption that taints them. Take these bronze claws . Use them to mount the back of a Shan'ze Cloudrunner. Attack them. Beat some sense back into their heads!",objectivesText="Use the Bronze Claws to mount 8 Shan'ze Cloudrunners. Attack them to free them of their corruption. Progress: How did it go?",starts={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},ends={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},coords={x=0.49,y=0.704,source="quest_giver",zoneID=5842},questType="standard"},
[31062] = {id=31062,name="When The Dead Speak",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="The Shan'ze's experiments are overseen by a powerful necromancer known as a Shan'ze Deathspeaker . If we are to put an end to their operations, we must eliminate their leader.",objectivesText="Kill the Shan'ze Deathspeaker . Progress: What would possess the mogu to perform such hideous experiments?",starts={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},ends={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},coords={x=0.49,y=0.704,source="quest_giver",zoneID=5842},questType="standard"},
[31063] = {id=31063,name="Lao-Chin and Serevex",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Lao-Chin is facing off against the leader just above the entrance in the tree, on the north side of Sik'vess. He is to bring back the second crystal that we need to get into the mantid tunnel. Go there and lend him your aid.",objectivesText="Kill Serevex with the aid of Lao-Chin the Iron Belly. Progress: The Sha of Hatred dies this day...",starts={{npcID=62274,x=0.54,y=0.78,zoneID=5842}},ends={{npcID=62275,x=0.474,y=0.788,zoneID=5842}},coords={x=0.54,y=0.78,source="quest_giver",zoneID=5842},questType="standard"},
[31064] = {id=31064,name="Nurong and Rothek",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Hawkmaster Nurong has gone ahead to the northwest of Sik'vess to make sure the last mantid leader cannot escape. Catch up with him and help him kill the mantid leader. Nurong will bring back the final crystal once you've aided him in this.",objectivesText="Kill Rothek with the aid of Hawkmaster Nurong. Progress: Act swiftly. I do not want the Sha of Hatred to escape our grasp again.",starts={{npcID=62274,x=0.54,y=0.78,zoneID=5842}},ends={{npcID=62275,x=0.474,y=0.788,zoneID=5842}},coords={x=0.54,y=0.78,source="quest_giver",zoneID=5842},questType="standard"},
[31065] = {id=31065,name="Buried Beneath",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="Taoshi set up a spyglass on the ridge edge to show me what her scouting uncovered. Go over and take a look.",objectivesText="Look through the spyglass in Rensai's Watchpost. Progress: Go. Look.",starts={{npcID=62274,x=0.54,y=0.78,zoneID=5842}},ends={{npcID=62274,x=0.54,y=0.78,zoneID=5842}},coords={x=0.54,y=0.78,source="quest_giver",zoneID=5842},questType="standard"},
[31066] = {id=31066,name="A Cry From Darkness",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="So, you survived the imperial clutches. You are... resilient. The Klaxxi hear another paragon to the north, among the sha-scorched roots of Kypari Vor. This one cries out in terror and agony. It cannot be saved. The Klaxxi want him put down. Go and defeat him or do not return here.",objectivesText="Slay the corrupted paragon at Kypari Vor. Progress: The order stands. Slay the fallen paragon.",starts={{npcID=64815,x=0.548,y=0.34,zoneID=6138}},ends={{npcID=64815,x=0.548,y=0.34,zoneID=6138}},coords={x=0.548,y=0.34,source="quest_giver",zoneID=6138},questType="standard"},
[31067] = {id=31067,name="The Heavens Hum With War",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="The mantid don't ever make my job easy, but now they've gone too far. We can fend off the occasional attack from Kor'vess, but now... now they're starting to surround us. What's worse, they're draining the amber from our tree. This will not stand! We need that amber! To make beer! They've dug a burrow into the south side of the tree. I'm short-handed here. Could you take care of them for me?",objectivesText="Slay Azzix K'tai .",starts={{npcID=62666,x=0.512,y=0.114,zoneID=6138}},ends={{npcID=62666,x=0.512,y=0.114,zoneID=6138}},coords={x=0.512,y=0.114,source="quest_giver",zoneID=6138},questType="standard"},
[31068] = {id=31068,name="Sacred Recipe",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="\"When the horror comes a-rising And the heavens hum with war Our great vessel of salvation Must be broken from its core.\" The scroll continues on for several stanzas. Perhaps somebody at The Sunset Brewgarden will be able to decipher its cryptic message.",objectivesText="Bring the Scroll of Auspice to Lya of Ten Songs at The Sunset Brewgarden. Progress: Is that some sort of scroll? Would you mind if I took a look?",starts={{npcID=212389,x=0.531,y=0.124,zoneID=6138}},ends={{npcID=62667,x=0.506,y=0.118,zoneID=6138}},coords={x=0.531,y=0.124,source="quest_giver",zoneID=6138},questType="standard"},
[31069] = {id=31069,name="Bound With Shade",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="About that scroll you found... I keep looking at that line in the second stanza - \"bound with wood and shade\". The \"shade\", in particular, intrigues me. I must admit, I've often considered taking some of the area's residual sha essence and incorporating it into a brew. I suspect that this is the shade which our recipe calls for. You will find large amalgamations of sha to the southeast of our tree... though you may also be able to harvest some from the local wildlife.",objectivesText="Harvest 100 drops of Shade by slaying sha creatures and wildlife near The Sunset Brewgarden.",starts={{npcID=62666,x=0.512,y=0.114,zoneID=6138}},ends={{npcID=62666,x=0.512,y=0.114,zoneID=6138}},coords={x=0.512,y=0.114,source="quest_giver",zoneID=6138},questType="standard"},
[31070] = {id=31070,name="Daggers of the Great Ones",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="That recipe said: \"rending daggers of the great ones\"... Olon ponders this line.> Mushan! That's it! There's plenty of mushan roaming out there with these great, big teeth... they're as long as daggers. That's gotta be what the recipe calls for.",objectivesText="Obtain 3 Large Mushan Teeth. Progress: I wonder how we'll mix those things into the brew? Can't grind them up - that'd be too gritty. Maybe I'll just soak 'em for a while.",starts={{npcID=62668,x=0.51,y=0.112,zoneID=6138}},ends={{npcID=62668,x=0.51,y=0.112,zoneID=6138}},coords={x=0.51,y=0.112,source="quest_giver",zoneID=6138},questType="standard"},
[31071] = {id=31071,name="I Bring Us Great Shame",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="I have failed my fellow brewers. I took some supplies out to the clearing, east of our tree... and I left them there. Now, with the sha corrupting the land, and the mantid on the prowl, it is too dangerous for me to bring them back. If you would help me look for them, perhaps I could regain some of my lost honor.",objectivesText="Find the Lost Keg , the Lost Mugs , and the Lost Picnic Supplies . Progress: Did you find them? Can it be?",starts={{npcID=62859,x=0.51,y=0.112,zoneID=6138}},ends={{npcID=62859,x=0.51,y=0.112,zoneID=6138}},coords={x=0.51,y=0.112,source="quest_giver",zoneID=6138},questType="standard"},
[31072] = {id=31072,name="Rending Daggers",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Forget about them, and forget their BREW. We've got real work to do. The scroll mentions \"rending daggers of the great ones\". I've got a feeling I know where to find them. A pair of mantid lieutenants patrol the Horrid March, to the south. Each one carries a ceremonial dagger. Bring those daggers back here, . We may be on the brink of something big.",objectivesText="Obtain the Blade of Kz'Kzik and the Blade of Ilikkax . Progress: I think I'm starting to understand the next few lines of this prophecy, <name>. Do you have the daggers yet?",starts={{npcID=62667,x=0.506,y=0.118,zoneID=6138}},ends={{npcID=62667,x=0.506,y=0.118,zoneID=6138}},coords={x=0.506,y=0.118,source="quest_giver",zoneID=6138},questType="standard"},
[31073] = {id=31073,name="Bound With Wood",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Hmm... \"bound with wood\". We don't typically brew with wood. Sap, yes... but not wood. We have, on rare occasions, infused our drinks with corewood from the treants to the west of here. Most of them have fallen to the mantid... but their remains should suffice for our recipe.",objectivesText="Obtain 8 pieces of Fragrant Corewood . Progress: We don't brew with wood here. It gives the brew a harsh, insipid flavor, not unlike that of wine. <Vu spits.>",starts={{npcID=62666,x=0.512,y=0.114,zoneID=6138}},ends={{npcID=62666,x=0.512,y=0.114,zoneID=6138}},coords={x=0.512,y=0.114,source="quest_giver",zoneID=6138},questType="standard"},
[31074] = {id=31074,name="Wood and Shade",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="\"Rending daggers of the great ones shall be bound with WOOD and SHADE.\" Hmm. I've learned a lot about the Kor'thik mantid in my time here. I know that they maintain shrines within their settlement, Kor'vess. One is a heartroot of the very tree that they inhabit. The other is a dark pillar, connecting them with their queen. These shrines are the wood and shade. If my predictions are right... the daggers should react in their presence.",objectivesText="Find the Mark of the Empress and the Heartroot of Kypari Kor. Progress: <Lya looks concerned.>",starts={{npcID=62667,x=0.506,y=0.118,zoneID=6138}},ends={{npcID=62667,x=0.506,y=0.118,zoneID=6138}},coords={x=0.506,y=0.118,source="quest_giver",zoneID=6138},questType="standard"},
[31075] = {id=31075,name="Sunset Kings",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Olon had a clever idea. He thinks that we should visit the sprites to the west, and ask them if they have any of these ingredients. Some of the elements to this recipe are seeming... strange. The Rikkitun sprites have a village to the west of Kor'vess. I hope to see you there, .",objectivesText="Meet Sapmaster Vu at Rikkitun Village.",starts={{npcID=62666,x=0.512,y=0.114,zoneID=6138}},ends={{npcID=62666,x=0.512,y=0.114,zoneID=6138}},coords={x=0.512,y=0.114,source="quest_giver",zoneID=6138},questType="standard"},
[31076] = {id=31076,name="Fate of the Stormstouts",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Greetings, . I am Chen Stormstout . I'm looking for my family. I am told that several Stormstouts came across the wall to help face the mantid threat. I mean to find them, and join them. Have you seen anyone named Stormstout come through here? Would you mind helping me ask around?",starts={{npcID=62779,x=0.504,y=0.12,mapID=422}},ends={{npcID=62779,x=0.504,y=0.12,mapID=422}},coords={x=0.504,y=0.12,source="quest_giver",mapID=422},questType="standard"},
[31077] = {id=31077,name="Evie Stormstout",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="I was too late. She was so small... and I was too late. She should be given a proper burial. A little warrior like her deserves better than this.",objectivesText="Meet Chen Stormstout at The Sunset Brewgarden, then listen to his eulogy. Progress: <Chen is in mourning.>",starts={{npcID=67138,x=0.502,y=0.102,zoneID=6138}},ends={{npcID=67138,x=0.502,y=0.102,zoneID=6138}},coords={x=0.502,y=0.102,source="quest_giver",zoneID=6138},questType="standard"},
[31078] = {id=31078,name="Han Stormstout",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="There will be time for mourning later. For now, there are other Stormstouts to be found. They say that Han Stormstout was last seen exploring Kor'vess. I suspect he headed into that mantid burrow, just across the way. You should meet me down there, . I don't doubt that I can handle a few mantid by myself... but I'd feel better with you by my side.",objectivesText="Find Han Stormstout in the Morrowchamber beneath Kor'vess. Progress: I think I see someone over there, but I can't seem to get across these amber beams.",starts={{npcID=67138,x=0.502,y=0.102,zoneID=6138}},ends={{npcID=62779,x=0.504,y=0.12,zoneID=6138}},coords={x=0.502,y=0.102,source="quest_giver",zoneID=6138},questType="standard"},
[31079] = {id=31079,name="The Horror Comes A-Rising",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="We are protected from the mantid. Such was the agreement made so many millennia ago. There are forces from which we are not safe, however. The kyparites beneath the ground to the west will haunt us, chase us... even eat us. The mistlurkers eat our kind by the handful. Help our people, outsider. Defeat our enemies.",starts={{npcID=62772,x=0.382,y=0.172,mapID=422}},ends={{npcID=62772,x=0.382,y=0.172,mapID=422}},coords={x=0.382,y=0.172,source="quest_giver",mapID=422},questType="standard"},
[31080] = {id=31080,name="Fiery Wings",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="I think that old paper said something about \"fiery wings.\" Those little dragons around here have wings. They're kind of fiery, in a way. You're quicker than me. Try catching some of those dragons... or at least slapping the powder off of them. No point in killing a harmless little dragon, if all you want is the sparkle from their wings.",objectivesText="Slap Rikkilea Flitterlings, then catch 88 flecks of Flitterling Dust . Progress: I haven't been able to catch any of those things!",starts={{npcID=62668,x=0.51,y=0.112,zoneID=6138}},ends={{npcID=62668,x=0.51,y=0.112,zoneID=6138}},coords={x=0.51,y=0.112,source="quest_giver",zoneID=6138},questType="standard"},
[31081] = {id=31081,name="Incantations Fae and Primal",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="I suspect we are going to need the help of these sprites. We have two enchanted daggers, bound together with wood and shade. Now we need someone to perform ancient \"incantations\" on our artifact. Before we ask for favors, let's show the sprites that we mean well. I heard their leader talking about a pair of mistlurkers that kidnapped several of their villagers. If we slay these fog beasts... we may get the \"incantation\" we need in return.",starts={{npcID=62667,x=0.506,y=0.118,mapID=422}},ends={{npcID=62667,x=0.506,y=0.118,mapID=422}},coords={x=0.506,y=0.118,source="quest_giver",mapID=422},questType="standard"},
[31082] = {id=31082,name="Great Vessel of Salvation",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="I know what you and the girl-panda seek. We can perform the rite for you... in time. First, I require aid. The seeds fall from our great mother-tree. It is our responsibility to collect them, even in dangerous times like these. Escort my chanters to the motherseeds , that they may bring them back to the collection pit.",starts={{npcID=62771,x=0.386,y=0.172,mapID=422}},ends={{npcID=62771,x=0.386,y=0.172,mapID=422}},coords={x=0.386,y=0.172,source="quest_giver",mapID=422},questType="standard"},
[31083] = {id=31083,name="Promises of Gold",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="As soon as the creature died, a strange group of sprites appeared and took its pearl away. The sprites have a village nearby, called Rikkitun Village. Perhaps you should investigate.",objectivesText="Report to Chief Rikkitun at Rikkitun Village in Dread Wastes .",starts={{x=0.274,y=0.162,mapID=422,npcID=62767}},ends={{npcID=62771,x=0.386,y=0.172,zoneID=6138}},coords={mapID=422,x=0.274,y=0.162},questType="standard"},
[31084] = {id=31084,name="Bind the Glamour",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="It has been a very, very long time since our tribe has been called on to perform this rite. I will do the best I can.",objectivesText="Allow Chief Rikkitun to enchant the Forked Blade. Progress: ...",starts={{npcID=62771,x=0.386,y=0.172,zoneID=6138}},ends={{npcID=62771,x=0.386,y=0.172,zoneID=6138}},coords={x=0.386,y=0.172,source="quest_giver",zoneID=6138},questType="standard"},
[31085] = {id=31085,name="Fires and Fears of Old",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="We've found the blades, bound them together with wood and shade, and blessed them with an ancient incantation. If I'm not mistaken, it's time to use this thing. The sprites spoke of an ancient piece of sap within the Amber Hibernal, a mantid cave near their empress' palace. That must be the \"Blood of Ancients\" that the prophecy spoke of. Whatever's inside that sap must be important. Good luck, .",objectivesText="Use the Ruining Fork on Iyyokuk the Lucid, then protect him until he is able to escape. Progress: Make sure to bring that forked blade with you.",starts={{npcID=62667,x=0.506,y=0.118,zoneID=6138}},ends={{npcID=62667,x=0.506,y=0.118,zoneID=6138}},coords={x=0.506,y=0.118,source="quest_giver",zoneID=6138},questType="standard"},
[31086] = {id=31086,name="Blood of Ancients",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Lya and I agree on one thing: \"Blood of Ancients\" is almost certainly the sap from the great trees of the area. I should know - I brew with the stuff all the time. The most ancient tree of all is the one that Grand Empress Shek'zeer calls her home, now known as the Heart of Fear. Find some amber from that tree, and our brew should be complete.",objectivesText="Obtain a Chunk of Solidified Amber . Progress: Any luck?",starts={{npcID=62666,x=0.512,y=0.114,zoneID=6138}},ends={{npcID=62666,x=0.512,y=0.114,zoneID=6138}},coords={x=0.512,y=0.114,source="quest_giver",zoneID=6138},questType="standard"},
[31087] = {id=31087,name="Extending Our Coverage",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="The Klaxxi 'va hear another paragon. His cries are weak and lost in darkness. The signal must be strengthened. There is a tower in Amberglow Hollow that has been silent for many years. It must sing; The Klaxxi demand it! This time I will go with you. You will help me repair it. Take the resonating crystal and meet me in Amberglow.",objectivesText="Activate the Resonating Beacon in Amberglow Hollow.",starts={{npcID=64815,x=0.548,y=0.34,zoneID=6138}},ends={{npcID=65365,x=0.48,y=0.496,zoneID=6138},{npcID=65542,x=0.48,y=0.496,zoneID=6138}},coords={x=0.548,y=0.34,source="quest_giver",zoneID=6138},questType="standard"},
[31088] = {id=31088,name="Crime and Punishment",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="The Stinging Trail nurtures young Kypari trees. The empress drains the saplings too early, outsider. They must grow before the amber can be taken. The Klaxxi 'va demand punishment for this crime! It will please them if you rain death on the Ik'thik harvesters .",objectivesText="Kill 8 Ik'thik Harvesters on the Stinging Trail. Progress: Have the harvesters been punished?",starts={{npcID=65365,x=0.48,y=0.496,zoneID=6138}},ends={{npcID=65365,x=0.48,y=0.496,zoneID=6138}},coords={x=0.48,y=0.496,source="quest_giver",zoneID=6138},questType="standard"},
[31089] = {id=31089,name="By the Sea, Nevermore",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="The Klaxxi 'va have spoken to me, outsider. The paragon is hidden in the Briny Muck only, he is not so hidden anymore. The lizard men surround him. He cannot fall into their scaly hands. You will find him; you will awaken him. Do not return without him! If you do this The Klaxxi will be pleased with us.",objectivesText="Use the Klaxxi Tuning Fork on the Ocean-Worn Rocks to awaken the paragon.",starts={{npcID=65365,x=0.48,y=0.496,zoneID=6138},{npcID=65975,x=0.48,y=0.496,zoneID=6138}},ends={{npcID=63876,x=0.434,y=0.634,zoneID=6138}},coords={x=0.48,y=0.496,source="quest_giver",zoneID=6138},questType="standard"},
[31090] = {id=31090,name="Better With Age",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="It is a crime to harvest the young trees, but a much bigger crime to waste the amber. Young amber is not as strong, but the Klaxxi need it to continue the fight. We will bring them more and they will sing my praises! Gather the young amber. We will store it until it is aged and can be consumed.",objectivesText="Gather 7 Amber-Filled Jars from the Amber Collectors on the Stinging Trail. Progress: I would go with you to gather amber, but my talents are more useful here.",starts={{npcID=65365,x=0.48,y=0.496,zoneID=6138}},ends={{npcID=65365,x=0.48,y=0.496,zoneID=6138}},coords={x=0.48,y=0.496,source="quest_giver",zoneID=6138},questType="standard"},
[31091] = {id=31091,name="Reunited",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="You look at me and see I am no great warrior. Why was I chosen to be a Paragon? Not all weapons can be seen, Wakener. One should not judge by appearance alone. Before I explain further, I need to know that you are trustworthy. Something precious to me was hidden at the time of my preservation. I am nothing without it. Defend me as I unearth my greatest weapon, and you will have my trust.",objectivesText="Assist Kaz'tik the Manipulator as he unearths his greatest weapon.",starts={{npcID=63876,x=0.434,y=0.634,zoneID=6138}},ends={{npcID=64013,x=0.434,y=0.634,zoneID=6138},{npcID=64344,x=0.416,y=0.72,zoneID=6138}},coords={x=0.434,y=0.634,source="quest_giver",zoneID=6138},questType="standard"},
[31092] = {id=31092,name="Feed or Be Eaten",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="After years of working with the Kunchong I developed a theory; raising one from infancy would strengthen the bond and therefore strengthen the sonic connection. I had just begun training Kovok when I was chosen for encasement. He is still very young and will need diligent training to reach his full potential. I'm entrusting Kovok to you, but be warned; if any harm comes to him your life is forfeit. First, you must feed him to gain his trust. The turtles in the area should be suitable for this.",objectivesText="Begin Kovok's training by feeding him 6 Succulent Turtle Filets found on the Brineshell Snappers in the Briny Muck.",starts={{npcID=64013,x=0.434,y=0.634,zoneID=6138},{npcID=64344,x=0.416,y=0.72,zoneID=6138}},ends={{npcID=63758,x=0.542,y=0.358,zoneID=6138}},coords={x=0.434,y=0.634,source="quest_giver",zoneID=6138},questType="standard"},
[31093] = {id=31093,name="Hozen in the Mist",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,description="Dear $p, Your research into the hozen has proven quite enlightening. If you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection. Thank you for your diligence! Sincerely, Lorewalker Cho",objectivesText="Bring Hozen in the Mist to Lorewalker Cho at the Seat of Knowledge. Provided item:",starts={{x=0.832,y=0.296,mapID=390,npcID=61962}},ends={{npcID=61962,x=0.832,y=0.296,zoneID=5840}},coords={mapID=390,x=0.832,y=0.296},questType="standard"},
[31094] = {id=31094,name="Fish Tales",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,description="Dear $p, I have thoroughly enjoyed reading your research in to the jinyu. A fascinating people and quite clever too. If you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection. Thank you for your diligence! Sincerely, Lorewalker Cho",objectivesText="Bring Fish Tails to Lorewalker Cho at the Seat of Knowledge. Provided item:",starts={{x=0.832,y=0.296,mapID=390,npcID=61962}},ends={{npcID=61962,x=0.832,y=0.296,zoneID=5840}},coords={mapID=390,x=0.832,y=0.296},questType="standard"},
[31095] = {id=31095,name="The Dark Heart of the Mogu",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,description="Dear $p, We have always known the mogu to be dark and sinister. Your research however would imply that they are far worse. If you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection. Thank you for your diligence! Sincerely, Lorewalker Cho",objectivesText="Bring The Dark Heart of the Mogu to Lorewalker Cho at the Seat of Knowledge. Provided item:",starts={{x=0.832,y=0.296,mapID=390,npcID=61962}},ends={{npcID=61962,x=0.832,y=0.296,zoneID=5840}},coords={mapID=390,x=0.832,y=0.296},questType="standard"},
[31096] = {id=31096,name="What is Worth Fighting For",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,mapID=1530,description="Dear $p, You have recovered the story of our people's freedom from the mogu empire. If you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection. Thank you for your diligence! Sincerely, Lorewalker Cho",ends={{npcID=61962,x=0.832,y=0.296,mapID=1530}},questType="standard"},
[31097] = {id=31097,name="Heart of the Mantid Swarm",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,description="Dear $p, While we appreciate your efforts to investigate the lore of Pandaria, the documents you sent us on the mantid managed to rob me of several nights sleep. Terrifying stuff. If you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection. Thank you for your diligence! Sincerely, Lorewalker Cho",objectivesText="Bring Heart of the Mantid Swarm to Lorewalker Cho at the Seat of Knowledge. Provided item:",starts={{x=0.832,y=0.296,mapID=390,npcID=61962}},ends={{npcID=61962,x=0.832,y=0.296,zoneID=5840}},coords={mapID=390,x=0.832,y=0.296},questType="standard"},
[31100] = {id=31100,name="The Song of the Yaungol",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,description="Dear $p, Your research in to the yaungol has proven most insightful. If you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection. Thank you for your diligence! Sincerely, Lorewalker Cho",objectivesText="Bring The Song of the Yaungol to Lorewalker Cho at the Seat of Knowledge. Provided item:",starts={{x=0.832,y=0.296,mapID=390,npcID=61962}},ends={{npcID=61962,x=0.832,y=0.296,zoneID=5840}},coords={mapID=390,x=0.832,y=0.296},questType="standard"},
[31102] = {id=31102,name="The Seven Burdens of Shaohao",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,description="Dear $p, It would seem you have discovered the full tale of Shaohao, the last emperor of Pandaria. If you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection. Thank you for your diligence! Sincerely, Lorewalker Cho",objectivesText="Bring The Seven Burdens of Shaohao to Lorewalker Cho at the Seat of Knowledge. Provided item:",starts={{x=0.832,y=0.296,mapID=390,npcID=61962}},ends={{npcID=61962,x=0.832,y=0.296,zoneID=5840}},coords={mapID=390,x=0.832,y=0.296},questType="standard"},
[31103] = {id=31103,name="The Ballad of Liu Lang",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,description="Dear $p, At long last thanks to your research we have the full Ballad of Liu Lang. If you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection. Thank you for your diligence! Sincerely, Lorewalker Cho",objectivesText="Bring The Ballad of Liu Lang to Lorewalker Cho at the Seat of Knowledge. Provided item:",starts={{x=0.832,y=0.296,mapID=390,npcID=61962}},ends={{npcID=61962,x=0.832,y=0.296,zoneID=5840}},coords={mapID=390,x=0.832,y=0.296},questType="standard"},
[31104] = {id=31104,name="The Challenger's Ring: Yalia Sagewhisper",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="The Shado-Pan brothers and sisters continue to whisper of your deeds, . In fact, Yalia herself has taken quite an interest in your studies. She wishes to challenge you in the training ring. You would do well to impress her. If you do, she just may be willing to help you in the future.",objectivesText="Challenge Yalia Sagewhisper and defeat her in the Challenger's Ring. Progress: Did you speak to Yalia?",starts={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},ends={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},coords={x=0.49,y=0.704,source="quest_giver",zoneID=5842},questType="standard"},
[31105] = {id=31105,name="The Mogu Menace",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Our scouts have discovered a heavy mogu force at Shan'ze Dao to the northwest. The island was supposedly uninhabited, so their presence is disturbing news. Even more disturbing is the fact that they are performing sinister experiments on the island. I need a capable to check out the situation. The Shan'ze are likely to give you trouble, and if they do, kill them.",objectivesText="Kill 12 Shan'ze Serpentbinders or Shan'ze Beastmasters. Progress: How many were there?",starts={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},ends={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},coords={x=0.49,y=0.704,source="quest_giver",zoneID=5842},questType="standard"},
[31106] = {id=31106,name="The Mogu Menace",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Our scouts have discovered a heavy mogu force at Shan'ze Dao to the northwest. The island was supposedly uninhabited, so their presence is disturbing news. Even more disturbing is the fact that they are performing sinister experiments on the island. I need a capable to check out the situation. The Shan'ze are likely to give you trouble, and if they do, kill them.",objectivesText="Kill 12 Shan'ze Serpentbinders or Shan'ze Beastmasters. Progress: How many were there?",starts={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},ends={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},coords={x=0.49,y=0.704,source="quest_giver",zoneID=5842},questType="standard"},
[31107] = {id=31107,name="Citizens of a New Empire",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="At Shek'zeer's command, the great kypari tree of Kypari Vor was twisted into a totem of horror. Like those outside of the palace, the clutch nearby is now used to corrupt our swarmborn. Recover the eggs of the Vor'thik before they are tainted. We shall raise them here. They will be the citizens of a new empire, free from the sha.",objectivesText="Gather 10 Vor'thik Eggs from Kypari Vor. Progress: Kypari Vor was beautiful once. Rich with amber and surrounded by prime hunting grounds.",starts={{npcID=62774,x=0.55,y=0.354,zoneID=6138}},ends={{npcID=62774,x=0.55,y=0.354,zoneID=6138}},coords={x=0.55,y=0.354,source="quest_giver",zoneID=6138},questType="standard"},
[31108] = {id=31108,name="Concentrated Fear",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Amber is power. It brings life. This... dread amber you brought me has been twisted. It is concentrated fear. The Vor'thik know this well. Their kypari has been completely engulfed by sha, and they use the dread amber to quicken their own swarmborn. Bring me the crystals used by the Vor'thik fear-shapers in their rituals. The Klaxxi will study them and decide on a protocol for disposal.",objectivesText="Gather 4 Dread Amber Foci from Vor'thik Fear-Shapers at Kypari Vor. Progress: Do you have the crystals?",starts={{npcID=64599,x=0.55,y=0.354,zoneID=6138}},ends={{npcID=64599,x=0.55,y=0.354,zoneID=6138}},coords={x=0.55,y=0.354,source="quest_giver",zoneID=6138},questType="standard"},
[31109] = {id=31109,name="Culling the Swarm",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="The Empress continues to amass her forces. Without intervention, they WILL overrun that wall - even if it means smothering it in the corpses of a million swarmborn. Let us find a better place for those corpses. Let me know when you are ready to depart for the clutches - I will gladly drop you in from above.",objectivesText="Slay 40 Shek'zeer Mantid in the Clutches of Shek'zeer. Speak with Kil'ruk the Wind-Reaver for an air-drop. Progress: We must kill faster than they can multiply. It is that simple.",starts={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},ends={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},coords={x=0.55,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31110] = {id=31110,name="Through the Portal",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Ah, just the I wanted to see! We've finally figured out why the portal is not working. We need more arcane powder! It would take us months to get a shipment sent out to us, but luckily, the mogu on this island carry plenty for their own spells. They tend to use some older stuff, so we're going to need a lot of it.",objectivesText="Collect 1000 Ancient Arcane Powder . Progress: Did you find the powders?",starts={{npcID=62810,x=0.288,y=0.226,zoneID=5842}},ends={{npcID=62810,x=0.288,y=0.226,zoneID=5842}},coords={x=0.288,y=0.226,source="quest_giver",zoneID=5842},questType="standard"},
[31111] = {id=31111,name="Eradicating the Zan'thik",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="The warriors of Zan'vess are some of the most feared and respected in the empire, for good reason. Impalers are unmatched in their mastery of the polearm - no doubt Malik trained among the Zan'thik in his time. Their manipulators command terrifying sonic power with the ease and subtlety of a breath. Both will need to be dealt with.",objectivesText="Kill 6 Zan'thik Impalers and 6 Zan'thik Manipulators in Zan'vess.",starts={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},ends={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},coords={x=0.55,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31112] = {id=31112,name="They're So Thorny!",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,mapID=371,description="The crate, once full of desperately needed supplies, has been thoroughly pillaged. A quick scan of the area shows evidence left behind by the thieves. Icy thorns, just like the ones on the water sprites on the shoreline to the east. This is a life or death situation for your band of survivors. Those supplies need to be retrieved from these thieving pests and returned to camp.",objectivesText="Collect 5 Emergency Supplies from the Water Sprites. Progress: You manage to get your hands on them supplies, pal?",starts={{x=0.228,y=0.305,mapID=371,npcID=62923}},ends={{npcID=55521,x=0.312,y=0.216,zoneID=5785}},coords={mapID=371,x=0.228,y=0.305},questType="standard"},
[31113] = {id=31113,name="Assault Fire Camp Gai-Cho",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="The Yaungol are a constant nuisance, but the group at Fire Camp Gai-Cho, to the northeast, conspired with the Osul yaungol in their recent incursion into Kun-Lai. We cannot allow such an incursion to go unpunished. Go, attack Fire Camp Gai-Cho. We need to make sure they remain occupied, so that they cannot rise up and threaten The Ox Gate again.",objectivesText="Kill 16 Gai-Cho Yaungol , Earthtalkers or Pitchthrowers. Progress: Is your raid on Gai-Cho complete?",starts={{npcID=63009,x=0.494,y=0.706,zoneID=5842}},ends={{npcID=63009,x=0.494,y=0.706,zoneID=5842}},coords={x=0.494,y=0.706,source="quest_giver",zoneID=5842},questType="standard"},
[31114] = {id=31114,name="Assault Deadtalker's Plateau",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="We have always left the Deadtalkers alone. For so long, they were just responsible for maintaining the sacred burial grounds of the yaungol tribes. Now, though, they are practicing dark magic, defiling the corpses of their former clanmates... I know not where they learned those dark magics, or why they no longer treat their dead with respect, but we do not have time to find out. We need to stop them.",objectivesText="Kill 8 Deadtalker Corpsedefilers and 1 Deadtalker Crusher . Progress: Have you defeated the Deadtalkers?",starts={{npcID=63009,x=0.494,y=0.706,zoneID=5842}},ends={{npcID=63009,x=0.494,y=0.706,zoneID=5842}},coords={x=0.494,y=0.706,source="quest_giver",zoneID=5842},questType="standard"},
[31115] = {id=31115,name="FLAG - Freed Han",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=6138,mapID=422,questType="standard"},
[31116] = {id=31116,name="Spirit Dust",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="The spirits that the Yaungol are entrapping from the remains of their ancestors still have a bit of the essence of life within them. If you defeat the spirits in battle, you can collect essence from the spirits as dust, and then return it to the corpses in the area, which will send the spirits, finally, to the next life. This is the only way to set right what the Deadtalkers have done. It will also help keep us safe.",objectivesText="Return 8 spirits to their remains at the Deadtalker Plateau in Townlong Steppes .",starts={{npcID=63009,x=0.494,y=0.706,zoneID=5842}},ends={{npcID=63009,x=0.494,y=0.706,zoneID=5842}},coords={x=0.494,y=0.706,source="quest_giver",zoneID=5842},questType="standard"},
[31117] = {id=31117,name="Uruk!",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Uruk is the Deadtalker of the Townlong yaungol. Your mission will not be truly complete until you defeat him. Go to it!",objectivesText="Kill Uruk at Deadtalker's Plateau in Townlong Steppes . Progress: How goes the mission?",starts={{npcID=63009,x=0.494,y=0.706,zoneID=5842}},ends={{npcID=63009,x=0.494,y=0.706,zoneID=5842}},coords={x=0.494,y=0.706,source="quest_giver",zoneID=5842},questType="standard"},
[31118] = {id=31118,name="The Deadtalker Cipher",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="We need to understand what went wrong with the Deadtalkers. For so many years, the Deadtalkers were simply responsible for maintaining the burial grounds and holding funerals for fallen warriors. From a recent raid, we've recovered a tablet from the grounds that is clearly written using a cipher, but it isn't one we've encountered before. If you can gather a ciphered scroll from one of the Deadtalkers, we can begin to put together the cypher and understand what's happened.",starts={{npcID=63009,x=0.494,y=0.706,mapID=388}},ends={{npcID=63009,x=0.494,y=0.706,mapID=388}},coords={x=0.494,y=0.706,source="quest_giver",mapID=388},questType="standard"},
[31119] = {id=31119,name="The Enemy of My Enemy... Is Still My Enemy!",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="The mantid are our enemies. As are the yaungol at Fire Camp Gai-Cho. It is fortunate, then, that they are also each other's enemies. Mantid from Kri'vess constantly attack the Gai-Cho yaungol, who hold them off at their front gates. I want you to wreak havoc. \"Borrow\" some highly explosive oil barrels from camp Gai-Cho, and toss them down onto the battlefield from the air. I don't care which ones you kill, just kill a lot of them.",objectivesText="Use Highly Explosive Yaungol Oil Barrels to kill 100 mantid or yaungol on the Gai-Cho Battlefield. Progress: How goes the battle?",starts={{npcID=63009,x=0.494,y=0.706,zoneID=5842}},ends={{npcID=63009,x=0.494,y=0.706,zoneID=5842}},coords={x=0.494,y=0.706,source="quest_giver",zoneID=5842},questType="standard"},
[31120] = {id=31120,name="Cheng Bo!",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Cheng Bo is the Warbringer of Fire Camp Gai-Cho. While you've made a dent in their operations, you now have an opportunity to strike a major blow. Slay the Warbringer!",objectivesText="Kill Cheng-Bo at Fire Camp Gai-Cho in Townlong Steppes Progress: How goes the assualt?",starts={{npcID=63009,x=0.494,y=0.706,zoneID=5842}},ends={{npcID=63009,x=0.494,y=0.706,zoneID=5842}},coords={x=0.494,y=0.706,source="quest_giver",zoneID=5842},questType="standard"},
[31121] = {id=31121,name="Stay a While, and Listen",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,mapID=371,description="Rush rush rush - are your people always in such a hurry? Sit and have some tea with me a moment, and we will discuss your plight. Lorewalker Cho 's features settle into a patient smile.>",objectivesText="Drink from Cho's Teapot. Progress: I hope I didn't bore you, traveler.",starts={{npcID=55768,x=0.276,y=0.326,zoneID=5785}},ends={{npcID=55768,x=0.276,y=0.326,zoneID=5785}},coords={x=0.276,y=0.326,source="quest_giver",zoneID=5785},questType="standard"},
[31122] = {id=31122,name="Chose Prot Warrior",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31123] = {id=31123,name="Chose Arms Warrior",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31124] = {id=31124,name="Chose Brewmaster",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31125] = {id=31125,name="Unlocked Chao",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31126] = {id=31126,name="Unlocked Lao-Chen",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31127] = {id=31127,name="The Challenger's Ring: Chao the Voice",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="It looks like you're quite the fighter, $p. Chao heard about it, and she's been talking about how she'd kick your... Well, let's just say I think you should challenge her and try to get her respect.",objectivesText="Challenge Chao the Voice, and then defeat her in combat at Shado-Pan Garrison in Townlong Steppes . Progress: Well? How did it go?",starts={{npcID=63009,x=0.494,y=0.706,zoneID=5842}},ends={{npcID=63009,x=0.494,y=0.706,zoneID=5842}},coords={x=0.494,y=0.706,source="quest_giver",zoneID=5842},questType="standard"},
[31128] = {id=31128,name="The Challenger's Ring: Lao-Chin the Iron Belly",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Lao-Chin seems to have his head in the clouds... or, rather, in his beer. After all of his recent battles, he seems completely obsessed with with trying to develop the perfect brew for fighting. That's well and good, but we need him to actually do some fighting! You should go challenge him, see if you can snap him out of his rut. If you beat him, he'll probably want to go out and help fight just to try to one-up you!",objectivesText="Challenge Lao-Chen the Iron Belly and then defeat him in combat at Shado-Pan Garrison in Townlong Steppes . Progress: Well?",starts={{npcID=63009,x=0.494,y=0.706,zoneID=5842}},ends={{npcID=63009,x=0.494,y=0.706,zoneID=5842}},coords={x=0.494,y=0.706,source="quest_giver",zoneID=5842},questType="standard"},
[31129] = {id=31129,name="Fate of the Stormstouts",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="$p! It is so great to see you healthy, and traveling so far. It would seem that our paths are quite tightly intertwined. I'm here looking for my family. I am told that several Stormstouts came across the wall to help face the mantid threat. I mean to find them, and join them. Have you seen anyone named Stormstout come through here? Would you mind helping me ask around?",objectivesText="Ask the inhabitants of The Sunset Brewgarden if they've seen any Stormstouts. Progress: You are brave to have come across the wall, <race>.",starts={{npcID=62779,x=0.504,y=0.12,mapID=422}},ends={{npcID=62779,x=0.504,y=0.12,mapID=422}},coords={x=0.504,y=0.12,source="quest_giver",mapID=422},questType="standard"},
[31130] = {id=31130,name="A Visit with Lorewalker Cho",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,mapID=371,description="Stranger, I may be able to help you find your prince. But first, I would like to know a little more about you and your people. Come, help me with my chores, and we will chat. You have the look of a grizzled war veteran, but certainly you have a few minutes to help a bookish Pandaren like myself putter around the house, yes?",objectivesText="Befriend Lorewalker Cho by assisting him around his house: Trim his tree, paint his wall, and feed his birds. Progress: There is nothing like a little manual labor to bring strangers together, don't you think?",starts={{npcID=54961,x=0.536,y=0.914,zoneID=5785}},ends={{npcID=56287,x=0.538,y=0.906,zoneID=5785},{npcID=61218,x=0.536,y=0.914,zoneID=5785}},coords={x=0.536,y=0.914,source="quest_giver",zoneID=5785},questType="standard"},
[31131] = {id=31131,name="Whitepetal Lake",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="Reports suggest that things are quiet at Whitepetal Lake today, but I've dispatched Ren Firetongue and He Softfoot to make sure it stays they way. If you want to aid the effort further, head to the west to the lake, meet up with He, and help him keep things secure from any hostile threats.",objectivesText="Speak to He Softfoot at Whitepetal Lake.",starts={{x=0.566,y=0.436,mapID=390,npcID=58408}},ends={{x=0.566,y=0.436,mapID=390,npcID=58408}},coords={mapID=390,x=0.566,y=0.436},questType="standard"},
[31132] = {id=31132,name="A Mile in My Shoes",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,mapID=371,description="Oh, where have my manners gone? Technically, I suppose I am the host here. Allow me to tell you a little bit about myself and my people before asking questions of you.",objectivesText="Speak to Lorewalker Cho at the Circle of Bone.",starts={{npcID=55768,x=0.276,y=0.326,zoneID=5785}},ends={{npcID=63217,x=0.308,y=0.34,zoneID=5785}},coords={x=0.276,y=0.326,source="quest_giver",zoneID=5785},questType="standard"},
[31133] = {id=31133,name="Kor'thik Aggression",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="I'm no brewer - just looking at all those heaps of ingredients makes my head spin. Just put the brew in front of me when it's finished, thank you. No, I'm here to make sure that the brewers don't get cut in half while they're trying to make that perfect brew. It's not an easy job. The Kor'thik mantid across this basin have been attacking us nightly. If you're already heading over there, why don't you return the favor and attack a few of them?",objectivesText="Slay 17 Kor'thik Mantid at Kor'vess. Progress: Can't stand those mantid.",starts={{npcID=63218,x=0.502,y=0.124,zoneID=6138}},ends={{npcID=63218,x=0.502,y=0.124,zoneID=6138}},coords={x=0.502,y=0.124,source="quest_giver",zoneID=6138},questType="standard"},
[31134] = {id=31134,name="If These Stones Could Speak",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,mapID=371,description="This is a very ancient place, traveler. Only recently have I pieced together a method of translating the forgotten language carved into these stones. Oh, the thrill of discovery! This never gets old, I assure you. Here, you are the guest. You do the honors. I insist. Use this key to unlock the secrets the stones contain.",objectivesText="Use the Stone Monoliths at the Circle of Bone. Progress: Your assistance is most appreciated, traveler.",starts={{npcID=63217,x=0.308,y=0.34,zoneID=5785}},ends={{npcID=63217,x=0.308,y=0.34,zoneID=5785}},coords={x=0.308,y=0.34,source="quest_giver",zoneID=5785},questType="standard"},
[31135] = {id=31135,name="The Future of Gnomeregan",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=6457,mapID=469,description="It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts. Xi, Friend of the Small has visited us from a faraway land and will help oversee your training and adjustment to life on the surface. She's waiting for you on the small practice field across the road.",objectivesText="Meet with Xi, Friend of the Small in New Tinkertown.",starts={{npcID=42396,x=0.338,y=0.386,zoneID=1},{npcID=42396,x=0.394,y=0.382,zoneID=6457}},ends={{npcID=63238,x=0.4,y=0.356,zoneID=6457}},coords={x=0.338,y=0.386,source="quest_giver",zoneID=1},questType="standard"},
[31136] = {id=31136,name="Behind Our Lines",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="Scouts bring me reports of a powerful Imperion that slipped through our lines in the south and is now heading for the road in the eastern vale. I need someone I can trust to stop it. Find it and kill it quickly, <name>.",objectivesText="Kill General Temuja . Progress: Did you hunt down the Imperion as I requested?",starts={{x=0.566,y=0.436,mapID=390,npcID=58408}},ends={{x=0.566,y=0.436,mapID=390,npcID=58408}},coords={mapID=390,x=0.566,y=0.436},questType="standard"},
[31137] = {id=31137,name="Meet the High Tinker",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=1,mapID=469,description="I don't know if you'll remember Mekkatorque or not. Nevin and the other gnomes have mentioned that memory loss is pretty common for you survivors. Anyways, High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.",objectivesText="Introduce yourself to High Tinker Mekkatorque in New Tinkertown.",starts={{npcID=63238,x=0.4,y=0.356,zoneID=6457}},ends={{npcID=42317,x=0.388,y=0.328,zoneID=6457},{npcID=42317,x=0.336,y=0.364,zoneID=1}},coords={x=0.4,y=0.356,source="quest_giver",zoneID=6457},questType="standard"},
[31138] = {id=31138,name="The Arts of a Monk",level=3,requiredLevel=1,faction="alliance",expansion=4,zoneID=6457,description="When you fight, you grow in skill. As you grow in skill, you will begin to figure out new moves. Go, explore, learn, and show me what you figure out.",objectivesText="Reach level 3 to learn Tiger Palm . Once you've learned it, use it twice at a Training Dummy in New Tinkertown.",starts={{x=0.401,y=0.356,mapID=469,npcID=63238}},ends={{x=0.401,y=0.356,mapID=469,npcID=63238}},coords={mapID=469,x=0.401,y=0.356},questType="standard"},
[31139] = {id=31139,name="Beating Them Back!",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=6170,mapID=425,description="So you're the new recruit from Stormwind, eh? I'm Marshal McBride , commander of this garrison. Glad to have you on board... . It is , right? You've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon. Head northwest into the forest and kill the attacking Blackrock worgs ! Help my soldiers!",objectivesText="Kill 6 Blackrock Battle Worgs . Progress: Have you beaten back the Blackrock battle worgs ?",starts={{npcID=197,x=0.48,y=0.42,zoneID=12},{npcID=197,x=0.332,y=0.532,zoneID=6170}},ends={{npcID=197,x=0.48,y=0.42,zoneID=12},{npcID=197,x=0.332,y=0.532,zoneID=6170}},coords={x=0.48,y=0.42,source="quest_giver",zoneID=12},questType="standard"},
[31140] = {id=31140,name="Lions for Lambs",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=6170,mapID=425,description="The invading orcs aren't fools. They are sizing us up, making sure that when they attack it will be to their advantage. In the forest, to the northwest, are Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. I want you take the fight to them! Kill the Blackrock spies! We must show them that we know they are watching us and that we are prepared!",objectivesText="Kill 8 Blackrock Spies .",starts={{npcID=197,x=0.48,y=0.42,zoneID=12},{npcID=197,x=0.332,y=0.532,zoneID=6170}},ends={{npcID=197,x=0.48,y=0.42,zoneID=12},{npcID=197,x=0.332,y=0.532,zoneID=6170}},coords={x=0.48,y=0.42,source="quest_giver",zoneID=12},questType="standard"},
[31141] = {id=31141,name="Calligraphed Letter",level=3,requiredLevel=2,faction="alliance",expansion=4,zoneID=6170,description="I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, <name>. It appears to be a letter sealed with the insignia of Bao , a pandaren who is visiting us from a faraway land. I wouldn't hesitate to read it before you go about any other business here in the Abbey.",objectivesText="Read the Calligraphed Letter and speak to Bao in Northshire Abbey. Progress: Ah, you got my letter, <name>... good. I've come from afar to teach your people the ways of the <class>.",starts={{x=0.335,y=0.53,mapID=425,npcID=197}},ends={{x=0.335,y=0.53,mapID=425,npcID=197}},coords={mapID=425,x=0.335,y=0.53},questType="standard"},
[31142] = {id=31142,name="Palm of the Tiger",level=3,requiredLevel=2,faction="alliance",expansion=4,zoneID=6170,description="Now that you've had the chance to test your abilities in battle, it's time to explain one more reason why training is so important. As you get more experience, you'll be able to do new techniques you never thought of. Go, get some experience, learn a new skill, and demonstrate it on one of the training dummies.",objectivesText="Reach level 3 to learn Tiger Palm , then practice using it on a Training Dummy south of the entrance to Northshire Abbey. Progress: Well, did you give it a try?",starts={{x=0.412,y=0.521,mapID=425,npcID=63258}},ends={{x=0.412,y=0.521,mapID=425,npcID=63258}},coords={mapID=425,x=0.412,y=0.521},questType="standard"},
[31143] = {id=31143,name="Join the Battle!",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=6170,mapID=425,description="I received an urgent message from Sergeant Willem . Turns out that the Blackrock orcs have hired goblin assassins. They ambushed our battalion behind the abbey. Willem has asked me to send him a hero. You have to go help them, ! Find Sergeant Willem north of the abbey at the command tent. Go!",objectivesText="Report to Sergeant Willem behind Northshire Abbey in Elwynn Forest .",starts={{npcID=197,x=0.48,y=0.42,zoneID=12},{npcID=197,x=0.332,y=0.532,zoneID=6170},{npcID=63258,x=0.41,y=0.522,zoneID=6170}},ends={{npcID=823,x=0.488,y=0.384,zoneID=12},{npcID=823,x=0.356,y=0.4,zoneID=6170}},coords={x=0.48,y=0.42,source="quest_giver",zoneID=12},questType="standard"},
[31144] = {id=31144,name="They Sent Assassins",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=6170,mapID=425,description="Have you ever seen a goblin, ? They're wretched little monsters that love only two things: gold and themselves. The Blackrock orcs have enlisted the aid of goblin assassins to kill our soldiers. If you look to the field in the north you can barely make out their silhouettes, sneaking about in the grass. I need you to head out there and kill every goblin that you see. They need to learn that nobody messes with the Alliance!",objectivesText="Kill 8 Goblin Assassins .",starts={{npcID=823,x=0.488,y=0.384,zoneID=12},{npcID=823,x=0.356,y=0.4,zoneID=6170}},ends={{npcID=823,x=0.488,y=0.384,zoneID=12},{npcID=823,x=0.356,y=0.4,zoneID=6170}},coords={x=0.488,y=0.384,source="quest_giver",zoneID=12},questType="standard"},
[31145] = {id=31145,name="The Rear is Clear",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=6170,mapID=425,description="Excellent work, ! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride , standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control. Farewell, .",objectivesText="Report to Marshal McBride in front of Northshire Abbey in Elwynn Forest .",starts={{npcID=823,x=0.488,y=0.384,zoneID=12},{npcID=823,x=0.356,y=0.4,zoneID=6170}},ends={{npcID=197,x=0.48,y=0.42,zoneID=12},{npcID=197,x=0.332,y=0.532,zoneID=6170}},coords={x=0.488,y=0.384,source="quest_giver",zoneID=12},questType="standard"},
[31146] = {id=31146,name="Scribbled Scroll",level=3,requiredLevel=2,faction="horde",expansion=4,zoneID=6454,description="Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. The pandaren visitor, Ting, sent it for you. Maybe you monks can read this garbage, but I can't. You should go talk to her. She's in the Inn across the way.",objectivesText="Read the Elegant Scroll and speak to Ting, Strong of Stomach in Deathknell. Progress: Oh, yes, I sent that for you. I hope to prove that Forsaken can learn the arts of the <class> - perhaps you can help?",starts={{x=0.466,y=0.588,mapID=465,npcID=1569}},ends={{x=0.466,y=0.588,mapID=465,npcID=1569}},coords={mapID=465,x=0.466,y=0.588},questType="standard"},
[31147] = {id=31147,name="Tiger Palm",level=3,requiredLevel=2,faction="horde",expansion=4,zoneID=6454,description="As you overcome great challenges in your journey to master struggles both internal and external, you will begin to uncover new abilities hidden inside yourself. Go, now, and develop a mastery of yourself, such that you uncover the Tiger Palm technique. Then, go practice it on a training dummy.",objectivesText="Reach level 3 to learn Tiger Palm , then practice using it on a Training Dummy.",starts={{x=0.53,y=0.564,mapID=465,npcID=63272}},ends={{x=0.53,y=0.564,mapID=465,npcID=63272}},coords={mapID=465,x=0.53,y=0.564},questType="standard"},
[31148] = {id=31148,name="Novice Elreth",level=5,requiredLevel=5,faction="horde",expansion=4,zoneID=85,mapID=18,description="Actually, before I go - you should speak with Novice Elreth. She had some work for you, and you would do well to help others and improve your skills. The next time you see me, I will be in Undercity.",objectivesText="Speak to Novice Elreth at Deathknell in Tirisfal Glades .",questType="standard"},
[31150] = {id=31150,name="Elegant Rune",level=5,requiredLevel=5,faction="alliance",expansion=4,zoneID=6176,description=", this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I'm thinkin' it came from our visitor from afar, Lo . Take a gander at it and go find him inside Anvilmar.",objectivesText="Read the Elegant Rune and speak to Lo in Coldridge Valley. Progress: I like it here, <name>. Your people have quite an appreciation for the finer things!",starts={{npcID=37087,x=0.608,y=0.218,zoneID=6176}},ends={{npcID=63285,x=0.63,y=0.222,zoneID=6176}},coords={x=0.608,y=0.218,source="quest_giver",zoneID=6176},questType="standard"},
[31152] = {id=31152,name="Peering Into the Past",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,mapID=371,description="Just a moment, now. Allow me to gather my things. Wouldn't want me to lose these notes now, would we? Especially after you risked life and limb for them! There, all set. Let us be off, shall we? I must say, I feel much safer traveling with you after seeing how you handled that saurok!",starts={{npcID=63217,x=0.308,y=0.34,mapID=371}},ends={{npcID=63307,x=0.288,y=0.326,mapID=371}},coords={x=0.308,y=0.34,source="quest_giver",mapID=371},questType="standard"},
[31153] = {id=31153,name="Tracking Event - Saved Diaani",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[31154] = {id=31154,name="Tracking Event - Saved Zuulo",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[31156] = {id=31156,name="Calligraphed Parchment",level=3,requiredLevel=2,faction="horde",expansion=4,zoneID=6451,description="Ah, while you were gone a parchment came for you, <name>. Read it when you have time. If I'm not mistaken, it came from our Pandaren friend, Gato . He visits from afar to grant us the honor of his wisdom, and to teach the ways of the monk. Do not shame your people by failing at his lessons!",objectivesText="Read the Calligraphed Parchment and speak with Gato in the Valley of Trials. Progress: Ahh, you have come.",starts={{x=0.448,y=0.666,mapID=461,npcID=3143}},ends={{x=0.448,y=0.666,mapID=461,npcID=3143}},coords={mapID=461,x=0.448,y=0.666},questType="standard"},
[31157] = {id=31157,name="Tiger Palm",level=3,requiredLevel=2,faction="horde",expansion=4,zoneID=6451,description="As you walk the road of your training, you will begin to discover within yourself the power to unlock new techniques. You need not even learn them from me, or another more experienced monk - you will find that they come to you on their own. For now, you should go and practice the basics. Gather more experience, and develop a new technique - once you have, you can practice it on the dummies nearby to master it.",objectivesText="Reach level 3 to learn Tiger Palm . Locate a Training Dummy and practice using Tiger Palm 2 times.",starts={{x=0.426,y=0.684,mapID=461,npcID=63296}},ends={{x=0.426,y=0.684,mapID=461,npcID=63296}},coords={mapID=461,x=0.426,y=0.684},questType="standard"},
[31158] = {id=31158,name="The Basics: Hitting Things",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=14,mapID=463,description="Alright, mon. We start with da basics. I need ta know dat you know how ta swing dat weapon you're totin' around. Go thrash dose tiki targets . Take it slowly. Natural-like. I'll watch ya fighting form and we'll go from dere.",objectivesText="Destroy 6 Tiki Targets .",starts={{npcID=63310,x=0.524,y=0.518,zoneID=6453}},ends={{npcID=63310,x=0.524,y=0.518,zoneID=6453}},coords={x=0.524,y=0.518,source="quest_giver",zoneID=6453},questType="standard"},
[31159] = {id=31159,name="The Rise of the Darkspear",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=6453,mapID=463,description="Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here. Vol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream. No, dis time we not fleein'. Dis time, we are fightin' for a home dat will last. It's time to begin ya trainin', . Speak with Zabrax to the east.",objectivesText="Meet with Zabrax in the Darkspear Training Grounds.",starts={{npcID=37951,x=0.624,y=0.844,zoneID=14},{npcID=37951,x=0.426,y=0.536,zoneID=6453}},ends={{npcID=63310,x=0.524,y=0.518,zoneID=6453}},coords={x=0.624,y=0.844,source="quest_giver",zoneID=14},questType="standard"},
[31160] = {id=31160,name="A Rough Start",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=14,mapID=463,description="Lets put dose skills ta use. I'll start ya off easy, mon. There be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight. Dey're all over the island. Bring me some cat pelts.",objectivesText="Retrieve 6 Wildmane Cat Pelts . Progress: I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.",starts={{npcID=63310,x=0.524,y=0.518,zoneID=6453}},ends={{npcID=63310,x=0.524,y=0.518,zoneID=6453}},coords={x=0.524,y=0.518,source="quest_giver",zoneID=6453},questType="standard"},
[31161] = {id=31161,name="Proving Pit",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=14,mapID=463,description="Ya done quite well for ya'self, . I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer. l put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.",objectivesText="Speak to a Darkspear Jailor , then enter the proving pit and kill a Captive Spitescale Scout .",starts={{npcID=63310,x=0.524,y=0.518,zoneID=6453}},ends={{npcID=63310,x=0.524,y=0.518,zoneID=6453}},coords={x=0.524,y=0.518,source="quest_giver",zoneID=6453},questType="standard"},
[31162] = {id=31162,name="The Arts of a Monk",level=0,requiredLevel=0,faction="horde",expansion=4,zoneID=6453,mapID=463,description="As ya get bettah' at fightin', you'll start to find new tings that ya nevah knew you could do. Wanna see? Go, train up some, and learn someting new. 'Den come back and ya can show me.",objectivesText="Reach level 3 to learn Tiger Palm . Practice using Tiger Palm against a Tiki Target.",starts={{npcID=63310,x=0.524,y=0.518,mapID=463}},ends={{npcID=63310,x=0.524,y=0.518,mapID=463}},coords={x=0.524,y=0.518,source="quest_giver",mapID=463},questType="standard"},
[31163] = {id=31163,name="More Than Expected",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=14,mapID=463,description="Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more. Head down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.",objectivesText="Report to Vol'jin at Darkspear Hold.",starts={{npcID=63310,x=0.524,y=0.518,zoneID=6453}},ends={{npcID=38966,x=0.614,y=0.656,zoneID=6453},{npcID=38966,x=0.688,y=0.886,zoneID=14}},coords={x=0.524,y=0.518,source="quest_giver",zoneID=6453},questType="standard"},
[31166] = {id=31166,name="Tiger Palm",level=3,requiredLevel=2,faction="horde",expansion=4,zoneID=6452,description="You have done well. As you continue along your path, you will grow, learning new techniques that you couldn't have imagined before. Your first lesson is the power of experience. Go, learn a new ability, and demonstrate it for me.",objectivesText="Reach level 3 to learn Tiger Palm . Locate a Training Dummy in Camp Narache and practice using it.",starts={{x=0.278,y=0.286,mapID=462,npcID=63327}},ends={{x=0.278,y=0.286,mapID=462,npcID=63327}},coords={mapID=462,x=0.278,y=0.286},questType="standard"},
[31167] = {id=31167,name="Family Tree",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,mapID=371,description="So there you have it, traveler, or as much of it as would make for a proper introduction, hmm? What of you, then? Are your people so much different than mine? Surely, there must be things we share in common. Let us see...",objectivesText="Light the Incense Bundle at the Circle of Stone. Progress: A fine day we're having, wouldn't you say?",starts={{npcID=63307,x=0.288,y=0.326,zoneID=5785}},ends={{npcID=63307,x=0.288,y=0.326,zoneID=5785}},coords={x=0.288,y=0.326,source="quest_giver",zoneID=5785},questType="standard"},
[31170] = {id=31170,name="Monk Training",level=3,requiredLevel=2,faction="horde",expansion=4,zoneID=6455,description="As you advance within your class, you will want to take advantage of the training that your class trainer can provide you. For young monks here on Sunstrider Isle, your trainer is Pao , our Pandaren visitor. Speak with her and see what training she has available for you. Pao - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.",objectivesText="Speak with Pao , the Monk class trainer, inside the Sunspire on Sunstrider Isle.",starts={{x=0.61,y=0.451,mapID=467,npcID=15278}},ends={{x=0.61,y=0.451,mapID=467,npcID=15278}},coords={mapID=467,x=0.61,y=0.451},questType="standard"},
[31171] = {id=31171,name="Tiger Palm",level=3,requiredLevel=2,faction="horde",expansion=4,zoneID=6455,description="Good. You are off to a bright start. This road will be long, and as you become more accomplished, you will begin to discover that you can do things you could never have imagined before. Go, get more experience, and learn a new technique. Once you have, demonstrate it on one of the training dummies.",objectivesText="Reach level 3 to learn Tiger Palm . Locate a Training Dummy outside the Sunspire and practice using it. Progress: Have you practiced your Tiger Palm ?",starts={{x=0.636,y=0.426,mapID=467,npcID=63332}},ends={{x=0.636,y=0.426,mapID=467,npcID=63332}},coords={mapID=467,x=0.636,y=0.426},questType="standard"},
[31172] = {id=31172,name="Monk Training",level=5,requiredLevel=5,faction="none",expansion=4,questType="standard"},
[31173] = {id=31173,name="The Tiger Palm",level=3,requiredLevel=2,faction="alliance",expansion=4,zoneID=6456,description="I hope your people are all alright... the crash was unbelievably loud and destructive! <Mojo looks you over, evaluating your potential.> Yes, you'll do fine. They've said that they need more people to fight, and they don't want me to hurt myself. I'm not afraid, but I don't want to intrude. So, I'll teach you. As you may have discovered, your experiences in combat will unlock new potential within you. Go, see if you can master a new ability. Show it to me. You'll get the hang of things.",objectivesText="Reach level 3 to learn Tiger Palm . Find a Training Dummy on the northwest side of the Crash Site and practice using it.",starts={{x=0.506,y=0.486,mapID=468,npcID=63335}},ends={{x=0.506,y=0.486,mapID=468,npcID=63335}},coords={mapID=468,x=0.506,y=0.486},questType="standard"},
[31175] = {id=31175,name="Skeer the Bloodseeker",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Our efforts to secure the shallows before Zan'vess have paid off. We have spotted another paragon buried in amber, hidden in the waters to the southwest. Adding another paragon to our numbers is vital. Another champion from ages past could turn the tide in our favor. I would go immediately, but unfortunately, I am needed here. Since you are already a Wakener, you can carry out this task in my stead.",objectivesText="Awaken Skeer the Bloodseeker in the underwater cave.",starts={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},ends={{npcID=63071,x=0.544,y=0.362,zoneID=6138}},coords={x=0.55,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31176] = {id=31176,name="A Strange Appetite",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Food. I must have food. In my time, the meat of the starfish brought not only strength, but also clarity of mind. This is what I must eat. Bring this to me from the nearby shallows. Wait much longer, and I will devour you instead.",objectivesText="Collect 12 Starfish Meat . Progress: The juices of the starfish will clear my mind.",starts={{npcID=63071,x=0.544,y=0.362,zoneID=6138}},ends={{npcID=63071,x=0.544,y=0.362,zoneID=6138}},coords={x=0.544,y=0.362,source="quest_giver",zoneID=6138},questType="standard"},
[31177] = {id=31177,name="Fine Dining",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="In my living years, I was the greatest warrior of the swarm. Help me regain my strength, and I shall show you. I smell the salt sea nearby, and where you can find the sea, you will find briny clackers. Bring me their tails. I must feast upon their flesh.",objectivesText="Collect 8 Clacker Tails . Progress: I have much work to do. The sooner I can fight, the sooner I can return to the Council.",starts={{npcID=63071,x=0.544,y=0.362,zoneID=6138}},ends={{npcID=63071,x=0.544,y=0.362,zoneID=6138}},coords={x=0.544,y=0.362,source="quest_giver",zoneID=6138},questType="standard"},
[31178] = {id=31178,name="A Bloody Delight",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="A warrior is not ready for battle until he tastes the blood of his enemies. I am still too weak to hunt, so you must go in my stead. Only the blood from the fiercest predators will do. I can smell their presence in the waters outside this cave! Bring this to me, and then perhaps you shall see why they call me the Bloodseeker.",objectivesText="Collect 100 Volatile Blood from Dread Remoras. Progress: By drinking the blood of your enemies, you acquire their strength.",starts={{npcID=63071,x=0.544,y=0.362,zoneID=6138}},ends={{npcID=63071,x=0.544,y=0.362,zoneID=6138}},coords={x=0.544,y=0.362,source="quest_giver",zoneID=6138},questType="standard"},
[31179] = {id=31179,name="The Scent of Blood",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="I'm afraid that I wet my hands with saurok blood while you were away. I'm sorry, but I could not help myself. Now, watch them attack me. Pitiful! Do they think to take vengeance for their fallen? Do they come challenge ME? I, who have won a hundred wars? I, who stood alone against thousands and still shouted for my enemies to come? No, these... saurok... will crumple before me like paper before the flame! I shall show you my might, Wakener. Fight alongside me and see. Here they come!",objectivesText="Kill 12 Muckscale Flesheaters and the Muckscale Serpentus .",starts={{npcID=63071,x=0.544,y=0.362,zoneID=6138}},ends={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},coords={x=0.544,y=0.362,source="quest_giver",zoneID=6138},questType="standard"},
[31181] = {id=31181,name="Fresh Pots",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="We got a load of empty crab pots out there that need fresh bait. Now, we COULD pull them one at a time and bait them up here in comfort. A nice chair to sit on, maybe a hot cup of tea to keep you warm. Sounds nice, doesn't it? Never gonna happen. Head to Lonesome Cove, immediately southeast, and bait those pots with two chunks of fresh sea monarch. By \"fresh\" I mean killed right there in the water. Oh, and by \"pots\" I mean traps. If you wanna be part of the crew, you'd better learn the lingo.",objectivesText="Bait 10 Empty Crab Pots in Lonesome Cove. Each pot requires 2 Sea Monarch Chunks . Progress: What's wrong, green? You aren't afraid of the dark, icy sea are you?",starts={{npcID=63349,x=0.548,y=0.722,zoneID=6138}},ends={{npcID=63349,x=0.548,y=0.722,zoneID=6138}},coords={x=0.548,y=0.722,source="quest_giver",zoneID=6138},questType="standard"},
[31182] = {id=31182,name="You Otter Know",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="You know what happened to the bait in those pots? Otters. That's what happened. They prefer fresh clams, but they'll pick our crab traps clean if they're hungry enough. The otters in Lonesome Cove are protected by law and we run a legitimate operation here. As much as I'd love to chum those little rats and call it a day, we just make sure they aren't hungry enough to raid the crab pots. Toss 'em a few clams to keep them busy while you're out there.",objectivesText="Use the Bag of Clams to feed 8 Coldwhisker Otters in Lonesome Cove.",starts={{npcID=63349,x=0.548,y=0.722,zoneID=6138}},ends={{npcID=63349,x=0.548,y=0.722,zoneID=6138}},coords={x=0.548,y=0.722,source="quest_giver",zoneID=6138},questType="standard"},
[31183] = {id=31183,name="Meet the Cap'n",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Alright, $p, I got another job for ya. You see that lion seal in the pen over there? Name's Dog. He's been Soggy's pet for years. Dog's acting up lately - I think he's getting restless in that pen. Why don't you go talk to Soggy and let him know. I'd say it's about time you meet the cap'n anyway.",objectivesText="Speak with \"Soggy\" Su-Dao in Soggy's Gamble.",starts={{npcID=63349,x=0.548,y=0.722,zoneID=6138}},ends={{npcID=63317,x=0.556,y=0.724,zoneID=6138}},coords={x=0.548,y=0.722,source="quest_giver",zoneID=6138},questType="standard"},
[31184] = {id=31184,name="Old Age and Treachery",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Look, I ain't got reason to trust you, but there's a task I can't give to my crew. I need you to search the wreck of our old ship, the Mist-Hopper, and bring back the charter. It'd be sealed up in a silver tube, in a footlocker. It's sort of, uh... incriminating. I can't risk any of the crew finding it if they decide to visit the ol' girl. She's resting on the Shelf of Mazu, to the west. I'd suggest riding a rip current out there, if you got the stomach. They're all over the shelf.",objectivesText="Recover the charter from the Wreck of the Mist-Hopper. Progress: To be honest, I hope a grouper ate the old charter. Wait, then it might end up here anyway. Dang it!",starts={{npcID=63317,x=0.556,y=0.724,zoneID=6138}},ends={{npcID=63317,x=0.556,y=0.724,zoneID=6138}},coords={x=0.556,y=0.724,source="quest_giver",zoneID=6138},questType="standard"},
[31185] = {id=31185,name="Walking Dog",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Dog ain't my \"pet.\" He's a member of this crew, and my best friend. Saved my life more than once, you know. But I'm gettin' too old to walk him anymore, and he still needs his exercise. Take Dog for a trip around the shelf for me, would ya? He loves to swim through the hot geysers just southeast of the shallows. He absolutely has to... er... \"leave his mark\" on the dead whale at the far western edge of the shelf. Oh, and he'll want to visit our old shipwreck, too. He likes to reminisce.",objectivesText="Take Dog to visit the hot geysers, the whale corpse, and the wreck of the Mist-Hopper on the Shelf of Mazu.",starts={{npcID=63317,x=0.556,y=0.724,zoneID=6138}},ends={{npcID=63317,x=0.556,y=0.724,zoneID=6138}},coords={x=0.556,y=0.724,source="quest_giver",zoneID=6138},questType="standard"},
[31186] = {id=31186,name="Dog Food",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Dog whines as best as a lion seal can, feebly lifting one flipper toward his massive jaws. He's hungry. The Shelf of Mazu is covered in rockshell makrura that should make a fine meal for him.>",objectivesText="Help Dog to eat the remains of 10 Rockshell Snapclaws. Progress: <This has got to be the most pathetic lion seal you've ever seen.>",starts={{npcID=63955,x=0.39,y=0.796,zoneID=6138}},ends={{npcID=63277,x=0.546,y=0.714,zoneID=6138},{npcID=63955,x=0.39,y=0.796,zoneID=6138}},coords={x=0.39,y=0.796,source="quest_giver",zoneID=6138},questType="standard"},
[31187] = {id=31187,name="On the Crab",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="I just got word that a string of pots we dropped this morning hit it BIG. We're on the crab! Problem is, the rips are getting stronger and we lost track of some of the pots. They're just sitting out there, filled with spiky blue GOLD! I need you back out there. Hook one of these buoys up to any of the full traps you find and send it to the surface for us.",objectivesText="Attach a Mist-Hopper Buoy to 8 Full Crab Pots on the Shelf of Mazu.",starts={{npcID=63349,x=0.548,y=0.722,zoneID=6138}},ends={{npcID=63349,x=0.548,y=0.722,zoneID=6138}},coords={x=0.548,y=0.722,source="quest_giver",zoneID=6138},questType="standard"},
[31188] = {id=31188,name="Shark Week",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Crabbing is our big money-maker, but we send all kinds of goods back around the wall. Oils, plants, even rare minerals - the sea's bounty is rich out here! Right now the big craze in the markets back home is thresher teeth . Apparently they make great necklaces? Threshers are all over the Shelf of Mazu to the west. Bring me lots of teeth!",objectivesText="Collect 200 Thresher Teeth by pulling them from the jaws of Longfin Threshers on the Shelf of Mazu. Progress: Having actually seen someone eaten by a thresher, I'm not sure why you'd willingly string their teeth around your neck, but whatever.",starts={{npcID=63349,x=0.548,y=0.722,zoneID=6138},{npcID=64259,x=0.536,y=0.76,zoneID=6138}},ends={{npcID=63349,x=0.548,y=0.722,zoneID=6138}},coords={x=0.548,y=0.722,source="quest_giver",zoneID=6138},questType="standard"},
[31189] = {id=31189,name="Reeltime Strategy",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="I never thought I'd see the day, but for the first time since... well, EVER, Master Angler Ju Lien asked for some help with his lines. Apparently the sea is going crazy today and he can't keep up. See if you can give him a hand. He's fishing just south of here.",objectivesText="Assist Master Angler Ju Lien in Soggy's Gamble. Progress: Go give Ju Lien a hand, would ya?",starts={{npcID=63349,x=0.548,y=0.722,zoneID=6138}},ends={{npcID=63349,x=0.548,y=0.722,zoneID=6138}},coords={x=0.548,y=0.722,source="quest_giver",zoneID=6138},questType="standard"},
[31190] = {id=31190,name="The Mariner's Revenge",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="I'm not gonna sit in a damn rocking chair while my crew gets devoured by a leviathan! Come on, let's get to the dock and launch a dinghy. I got a special one set up just for this kind of situation. My own little Mist-Hopper Jr. We'll give that thing a case of harpoon fever.",objectivesText="Launch the Mist-Hopper Jr. from the dock in Soggy's Gamble and use it to bring down Jiao. Progress: Let's go!",starts={{npcID=63317,x=0.556,y=0.724,zoneID=6138}},ends={{npcID=63317,x=0.556,y=0.724,zoneID=6138}},coords={x=0.556,y=0.724,source="quest_giver",zoneID=6138},questType="standard"},
[31194] = {id=31194,name="Slitherscale Suppression",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="The Slitherscale take orders from their leader, the Slitherscale Lizard-Lord . He can be found celebrating his victories on the southeastern corner of Windward Isle. If we can destroy this leader, we can deal their tribe a great blow. Without their lord, the Slitherscale will think twice before attacking the gentle cloud serpents of the east.",objectivesText="Kill the Slitherscale Lizard-Lord . Progress: A snake without a head cannot strike.",starts={{npcID=58564,x=0.576,y=0.448,zoneID=5785}},ends={{npcID=58564,x=0.576,y=0.448,zoneID=5785}},coords={x=0.576,y=0.448,source="quest_giver",zoneID=5785},questType="standard"},
[31196] = {id=31196,name="Sra'vess Wetwork",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="The mantid outnumber us quite badly. Hundreds of them for each of us. And, they surround us on two sides - at Gao-Ran in the south we're holding them off, but to the west, on the island they call Sra'vess, they continue to mass unabated. We're not stupid. We're not going to launch a full scale attack on them. We can't sustain an intense battle on multiple fronts. Instead, we're going to send you, and one of our Wu Kao, to do some dirty work. Sounds fun, doesn't it?",objectivesText="Kill any 15 non-elite mantid near Sra'vess. Progress: The mission isn't complete, <name>.",starts={{npcID=63614,x=0.49,y=0.712,zoneID=5842}},ends={{npcID=63614,x=0.49,y=0.712,zoneID=5842}},coords={x=0.49,y=0.712,source="quest_giver",zoneID=5842},questType="standard"},
[31197] = {id=31197,name="The Bigger They Come...",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Killing the smaller mantid works mostly as a distraction. It forces them to replenish their numbers before they consider any serious offensive. The big ones, though - we kill a few of those, and we really disrupt operations on the island. That buys ourselves a substantial amount of time. With mantid, it's like their size is directly proportional to their importance in the empire. So kill some of the big ones for me, while you're out there.",objectivesText="Kill any 4 elite mantid at Sra'vess. Progress: I don't think you're done yet.",starts={{npcID=63614,x=0.49,y=0.712,zoneID=5842}},ends={{npcID=63614,x=0.49,y=0.712,zoneID=5842}},coords={x=0.49,y=0.712,source="quest_giver",zoneID=5842},questType="standard"},
[31198] = {id=31198,name="A Morale Victory",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="The mantid have statues built on Sra'vess. We don't know exactly what they use them for. They may have some sort of religious significance, or maybe they assist with their sonic communication. When you fight your opponent, you don't just engage them physically, you also engage them mentally. Whatever they use them for, the fact is that those statues are important to them. Which is why I want you to blow them up. Losing something important will be a substantial hit to morale.",objectivesText="Destroy the Southern, Central, Eastern and Western Idols at Sra'vess. Progress: The statues?",starts={{npcID=63614,x=0.49,y=0.712,zoneID=5842}},ends={{npcID=63614,x=0.49,y=0.712,zoneID=5842}},coords={x=0.49,y=0.712,source="quest_giver",zoneID=5842},questType="standard"},
[31199] = {id=31199,name="Destroy the Siege Weapons!",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="The mantid don't just attack in swarms. They're smart. They use alchemy, bombs... and what's worst, they've got siege weapons. Those have the potential to be incredibly destructive if they attack with them. We've got reports that they're building up a force of siege weapons to the west at Sra'vess. Go and destroy them.",objectivesText="Destroy the four mantid siege weapons at Sra'vess in Townlong Steppes . Progress: You need to take out those siege weapons, <name>!",starts={{npcID=63614,x=0.49,y=0.712,zoneID=5842}},ends={{npcID=63614,x=0.49,y=0.712,zoneID=5842}},coords={x=0.49,y=0.712,source="quest_giver",zoneID=5842},questType="standard"},
[31200] = {id=31200,name="Fumigation",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Our alchemists have cooked up a set of gas bombs that will discourage mantid from staying anywhere that we set them off. If we plant these in the critical structures of Sra'vess, they'll need to evacuate. That should sow some chaos and delay any action from the mantid there for days. Get to it, .",objectivesText="Plant Shado-Pan Gas Bombs within the 5 targeted structures on Sra'vess. Progress: Have you planted the gas bombs?",starts={{npcID=63614,x=0.49,y=0.712,zoneID=5842}},ends={{npcID=63614,x=0.49,y=0.712,zoneID=5842}},coords={x=0.49,y=0.712,source="quest_giver",zoneID=5842},questType="standard"},
[31201] = {id=31201,name="Friends, Not Food!",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Our scouts have sent a very troubling report. Three of our trainees have gone missing, and our scouts found them... They've been captured by the mantid and sent to their Kunchong pits. Their Kunchong FEEDING pits. We're lucky that the Kunchong don't eat that often. I need you to get in there, give them these escape kites, and get them out!",objectivesText="Rescue a Shado-Pan Trainee in each of the north, central and south Kunchong feeding pits. Progress: The trainees, <name>! You have to save them!",starts={{npcID=63614,x=0.49,y=0.712,zoneID=5842}},ends={{npcID=63614,x=0.49,y=0.712,zoneID=5842}},coords={x=0.49,y=0.712,source="quest_giver",zoneID=5842},questType="standard"},
[31203] = {id=31203,name="Target of Opportunity: Sra'thik Swarmlord",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="While we're here, we should do one more thing. The Sra'thik Swarmlord is responsible for directing the mantid forces from the air. If we leave it alive, it's going to cause trouble for the garrison. So we're not going to leave it alive. Let's take it out, $p.",objectivesText="Kill the Sra'thik Swarmlord at Sra'vess in Townlong Steppes . Progress: We need to take down the Swarmlord!",starts={{npcID=63614,x=0.49,y=0.712,zoneID=5842}},ends={{npcID=63614,x=0.49,y=0.712,zoneID=5842}},coords={x=0.49,y=0.712,source="quest_giver",zoneID=5842},questType="standard"},
[31204] = {id=31204,name="Target of Opportunity: Sra'thik Hivelord",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Near the ocean, on the eastern side of Sra'vess, there is a cavern that leads to a network of caves. From there, the Sra'thik Hivelord maintains Sra'vess and plots against us. If we manage to take him out, we'll disrupt their operations for days. Let's go to it.",objectivesText="Defeat the Sra'thik Hivelord . Progress: We've got to kill the Hivelord.",starts={{npcID=63614,x=0.49,y=0.712,zoneID=5842}},ends={{npcID=63614,x=0.49,y=0.712,zoneID=5842}},coords={x=0.49,y=0.712,source="quest_giver",zoneID=5842},questType="standard"},
[31206] = {id=31206,name="The Crucible of Carnage: The Bloodeye Bruiser!",level=30,requiredLevel=30,faction="none",expansion=4,zoneID=4922,mapID=241,description="I'll tell you what, buddy, this place is a far cry from the rolling plains of Nagrand or the bloodbowl in Zul'Drak, but hey, I go where the gold's at! So welcome to Twi-Hi, pal. You're new to this pit, so let me set you straight. I'm the fight promoter and this feisty troll next to me is Wodin, my bodyguard. You're the entertainment. When you wanna fight, let me know and I'll set up the match. If you're ready and got a group of friends with you, we can start! What do you say?",objectivesText="Get in the arena at the Crucible of Carnage and defeat Hurp'derp!",questType="group"},
[31207] = {id=31207,name="The Arena of Annihilation",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=6852,description="Ah, I can still remember running fights out of a muddy hole in the ground back in Nagrand. We've come a long way, eh, Wodin? I tell you, there's nothing more these Tiger monks like than a good scrap. So much so that they've paid good coin for me to set up shop here and help draw the strongest fighters from all around! So how about it? You and a couple friends up for a few rounds in the Arena of Annihilation...? Big money, big prizes!",objectivesText="Enter and complete the Arena of Annihilation scenario. Afterwards, collect your reward from Wodin the Troll-Servant . Progress: What are you waiting for? The monks are spoiling for a good show.",starts={{npcID=63315,x=0.686,y=0.484,zoneID=5841}},ends={{npcID=63314,x=0.686,y=0.484,zoneID=5841}},coords={x=0.686,y=0.484,source="quest_giver",zoneID=5841},questType="standard"},
[31208] = {id=31208,name="Venomous Intent",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="If we are to strike against the Empress, we must arm ourselves with weapons. My own choice of weapon is of a particularly toxic design. The scorpions wandering the ledge produce a deadly venom that they store in their tails. Bring me their stingers, and I will show you how I earned the title of paragon.",objectivesText="Collect 8 Venomous Stingers . Progress: Did you feel the venomtail's sting? Such lovely pain.",starts={{npcID=62151,x=0.548,y=0.36,zoneID=6138}},ends={{npcID=62151,x=0.548,y=0.36,zoneID=6138}},coords={x=0.548,y=0.36,source="quest_giver",zoneID=6138},questType="standard"},
[31209] = {id=31209,name="Dark Wings, Dark Things",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="I require another ingredient to create my first poison, Wakener. This ingredient you can easily find on the scarabs nearby. Kill them and bring me their wings.",objectivesText="Collect 150 Scarab Wings . Progress: Scarab wings can be crushed to produce a very fine white, deadly powder.",starts={{npcID=62151,x=0.548,y=0.36,zoneID=6138}},ends={{npcID=62151,x=0.548,y=0.36,zoneID=6138}},coords={x=0.548,y=0.36,source="quest_giver",zoneID=6138},questType="standard"},
[31210] = {id=31210,name="A Shade of Dread",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="The last ingredient is perhaps the deadliest. The dreadshade flower grows all along these hills. It is by eating these poisonous plants that the local wildlife has become so venomous. A single drop of dreadshade nectar can stop a kunchong's heart. Go and bring me some of these flowers. Do not be tempted to taste them.",objectivesText="Collect 8 Dreadshade . Progress: Sometimes, the most beautiful things are also the most dangerous.",starts={{npcID=62151,x=0.548,y=0.36,zoneID=6138}},ends={{npcID=62151,x=0.548,y=0.36,zoneID=6138}},coords={x=0.548,y=0.36,source="quest_giver",zoneID=6138},questType="standard"},
[31211] = {id=31211,name="The Poisoned Mind",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="Before we return to Klaxxi'vess, I wish to look upon the empire. The Klaxxi Council told me that the enemy gathers outside the Empress's palace. My poisons are ready. What better way to announce my return than with death and destruction? Just be careful not to mix the two serums... at least not while you're holding the vessels. Speak to me when you are ready to fly.",objectivesText="Speak to Xaril the Poisoned Mind . Kill 200 mantid and 3 kunchong while flying with him. Progress: Fight from above.",starts={{npcID=62151,x=0.548,y=0.36,zoneID=6138}},ends={{npcID=62151,x=0.548,y=0.36,zoneID=6138}},coords={x=0.548,y=0.36,source="quest_giver",zoneID=6138},questType="standard"},
[31212] = {id=31212,name="FLAG - Chose Tenwu",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31213] = {id=31213,name="FLAG - Chose Taoshi",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31214] = {id=31214,name="FLAG - Chose Nurong",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31216] = {id=31216,name="Dark Skies",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="The swarm begins, Wakener! The mantid amass at the Heart of Fear. Already they fill the skies with their wings and rend the earth with their claws. They shall not stop the dark march until their bodies are laid open and bleeding upon the ground. This we shall gladly do. We will attack them from above. While I fly, use my poisons to destroy their advance. Do not mix the two serums until you are ready to attack. The reaction can be quite... violent. Speak to me when you are ready to go.",objectivesText="Kill 200 Mantid and 3 Kunchong or Dread Behemoths while flying with Xaril the Poisoned Mind . Progress: Such wonderful destruction!",starts={{npcID=62151,x=0.548,y=0.36,zoneID=6138}},ends={{npcID=62151,x=0.548,y=0.36,zoneID=6138}},coords={x=0.548,y=0.36,source="quest_giver",zoneID=6138},questType="standard"},
[31218] = {id=31218,name="FLAG - Unlocked Tenwu",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31219] = {id=31219,name="FLAG - Unlocked Nurong",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31220] = {id=31220,name="The Challenger's Ring: Hawkmaster Nurong",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="You've really been building up respect with the Shado-Pan, . Nurong's interested in trying out his skills against you. The good news is, if you win, I'll allow him to go with you on your missions. The bad news is, I really don't think you'll win.",objectivesText="Challenge Hawkmaster Nurong, and then defeat him in combat at Shado-Pan Garrison in Townlong Steppes . Progress: Not up to the challenge? I understand.",starts={{npcID=63614,x=0.49,y=0.712,zoneID=5842}},ends={{npcID=63614,x=0.49,y=0.712,zoneID=5842}},coords={x=0.49,y=0.712,source="quest_giver",zoneID=5842},questType="standard"},
[31221] = {id=31221,name="The Challenger's Ring: Tenwu of the Red Smoke",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="So... you've been challenged by the infamous Tenwu of the Red Smoke. That's what he calls himself, at least. He's a good fighter, and a good rogue, but it's a wonder he manages to sneak up on anyone with how loudly he brags about himself. Anyways, I think you should answer the challenge. Maybe it'll give him a touch of humility. Maybe not. Either way, if you win, he'll probably be willing to go with you on your missions. And I get some entertainment.",starts={{npcID=63614,x=0.49,y=0.712,mapID=388}},ends={{npcID=63614,x=0.49,y=0.712,mapID=388}},coords={x=0.49,y=0.712,source="quest_giver",mapID=388},questType="standard"},
[31228] = {id=31228,name="Prophet Khar'zul",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="Prophet Khar'zul is a powerful caster, but he is also underestimating your abilities. Khar'zul and his forces must be destroyed to protect this village. His death will send a strong message to the Thunder King that we will not be defeated! You'll find him on the Isle of Reckoning.",objectivesText="Defeat Prophet Kharzul. Progress: Is Khar'zul dead?",starts={{npcID=63784,x=0.624,y=0.292,zoneID=5841}},ends={{npcID=63784,x=0.624,y=0.292,zoneID=5841}},coords={x=0.624,y=0.292,source="quest_giver",zoneID=5841},questType="standard"},
[31230] = {id=31230,name="Welcome to Dawn's Blossom",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="Cho's off on another one of his adventures, and this one requires a big order of jade. I'm going to have to call in some favors. How 'bout in the meantime you introduce yourself to some of the locals. Kai Wanderbrew is a good guy to know, as is Master Windfur . Oh, and say hi to Peiji Goldendraft up at the inn. Between the three of them, you should get the feel for life in Dawn's Blossom.",objectivesText="Speak with Kai Wanderbrew , Master Windfur , and Peiji Goldendraft in Dawn's Blossom. Progress: Any luck?",starts={{npcID=56348,x=0.47,y=0.46,zoneID=5785}},ends={{npcID=56348,x=0.47,y=0.46,zoneID=5785}},coords={x=0.47,y=0.46,source="quest_giver",zoneID=5785},questType="standard"},
[31231] = {id=31231,name="Dreadspinner Extermination",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Back in Gurthani Terrace where you found me, dreadspinners continue to occupy the attention of Shado-Pan marksmen who could otherwise be thinning out this wretched swarm. Eradicate those spiders and offer some relief to the archers on that wall.",objectivesText="Slay 8 Dreadspinner Tenders in the Terrace of Gurthan. Speak with Kil'ruk the Wind-Reaver for an air-drop.",starts={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},ends={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},coords={x=0.55,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31232] = {id=31232,name="An Ancient Empire",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="My brothers speak of an ancient mogu empire that once dwelled in the ruins to the east. Once, this tribe knew untold secrets of sorcery and subjugation. I have a curious mind, Wakener, and I wish to learn of the empires that ruled after my time. Knowledge of the past will determine our future. Go search the ruins for their ancient tablets. I will study their secrets and make them our own.",objectivesText="Collect 8 Gurthani Tablets . Progress: What knowledge do you bring?",starts={{npcID=62180,x=0.544,y=0.36,zoneID=6138}},ends={{npcID=62180,x=0.544,y=0.36,zoneID=6138}},coords={x=0.544,y=0.36,source="quest_giver",zoneID=6138},questType="standard"},
[31233] = {id=31233,name="Sap Tapping",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="I found a grove of young amber trees to the east, Wakener. I've placed tapping devices on these trees, but I have been too busy to retrieve the sap. I need someone to find the extractors. Activate them, then bring me samples of the amber.",objectivesText="Collect 6 Amber Sap . Progress: These trees are still young. They are not yet kypari. Their sap is like water, while the sap of a true kypari tree is like wine. They must be allowed to grow.",starts={{npcID=62180,x=0.544,y=0.36,zoneID=6138}},ends={{npcID=62180,x=0.544,y=0.36,zoneID=6138}},coords={x=0.544,y=0.36,source="quest_giver",zoneID=6138},questType="standard"},
[31234] = {id=31234,name="Putting An Eye Out",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Ah! Wakener! You must help me! (You will help me, or else I will help myself to you!) I need more materials for my experiments, yes yes! (Blood and guts, hearts and brains, tongues and eyes, eyes, eyes!) To the west, I have seen creatures of mist and fog. They possess such big, round, wonderful globes! Big for seeing, round and unblinking! Go now, little Wakener. Bring me back a single pristine eye!",objectivesText="Collect 1 Pristine Mire Beast Eye . Progress: Ooooh, what wonderful, tasty parts have you brought me?",starts={{npcID=63072,x=0.544,y=0.358,zoneID=6138},{npcID=67091,x=0.318,y=0.89,zoneID=6138}},ends={{npcID=63072,x=0.544,y=0.358,zoneID=6138}},coords={x=0.544,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31235] = {id=31235,name="Nope Nope Nope",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="I recovered this weapon on a recent scouting run near the wall. It would seem ideal for helping your Shado-Pan with their infestation problem in Gurthani Terrace. The more they are focused on keeping spiders off the wall, the less time they are killing fear-gripped swarmborn.",objectivesText="Use the Shado-Pan Dragon Gun to destroy 20 Dreadspinner Eggs in Gurthani Terrace.",starts={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},ends={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},coords={x=0.55,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31237] = {id=31237,name="Debugging the Terrace",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="If this Empress is truly possessed by fear and paranoia, she will have sent scouts to every corner of the land in order to cement her control. These scout grubs are likely everywhere, but difficult to spot with the naked eye. Better to track them by the pheromone trails they leave behind. I've already... gifted you... a reactive toxin that will reveal these trails to you for a brief time after experiencing the thrill of victory. Go now to the Terrace of Gurthan and root out these spies.",objectivesText="Stomp out 6 Eyes of the Empress around the Terrace of Gurthan. Killing anything will grant you Pheromone Tracking, helping you detect them. Progress: Best not to ask how I afflicted you with the toxin - you have become quite useful to us, and it would be a shame if we drove you mad with horror just yet.",starts={{npcID=63785,x=0.548,y=0.36,zoneID=6138}},ends={{npcID=63785,x=0.548,y=0.36,zoneID=6138}},coords={x=0.548,y=0.36,source="quest_giver",zoneID=6138},questType="standard"},
[31238] = {id=31238,name="Brain Food",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Kovok is growing at an accelerated rate, but his brain may not be able to keep up. He'll require a special diet to ensure that he does not outgrow the capacity to control his own body. Mushan tongue is rich in the nutrients that promote brain growth in kunchong, but they normally eat the beasts whole and fill up quickly. If we feed Kovok only mushan tongues every couple of days or so, it should balance out his growth. Greatback mushan graze the hills east of here, near the Gurthani Terrace.",objectivesText="Bring 4 Mushan Tongues to Kaz'tik the Manipulator at Klaxxi'vess. Progress: Have you found a suitable meal for Kovok?",starts={{npcID=63758,x=0.542,y=0.358,zoneID=6138}},ends={{npcID=63758,x=0.542,y=0.358,zoneID=6138}},coords={x=0.542,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31239] = {id=31239,name="What's in a Name Name?",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,mapID=371,description="So, you wanna be a hozen. Huh, wikket? Hozen defend their lands from enemies, like jinyu. Kah Kah fought many jinyu fights, and won them all. Hozen only give name name to good grookers. Go grook jinyu and maybe they call you . Jinyu creepin' down by the river. Ook 'em in the dooker!",starts={{npcID=56336,x=0.28,y=0.47,mapID=371}},ends={{npcID=56336,x=0.28,y=0.47,mapID=371}},coords={x=0.28,y=0.47,source="quest_giver",mapID=371},questType="standard"},
[31240] = {id=31240,name="Guo-Lai Infestation",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="Anji came by and asked for you. Said she was heading to the northeast ruins. Oh, Anji, such a fiery spirit, that girl! Probably better for your long-term health if you not keep her waiting.",objectivesText="Speak to Anji Autumnlight at the Ruins of Guo-Lai.",starts={{x=0.424,y=0.46,mapID=390,npcID=59343}},ends={{x=0.424,y=0.46,mapID=390,npcID=59343}},coords={mapID=390,x=0.424,y=0.46},questType="standard"},
[31241] = {id=31241,name="Wicked Wikkets",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,mapID=371,description="good wikket, they say... help hozen, they say... No more grookin' , they say. That ok. Look out there. Wicked wikkets fallin' like rain, ripe for the grookin'! Go, join the fun. But remember, Chief Kah Kah gets all the shinies! That's hozen rule number two. Jeek Jeek scratches his head.> Hmm, all hozen rules are number two...",objectivesText="Collect 6 Alliance Service Medallions from Battleworn Paratroopers Progress: Whatcha got, wikket?",starts={{npcID=56336,x=0.28,y=0.47,zoneID=5785},{npcID=63748,x=0.282,y=0.39,zoneID=5785}},ends={{npcID=56336,x=0.28,y=0.47,zoneID=5785}},coords={x=0.28,y=0.47,source="quest_giver",zoneID=5785},questType="standard"},
[31242] = {id=31242,name="Mistfall Village",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="My scouts have spotted no mogu near Mistfall Village today, but I've been hearing of some troubles with local wildlife and spirits in the graveyard. I dispatched Che to assess the situation, but he'll most likely need your help. Find your way southwest to the village and meet Che there. Do what you can.",objectivesText="Speak to Che Wildwalker at Mistfall Village.",starts={{x=0.566,y=0.436,mapID=390,npcID=58408}},ends={{x=0.566,y=0.436,mapID=390,npcID=58408}},coords={mapID=390,x=0.566,y=0.436},questType="standard"},
[31243] = {id=31243,name="Attack on Mistfall Village",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="Mogu have been sighted at Mistfall Village to the southwest. I dispatched Rook and Sun immediately, but I need another capable hand there as soon as possible. Don't delay. The villagers need you.",objectivesText="Speak to Sun Tenderheart at Mistfall Village.",starts={{x=0.566,y=0.436,mapID=390,npcID=58408}},ends={{x=0.566,y=0.436,mapID=390,npcID=58408}},coords={mapID=390,x=0.566,y=0.436},questType="standard"},
[31244] = {id=31244,name="Guo-Lai Encampment",level=90,requiredLevel=90,faction="none",expansion=4,description="Leven came by in quite a huff! Said something about mogu in the ruins. Best be off to find him I think. Angry Leven is not a fun Leven.",objectivesText="Speak to Leven Dawnblade at the Ruins of Guo-Lai.",starts={{x=0.424,y=0.46,mapID=390,npcID=59343}},ends={{x=0.424,y=0.46,mapID=390,npcID=59343}},coords={mapID=390,x=0.424,y=0.46},questType="standard"},
[31248] = {id=31248,name="The Ruins of Guo-Lai",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="I've instructed Anji and Kun to resume investigation of the Ruins of Guo-Lai. We have no reports of any significant mogu presence there today, but it seems to be one of their central interests here in the Vale, and want it under thorough watch consider their attack on the lake. That's why I'm sending you as well. Head west, past the lake, to the ruins. Anji will instruct you further.",objectivesText="Speak to Anji Autumnlight at the Ruins of Guo-Lai.",starts={{x=0.566,y=0.436,mapID=390,npcID=58408}},ends={{x=0.566,y=0.436,mapID=390,npcID=58408}},coords={mapID=390,x=0.566,y=0.436},questType="standard"},
[31249] = {id=31249,name="Mistfall Village",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="Everything I've heard suggests the village has been unaffected by the Shao-Tien offensive at the lake, but I won't take any risks. I'm dispatching you and Che Wildwalker to keep watch at the village, and aid the townsfolk while you're there.",objectivesText="Speak to Che Wildwalker at Mistfall Village.",starts={{x=0.566,y=0.436,mapID=390,npcID=58408}},ends={{x=0.566,y=0.436,mapID=390,npcID=58408}},coords={mapID=390,x=0.566,y=0.436},questType="standard"},
[31250] = {id=31250,name="Setting Sun Garrison",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="We've taken losses from the mogu forces descending the Golden Stair and their flanking attackers at Whitepetal Lake. Our lines are thin. I'm dispatching Anji and Kun to the Setting Sun Garrison to double our efforts at training new recruits. I'd like you there with them, <name>. Show them what a true <class> is made of.",objectivesText="Speak to Anji Autumnlight at the Setting Sun Garrison.",starts={{x=0.566,y=0.436,mapID=390,npcID=58408}},ends={{x=0.566,y=0.436,mapID=390,npcID=58408}},coords={mapID=390,x=0.566,y=0.436},questType="standard"},
[31251] = {id=31251,name="Best Meals Anywhere!",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=6141,mapID=379,description="Yeah, yeah. Everyone knows us goblins do tinkering. And explosives. And... well, ya' know, the less reputable stuff. But what nobody knows is that I'm really a great chef! It's a hobby of mine. Gather us up some meaty bits from the creatures around here, and I'll cook us up the best meals ANYWHERE! And I promise, I'll only use three or four percent rocket fuel.",objectivesText="Collect 160 Kun-Lai Meaty Bits . Progress: The meaty bits, <name>? We need 'em!",starts={{npcID=59448,x=0.628,y=0.798,zoneID=5841}},ends={{npcID=59448,x=0.628,y=0.798,zoneID=5841}},coords={x=0.628,y=0.798,source="quest_giver",zoneID=5841},questType="standard"},
[31252] = {id=31252,name="Back to Westwind Rest",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="Well, far as I figure, we've got quite a lot of rebuildin' to do. I'm not one for joining any big causes, but my farmhands aren't gonna have much to do 'round here, to be honest. And, since you helped them out, they want to join your \"Alliance.\" So, who am I to stop 'em? Bring 'em with you, back to Farmhand Bo . I'll miss 'em, but they're better off with you.",objectivesText="Return to Farmhand Bo at Westwind Rest in Kun-Lai Summit .",starts={{npcID=59573,x=0.602,y=0.858,zoneID=5841}},ends={{npcID=63754,x=0.538,y=0.84,zoneID=5841}},coords={x=0.602,y=0.858,source="quest_giver",zoneID=5841},questType="standard"},
[31253] = {id=31253,name="Back to Eastwind Rest",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,description="Well, far as I figure, we've got quite a lot of rebuildin' to do. I'm not one for joining any big causes, but my farmhands aren't gonna have much to do 'round here, to be honest. And, since you helped them out, they want to join your \"Horde\". So, who am I to stop 'em? Bring 'em with you, back to Farmhand Ko . I'll miss 'em, but they're better off with you.",objectivesText="Return to Farmhand Ko at Eastwind Rest in Kun-Lai Summit .",starts={{npcID=59573,x=0.602,y=0.858,zoneID=5841}},ends={{npcID=63751,x=0.636,y=0.866,zoneID=5841}},coords={x=0.602,y=0.858,source="quest_giver",zoneID=5841},questType="standard"},
[31254] = {id=31254,name="The Road to Kun-Lai",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=6006,description="Ah! Greetings friend of Lorewalker Cho. I have a message for you. The Lorewalker waits for you in Kun-Lai. Very dangerous to travel there, yes, very dangerous. Look for guides along the road to help you find your way.",objectivesText="Travel through the Veiled Stair to Binan Village. Progress: More strangers? This day is testing my limits.",starts={{npcID=63778,x=0.458,y=0.438,zoneID=5785},{npcID=63778,x=0.7,y=0.236,zoneID=5805},{npcID=63778,x=0.404,y=0.34,zoneID=6134}},ends={{npcID=59073,x=0.722,y=0.918,zoneID=5841}},coords={x=0.458,y=0.438,source="quest_giver",zoneID=5785},questType="standard"},
[31255] = {id=31255,name="The Road to Kun-Lai",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=6006,mapID=379,description="Ah! Greetings friend of Lorewalker Cho. I have a message for you. The Lorewalker waits for you in Kun-Lai. Very dangerous to travel there, yes, very dangerous. Look for guides along the road to help you find your way.",starts={{npcID=63778,x=0.458,y=0.438,mapID=371},{npcID=63778,x=0.7,y=0.236,mapID=376},{npcID=63778,x=0.404,y=0.34,mapID=418}},ends={{npcID=59073,x=0.722,y=0.918,mapID=379}},coords={x=0.458,y=0.438,source="quest_giver",mapID=379},questType="standard"},
[31256] = {id=31256,name="Round 'Em Up",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,description="Lok'tar, . We've made progress, but we're going to need mobility if we want to maintain our foothold here in Kun-Lai. I don't see many worgs, kodo, or the like around here. What I do see are yaks. Our pandaren allies have said they make good mounts, so they'll have to do. Go round some up and return them here, so we can get our people riding them!",objectivesText="Round up 3 Wild Plains Yaks and return them to Eastwind Rest. Progress: The yaks?",starts={{npcID=59442,x=0.716,y=0.932,zoneID=5841}},ends={{npcID=59442,x=0.716,y=0.932,zoneID=5841}},coords={x=0.716,y=0.932,source="quest_giver",zoneID=5841},questType="standard"},
[31260] = {id=31260,name="Profit Mastery: Chasheen",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="I am totally on to another great scam! When I was flying overhead I saw a really ancient tigress prowling about. Do you know how much her blood would go for on the black market? Not to mention if I convince some warlocks it adds extra potency to their summoning spells or something. If you bring me back some of her blood I will cut you in on the scam. She was prowling about on the far side of the Dojani River from here.",objectivesText="Collect Ancient Tiger's Blood . Progress: I thought about taking that tiger on myself but to be honest I like living...",starts={{npcID=58779,x=0.676,y=0.256,zoneID=6134}},ends={{npcID=58779,x=0.676,y=0.256,zoneID=6134}},coords={x=0.676,y=0.256,source="quest_giver",zoneID=6134},questType="standard"},
[31261] = {id=31261,name="Captain Jack's Dead",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="Gore from Captain Jack's head drips and mysteriously seeps into the ground as you examine your hard-won trophy. Strange, but no time to investigate that now. There's too much work to be done. The chieftain of your newfound friends will doubtlessly be impressed with this proof of your grookin' skills.",objectivesText="Bring Captain Jack's head to Chief Kah Kah at Grookin Hill. Provided item:",starts={{x=0.308,y=0.413,mapID=371}},ends={{npcID=56336,x=0.28,y=0.47,zoneID=5785}},coords={mapID=371,x=0.308,y=0.413},questType="standard"},
[31262] = {id=31262,name="Crane Mastery: Needlebeak",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="So, now that you've got a vibe for how cranes fight, I've got a doozy for you. Needlebeak! Or at least, that's what I'm calling him. Biggest crane I ever saw. And its beak is so sharp it's like a sword. Northwest of here you'll find the big water fall that kicks off the Dojani River. Needlebeak likes to hang out by the waterfall. You bring me its beak as a trophy and I will talk you up a good game to Nesingwary.",objectivesText="Acquire the Needlebeak . Progress: I watched that bird stab a tiger through the face. What kind of place is this where birds are the predators for tigers?",starts={{npcID=58779,x=0.676,y=0.256,zoneID=6134}},ends={{npcID=58779,x=0.676,y=0.256,zoneID=6134}},coords={x=0.676,y=0.256,source="quest_giver",zoneID=6134},questType="standard"},
[31265] = {id=31265,name="Mazu's Breath",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Here to help, are ya? Well, first thing's first. Here it is! \"Mazu's Breath.\" Cap'n's own formula. What? You thought I'd send you out to sea without a means of breathin'? I need deckhands, not corpses! Down the hatch with it, green. This'll give you a fighting chance out there on the shelf.",objectivesText="Drink the Potion of Mazu's Breath . Progress: No, I don't have a \"chaser!\" Just drink it!",starts={{npcID=63349,x=0.548,y=0.722,zoneID=6138}},ends={{npcID=63349,x=0.548,y=0.722,zoneID=6138}},coords={x=0.548,y=0.722,source="quest_giver",zoneID=6138},questType="standard"},
[31266] = {id=31266,name="Mogu Incursions",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="We've heard reports of a group of Mogu infiltrating the coast here in Townlong. I have no idea what they are doing. Frankly, I don't care. You've proven yourself, so we've decided to give this mission to you. What's going to happen is this - you're going to go, find them, and kill them. Our scouts reported the first group landed to the north, between here and Deadtalker's Plateau. Go there and wipe them out.",objectivesText="Find and kill the Shan'ze Spymaster . Progress: Why aren't they dead already?",starts={{npcID=63009,x=0.494,y=0.706,zoneID=5842}},ends={{npcID=63009,x=0.494,y=0.706,zoneID=5842}},coords={x=0.494,y=0.706,source="quest_giver",zoneID=5842},questType="standard"},
[31267] = {id=31267,name="Mistblade Destruction",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Korven has told me of his findings. There is an enormous amber deposit sitting at the bottom of the Lake of Stars. Unfortunately, a hostile saurok tribe lives at the edge of the lake, and revere the amber as their own. They will not allow us to enter their territory easily. Go south to the lake. Kill the Mistblade saurok, so that we can more easily harvest the nearby amber.",objectivesText="Kill 6 Mistblade Rippers . Progress: Have you eliminated the opposition?",starts={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},ends={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},coords={x=0.55,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31268] = {id=31268,name="A Little Brain Work",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Far to the south, the swarm breeds weapons of destruction - enormous, nearly unbreakable amber scorpions. Like all other creatures, they are subject to manipulation, but unlike other creatures, they have not yet submitted to my mind control. It appears that further research is necessary before I can dominate them for our own purposes. I must study their brains, and you must retrieve some specimens for me. Take this sonic emitter . I have found it to be quite effective against the beasts.",objectivesText="Collect 3 Amber-Encrusted Brains from Ik'thik Amberstingers. Progress: They continue to resist my sonic manipulation. I must understand why.",starts={{npcID=63758,x=0.542,y=0.358,zoneID=6138}},ends={{npcID=63758,x=0.542,y=0.358,zoneID=6138}},coords={x=0.542,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31269] = {id=31269,name="The Scale-Lord",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="The saurok at the Lake of Stars take their orders from their Scale-Lord, a vicious, merciless leader who guards his territory fiercely. If we can eliminate this leader, then we can gain access to the enormous amber lode beneath the lake. Go. Their leader gives his orders from his underground dwelling, at the southern edge of the lake.",objectivesText="Kill the Mistblade Scale-Lord .",starts={{npcID=62180,x=0.544,y=0.36,zoneID=6138}},ends={{npcID=62180,x=0.544,y=0.36,zoneID=6138}},coords={x=0.544,y=0.36,source="quest_giver",zoneID=6138},questType="standard"},
[31270] = {id=31270,name="The Fight Against Fear",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="When we discovered the sha influence at Kypari Zar, I had hoped the corruption could still be cleansed. Unfortunately, the Klaxxi Council has confirmed that the sha of fear's corruption is deep-seated, and continues to spread. To the south, I have observed some of the local wildlife consumed by an unnamed terror. The sha can warp and twist its victims into unimaginable horrors. We must stop the corruption before it becomes worse. Seek out the sha-infected Horrorscale Scorpids . Eliminate them.",objectivesText="Kill 15 Horrorscale Scorpid .",starts={{npcID=62180,x=0.544,y=0.36,zoneID=6138}},ends={{npcID=62180,x=0.544,y=0.36,zoneID=6138}},coords={x=0.544,y=0.36,source="quest_giver",zoneID=6138},questType="standard"},
[31271] = {id=31271,name="Bad Genes",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Far to the south, Wakener, the Empress's genemancers set about their dark experiments. (Dark yes, but not as dark as mine!) They dissect and mutate the nearby wildlife, breeding creatures of their own design. (Their design, which will become my design!) We must not let them succeed! (No, no! Only I am allowed such power!) Their mutations are already being unleashed for war. Go! Destroy them at any cost!",objectivesText="Kill 3 Ik'thik Genemancers and 6 Ik'thik Egg-Drones . Progress: Is it done? Are my competitio - I mean, our enemies - dead?",starts={{npcID=63072,x=0.544,y=0.358,zoneID=6138},{npcID=67091,x=0.318,y=0.89,zoneID=6138}},ends={{npcID=63072,x=0.544,y=0.358,zoneID=6138}},coords={x=0.544,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31272] = {id=31272,name="Infection",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="The Empress's genemancers play with dangerous toys. To the south, they are injecting local wildlife with pheromone-laden parasites, in an attempt to create monstrous mutations for war. Carelessly, they have allowed their parasitic worms to escape into the local ecosystem. Left unchecked, the infection will spread from one animal to another, until we have an outbreak. I will inject you with a mild toxin. With it, you will be able to identify infected creatures. Kill the carriers at once.",objectivesText="Kill 6 infected wildlife. Infected wildlife may include Bonedust Moths, Bluehide Mushan, and Mutating Scorpid. Progress: Do not worry. I have given you a weak toxin that allows you to share my ability to sense pheromones. It has no effect on mantid.",starts={{npcID=63785,x=0.548,y=0.36,zoneID=6138}},ends={{npcID=63785,x=0.548,y=0.36,zoneID=6138}},coords={x=0.548,y=0.36,source="quest_giver",zoneID=6138},questType="standard"},
[31274] = {id=31274,name="LFGDungeons - Mists - Raid Finder - 1st",level=35,requiredLevel=35,faction="none",expansion=4,questType="standard"},
[31277] = {id=31277,name="Surprise Attack!",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="Those damnable Mogu... Those scouts were a distraction! While we were hunting their spies, the main force moved on Niuzao Temple. Corrupted serpents, Mogu everywhere... this is a disaster! Thankfully, Ban was able to make it past their lines with the most elite members of our order. If you can slip past, too, meet up with him. We need to put a stop to this!",objectivesText="Meet up with Ban Bearheart outside Niuzao Temple in Townlong Steppes , and put a stop to the Mogu Invasion there.",starts={{npcID=63009,x=0.494,y=0.706,zoneID=5842}},ends={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},coords={x=0.494,y=0.706,source="quest_giver",zoneID=5842},questType="standard"},
[31278] = {id=31278,name="Figuring out how to make quests",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5042,mapID=207,description="Whee! You get to make a breadcrumb quest! Now figure out what to do next.",objectivesText="Make a breadcrumb quest.",questType="standard"},
[31279] = {id=31279,name="Everything I Know About Cooking",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,description="I'm so glad you enjoy my food. Are you interested in the recipes? If so, you should learn them properly, from my teachers in Halfhill Market. Everything I know about the kitchen, I learned from them. Say, if you happen to pass through there, would you deliver this note to Sungshin Ironpaw for me? She was my favorite teacher, and I want her to know that I miss her.",objectivesText="Deliver the Letter to Sungshin Ironpaw . She teaches in Halfhill Market. Progress: You have a letter for me?",starts={{npcID=59405,x=0.642,y=0.612,zoneID=5841},{npcID=62322,x=0.482,y=0.348,zoneID=5785},{npcID=64041,x=0.628,y=0.112,zoneID=9105},{npcID=65528,x=0.836,y=0.202,zoneID=5805}},ends={{npcID=64231,x=0.536,y=0.512,zoneID=5805}},coords={x=0.642,y=0.612,source="quest_giver",zoneID=5841},questType="standard"},
[31280] = {id=31280,name="Ways of Cooking",level=5,requiredLevel=5,faction="both",expansion=4,zoneID=5042,mapID=207,description="There are many ways of cooking, and each creates dishes with unique properties. The Pandaren Ways of Cooking are the Ways of the Grill, the Wok, the Pot, the Steamer, the Oven and the Brew. You seem to already have the basics of each way, from your experience in faraway lands. If you wish to progress further, speak with my siblings and learn the first advanced recipe each of them teaches. Find out which Way suits you the best.",objectivesText="Learn the recipes for Charbroiled Tiger Steak , Jade Forest Fried Rice, Swirling Mist Soup , Shrimp Dumplings , Wildfowl Roast and Ginseng Tea from the masters in Halfhill Market.",questType="standard"},
[31281] = {id=31281,name="So You Want to Be a Chef...",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,mapID=376,description="You wish to be a chef? If you are dedicated, I can unlock your hidden potential, no matter how inexperienced you are. If you wish to learn, show me you can at least follow basic instructions. Learn how to slice peaches and show me what you've learned. I have fresh pandaren peaches which I will sell to you at a token price.",starts={{npcID=64231,x=0.536,y=0.512,mapID=376}},ends={{npcID=64231,x=0.536,y=0.512,mapID=376}},coords={x=0.536,y=0.512,source="quest_giver",mapID=376},questType="standard"},
[31284] = {id=31284,name="FLAG - Ancient Pandaren Fishing Pole",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[31285] = {id=31285,name="The Spring Drifter",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=6006,description="Nobody really travels up the Ancient Passage on foot. That is just asking for a faceful of saurok if you are not careful. Tell you what, Egg Shell and I were just about to set off upriver to Binan Village. Want a lift?",objectivesText="Survive a trip on the Spring Drifter . Progress: It is always good luck to have a grummle aboard when traveling through a saurok infested cave.",starts={{npcID=63367,x=0.726,y=0.93,zoneID=5841},{npcID=63367,x=0.52,y=0.438,zoneID=6006}},ends={{npcID=63367,x=0.726,y=0.93,zoneID=5841},{npcID=63367,x=0.52,y=0.438,zoneID=6006}},coords={x=0.726,y=0.93,source="quest_giver",zoneID=5841},questType="standard"},
[31286] = {id=31286,name="Robbing Robbers of Robbers",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=6006,description="Ah, a . I could make good use of your skills. A convoy was struck just up the road by a band of marauding saurok. These marauders made off with some... merchandise... her ladyship, the Madam Goya, had a mind to sell. One does not steal from her ladyship. If you recover these items I will gladly provide you a finders fee.",objectivesText="Recover 7 Black Market Merchandise . Progress: Saurok are seldom this bold.",starts={{npcID=63484,x=0.536,y=0.658,zoneID=6006}},ends={{npcID=63484,x=0.536,y=0.658,zoneID=6006}},coords={x=0.536,y=0.658,source="quest_giver",zoneID=6006},questType="standard"},
[31287] = {id=31287,name="Educating Saurok",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=6006,description="The Spring Road is under the protection of her ladyship, the esteemed Madam Goya. The saurok of Hatescale Burrow northeast of here require \"education\" in this fact. We have warned them before but sadly they seem to have a very short memory. Travel northeast to this burrow and find their shaman leader. Eliminate him and you will have the gratitude of her ladyship. As well as an appropriate bounty.",objectivesText="Defeat Leechfingers . Progress: It is unwise to challenge the domain of Madam Goya.",starts={{npcID=63484,x=0.536,y=0.658,zoneID=6006}},ends={{npcID=63484,x=0.536,y=0.658,zoneID=6006}},coords={x=0.536,y=0.658,source="quest_giver",zoneID=6006},questType="standard"},
[31288] = {id=31288,name="Research Project: The Mogu Dynasties",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=9105,description="Ah, an explorer. Just what I could use. I am on the verge of discovering the dark secrets of the mogu. Not all of the secrets, mind you. They kept a lot of dark secrets. But I am on the verge of discovering \"a\" secret at least. If, in your travels, you come across some fragments of the mogu past, bring them to me and I will happily reimburse you for them.",objectivesText="Obtain 20 Mogu Archaeology Fragments . Progress: It is dangerous to forget our past.",starts={{npcID=63984,x=0.834,y=0.31,zoneID=5840},{npcID=63984,x=0.84,y=0.286,zoneID=9105}},ends={{npcID=63984,x=0.834,y=0.31,zoneID=5840},{npcID=63984,x=0.84,y=0.286,zoneID=9105}},coords={x=0.834,y=0.31,source="quest_giver",zoneID=5840},questType="standard"},
[31289] = {id=31289,name="Research Project: The Pandaren Empire",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=9105,description="Ah, adventurer. You come at a most opportune time. My daughter and I are researching the history of our people and have hit a roadblock in our research. Should you come across fragments of the pandaren past, please, bring them to us here. We would benefit greatly from the additional information.",objectivesText="Obtain 20 Pandaren Archaeology Fragments .",starts={{npcID=63984,x=0.834,y=0.31,zoneID=5840},{npcID=63984,x=0.84,y=0.286,zoneID=9105}},ends={{npcID=63984,x=0.834,y=0.31,zoneID=5840},{npcID=63984,x=0.84,y=0.286,zoneID=9105}},coords={x=0.834,y=0.31,source="quest_giver",zoneID=5840},questType="standard"},
[31291] = {id=31291,name="Uncovering the Past",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,description="Interested in being a Lorewalker? There is lots of digging and reading and digging and more reading. I have entire days where I stare at a broken vase trying to figure out how it goes back together. Should give it a try. Go solve one artifact of Pandaria and we will appreciate you sharing the knowledge of how you did it.",objectivesText="Solve 1 artifact from Pandaria. Progress: I am beginning to wonder if I'll ever get the hang of this stuff.",starts={{npcID=63983,x=0.834,y=0.31,zoneID=5840}},ends={{npcID=63983,x=0.834,y=0.31,zoneID=5840}},coords={x=0.834,y=0.31,source="quest_giver",zoneID=5840},questType="standard"},
[31292] = {id=31292,name="FLAG - Ancient Pandaren Woodcutter",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[31293] = {id=31293,name="Mogu Make Poor House Guests",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="Leven sent Rook here to stop mogu, but there are more than Rook can kill alone. You help? Rook will tell Leven you helped. Promise.",objectivesText="Kill 8 Shado-Tien attackers in Mistfall Village.",starts={{x=0.352,y=0.75,mapID=390,npcID=58911}},ends={{x=0.352,y=0.75,mapID=390,npcID=58911}},coords={mapID=390,x=0.352,y=0.75},questType="standard"},
[31294] = {id=31294,name="The Ruins of Guo-Lai",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="I have my heartfelt thanks for your continued aid. Anji awaits at the Ruins of Guo-Lai to northwest. Go with courage in your heart, young <class>.",objectivesText="Speak to Angi Autumnlight at the Ruins of Guo-Lai.",starts={{npcID=59338}},questType="standard"},
[31295] = {id=31295,name="Mogu within the Ruins of Guo-Lai",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="Thank you for your help, <class>. I would enjoy your company for longer, but Leven is leading an attack on the mogu within the Ruins of Guo-Lai to the northwest, and awaits your capable hands. May the celestials protect you, young one.",objectivesText="Speak to Leven Dawnblade at the Ruins of Guo-Lai.",starts={{npcID=59338}},questType="standard"},
[31296] = {id=31296,name="The Ruins of Guo-Lai",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="The villagers seem to be safe and the mogu are losing their foothold. We should be able to handle the rest from here. Thank you for your kind aid, <name>. Anji lead a group to investigate and clear out the Ruins of Guo-Lai to the northwest this morning. I am certain she would appreciate someone as capable as yourself. You should go to her.",objectivesText="Speak to Anji Autumnlight at the Ruins of Guo-Lai.",starts={{npcID=59337}},questType="standard"},
[31297] = {id=31297,name="Setting Sun Garrison",level=90,requiredLevel=90,faction="both",expansion=4,zoneID=5840,description="The mogu will not be able to maintain this attack much longer. We should be able to handle it here, thanks to your kind aid. Might you be willing to find Anji at the Setting Sun Training Camp to the west? She's been tasked with preparing fresh-faced pandaren to aid the cause. You could show them a thing or two as well, I imagine.",objectivesText="Speak to Anji Autumnlight at the Setting Sun Training Camp.",starts={{npcID=59337}},questType="standard"},
[31302] = {id=31302,name="Ready for Greatness",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,description="You seem to know your way around the kitchen. Demonstrate to me your skills and make me 5 bowls of rice pudding .",objectivesText="Make 5 Rice Pudding and give them to the Guide to the Ways. Progress: I believe you have the potential to be a great chef, but the proof is in the pudding, so to speak.",starts={{npcID=64231,x=0.536,y=0.512,zoneID=5805}},ends={{npcID=64231,x=0.536,y=0.512,zoneID=5805}},coords={x=0.536,y=0.512,source="quest_giver",zoneID=5805},questType="standard"},
[31303] = {id=31303,name="The Seal is Broken",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="I... I thought Sha of this immensity were a myth - we all did. Just a story to keep our children from fighting. No time to talk now. Those fissures - they're feeding it... it grows stronger by the moment! I must research the scrolls from my family archives. You, take this cannon and ride Mishi. You must find a way to contain this horror that has been unleashed!",objectivesText="Seal 12 Sha Fissures to banish the Sha of Doubt.",starts={{npcID=59411,x=0.446,y=0.67,zoneID=5785}},ends={{npcID=59418,x=0.492,y=0.614,zoneID=5785}},coords={x=0.446,y=0.67,source="quest_giver",zoneID=5785},questType="standard"},
[31304] = {id=31304,name="FLAG - Kafa Press",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[31306] = {id=31306,name="Seeker's Folly",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="I'm sure your pandaren friend has some ideas about what the mogu are after. He headed up the mountain a few days ago without a guide, and asked that only you be sent up after him. He was very specific: \"The must endure the trek alone, with only thoughts. will honor each shrine before meeting me at the top.\" The path is just northwest of the camp, marked by flags. Please be careful! Seeker's Folly is a dangerous trek even on a lucky day.",starts={{npcID=60180,x=0.48,y=0.49,mapID=379}},ends={{npcID=60795,x=0.438,y=0.51,mapID=379}},coords={x=0.48,y=0.49,source="quest_giver",mapID=379},questType="standard"},
[31307] = {id=31307,name="FLAG - Jade Infused Blade",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5785,mapID=371,questType="standard"},
[31308] = {id=31308,name="Learning the Ropes",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=12,mapID=37,description="Now that you are a pet trainer, it's time to test your skills! Head out into the forest and pick a fight with a battle pet. Make sure to use your Track Pets skill so you can see pets you can fight on the minimap. Come back to me after you have won and I will continue your training. Good luck!",starts={{npcID=63014,x=0.402,y=0.66,mapID=37}},ends={{npcID=63014,x=0.402,y=0.66,mapID=37}},coords={x=0.402,y=0.66,source="quest_giver",mapID=37},questType="standard"},
[31309] = {id=31309,name="On The Mend",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=12,mapID=37,description="Now that you have won a battle, we need to heal up your pets so they can fight another day! Visit Erma, our local stable master, to heal and revive your pets.",starts={{npcID=63014,x=0.402,y=0.66,mapID=37}},ends={{npcID=63014,x=0.402,y=0.66,mapID=37}},coords={x=0.402,y=0.66,source="quest_giver",mapID=37},questType="standard"},
[31311] = {id=31311,name="Way of the Grill",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,description="The Pandaren Way of the Grill produces foods that increase your physical strength. Bring some raw tiger steaks to the Master of the Grill, and he will teach you what you can do with them. There are many tigers in the Jade Forest and the Krasarang Wilds, but you can also find them in other places.",objectivesText="Bring 5 Raw Tiger Steaks to the Master of the Grill. Progress: If you wish to learn the Way of the Grill , bring me some raw tiger steaks .",starts={{npcID=64231,x=0.536,y=0.512,zoneID=5805}},ends={{npcID=58712,x=0.53,y=0.514,zoneID=5805}},coords={x=0.536,y=0.512,source="quest_giver",zoneID=5805},questType="standard"},
[31312] = {id=31312,name="The Old Map",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="The old, faded leather is falling apart, but still legible. Scrawled on it is some kind of map, and the following lines: Deep in the valley where four winds blow, The maiden laughs behind her golden fan. At the feet of her ancestors' stair, She whispers secrets into the echoing dark.",objectivesText="Show the map to Fish Fellreed at Cattail Lake or Halfhill Market in the Valley of the Four Winds . Provided item:",ends={{npcID=58705,x=0.528,y=0.518,mapID=376}},questType="standard"},
[31313] = {id=31313,name="Just A Folk Story",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="What!?! This don't make any sense! What's this mumber jumber about a maiden and an ancestor and a buncha stairs? I can't make any reason outta this, can you? Well, there are lotsa folks 'round here who're much older than you and me, . Can you go talk to the folks in Halfhill? I betcha they might know somethin'!",objectivesText="Speak to Grainsorter Pei , Stonecarver Mac , Mama Min , and Old Man Whitewhiskers .",starts={{npcID=58705,x=0.528,y=0.518,zoneID=5805}},ends={{npcID=58705,x=0.528,y=0.518,zoneID=5805}},coords={x=0.528,y=0.518,source="quest_giver",zoneID=5805},questType="standard"},
[31314] = {id=31314,name="Old Man Thistle's Treasure",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Well high golly! This is turning into a real life treasure hunt! There's gotta be some kind of entrance or opening to the north, where the mountains meet Cattail Lake. I'll meet ya at the entrance! Let's go get that treasure!",objectivesText="Find the cave entrance and recover Old Man Thistle's hidden treasure . Progress: If I weren't seeing it fer myself, I could hardly believe it!",starts={{npcID=58705,x=0.528,y=0.518,zoneID=5805}},ends={{npcID=213767,x=0.349,y=0.192,zoneID=5805}},coords={x=0.528,y=0.518,source="quest_giver",zoneID=5805},questType="standard"},
[31315] = {id=31315,name="The Heartland Legacy",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="At the very bottom of the treasure chest, you find a stack of scrolls and a soft leather sack with seeds. Unrolling the scrolls, you see they contain detailed farming notes, drawings of plants, numbers and calculations, locations of nearby water springs, and countless other snippets. There might be someone at the Tillers Union who would like to see this.",objectivesText="Take Old Man Thistle's Almanac to Seedkeeper Shing Sing at Halfhill in the Valley of the Four Winds . Progress: What do you have there?",starts={{npcID=213767,x=0.349,y=0.192,zoneID=5805}},ends={{npcID=64314,x=0.538,y=0.474,zoneID=5805}},coords={x=0.349,y=0.192,source="quest_giver",zoneID=5805},questType="standard"},
[31316] = {id=31316,name="Julia, The Pet Tamer",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=12,mapID=37,description="I can tell you have been honing your pet battle skills, . I think it's time for you to take on a real challenge. Julia Stevens can be found at the Maclure Vineyards south of Stormwind. She is an up and coming wild pet tamer and I think it's time you faced her in battle!",objectivesText="Defeat Julia Stevens in a pet battle. Progress: How is your team coming along? I have two snakes so far!",starts={{npcID=63596,x=0.692,y=0.25,zoneID=1519}},ends={{npcID=64330,x=0.416,y=0.836,zoneID=12}},coords={x=0.692,y=0.25,source="quest_giver",zoneID=1519},questType="standard"},
[31319] = {id=31319,name="Emergency Response",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,mapID=371,description="Your companions have made themselves at home in our land, and brought with them a dangerous conflict. The full extent of their destruction here we cannot yet know. Already it is... unspeakable. Nevertheless, to forsake your friends out of spite would be against our way. Any that yet live are doubtlessly wounded and in desperate need of care. These fireworks were to celebrate the statue's completion. Use them near your companions to signal Mishi, and she will bear them off to safety.",objectivesText="Use Cho's Fireworks near Admiral Taylor , Mishka and Sully .",starts={{npcID=59418,x=0.492,y=0.614,zoneID=5785}},ends={{npcID=59418,x=0.492,y=0.614,zoneID=5785}},coords={x=0.492,y=0.614,source="quest_giver",zoneID=5785},questType="standard"},
[31320] = {id=31320,name="Buy A Fish A Drink?",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Heeeey buddy, how'sh it goin'? You wanna buy a jinyu a drink?",objectivesText="Bring 1 Four Wind Soju to Jogu the Drunk . Four Wind Soju can be purchased from most bartenders in Pandaria. Progress: Thirsty...",starts={{npcID=58710,x=0.534,y=0.524,zoneID=5805}},ends={{npcID=58710,x=0.534,y=0.524,zoneID=5805}},coords={x=0.534,y=0.524,source="quest_giver",zoneID=5805},questType="standard"},
[31321] = {id=31321,name="Buy A Fish A Round?",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Heeeey it's my friend, the ! I guesh you've seen me hanging 'round, but I should 'splain that I'm not drunk. I mean, look at me now! Shober as a freshwater fish! Sure I like to drown my sorrowsh in some good brew now and then, but you can't inebriate a jinyu! Might as well try to drown a fish! No, the brewsh make me shleepy, and when I shleep, I have vishions of the future. The shtronger the brew, the more potent my dreamsh! If you bring me a drink, I'll owe you one.",objectivesText="Bring 5 Pandaren Plum Wine to Jogu the Drunk . Pandaren Plum Wine can be purchased from most bartenders in Pandaria. Progress: What do you mean I talk like I'm drunk? Thish ish how I shpeak!",starts={{npcID=58710,x=0.534,y=0.524,zoneID=5805}},ends={{npcID=58710,x=0.534,y=0.524,zoneID=5805}},coords={x=0.534,y=0.524,source="quest_giver",zoneID=5805},questType="standard"},
[31322] = {id=31322,name="Buy A Fish A Keg?",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="My dreams grow dim recently, . I need something powerful to kick myshelf back into gear! I heard there'sh a delishush drink that folksh are making nowadays. It'sh called Jade Witch Brew . I'd sure like to taste some.",objectivesText="Bring 10 Jade Witch Brew to Jogu the Drunk . Jade Witch Brew can be made using the cooking profession. Progress: Any luck?",starts={{npcID=58710,x=0.534,y=0.524,zoneID=5805}},ends={{npcID=58710,x=0.534,y=0.524,zoneID=5805}},coords={x=0.534,y=0.524,source="quest_giver",zoneID=5805},questType="standard"},
[31323] = {id=31323,name="Buy A Fish A Brewery?",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="All right, , in order to continue my vishions, I must now have my own brewery. ... Just kidding! You should have sheen your own face! Hilarioush... hic! Anyway, I heard of a new drink that is unlike any other, and I would like a tashte. Have you heard of the Mad Brewer'sh Breakfasht? If you can bring me some of thish shtuff, you will be my friend for life.",objectivesText="Bring 20 Mad Brewer's Breakfast to Jogu the Drunk . Mad Brewer's Breakfasts can be made using the cooking profession. Progress: Have you tried it?",starts={{npcID=58710,x=0.534,y=0.524,zoneID=5805}},ends={{npcID=58710,x=0.534,y=0.524,zoneID=5805}},coords={x=0.534,y=0.524,source="quest_giver",zoneID=5805},questType="standard"},
[31324] = {id=31324,name="Family Secrets",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5963,description="Our secret recipes! I was gathering them up. But then... hozen? How is Gao to brew anything? He needs those recipes or disaster is sure to strike!",objectivesText="Collect 5 Stormstout Secrets . Progress: Well, hello!",starts={{x=0.762,y=0.364,mapID=439,npcID=59822}},ends={{x=0.762,y=0.364,mapID=439,npcID=59822}},coords={mapID=439,x=0.762,y=0.364},questType="dungeon"},
[31325] = {id=31325,name="A Very Nice Necklace",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="The beautiful necklace is only partly smudged by dirty hozen hands. There's only one person in the Valley who would own such a beautiful piece of jewelry.",objectivesText="Bring the necklace to Tina Mudclaw at Haohan's House or Halfhill Market in the Valley of the Four Winds . Provided item:",ends={{npcID=58761,x=0.45,y=0.338,mapID=376}},questType="standard"},
[31326] = {id=31326,name="Tina's Tasteful Tiara",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="It's a dazzling diamond tiara. Who in the valley would be wealthy enough to own such a piece of jewelry? Whoever it is, they might be willing to give a nice reward.",objectivesText="Bring the Tasteful Tiara to Tina Mudclaw at Haohan's House or Halfhill Market in the Valley of the Four Winds . Provided item:",ends={{npcID=58761,x=0.45,y=0.338,mapID=376}},questType="standard"},
[31327] = {id=31327,name="Trouble Brewing",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5963,description="With the brewery infested by hozen and... and who knows what else, I'm sure that the brewers are in trouble. Would you mind helping me find out what's going on, my friend?",objectivesText="Kill Yan-Zhu the Uncasked .",starts={{x=0.766,y=0.368,mapID=439,npcID=59704}},ends={{x=0.766,y=0.368,mapID=439,npcID=59704}},coords={mapID=439,x=0.766,y=0.368},questType="dungeon"},
[31328] = {id=31328,name="An Exquisite Earring",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="You unhook the earring off the furry creature's ear. It looks like he was having some fun wearing the dangly hoop. TOO much fun. Perhaps the owner of this dainty bauble would like to see it returned. You don't have to tell her where you found it... or who was wearing it.",objectivesText="Bring the Exquisite Earring to Tina Mudclaw at Haohan's House or Halfhill Market in the Valley of the Four Winds . Provided item:",ends={{npcID=58761,x=0.45,y=0.338,mapID=376}},questType="standard"},
[31329] = {id=31329,name="A Beautiful Brooch",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="It is a very old, antique brooch with very detailed molding and filigree worked into the edges. It looks very valuable. There's only one person who keeps losing jewelry to furry hooligans, and she would probably want to see this heirloom returned.",objectivesText="Bring the Beautiful Brooch to Tina Mudclaw at Haohan's House or Halfhill Market in the Valley of the Four Winds . Provided item:",ends={{npcID=58761,x=0.45,y=0.338,mapID=376}},questType="standard"},
[31331] = {id=31331,name="Figuring out how to make quests",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5042,mapID=207,description="Whee! You get to make a breadcrumb quest! Now figure out what to do next.",objectivesText="Make a breadcrumb quest.",questType="standard"},
[31332] = {id=31332,name="Lesson 1: Sliced Peaches",level=90,requiredLevel=85,faction="both",expansion=4,description="I'm excited to start my training. We start with sliced peaches , right?",objectivesText="Obtain a 5 Pandaren Peaches for Nomi 's cooking lesson. Progress: I really want to be a chef, but the other kids already started a couple of months ago. There's no way I can catch up without your help.",starts={{npcID=64337}},questType="standard"},
[31333] = {id=31333,name="Lesson 2: Instant Noodles",level=90,requiredLevel=85,faction="both",expansion=4,description="Instant noodles aren't that hard to cook, right?",objectivesText="Obtain 5 Instant Noodles for Nomi 's Lesson. Progress: It's so easy to overcook the noodles!",starts={{npcID=64337}},questType="standard"},
[31334] = {id=31334,name="Lesson 3: Toasted Fish Jerky",level=90,requiredLevel=85,faction="both",expansion=4,description="Cooking is harder than I thought. It's so easy to burn things.",objectivesText="Obtain 5 Golden Carp for Nomi 's Lesson. Progress: I hope I don't burn myself. Eep.",starts={{npcID=64337}},questType="standard"},
[31335] = {id=31335,name="Lesson 4: Dried Needle Mushrooms",level=90,requiredLevel=85,faction="both",expansion=4,description="I'm not very fond of mushrooms... but I'll do my best to learn.",objectivesText="Obtain 5 Needle Mushrooms for Nomi 's Lesson. Progress: Ick.",starts={{npcID=64337}},questType="standard"},
[31336] = {id=31336,name="Lesson 5: Pounded Rice Cake",level=90,requiredLevel=85,faction="both",expansion=4,description="I love rice cakes. I'll do my best to make good ones!",objectivesText="Obtain 5 Rice for Nomi 's Lesson. Progress: I can't wait to see how they turn out!",starts={{npcID=64337}},questType="standard"},
[31337] = {id=31337,name="A Token of Appreciation",level=90,requiredLevel=85,faction="both",expansion=4,description="Thanks for checking to make sure I'm doing well! I've been able to help out the Ironpaws today, and they said I could give this to you.",objectivesText="Receive Nomi 's gift.",starts={{npcID=64337}},questType="standard"},
[31338] = {id=31338,name="Lost Sheepie",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Chee Chee 's prize sheep, Sheepie , is missing! That bad sheep is always wandering off the farm. Stupid sheep! I looked everywhere and couldn't find him. Can you help me, ?",objectivesText="Find Sheepie and return him to Chee Chee . Progress: Did you find my Sheepie ? Oh, I was so worried.",starts={{npcID=58709,x=0.53,y=0.52,zoneID=5805}},ends={{npcID=58709,x=0.53,y=0.52,zoneID=5805}},coords={x=0.53,y=0.52,source="quest_giver",zoneID=5805},questType="standard"},
[31339] = {id=31339,name="Lost Sheepie... Again",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="That stupid sheep! He wandered off again! Can you find him for me again?",objectivesText="Find Sheepie and bring him back to Chee Chee . Progress: Oh, poor Sheepie . He's probably so scared and alone...",starts={{npcID=58709,x=0.53,y=0.52,zoneID=5805}},ends={{npcID=58709,x=0.53,y=0.52,zoneID=5805}},coords={x=0.53,y=0.52,source="quest_giver",zoneID=5805},questType="standard"},
[31340] = {id=31340,name="Oh Sheepie...",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Sigh... you guessed it... Sheepie is gone... AGAIN. Stupid sheep! Gives me so much trouble! I hate to ask you again, but I promise this will be the last time. Can you find him for me?",objectivesText="Find Sheepie . Progress: Where's Sheepie ?",starts={{npcID=58709,x=0.53,y=0.52,zoneID=5805}},ends={{npcID=58709,x=0.53,y=0.52,zoneID=5805}},coords={x=0.53,y=0.52,source="quest_giver",zoneID=5805},questType="standard"},
[31341] = {id=31341,name="A Wolf In Sheep's Clothing",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="AAAIIIIEEUUGGHHHH!!!! This is the last straw! Those stupid hozen on the mountain killed my SHEEPIE! I know exactly who did this, and it is time for REVENGE. If you are willing to help me, take this old sheepskin . Use it to disguise yourself anywhere on the mountain to the north, wait for that little dooker Krungko to come out of hiding, and then break his bones!",objectivesText="Use the old sheepskin anywhere in the Skyrange or Kunzen Village, then kill Krungko.",starts={{npcID=58709,x=0.53,y=0.52,zoneID=5805}},ends={{npcID=58709,x=0.53,y=0.52,zoneID=5805}},coords={x=0.53,y=0.52,source="quest_giver",zoneID=5805},questType="standard"},
[31342] = {id=31342,name="The Path to Respect Lies in Violence",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5918,description="You have proven yourself in battle. Still, if you would aid us further, I must ask something else of you. The Sha of Violence awaits beyond within the Sealed Chambers. Destroy it if you would earn my respect.",objectivesText="Kill the Sha of Violence .",starts={{npcID=56541,x=0.295,y=0.73,zoneID=5918}},ends={{npcID=64387,zoneID=5918}},coords={x=0.295,y=0.73,source="quest_giver",zoneID=5918},questType="dungeon"},
[31354] = {id=31354,name="Mazu's Bounty",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="That was some amazing work you and the captain did out there, $p! It's an honor to have you on the crew. Oh! And Ju Lien survived! He swam ashore just after you started letting the harpoons fly. He was raving about some kind of gigantic egg or something that washed in with Jiao. Go check up on him, will you? He's probably hauled it out of the water by now.",starts={{npcID=63349,x=0.548,y=0.722,mapID=422}},ends={{npcID=64259,x=0.536,y=0.76,mapID=422}},coords={x=0.548,y=0.722,source="quest_giver",mapID=422},questType="standard"},
[31355] = {id=31355,name="Restoring Jade's Purity",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5956,description=", will you aid us? The temple's purity has been jeopardized. Even now the three masters struggle against their doubts. Please, I beg you, head in and help Wise Mari, Liu Flameheart, and Lorewalker Stonestep in their fight against the sha.",questType="dungeon"},
[31356] = {id=31356,name="Deep Doubts, Deep Wisdom",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5956,description="There is an ancient pandaren saying that states, \"With deep doubts comes deep wisdom.\" The Sha of Doubt has infested the Heart of Jade within the temple. It must be destroyed. I dare say that you are about to become all the wiser, .",objectivesText="Kill the Sha of Doubt . Progress: The Sha of Doubt must be destroyed, <name>, or we are all lost.",starts={{x=0.354,y=0.444,mapID=429,npcID=64399}},ends={{x=0.354,y=0.444,mapID=429,npcID=64399}},coords={mapID=429,x=0.354,y=0.444},questType="dungeon"},
[31357] = {id=31357,name="Relics of the Four Kings",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=6182,description="The mogu have reawakened and are a threat to all of Pandaria. They are on the cusp of becoming even more dangerous. There are four great mogu kings of legend: Zian of the Endless Shadow, Meng the Demented, Qiang the Merciless, and Subetai the Swift. Four artifacts of these kings are secreted away in the Vault of Kings Past, below. You must retrieve these relics before the mogu discover them and become unstoppable.",objectivesText="Collect the Lantern of the Sorcerer King , Mad King Meng's Balance , Qiang's \"The Science of War\", and Subetai's Bow of the Swift . Progress: We must retrieve the lantern, balance, scroll, and bow before Xin and his clans uncover them.",starts={{x=0.388,y=0.818,mapID=455,npcID=64432}},ends={{x=0.388,y=0.818,mapID=455,npcID=64432}},coords={mapID=455,x=0.388,y=0.818},questType="dungeon"},
[31359] = {id=31359,name="The Kunchong Whisperer",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="To really connect with Kovok you need to challenge him mentally and physically. You must respect his strength and intelligence; only then will he allow you to really train him. The muckscale tribe may provide an adequate test of his abilities and with you there he shouldn't be in danger. Additionally, this will allow us to decrease their numbers in the Briny Muck.",objectivesText="Kill Oracle Hiss'ir and 10 Muckscale tribe members.",starts={{npcID=64013,x=0.434,y=0.634,zoneID=6138},{npcID=64344,x=0.416,y=0.72,zoneID=6138}},ends={{npcID=63758,x=0.542,y=0.358,zoneID=6138}},coords={x=0.434,y=0.634,source="quest_giver",zoneID=6138},questType="standard"},
[31360] = {id=31360,name="A New Lesson for the Master",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=6182,description="A new king of the mogu has arisen: Xin the Weaponmaster . He single-handedly subjugated the mogu clans, and now they and their new leaders vie for his favor. I've never seen or read of any who are his equal in battle. Do not underestimate Xin, . Our fate rests in your hands.",questType="dungeon"},
[31362] = {id=31362,name="Last Piece of the Puzzle",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,mapID=371,description="I must say, , despite their skirmishes with the hozen, I've never seen the jinyu so militant. This troubles me. We must discuss it another time, however. I have come to ask for your assistance. The fresco, where last we spoke, is nearly unveiled. I am certain that it holds ancient wisdom - knowledge that the emperor would have us remember. My meditations alone may not be enough to discern its meaning. Please, take this heirloom to the shrine of my ancestors. I shall require their assistance.",starts={{npcID=59620,x=0.588,y=0.81,mapID=371}},ends={{npcID=59411,x=0.446,y=0.67,mapID=371}},coords={x=0.588,y=0.81,source="quest_giver",mapID=371},questType="standard"},
[31363] = {id=31363,name="Lighting the Way",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5976,description="We need reinforcements! Someone has to fight through and light the signal flame. It's all up to you, . No pressure or anything.",objectivesText="Light the Signal Flame.",starts={{x=0.61,y=0.882,mapID=437,npcID=64467}},ends={{x=0.61,y=0.882,mapID=437,npcID=64467}},coords={mapID=437,x=0.61,y=0.882},questType="dungeon"},
[31364] = {id=31364,name="That's a Big Bug!",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5976,description="The mantid have something they call Raigonn . It's a giant bug they're using to bust down the wall's gates! Let's keep that thing from getting into the vale!",questType="dungeon"},
[31365] = {id=31365,name="Somewhere Inside",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=6214,description="I sent a dozen of my best men ahead to infiltrate the mantid siege. None have returned. Since you are taking the fight directly to the mantid, you will be in a position to free any who had the misfortune to be captured. You will do this?",starts={{npcID=64517,x=0.58,y=0.23,zoneID=6214},{npcID=64517,zoneID=6214}},ends={{npcID=64517,x=0.58,y=0.23,zoneID=6214},{npcID=64517,zoneID=6214}},coords={x=0.58,y=0.23,source="quest_giver",zoneID=6214},questType="dungeon"},
[31366] = {id=31366,name="Take Down the Wing Leader",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=6214,description="The mantid have lain siege to Niuzao Temple. Even now, Wing Leader Ner'onok and his forces work to cross the final chasm. You must stop him before they reconstruct that bridge.",starts={{npcID=64517,x=0.58,y=0.23,zoneID=6214},{npcID=64517,zoneID=6214}},ends={{npcID=64517,x=0.58,y=0.23,zoneID=6214},{npcID=64517,zoneID=6214}},coords={x=0.58,y=0.23,source="quest_giver",zoneID=6214},questType="dungeon"},
[31367] = {id=31367,name="The Lorewalkers",level=30,requiredLevel=30,faction="alliance",expansion=4,zoneID=5840,mapID=1530,description="So you are interested in learning more of the lore of this land? Very well! You should speak to Lorewalker Cho at the Seat of Knowledge. He can be found in the room above the entrance to the Mogu'shan Palace. Speak with Mishi for a ride.",starts={{npcID=64508,x=0.854,y=0.602,mapID=1530}},ends={{npcID=61962,x=0.832,y=0.296,mapID=1530}},coords={x=0.854,y=0.602,source="quest_giver",mapID=1530},questType="standard"},
[31368] = {id=31368,name="The Lorewalkers",level=30,requiredLevel=30,faction="horde",expansion=4,zoneID=5840,description="So you are interested in learning more of the lore of this land? Very well! You should speak to Lorewalker Cho at the Seat of Knowledge. He can be found in the room above the entrance to the Mogu'shan Palace. Speak with Mishi for a ride.",objectivesText="Speak to Lorewalker Cho at the Seat of Knowledge in the Vale of Eternal Blossoms . Progress: Welcome, traveler.",starts={{npcID=64531,x=0.624,y=0.216,zoneID=5840}},ends={{npcID=61962,x=0.832,y=0.296,zoneID=5840}},coords={x=0.624,y=0.216,source="quest_giver",zoneID=5840},questType="standard"},
[31369] = {id=31369,name="The Anglers",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="If you want to explore all the secrets of the deep ocean, and catch some big fish, speak to Haito at the Anglers Wharf in Krasarang Wilds . I'm sure he'd love to show you a thing or two about reeling!",objectivesText="Speak to Fisherman Haito at the Anglers Wharf in the Krasarang Wilds .",starts={{npcID=64033,x=0.864,y=0.602,zoneID=5840}},ends={{npcID=59584,x=0.678,y=0.452,zoneID=6134}},coords={x=0.864,y=0.602,source="quest_giver",zoneID=5840},questType="standard"},
[31370] = {id=31370,name="The Anglers",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,mapID=418,description="If you want to explore all the secrets of the deep ocean, and catch some big fish, speak to Haito at the Anglers Wharf in Krasarang Wilds . I'm sure he'd love to show you a thing or two about reeling!",starts={{npcID=64010,x=0.608,y=0.234,mapID=1530}},ends={{npcID=59584,x=0.678,y=0.452,mapID=418}},coords={x=0.608,y=0.234,source="quest_giver",mapID=418},questType="standard"},
[31372] = {id=31372,name="The Tillers",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=5805,description="The Tillers do their business at Halfhill in the Valley of the Four Winds . If you're interested in getting started, I hear there's a new farmer in town by the name of Farmer Yoon . I betcha he'll be looking for help.",objectivesText="Speak to Farmer Yoon at Sunsong Ranch in the Valley of the Four Winds .",starts={{npcID=64036,x=0.87,y=0.608,zoneID=5840}},ends={{npcID=58721,x=0.52,y=0.48,zoneID=5805}},coords={x=0.87,y=0.608,source="quest_giver",zoneID=5840},questType="standard"},
[31373] = {id=31373,name="The Order of the Cloud Serpent",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="The Order of the Cloud Serpent is always searching for talented riders. If you wish to follow our way, you should speak to Instructor Skythorn at The Arboretum in the Jade Forest . I wish you luck, .",objectivesText="Speak to Instructor Skythorn at The Arboretum in The Jade Forest .",starts={{npcID=64484,x=0.858,y=0.622,zoneID=5840}},ends={{npcID=58228,x=0.574,y=0.45,zoneID=5785}},coords={x=0.858,y=0.622,source="quest_giver",zoneID=5840},questType="standard"},
[31374] = {id=31374,name="The Tillers",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=5805,description="The Tillers do their business at Halfhill in the Valley of the Four Winds . If you're interested in getting started, I hear there's a new farmer in town by the name of Farmer Yoon . I betcha he'll be looking for help.",objectivesText="Speak to Farmer Yoon at Sunsong Ranch in the Valley of the Four Winds .",starts={{npcID=64011,x=0.604,y=0.228,zoneID=5840}},ends={{npcID=58721,x=0.52,y=0.48,zoneID=5805}},coords={x=0.604,y=0.228,source="quest_giver",zoneID=5840},questType="standard"},
