[31376] = {id=31376,name="Attack At The Temple of the Jade Serpent",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,mapID=371,description="Darkness enshrouds the Temple of the Jade Serpent, and Yu'Lon's priests beseech us for aid. They hold the sha in check, but just barely. You may be able to turn the tide, .",starts={{npcID=64032,x=0.846,y=0.636,mapID=1530}},ends={{npcID=57324,x=0.538,y=0.618,mapID=371}},coords={x=0.846,y=0.636,source="quest_giver",mapID=371},questType="standard"},
[31377] = {id=31377,name="Attack At The Temple of the Jade Serpent",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,mapID=371,description="Darkness enshrouds the Temple of the Jade Serpent, and Yu'Lon's priests beseech us for aid. They hold the sha in check, but just barely. You may be able to turn the tide, .",starts={{npcID=64001,x=0.626,y=0.232,mapID=1530}},ends={{npcID=57324,x=0.538,y=0.618,mapID=371}},coords={x=0.626,y=0.232,source="quest_giver",mapID=371},questType="standard"},
[31378] = {id=31378,name="Challenge At The Temple of the Red Crane",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="The Temple of the Red Crane still reels from the aftermath of the sha's presence, and has only recently gathered to rebuild and retrain its warriors. If you wish to help at the temple, speak to Thelonius at the Cradle of Chi-Ji.",objectivesText="Speak to Thelonius at the Cradle of Chi-Ji in the Krasarang Wilds .",starts={{npcID=64032,x=0.846,y=0.636,zoneID=5840}},ends={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},coords={x=0.846,y=0.636,source="quest_giver",zoneID=5840},questType="standard"},
[31379] = {id=31379,name="Challenge At The Temple of the Red Crane",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="The Temple of the Red Crane still reels from the aftermath of the sha's presence, and has only recently gathered to rebuild and retrain its warriors. If you wish to help at the temple, speak to Thelonius at the Cradle of Chi-Ji.",objectivesText="Speak to Thelonius at the Cradle of Chi-Ji in the Krasarang Wilds .",starts={{npcID=64001,x=0.626,y=0.232,zoneID=5840}},ends={{npcID=60506,x=0.312,y=0.634,zoneID=6134}},coords={x=0.626,y=0.232,source="quest_giver",zoneID=5840},questType="standard"},
[31380] = {id=31380,name="Trial At The Temple of the White Tiger",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,description="Xuen , the great Celestial of the North, seeks the greatest champions in the land. Today, he holds trials of battle at his temple in Kun-Lai Summit . If you wish to test yourself against skilled fighters from all across Pandaria, then go to him and enter the challenger's ring!",objectivesText="Speak to Xuen at the Temple of the White Tiger in Kun-Lai Summit .",starts={{npcID=64032,x=0.846,y=0.636,zoneID=5840}},ends={{npcID=60968,x=0.664,y=0.464,zoneID=5841}},coords={x=0.846,y=0.636,source="quest_giver",zoneID=5840},questType="standard"},
[31381] = {id=31381,name="Trial At The Temple of the White Tiger",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,description="Xuen , the great Celestial of the North, seeks the greatest champions in the land. Today, he holds trials of battle at his temple in Kun-Lai Summit . If you wish to test yourself against skilled fighters from all across Pandaria, then go to him and enter the challenger's ring!",objectivesText="Speak to Xuen at the Temple of the White Tiger in Kun-Lai Summit .",starts={{npcID=64001,x=0.626,y=0.232,zoneID=5840}},ends={{npcID=60968,x=0.664,y=0.464,zoneID=5841}},coords={x=0.626,y=0.232,source="quest_giver",zoneID=5840},questType="standard"},
[31382] = {id=31382,name="Defense At Niuzao Temple",level=25,requiredLevel=25,faction="alliance",expansion=4,zoneID=5842,description="Niuzao Temple, far to the west, is under attack by the mantid. The great Celestial holds them back for now, but he cannot stand alone forever. Go and help the defenders, . The Temple must not fall!",objectivesText="Speak to Ogo the Elder at Niuzao Temple in the Townlong Steppes .",starts={{npcID=64032,x=0.846,y=0.636,zoneID=5840}},ends={{npcID=61580,x=0.392,y=0.622,zoneID=5842}},coords={x=0.846,y=0.636,source="quest_giver",zoneID=5840},questType="standard"},
[31383] = {id=31383,name="Defense At Niuzao Temple",level=25,requiredLevel=25,faction="horde",expansion=4,zoneID=5842,description="Niuzao Temple, far to the west, is under attack by the mantid. The great Celestial holds them back for now, but he cannot stand alone forever. Go and help the defenders, . The Temple must not fall!",objectivesText="Speak to Ogo the Elder at Niuzao Temple in the Townlong Steppes .",starts={{npcID=64001,x=0.626,y=0.232,zoneID=5840}},ends={{npcID=61580,x=0.392,y=0.622,zoneID=5842}},coords={x=0.626,y=0.232,source="quest_giver",zoneID=5840},questType="standard"},
[31384] = {id=31384,name="The Golden Lotus",level=30,requiredLevel=30,faction="alliance",expansion=4,zoneID=5840,description="The Golden Lotus have guarded the Vale for centuries, keeping it safe and hidden from harm. Recent events have unleashed terrible horrors upon our sacred vale, but allies of the Golden Lotus still stand against them, attempting to bring peace. If you wish to help, you had best join them at the Setting Sun Garrison.",objectivesText="Speak to Anji Autumnlight at the Setting Sun Garrison in the Vale of Eternal Blossoms .",starts={{npcID=64031,x=0.842,y=0.624,zoneID=5840}},ends={{npcID=58408,x=0.566,y=0.436,zoneID=5840},{npcID=58919,x=0.214,y=0.716,zoneID=5840}},coords={x=0.842,y=0.624,source="quest_giver",zoneID=5840},questType="standard"},
[31385] = {id=31385,name="The Golden Lotus",level=30,requiredLevel=30,faction="horde",expansion=4,zoneID=5840,mapID=1530,description="The Golden Lotus have guarded the Vale for centuries, keeping it safe and hidden from harm. Recent events have unleashed terrible horrors upon our sacred vale, but allies of the Golden Lotus still stand against them, attempting to bring peace. If you wish to help, you had best join them at the Setting Sun Garrison.",starts={{npcID=64007,x=0.63,y=0.222,mapID=1530}},ends={{npcID=58408,x=0.566,y=0.436,mapID=1530},{npcID=58919,x=0.214,y=0.716,mapID=1530}},coords={x=0.63,y=0.222,source="quest_giver",mapID=1530},questType="standard"},
[31386] = {id=31386,name="The Shado-Pan Offensive",level=25,requiredLevel=25,faction="alliance",expansion=4,zoneID=5842,description="We Shado-Pan have amassed our forces for the first time in many ages. The Sha of Hatred has escaped beyond the Serpent's Spine, and it is our sacred duty to imprison it once more. However, our warriors are great, but our numbers too few. Help from a capable may not be turned away. If you wish to join the offensive, speak to Taran Zhu in the Townlong Steppes .",objectivesText="Speak to Taran Zhu at Longying Outpost in the Townlong Steppes .",starts={{npcID=64030,x=0.844,y=0.614,zoneID=5840}},ends={{npcID=60688,x=0.712,y=0.566,zoneID=5842}},coords={x=0.844,y=0.614,source="quest_giver",zoneID=5840},questType="standard"},
[31387] = {id=31387,name="Understanding The Shado-Pan",level=25,requiredLevel=25,faction="alliance",expansion=4,zoneID=5842,description="The Shado-Pan rank among Pandaria's oldest defenders. For years we train in our snow-capped monastery high in the Kun-Lai Summit, perfecting the martial secrets passed down by our ancestors. Our numbers may seem few, but a single Shado-Pan can be deadlier than a hundred trained soldiers. To join the Shado-Pan order is a long journey full of hardship. If this is the path you seek, then you must first prove your worth. There is urgent work to be done here. Help the Golden Lotus defend the Vale.",objectivesText="Earn Revered standing with the Golden Lotus .",starts={{npcID=64030,x=0.844,y=0.614,zoneID=5840}},ends={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},coords={x=0.844,y=0.614,source="quest_giver",zoneID=5840},questType="standard"},
[31388] = {id=31388,name="The Shado-Pan Offensive",level=25,requiredLevel=25,faction="horde",expansion=4,zoneID=5842,description="We Shado-Pan have amassed our forces for the first time in many ages. The Sha of Hatred has escaped beyond the Serpent's Spine, and it is our sacred duty to imprison it once more. However, our warriors are great, but our numbers too few. Help from a capable may not be turned away. If you wish to join the offensive, speak to Taran Zhu in the Townlong Steppes .",objectivesText="Speak to Taran Zhu at Longying Outpost in the Townlong Steppes .",starts={{npcID=64002,x=0.63,y=0.212,zoneID=5840}},ends={{npcID=60688,x=0.712,y=0.566,zoneID=5842}},coords={x=0.63,y=0.212,source="quest_giver",zoneID=5840},questType="standard"},
[31389] = {id=31389,name="Understanding The Shado-Pan",level=25,requiredLevel=25,faction="horde",expansion=4,zoneID=5842,description="The Shado-Pan rank among Pandaria's oldest defenders. For years we train in our snow-capped monastery high in the Kun-Lai Summit, perfecting the martial secrets passed down by our ancestors. Our numbers may seem few, but a single Shado-Pan can be deadlier than a hundred trained soldiers. To join the Shado-Pan order is a long journey full of hardship. If this is the path you seek, then you must first prove your worth. There is urgent work to be done here. Help the Golden Lotus defend the Vale.",objectivesText="Earn Revered standing with the Golden Lotus .",starts={{npcID=64002,x=0.63,y=0.212,zoneID=5840}},ends={{npcID=62304,x=0.49,y=0.704,zoneID=5842}},coords={x=0.63,y=0.212,source="quest_giver",zoneID=5840},questType="standard"},
[31390] = {id=31390,name="The Klaxxi",level=30,requiredLevel=30,faction="alliance",expansion=4,zoneID=5840,description="The Klaxxi are only rumored to exist, far beyond the wall in the Dread Wastes . Few have ventured into that territory, and none have returned to tell the tale. If you are set on finding these... Klaxxi... there is a small group of Shado-Pan manning the wall to the far southwest who may know more.",objectivesText="Speak to Bowmistress Li at the Gate of the Setting Sun between the Vale of Eternal Blossoms and the Dread Wastes .",starts={{npcID=64488,x=0.844,y=0.616,zoneID=5840}},ends={{npcID=62112,x=0.14,y=0.77,zoneID=5840}},coords={x=0.844,y=0.616,source="quest_giver",zoneID=5840},questType="standard"},
[31391] = {id=31391,name="The Klaxxi",level=30,requiredLevel=30,faction="horde",expansion=4,zoneID=5840,description="The Klaxxi are only rumored to exist, far beyond the wall in the Dread Wastes . Few have ventured into that territory, and none have returned to tell the tale. If you are set on finding these... Klaxxi... there is a small group of Shado-Pan manning the wall to the far southwest who may know more.",objectivesText="Speak to Bowmistress Li at the Gate of the Setting Sun between the Vale of Eternal Blossoms and the Dread Wastes .",starts={{npcID=64534,x=0.632,y=0.208,zoneID=5840}},ends={{npcID=62112,x=0.14,y=0.77,zoneID=5840}},coords={x=0.632,y=0.208,source="quest_giver",zoneID=5840},questType="standard"},
[31392] = {id=31392,name="Temple of the White Tiger",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5842,description="Have you heard the news, traveller? There's been an attack at one of our most sacred places, the Vale of Eternal Blossoms! Even now, there's a human prince within the White Tiger Temple arguing that you and the other races from beyond the mists should be allowed within. The temple is in the northeast of Kun-Lai. Maybe you can convince the White Tiger to allow you inside? I only hope the Vale has not been utterly destroyed...",objectivesText="Speak to Anduin Wrynn at the Temple of the White Tiger in Kun-Lai Summit .",starts={{npcID=55809,x=0.458,y=0.436,zoneID=5785},{npcID=60289,x=0.524,y=0.778,zoneID=6134},{npcID=63754,x=0.538,y=0.84,zoneID=5841},{npcID=64521,x=0.72,y=0.942,zoneID=5841},{npcID=64448,x=0.558,y=0.518,zoneID=5805},{npcID=66247,x=0.748,y=0.812,zoneID=5842}},ends={{npcID=64540,x=0.688,y=0.432,zoneID=5841}},coords={x=0.458,y=0.436,source="quest_giver",zoneID=5785},questType="standard"},
[31393] = {id=31393,name="Temple of the White Tiger",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5842,description="Have you heard the news, traveller? There's been an attack at one of our most sacred places, the Vale of Eternal Blossoms! Even now, there's a human prince within the White Tiger Temple arguing that you and the other races from beyond the mists should be allowed within. The temple is in the northeast of Kun-Lai. Maybe you can convince the White Tiger to allow you inside? I only hope the Vale has not been utterly destroyed...",objectivesText="Speak to Dezco at the Temple of the White Tiger in Kun-Lai Summit .",starts={{npcID=55809,x=0.458,y=0.436,zoneID=5785},{npcID=60289,x=0.524,y=0.778,zoneID=6134},{npcID=63751,x=0.636,y=0.866,zoneID=5841},{npcID=64521,x=0.72,y=0.942,zoneID=5841},{npcID=64448,x=0.558,y=0.518,zoneID=5805},{npcID=66247,x=0.748,y=0.812,zoneID=5842}},ends={{npcID=64542,x=0.686,y=0.43,zoneID=5841}},coords={x=0.458,y=0.436,source="quest_giver",zoneID=5785},questType="standard"},
