[31398] = {id=31398,name="Falling to Pieces",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Why would the saurok have amber? More importantly, why would Oracle Hiss'ir be so protective of it? It is unlikely this came from the heavily guarded Zan'vess, so where did it come from? Perhaps the Klaxxi will know what to make of it.",objectivesText="Return the Glowing Amber to Kaz'tik the Manipulator . Progress: Where did you find this?",starts={{npcID=214062,x=0.419,y=0.638,zoneID=6138}},ends={{npcID=63758,x=0.542,y=0.358,zoneID=6138}},coords={x=0.419,y=0.638,source="quest_giver",zoneID=6138},questType="standard"},
