[31833] = {id=31833,name="Continue Your Training: Master Woo",requiredLevel=30,faction="both",expansion=4,zoneID=5841,description="Welcome back <name>, the time has come for the next step of your training. Speak with Master Woo in the Training Grounds below us for your next lesson.",objectivesText="Speak with Master Woo in the Peak of Serenity and complete your training with her. Progress: Complete your training with Master Woo .",starts={{x=0.486,y=0.428,mapID=379,npcID=66260}},ends={{x=0.486,y=0.428,mapID=379,npcID=66260}},coords={mapID=379,x=0.486,y=0.428},questType="standard"},
[31834] = {id=31834,name="Begin Your Training: Master Cheng",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5841,description="Greetings, . Welcome to the Peak of Serenity. It is here that we monks train and hone our skills in the martial arts. The time has come for you to begin your training. Speak with Master Cheng in the Training Grounds below us to begin.",objectivesText="Speak with Master Cheng in the Training Grounds and complete your training with him. Progress: Complete your training with Master Cheng .",starts={{npcID=66260,x=0.486,y=0.428,zoneID=5841}},ends={{npcID=66260,x=0.486,y=0.428,zoneID=5841}},coords={x=0.486,y=0.428,source="quest_giver",zoneID=5841},questType="standard"},
