[31840] = {id=31840,name="Practice Makes Perfect: Master Cheng",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5841,description="Welcome Back, . I see you've returned to hone your skills. Speak with Master Cheng in the Training Grounds below us for a practice sparring session.",objectivesText="Speak with Master Cheng in the Peak of Serenity and spar with him. Progress: Spar with Master Cheng .",starts={{npcID=66260,x=0.486,y=0.428,zoneID=5841}},ends={{npcID=66260,x=0.486,y=0.428,zoneID=5841}},coords={x=0.486,y=0.428,source="quest_giver",zoneID=5841},questType="standard"},
