[31847] = {id=31847,name="Better Dead than Dread",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,description="I am sure many of our associates will be requesting your services after your victory here. But I have received a request for aid from our defenders at the wall along the Dread Wastes . If you would assist them, then take a kite and check in with Bowmistress Li .",objectivesText="Speak with Bowmistress Li on the Serpent's Spine.",starts={{npcID=61512,x=0.346,y=0.59,zoneID=5841}},ends={{npcID=62112,x=0.14,y=0.77,zoneID=5840}},coords={x=0.346,y=0.59,source="quest_giver",zoneID=5841},questType="standard"},
[31850] = {id=31850,name="Eric Davidson",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=10,mapID=47,description="Ah, so you've braved the woods again to face me in battle. I accept your brazen challenge to my vicious spawn.",objectivesText="Defeat Eric Davidson in a pet battle.",starts={{npcID=65655,x=0.198,y=0.448,mapID=47}},ends={{npcID=65655,x=0.198,y=0.448,mapID=47}},coords={x=0.198,y=0.448,source="quest_giver",mapID=47},questType="standard"},
[31851] = {id=31851,name="Bill Buckler",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5287,mapID=210,description="So ye've come fer another round, have ye? I'll show ya why they be callin' me the shcourge o' the vale!",objectivesText="Defeat Bill Buckler in a pet battle. Progress: I've sheen better ...hic!",starts={{npcID=65656,x=0.514,y=0.732,mapID=210}},ends={{npcID=65656,x=0.514,y=0.732,mapID=210}},coords={x=0.514,y=0.732,source="quest_giver",mapID=210},questType="standard"},
[31852] = {id=31852,name="Steven Lisbane",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=33,mapID=50,description="You dare to challenge me again? This time, I do believe our battle is going to sway in my favor!",objectivesText="Defeat Steven Lisbane in a pet battle.",starts={{npcID=63194,x=0.46,y=0.404,mapID=50}},ends={{npcID=63194,x=0.46,y=0.404,mapID=50}},coords={x=0.46,y=0.404,source="quest_giver",mapID=50},questType="standard"},
[31853] = {id=31853,name="All Aboard!",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=14,mapID=76,description="You hear all of that, ? There are Alliance that need killing and I need to round up a veteran crew. You're coming with me! We won't be returning until our assignment's complete, so round up your things and make ready. I'll be aboard a newly commissioned gunship over Bladefist Bay. Don't keep me waiting!",objectivesText="Speak to General Nazgrim aboard Hellscream's Fist.",starts={{npcID=54870,x=0.486,y=0.708,zoneID=1637}},ends={{npcID=55054,x=0.612,y=0.446,zoneID=14}},coords={x=0.486,y=0.708,source="quest_giver",zoneID=1637},questType="standard"},
[31854] = {id=31854,name="Analynn",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=331,mapID=63,description="I see you have once again found me. I presume you wish to do battle once more? Yes, let's.",objectivesText="Defeat Analynn in a pet battle.",starts={{npcID=66136,x=0.202,y=0.296,mapID=63}},ends={{npcID=66136,x=0.202,y=0.296,mapID=63}},coords={x=0.202,y=0.296,source="quest_giver",mapID=63},questType="standard"},
[31855] = {id=31855,name="The Peak of Serenity - Continue Your Training",requiredLevel=30,faction="both",expansion=4,zoneID=5841,description="The time has come for you to return to the Peak of Serenity to continue your training. Use Zen Pilgrimage to return there and speak with Master Hight when you arrive.",objectivesText="Use Zen Pilgrimage to travel to the Peak of Serenity. Speak to Master Hight in the Shrine of the Ox when you arrive.",starts={{x=0.486,y=0.428,mapID=379,npcID=66260}},ends={{x=0.486,y=0.428,mapID=379,npcID=66260}},coords={mapID=379,x=0.486,y=0.428},questType="standard"},
[31856] = {id=31856,name="The Peak of Serenity - Begin Your Training",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5841,description="The time has come for you to venture to the Peak of Serenity to begin training in the ways of the Monk. Use Zen Pilgrimage to go there and speak with Master Hight when you arrive.",objectivesText="Use Zen Pilgrimage to travel to the Peak of Serenity. Speak to Master Hight in the Shrine of the Ox when you arrive.",starts={{x=0.486,y=0.428,mapID=379,npcID=66260}},ends={{npcID=66260,x=0.486,y=0.428,zoneID=5841}},coords={mapID=379,x=0.486,y=0.428},questType="standard"},
