[31862] = {id=31862,name="Zonya the Sadist",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=406,mapID=65,description="The prey be walkin' to the predator's territory, unaware of the danger that is in. You be givin' Zonya no trouble dis time.",objectivesText="Defeat Zonya the Sadist in a pet battle.",starts={{npcID=66137,x=0.596,y=0.716,mapID=65}},ends={{npcID=66137,x=0.596,y=0.716,mapID=65}},coords={x=0.596,y=0.716,source="quest_giver",mapID=65},questType="standard"},
