[31870] = {id=31870,name="Cassandra Kaboom",requiredLevel=1,faction="horde",expansion=4,zoneID=405,mapID=199,description="Cassandra Kaboom is a fierce tamer, known for her mechanical pets. She should serve as the next step on your journey to greatness. Find her in Southern Barrens near the Frazzlecraz Motherlode and challenge her. Beating Cassandra will surely prove yourself in the eyes of Varzok. Good luck.",objectivesText="Defeat Cassandra Kaboom in a pet battle. Progress: What's a <race> like you doin' in a place like this?",starts={{x=0.572,y=0.458,mapID=66,npcID=66372}},ends={{x=0.572,y=0.458,mapID=66,npcID=66372}},coords={mapID=66,x=0.572,y=0.458},questType="standard"},
[31871] = {id=31871,name="Traitor Gluk",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=357,mapID=69,description="You beat Gluk before, but now Gluk lay da smackdown on puny !",objectivesText="Defeat Traitor Gluk in a pet battle.",starts={{npcID=66352,x=0.596,y=0.496,mapID=69}},ends={{npcID=66352,x=0.596,y=0.496,mapID=69}},coords={x=0.596,y=0.496,source="quest_giver",mapID=69},questType="standard"},
[31872] = {id=31872,name="Merda Stronghoof",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=405,mapID=66,description="Just as the land continues to grow, my team is stronger than ever. Are you sure you wish to combat me? There is no shame in admitting defeat now.",objectivesText="Defeat Merda Stronghoof in a pet battle.",starts={{npcID=66372,x=0.572,y=0.458,mapID=66}},ends={{npcID=66372,x=0.572,y=0.458,mapID=66}},coords={x=0.572,y=0.458,source="quest_giver",mapID=66},questType="standard"},
[31876] = {id=31876,name="The Inkmasters of the Arboretum",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="I have heard that the Inkmasters at the Arboretum are in need of aid from a scribe of great skill. You should speak with Inkmaster Wei , if you wish to help.",objectivesText="Speak with Inkmaster Wei at the Arboretum in the Jade Forest.",starts={{npcID=64691,x=0.82,y=0.294,zoneID=5840}},ends={{npcID=56065,x=0.546,y=0.442,zoneID=5785}},coords={x=0.82,y=0.294,source="quest_giver",zoneID=5840},questType="standard"},
[31877] = {id=31877,name="The Inkmasters of the Arboretum",level=10,requiredLevel=10,faction="none",expansion=4,description="I have heard that the Inkmasters at the Arboretum are in need of aid from a scribe of great skill. You should speak with Inkmaster Wei, if you wish to help.",objectivesText="Speak with Inkmaster Wei at the Arboretum in the Jade Forest.",questType="standard"},
[31878] = {id=31878,name="Audrey Burnhep",requiredLevel=1,faction="alliance",expansion=4,description="I'm afraid I have nothing left to teach you, <name>. However, your journey as a trainer is far from over! <race>eport to Audrey Burnhep in Stormwind. She has connections with many of Azeroth's finest trainers, and will help you grow further.",objectivesText="Report to Audrey Burnhep in Stormwind.",starts={{x=0.692,y=0.25,mapID=84}},ends={{x=0.692,y=0.25,mapID=84}},coords={mapID=84,x=0.692,y=0.25},questType="standard"},
