[32035] = {id=32035,name="Got Silk?",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Strange noises comin' from over at the Silken Fields. Strange smells, too. Almost makes you think that they could use a cash-strapped to complete a few odd jobs for 'em. Make a few pieces of gold. Or not.",objectivesText="Report to Silkmaster Tsai at the Silken Fields in Valley of the Four Winds .",starts={{npcID=59585,x=0.556,y=0.52,zoneID=5805}},ends={{npcID=57405,x=0.626,y=0.596,zoneID=5805}},coords={x=0.556,y=0.52,source="quest_giver",zoneID=5805},questType="standard"},
