[32044] = {id=32044,name="Candy Bucket",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5840,mapID=1530,starts={{npcID=215903,x=0.351,y=0.777,mapID=1530}},ends={{npcID=215903,x=0.351,y=0.777,mapID=1530}},coords={x=0.351,y=0.777,source="quest_giver",mapID=1530},questType="standard"},
[32045] = {id=32045,name="Children of the Water",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="We are all children of the water here in the Valley of the Four Winds . It nourishes us, it grows our vegetables, it brings us life. Some creatures, however, drink too deeply from the water. They grow too large, and must be eliminated before they cause havoc to those around them. I am but a simple stonecarver. You, on the other hand...",objectivesText="Slay Kracor , Thundergill , and Succula .",starts={{npcID=64315,x=0.552,y=0.474,zoneID=5805}},ends={{npcID=64315,x=0.552,y=0.474,zoneID=5805}},coords={x=0.552,y=0.474,source="quest_giver",zoneID=5805},questType="standard"},
[32046] = {id=32046,name="Candy Bucket",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,mapID=376,starts={{npcID=215906,x=0.198,y=0.557,mapID=376}},ends={{npcID=215906,x=0.198,y=0.557,mapID=376}},coords={x=0.198,y=0.557,source="quest_giver",mapID=376},questType="standard"},
